#include <stdio.h>
#include <stdlib.h>

#define MAX_IMAGE_WIDTH 1024
#define MAX_IMAGE_HEIGHT 768
#define MAX_TOTAL_PIXELS (MAX_IMAGE_WIDTH * MAX_IMAGE_HEIGHT)
#define MAX_MEMORY_ALLOCATION (1024 * 1024 * 5) // 5 MB

typedef struct {
    unsigned char* pixels;
} ImageData;

ImageData** allocate_image_data(int width, int height) {
    if (width <= 0 || height <= 0) {
        fprintf(stderr, "Invalid image dimensions.\n");
        return NULL;
    }

    if ((unsigned long)width > MAX_IMAGE_WIDTH || (unsigned long)height > MAX_IMAGE_HEIGHT) {
        fprintf(stderr, "Image dimensions exceed maximum allowed size.\n");
        return NULL;
    }

    unsigned long total_pixels = (unsigned long)width * height;

    if (total_pixels > MAX_TOTAL_PIXELS) {
        fprintf(stderr, "Total number of pixels exceeds maximum allowed.\n");
        return NULL;
    }

    if (total_pixels * sizeof(unsigned char) > MAX_MEMORY_ALLOCATION) {
        fprintf(stderr, "Memory allocation would exceed maximum limit.\n");
        return NULL;
    }

    ImageData** image_data_array = (ImageData**)malloc(height * sizeof(ImageData*));
    if (!image_data_array) {
        perror("Failed to allocate memory for image data array.");
        return NULL;
    }

    for (int i = 0; i < height; ++i) {
        image_data_array[i] = (ImageData*)malloc(sizeof(ImageData));
        if (!image_data_array[i]) {
            fprintf(stderr, "Failed to allocate memory for row %d.\n", i);
            // Clean up previously allocated rows
            for (int j = 0; j < i; ++j) {
                free(image_data_array[j]);
            }
            free(image_data_array);
            return NULL;
        }

        image_data_array[i]->pixels = (unsigned char*)malloc(width * sizeof(unsigned char));
        if (!image_data_array[i]->pixels) {
            fprintf(stderr, "Failed to allocate memory for pixels in row %d.\n", i);
            // Clean up previously allocated rows and ImageData structures
            for (int j = 0; j <= i; ++j) {
                free(image_data_array[j]->pixels);
                free(image_data_array[j]);
            }
            free(image_data_array);
            return NULL;
        }
    }

    return image_data_array;
}

void free_image_data(ImageData** image_data_array, int height) {
    for (int i = 0; i < height; ++i) {
        if (image_data_array[i]->pixels) {
            free(image_data_array[i]->pixels);
        }
        free(image_data_array[i]);
    }
    free(image_data_array);
}

int main() {
    int width, height;
    printf("Enter image dimensions (width height): ");
    scanf("%d %d", &width, &height);

    ImageData** image_data = allocate_image_data(width, height);
    if (image_data) {
        // Use the allocated memory for processing
        free_image_data(image_data, height);
    }

    return 0;
}
