#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
} record;

record* allocate_records(int initial_capacity) {
    return (record*)malloc(initial_capacity * sizeof(record));
}

void free_records(record* records, int capacity) {
    if (records != NULL) {
        free(records);
    }
}

int random_int(int min, int max) {
    return min + rand() % (max - min + 1);
}

record* resize_records(record* old_records, int old_capacity, int new_capacity) {
    record* new_records = allocate_records(new_capacity);
    if (new_records != NULL) {
        for (int i = 0; i < old_capacity && i < new_capacity; i++) {
            new_records[i] = old_records[i];
        }
        free(old_records);
        return new_records;
    } else {
        printf("Memory allocation failed during resize.\n");
        return old_records;
    }
}

record* initialize_records(int initial_capacity, int range_min, int range_max) {
    record* records = allocate_records(initial_capacity);
    if (records != NULL) {
        srand(time(NULL)); // Seed PRNG
        for (int i = 0; i < initial_capacity; i++) {
            records[i].value = random_int(range_min, range_max);
        }
    } else {
        printf("Memory allocation failed.\n");
    }
    return records;
}

void clear_memory(record* records, int capacity) {
    free_records(records, capacity);
}

int main() {
    int initial_capacity = 100;
    int range_min = 0;
    int range_max = 1000;

    record* records = initialize_records(initial_capacity, range_min, range_max);

    // Simulate dynamic resizing
    for (int i = 0; i < 50; i++) {
        if (i == initial_capacity - 1) {
            initial_capacity *= 2;
            records = resize_records(records, initial_capacity / 2, initial_capacity);
        }
    }

    clear_memory(records, initial_capacity);

    return 0;
}
