#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define MAX_LINE_LENGTH 1024

void displayHelp() {
    printf("Usage: process_text -f <input_file> [-h] [-c] [-o <output_file>]\n");
    printf("Options:\n");
    printf("  -f <input_file>   Specifies the input file to process\n");
    printf("  -h                Displays this help message\n");
    printf("  -c                Enables concise output format (essential line numbers and content)\n");
    printf("  -o <output_file>  Redirects output to a specified file\n");
}

void processFile(const char* filePath, int isConcise, const char* outputFile) {
    FILE* inputFile = fopen(filePath, "r");
    if (!inputFile) {
        perror("Error opening input file");
        return;
    }

    FILE* outputFilePtr = NULL;
    if (outputFile) {
        outputFilePtr = fopen(outputFile, "w");
        if (!outputFilePtr) {
            perror("Error opening output file");
            fclose(inputFile);
            return;
        }
    } else {
        outputFilePtr = stdout;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), inputFile)) {
        if (isConcise && !strchr(line, ':')) {
            continue;
        }
        fprintf(outputFilePtr, "%s", line);
    }

    fclose(inputFile);
    if (outputFilePtr != stdout) {
        fclose(outputFilePtr);
    }
}

int main(int argc, char* argv[]) {
    const char* inputFilePath = NULL;
    int isConcise = 0;
    const char* outputFile = NULL;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0) {
            displayHelp();
            return 0;
        } else if (strcmp(argv[i], "-f") == 0 && i + 1 < argc) {
            inputFilePath = argv[++i];
        } else if (strcmp(argv[i], "-c") == 0) {
            isConcise = 1;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            outputFile = argv[++i];
        }
    }

    if (!inputFilePath) {
        fprintf(stderr, "Error: Input file not specified\n");
        displayHelp();
        return 1;
    }

    processFile(inputFilePath, isConcise, outputFile);

    return 0;
}
