#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

#define MAX_LINE_LENGTH 256

typedef struct {
    u_char ip[4];
} IPAddress;

int resolveDNS(const char *hostname, IPAddress *ip) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4 only
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "DNS resolution failed: %s\n", gai_strerror(status));
        return -1;
    }

    memcpy(ip->ip, &((struct sockaddr_in*)res->ai_addr)->sin_addr, sizeof(ip->ip));

    freeaddrinfo(res);
    return 0;
}

void processLine(const char *line) {
    char *token = strtok((char *)line, " ");
    double sum = 0.0;
    int count = 0;

    while (token != NULL) {
        if (count > 1) {
            sum += atof(token);
            count++;
        }
        token = strtok(NULL, " ");
    }

    if (count < 3) {
        printf("Insufficient data in line: %s\n", line);
        return;
    }

    double average = sum / 2.0;

    IPAddress ip;
    if (resolveDNS(line, &ip)) {
        printf("Error resolving DNS for: %s\n", line);
        return;
    }

    char ipStr[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, ip.ip, ipStr, INET_ADDRSTRLEN);

    printf("Hostname: %s, Average: %.2f, IP: %s\n", line, average, ipStr);
}

int main() {
    FILE *file = fopen("transactions.txt", "r");
    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    char buffer[MAX_LINE_LENGTH];
    while (fgets(buffer, sizeof(buffer), file)) {
        size_t len = strlen(buffer);
        if (len > 0 && buffer[len - 1] == '\n') {
            buffer[len - 1] = '\0';
        }
        processLine(buffer);
    }

    fclose(file);
    return EXIT_SUCCESS;
}
