#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

void find_largest(int* arr, int size) {
    if (size <= 0) {
        fprintf(stderr, "Invalid array size\n");
        return;
    }
    int max = arr[0];
    for (int i = 1; i < size; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    printf("Largest integer: %d\n", max);
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <file_path> <max_value>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char* file_path = argv[1];
    int max_value = atoi(argv[2]);

    FILE* file = fopen(file_path, "r");
    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    int num_integers = file_size / sizeof(int);
    int* arr = (int*)malloc(num_integers * sizeof(int));
    if (!arr) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(file);
        return EXIT_FAILURE;
    }

    size_t elements_read = fread(arr, sizeof(int), num_integers, file);
    if (elements_read != num_integers) {
        fprintf(stderr, "Error reading from file\n");
        free(arr);
        fclose(file);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < elements_read; ++i) {
        if (arr[i] > max_value) {
            fprintf(stderr, "Integer exceeds maximum value: %d\n", arr[i]);
            free(arr);
            fclose(file);
            return EXIT_FAILURE;
        }
    }

    find_largest(arr, elements_read);

    free(arr);
    fclose(file);

    return EXIT_SUCCESS;
}
