#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ADDRESSES 100

typedef struct {
    char ip[45]; // Variable-length IP string with space for worst-case scenario
    int port;
} NetworkAddress;

NetworkAddress* network_list = NULL;
int current_size = 0;
int capacity = 0;

void log_error(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vprintf(fmt, args);
    va_end(args);
}

void grow_network_list() {
    if (network_list == NULL) {
        network_list = malloc(MAX_ADDRESSES * sizeof(NetworkAddress));
        capacity = MAX_ADDRESSES;
    } else {
        NetworkAddress* new_list = realloc(network_list, capacity * 2 * sizeof(NetworkAddress));
        if (new_list == NULL) {
            log_error("Memory allocation failed for growing network list.\n");
            return;
        }
        network_list = new_list;
        capacity *= 2;
    }
}

void add_network_address(const char* ip, int port) {
    if (current_size >= capacity) {
        grow_network_list();
    }
    if (network_list == NULL) {
        log_error("Network list is not initialized.\n");
        return;
    }
    strncpy(network_list[current_size].ip, ip, sizeof(network_list[current_size].ip) - 1);
    network_list[current_size].ip[sizeof(network_list[current_size].ip) - 1] = '\0';
    network_list[current_size].port = port;
    current_size++;
}

void free_network_list() {
    if (network_list != NULL) {
        free(network_list);
        network_list = NULL;
        current_size = 0;
        capacity = 0;
    }
}
