import hashlib

def calculate_sha1_hash(file_path, expected_checksum=None):
    sha1 = hashlib.sha1()
    chunk_size = 8192  # Adjust chunk size based on performance needs

    try:
        with open(file_path, 'rb') as file:
            while True:
                data = file.read(chunk_size)
                if not data:
                    break
                sha1.update(data)

        hexdigest = sha1.hexdigest()
        match = expected_checksum is None or hexdigest == expected_checksum
        return (hexdigest, match)

    except IOError as e:
        print(f"Error reading file: {e}")
        return (None, False)

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return (None, False)

# Example usage:
file_path = 'path_to_large_file'
expected_checksum = None  # Set this to the expected checksum if available
hash_result, match = calculate_sha1_hash(file_path, expected_checksum)
print(f"SHA-1 Hash: {hash_result}, Match: {match}")
```

