import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class PokemonReportGenerator {

    private ConfigService configService;
    private ApiClient apiClient;
    private Cache<String, Map<String, Double>> cache;

    public PokemonReportGenerator(ConfigService configService, ApiClient apiClient) {
        this.configService = configService;
        this.apiClient = apiClient;
        this.cache = new HashMap<>();
    }

    public List<String> generateReports(List<Pokemon> pokemons) {
        if (pokemons == null || pokemons.isEmpty()) {
            return List.of();
        }

        Map<String, TypeMultiplier> typeMultipliers = fetchTypeMultipliersFromCache();

        List<String> reports = new ArrayList<>();
        for (Pokemon pokemon : pokemons) {
            String report = generateReport(pokemon, typeMultipliers);
            reports.add(report);
        }

        return reports;
    }

    private String generateReport(Pokemon pokemon, Map<String, TypeMultiplier> typeMultipliers) {
        StringBuilder reportBuilder = new StringBuilder();
        reportBuilder.append("Pokemon: ").append(pokemon.getName()).append("\n");

        List<String> types = pokemon.getTypes();
        for (String type : types) {
            if (typeMultipliers.containsKey(type)) {
                reportBuilder.append("Type: ").append(type).append(", Multiplier: ").append(typeMultipliers.get(type).getValue()).append("\n");
                reportBuilder.append("Weaknesses: ");
                typeMultipliers.get(type).getWeaknesses().forEach(weakness -> reportBuilder.append(weakness).append(", "));
                reportBuilder.append("\nResistances: ");
                typeMultipliers.get(type).getResistances().forEach(resistance -> reportBuilder.append(resistance).append(", "));
                reportBuilder.append("\nImmunities: ");
                typeMultipliers.get(type).getImmunities().forEach(immunity -> reportBuilder.append(immunity).append(", "));
            } else {
                reportBuilder.append("Type data not available for ").append(type).append("\n");
            }
        }

        return reportBuilder.toString();
    }

    private Map<String, TypeMultiplier> fetchTypeMultipliersFromCache() {
        if (cache.isEmpty()) {
            List<TypeMultiplier> multipliers = apiClient.fetchTypeMultipliers(configService.getApiKey());
            for (TypeMultiplier multiplier : multipliers) {
                cache.put(multiplier.getType(), multiplier);
            }
        }

        return cache;
    }

    public static class TypeMultiplier {
        private String type;
        private double value;
        private List<String> weaknesses;
        private List<String> resistances;
        private List<String> immunities;

        // Getters and setters
    }
}
