typedef struct {
    const char* name;
    void (*implementation)(void);
} CryptoFunction;

CryptoFunction* get_available_crypto_functions(int* count) {
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if (!ctx) {
        *count = 0;
        return NULL;
    }

    int num_algos = EVP_MD_count();
    CryptoFunction* functions = (CryptoFunction*)malloc(num_algos * sizeof(CryptoFunction));
    if (!functions) {
        EVP_MD_CTX_free(ctx);
        *count = 0;
        return NULL;
    }

    for (int i = 0; i < num_algos; i++) {
        const EVP_MD* algo = EVP_get_digestbynid(i);
        if (algo) {
            functions[i].name = EVP_MD_name(algo);
            functions[i].implementation = (void (*)(void))EVP_md_ctrl;
        }
    }

    *count = num_algos;
    return functions;
}

