#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>

#define TEMP_FILE_PREFIX "/tmp/tempfile_"
#define LOG_FILE "/tmp/sem_log.txt"

typedef struct {
    sem_t *sem;
    char *temp_file_path;
} SemaphoreData;

SemaphoreData* create_semaphore(int initial_value) {
    SemaphoreData *data = (SemaphoreData*)malloc(sizeof(SemaphoreData));
    data->sem = sem_open("my_semaphore", O_CREAT, 0644, initial_value);
    if (data->sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        free(data);
        return NULL;
    }

    char temp_file_path[1024];
    snprintf(temp_file_path, sizeof(temp_file_path), "%s%d", TEMP_FILE_PREFIX, getpid());
    data->temp_file_path = strdup(temp_file_path);

    int fd = open(temp_file_path, O_CREAT | O_RDWR, 0600);
    if (fd == -1) {
        perror("Failed to create temporary file");
        sem_close(data->sem);
        free(data->temp_file_path);
        free(data);
        return NULL;
    }
    close(fd);

    // Secure the file
    chmod(temp_file_path, 0600);

    return data;
}

void delete_semaphore(SemaphoreData *data) {
    if (data->sem != SEM_FAILED) {
        sem_close(data->sem);
        sem_unlink("my_semaphore");
    }

    if (data->temp_file_path != NULL) {
        remove(data->temp_file_path);
        free(data->temp_file_path);
    }

    free(data);
}

void perform_operation(SemaphoreData *data, int operation_type) {
    if (operation_type == 0) {
        sem_wait(data->sem); // Wait on semaphore
    } else {
        sem_post(data->sem); // Signal semaphore
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        char log_entry[256];
        snprintf(log_entry, sizeof(log_entry), "Operation: %s, PID: %d\n", operation_type == 0 ? "Wait" : "Signal", getpid());
        fwrite(log_entry, 1, strlen(log_entry), log_file);
        fclose(log_file);
    }
}

int main() {
    SemaphoreData *sem_data = create_semaphore(1);
    if (sem_data != NULL) {
        perform_operation(sem_data, 0); // Wait
        perform_operation(sem_data, 1); // Signal

        delete_semaphore(sem_data);
    }

    return 0;
}
```

