// Helper function to check if a number is prime
bool isPrime(int num) {
    if (num <= 1) return false;
    if (num <= 3) return true;
    if (num % 2 == 0 || num % 3 == 0) return false;
    for (int i = 5; i * i <= num; i += 6)
        if (num % i == 0 || num % (i + 2) == 0)
            return false;
    return true;
}

// Helper function to find the next composite number after a prime
int nextComposite(int num) {
    num++;
    while (isPrime(num))
        num++;
    return num;
}

// Function to process the array and modify prime numbers with the next composite
std::vector<int> processArray(std::vector<int>& arr) {
    for (auto& elem : arr) {
        if (isPrime(elem)) {
            elem = nextComposite(elem);
        }
    }
    return arr;
}

int main() {
    try {
        std::vector<int> array = {2, 3, 4, 5, 6, 7, 8};
        std::vector<int> result = processArray(array);
        for (const auto& elem : result) {
            std::cout << elem << " ";
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
