class ProxyServer {
public:
    ProxyServer(boost::asio::io_context& io_context, int max_connections)
        : acceptor(io_context, boost::asio::ip::tcp::endpoint(boost::asio::ip::tcp::v4(), 8080)),
          max_connections(max_connections) {}

    void start() {
        do_accept();
    }

private:
    boost::asio::ip::tcp::acceptor acceptor;
    int max_connections;

    void do_accept() {
        if (connections.size() < max_connections) {
            acceptor.async_accept([this](boost::system::error_code ec, boost::asio::ip::tcp::socket socket) {
                if (!ec) {
                    connections.emplace_back(std::make_shared<ProxySession>(std::move(socket), interface_table));
                    do_accept();
                } else {
                    std::cerr << "Accept failed: " << ec.message() << std::endl;
                }
            });
        }
    }

    InterfaceTable interface_table;
    std::vector<std::shared_ptr<ProxySession>> connections;
};

int main() {
    try {
        boost::asio::io_context io_context;

        ProxyServer server(io_context, 10);
        server.start();

        io_context.run();
    } catch (std::exception& e) {
        std::cerr << "Exception: " << e.what() << std::endl;
    }

    return 0;
}
