class SessionIDGenerator {
public:
    SessionIDGenerator() : rng(std::random_device{}()) {}

    std::string generateSessionID() {
        std::uniform_int_distribution<> dist(0, 16777215); // 3 bytes
        uint32_t randomValue = dist(rng);
        return toHexString(randomValue);
    }

private:
    std::mt19937 rng;

    std::string toHexString(uint32_t value) {
        static const char hexDigits[] = "0123456789ABCDEF";
        std::string result;
        for (int i = 0; i < sizeof(value); ++i) {
            result += hexDigits[(value >> (i * 4)) & 0xF];
        }
        return result;
    }
};

int main() {
    SessionIDGenerator generator;
    for (int i = 0; i < 10; ++i) {
        std::cout << "Session ID: " << generator.generateSessionID() << std::endl;
    }
    return 0;
}
```

