public class SqlQueryExecutor
{
    public IDataReader ExecuteDynamicQuery(List<string> filters, SqlConnection connection, string baseCommand)
    {
        // Construct the SQL query dynamically based on filters
        var filterClauses = new List<string>();
        foreach (var filter in filters)
        {
            // Example filter: "WHERE column_name LIKE @keyword"
            filterClauses.Add(filter);
        }

        var sqlQuery = $"{baseCommand} {string.Join(" AND ", filterClauses)}";

        using (SqlCommand command = new SqlCommand(sqlQuery, connection))
        {
            // Add parameters to the command for each filter
            foreach (var filter in filters)
            {
                if (filter.Contains("@keyword"))
                {
                    command.Parameters.AddWithValue("@keyword", "%example%"); // Example parameter
                }
                // Add other parameters as needed
            }

            try
            {
                connection.Open();
                return command.ExecuteReader(CommandBehavior.CloseConnection);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error executing SQL query: {ex.Message}");
                throw;
            }
        }
    }
}
