    public int TileSize { get; set; }
    public int MapWidth { get; set; }
    public int MapHeight { get; set; }
    public float PlayerSpeed { get; set; }

    static void Main(string[] args)
    {
        string configFilePath = "path_to_config_file.xml";
        GameWorldConfig gameConfig = LoadConfiguration(configFilePath);

        if (gameConfig != null)
        {
            // Initialize game world with the loaded configuration
            Console.WriteLine($"Tile Size: {gameConfig.TileSize}");
            Console.WriteLine($"Map Width: {gameConfig.MapWidth}");
            Console.WriteLine($"Map Height: {gameConfig.MapHeight}");
            Console.WriteLine($"Player Speed: {gameConfig.PlayerSpeed}");
        }
    }

    static GameWorldConfig LoadConfiguration(string filePath)
    {
        if (!File.Exists(filePath))
        {
            Console.WriteLine("Configuration file not found.");
            return null;
        }

        using (XmlReader reader = XmlReader.Create(filePath, new XmlReaderSettings
        {
            DtdProcessing = DtdProcessing.Prohibit,
            ValidationType = ValidationType.Schema,
            Schemas = new XmlSchemaSet { Add(null, "path_to_schema_file.xsd") }
        }))
        {
            GameWorldConfig config = null;
            while (reader.Read())
            {
                if (reader.IsStartElement() && reader.Name == "GameConfig")
                {
                    config = new GameWorldConfig
                    {
                        TileSize = int.Parse(reader.GetAttribute("TileSize")),
                        MapWidth = int.Parse(reader.GetAttribute("MapWidth")),
                        MapHeight = int.Parse(reader.GetAttribute("MapHeight")),
                        PlayerSpeed = float.Parse(reader.GetAttribute("PlayerSpeed"))
                    };
                }
            }

            if (config == null)
            {
                Console.WriteLine("Invalid configuration file.");
            }

            return config;
        }
    }
}
