from flask import Flask, request, jsonify
import requests
import time
import threading

app = Flask(__name__)

# In-memory cache for session tokens
session_tokens = {}

# Mock database service
database_service = {
    "1": {"id": "1", "name": "Resource 1", "version": 0},
    "2": {"id": "2", "name": "Resource 2", "version": 0}
}

# External API endpoint for fetching metadata
external_api_url = "https://api.example.com/metadata"

# CSRF protection token expiration time (in seconds)
csrf_token_expiration = 3600

# Optimistic locking function
def optimistic_locking(resource_id, new_data):
    resource = database_service.get(resource_id)
    if not resource:
        return False
    if resource["version"] != new_data["version"]:
        raise ValueError("Concurrent update conflict")
    resource.update(new_data)
    resource["version"] += 1
    return True

# Function to fetch metadata from external API
def fetch_metadata():
    try:
        response = requests.get(external_api_url)
        response.raise_for_status()
        return response.json()
    except Exception as e:
        print(f"Error fetching metadata: {e}")
        return None

# PUT endpoint for updating a resource
@app.route('/resource/<string:resource_id>', methods=['PUT'])
def update_resource(resource_id):
    if 'X-CSRF-Token' not in request.headers:
        return jsonify({"error": "CSRF token missing"}), 403

    csrf_token = request.headers['X-CSRF-Token']
    session_id = request.args.get('session_id')

    if session_id not in session_tokens or session_tokens[session_id] != csrf_token:
        return jsonify({"error": "Invalid CSRF token"}), 403

    # Check if CSRF token has expired
    if time.time() - session_tokens[session_id] > csrf_token_expiration:
        del session_tokens[session_id]
        return jsonify({"error": "CSRF token expired"}), 403

    try:
        new_data = request.json
        updated_resource = optimistic_locking(resource_id, new_data)

        if not updated_resource:
            return jsonify({"error": "Resource not found"}), 404

        # Fetch latest metadata from external API
        metadata = fetch_metadata()
        if metadata and 'updated_by' in new_data:
            new_data['last_updated'] = metadata.get('updated_at', time.time())

        database_service[resource_id].update(new_data)

        return jsonify(database_service[resource_id]), 200

    except ValueError as e:
        return jsonify({"error": str(e)}), 409
    except Exception as e:
        print(f"Error updating resource: {e}")
        return jsonify({"error": "Internal server error"}), 500

# Example usage of the API
@app.route('/update_resource', methods=['GET'])
def update_resource_example():
    session_id = str(time.time())
    csrf_token = str(time.time())

    # Simulate setting CSRF token in session
    session_tokens[session_id] = csrf_token

    new_data = {
        "name": "Updated Resource 1",
        "version": 0,
        "updated_by": "admin"
    }

    response = requests.put(f'http://localhost:5000/resource/1?session_id={session_id}', json=new_data, headers={"X-CSRF-Token": csrf_token})

    if response.status_code == 200:
        print("Resource updated successfully:", response.json())
    else:
        print("Error updating resource:", response.json())

if __name__ == '__main__':
    app.run(debug=True)
```

