        match env::set_var(env_var_name, full_path.display()) {
            Ok(_) => println!("Environment variable set successfully."),
            Err(e) => eprintln!("Failed to set environment variable: {}", e),
        }
    } else {
        println!("Environment variable already set.");
    }
}
