<?php

class UserManager {
    private $db;

    public function __construct($db) {
        $this->db = $db;
    }

    public function manageUser() {
        $response = ['message' => 'success'];

        // Validate input data
        if (!$this->validate($_REQUEST)) {
            $response['message'] = 'error';
            echo json_encode($response);
            return;
        }

        $id = isset($_REQUEST['id']) ? intval($_REQUEST['id']) : null;
        $name = $_REQUEST['name'];
        $email = $_REQUEST['email'];
        $password = $_REQUEST['password'];
        $redirect_to = isset($_REQUEST['redirect_to']) ? htmlspecialchars($_REQUEST['redirect_to']) : '';

        // Perform action based on sub_action
        if (isset($_REQUEST['sub_action']) && $_REQUEST['sub_action'] === 'delete') {
            if ($id !== null) {
                if (!$this->deleteUser($id)) {
                    $response['message'] = 'error';
                }
            } else {
                $response['message'] = 'error';
            }
        } elseif ($id === null) {
            // Create new user
            if (!$this->saveUser(null, $name, $email, $password)) {
                $response['message'] = 'error';
            }
        } else {
            // Update existing user
            if (!$this->saveUser($id, $name, $email, $password)) {
                $response['message'] = 'error';
            }
        }

        // Handle redirect
        if ($response['message'] === 'success' && !empty($redirect_to)) {
            header("Location: {$redirect_to}");
            exit();
        }

        echo json_encode($response);
    }

    private function validate($data) {
        $requiredFields = ['name', 'email', 'password'];
        foreach ($requiredFields as $field) {
            if (empty($data[$field])) {
                return false;
            }
        }

        if (!filter_var($data['email'], FILTER_VALIDATE_EMAIL)) {
            return false;
        }

        return true;
    }

    private function saveUser($id, $name, $email, $password) {
        try {
            if ($id === null) {
                // Insert new user
                $stmt = $this->db->prepare("INSERT INTO users (name, email, password) VALUES (:name, :email, :password)");
            } else {
                // Update existing user
                $stmt = $this->db->prepare("UPDATE users SET name = :name, email = :email, password = :password WHERE id = :id");
                $stmt->bindParam(':id', $id);
            }

            $stmt->bindParam(':name', $name);
            $stmt->bindParam(':email', $email);
            $stmt->bindParam(':password', password_hash($password, PASSWORD_DEFAULT));

            return $stmt->execute();
        } catch (PDOException $e) {
            error_log($e->getMessage());
            return false;
        }
    }

    private function deleteUser($id) {
        try {
            $stmt = $this->db->prepare("DELETE FROM users WHERE id = :id");
            $stmt->bindParam(':id', $id);
            return $stmt->execute();
        } catch (PDOException $e) {
            error_log($e->getMessage());
            return false;
        }
    }

    private function get($id) {
        try {
            $stmt = $this->db->prepare("SELECT id, name, email FROM users WHERE id = :id");
            $stmt->bindParam(':id', $id);
            $stmt->execute();
            return $stmt->fetch(PDO::FETCH_ASSOC);
        } catch (PDOException $e) {
            error_log($e->getMessage());
            return false;
        }
    }

    private function redirect($url) {
        // Implement URL validation and redirection logic here
        header("Location: {$url}");
        exit();
    }
}

