using Microsoft.EntityFrameworkCore;

public class PageController : Controller
{
    private readonly ApplicationDbContext _context;
    private readonly IValidator<UpdateRequest> _validator;
    private readonly ICachingService _cachingService;
    private readonly ILogger<PageController> _logger;
    private readonly IAuthenticationService _authenticationService;

    public PageController(ApplicationDbContext context, IValidator<UpdateRequest> validator, ICachingService cachingService, ILogger<PageController> logger, IAuthenticationService authenticationService)
    {
        _context = context;
        _validator = validator;
        _cachingService = cachingService;
        _logger = logger;
        _authenticationService = authenticationService;
    }

    [HttpPost("update")]
    public async Task<IActionResult> UpdateElement(UpdateRequest request)
    {
        var validationResult = await _validator.ValidateAsync(request);
        if (!validationResult.IsValid)
        {
            return BadRequest(validationResult.Errors);
        }

        if (!_authenticationService.IsAuthenticatedAndAuthorized(request.UserId, request.ElementId))
        {
            return Unauthorized();
        }

        var element = await _cachingService.GetElementFromCache(request.PageSectionId, request.ElementId);
        if (element == null)
        {
            element = await _context.Elements.FindAsync(request.ElementId);
            if (element == null)
            {
                return NotFound();
            }
            _cachingService.AddElementToCache(element);
        }

        try
        {
            element.Content = request.HtmlContent;
            _context.Elements.Update(element);
            await _context.SaveChangesAsync();

            _logger.LogInformation($"Updated element {request.ElementId} on page section {request.PageSectionId} by user {request.UserId}");

            return Ok(new { RefreshPage = element.NeedsFullRefresh });
        }
        catch (DbUpdateConcurrencyException)
        {
            _logger.LogError("Concurrent update conflict occurred.");
            return StatusCode(500, "Concurrent update conflict.");
        }
    }

    public class UpdateRequest
    {
        public int PageSectionId { get; set; }
        public int ElementId { get; set; }
        public string HtmlContent { get; set; }
        public int UserId { get; set; }
    }

    public interface IValidator<T>
    {
        Task<ValidationResult> ValidateAsync(T request);
    }

    public interface ICachingService
    {
        Task<Element> GetElementFromCache(int pageSectionId, int elementId);
        void AddElementToCache(Element element);
    }

    public interface IAuthenticationService
    {
        bool IsAuthenticatedAndAuthorized(int userId, int elementId);
    }

    public class ApplicationDbContext : DbContext
    {
        public DbSet<Element> Elements { get; set; }
    }

    public class Element
    {
        public int Id { get; set; }
        public int PageSectionId { get; set; }
        public string Content { get; set; }
        public bool NeedsFullRefresh { get; set; }
    }
}
