const fs = require('fs').promises;
const path = require('path');

async function readConfigFile(basePath, directoryPath, fileName) {
    try {
        // Validate directory path to prevent unauthorized access
        if (!directoryPath.startsWith(basePath)) {
            throw new Error("Unauthorized access: Directory path is outside the base path.");
        }

        const fullPath = path.join(basePath, directoryPath, fileName);

        // Check if file exists and is readable
        await fs.access(fullPath, fs.constants.R_OK);

        // Read file asynchronously using streams to minimize memory usage for large files
        return new Promise((resolve, reject) => {
            const readStream = fs.createReadStream(fullPath);
            let data = '';

            readStream.on('data', chunk => {
                data += chunk.toString();
            });

            readStream.on('end', () => {
                resolve(data);
            });

            readStream.on('error', err => {
                reject(err);
            });
        });
    } catch (err) {
        // Fetch default settings from an external configuration management service if the local file is missing
        if (err.code === 'ENOENT') {
            try {
                console.log("Fetching default settings from external service...");
                const defaultSettings = await fetchDefaultConfig(fileName);
                return JSON.parse(defaultSettings);
            } catch (defaultErr) {
                throw new Error(`Error fetching default config: ${defaultErr.message}`);
            }
        }
        throw err;
    }
}

