function runTests(config) {
    const { tests, moduleName, errorHandling } = config;
    let testIndex = 0;

    async function executeNextTest() {
        if (testIndex >= tests.length) {
            console.log('All tests completed.');
            return;
        }

        const { label, script } = tests[testIndex];
        try {
            console.log(`Executing test: ${moduleName} - ${label}`);
            await blueslip.run(script);
            console.log(`Test passed: ${moduleName} - ${label}`);
        } catch (error) {
            if (errorHandling && errorHandling.onError) {
                errorHandling.onError(error, moduleName, label);
            } else {
                console.error(`Test failed: ${moduleName} - ${label}`, error);
            }
        } finally {
            blueslip.reset();
            testIndex++;
            executeNextTest();
        }
    }

    executeNextTest();
}

