class StreamCollector {
  constructor(loadThreshold, pauseDuration) {
    this.dataBuffer = [];
    this.loadThreshold = loadThreshold;
    this.pauseDuration = pauseDuration;
    this.isPaused = false;
    this.lastLoadCheckTime = Date.now();
    this.cpuUsageHistory = [];
    this.memoryConsumptionHistory = [];
    this.latencyHistory = [];
  }

  async collectData(data) {
    if (this.isPaused) return;

    this.dataBuffer.push(data);
    await this.adjustCollectionRate();

    // Simulate data processing
    const startTime = Date.now();
    await this.processData(data);
    const endTime = Date.now();
    this.latencyHistory.push(endTime - startTime);

    this.monitorPerformance();
  }

  async adjustCollectionRate() {
    if (this.dataBuffer.length > this.loadThreshold) {
      this.isPaused = true;
      setTimeout(() => {
        this.isPaused = false;
        this.processDataBatch();
      }, this.pauseDuration);
    }
  }

  async processData(data) {
    // Simulate data processing logic
    await new Promise(resolve => setTimeout(resolve, 10));
  }

  async processDataBatch() {
    while (this.dataBuffer.length > 0 && !this.isPaused) {
      const batch = this.dataBuffer.splice(0, this.loadThreshold);
      for (const data of batch) {
        await this.processData(data);
      }
    }
  }

  monitorPerformance() {
    // Simulate performance monitoring logic
    this.cpuUsageHistory.push(Math.random());
    this.memoryConsumptionHistory.push(Math.random());
    if (
      Math.max(...this.cpuUsageHistory) > 0.8 ||
      Math.max(...this.memoryConsumptionHistory) > 0.8 ||
      Math.max(...this.latencyHistory) > 100
    ) {
      console.warn('Performance alert triggered');
    }
  }

  recoverFromFailure() {
    // Simulate automatic recovery logic
    console.log('Recovering from failure...');
  }
}

// Usage example:
const collector = new StreamCollector(10, 500);
collector.collectData({ type: 'data', value: 'example' });
```

