function traverseDOM(selector, excludeClass, root = document.body) {
  let result = [];

  const walk = node => {
    if (node.nodeType === Node.ELEMENT_NODE) {
      if (!node.classList.contains(excludeClass)) {
        if (node.matches(selector)) {
          result.push(node);
        }
        for (let child of node.childNodes) {
          walk(child);
        }
      }
    }
  };

  try {
    walk(root);
  } catch (e) {
    console.error("Traversal aborted due to error:", e);
  }

  return result;
}
