class ScriptLoader {
  constructor(apiEndpoint, fileType, maxRetries = 3, cacheDuration = 60) {
    this.apiEndpoint = apiEndpoint;
    this.fileType = fileType;
    this.maxRetries = maxRetries;
    this.cacheDuration = cacheDuration * 1000; // Convert to milliseconds
    this.cache = {};
    this.log = console.log.bind(console);
  }

  async loadScripts(fileNames) {
    for (let fileName of fileNames) {
      await this.loadScript(fileName);
    }
  }

  async loadScript(fileName) {
    const cacheKey = `${fileName}.${this.fileType}`;
    if (this.cache[cacheKey] && Date.now() - this.cache[cacheKey].time < this.cacheDuration) {
      return this.cache[cacheKey].script;
    }

    let retries = 0;
    while (retries <= this.maxRetries) {
      try {
        const response = await fetch(`${this.apiEndpoint}/${fileName}.${this.fileType}`);
        if (!response.ok) {
          throw new Error(`API error: ${response.status} ${response.statusText}`);
        }
        const scriptText = await response.text();
        const script = document.createElement('script');
        script.textContent = scriptText;
        document.head.appendChild(script);
        this.log(`Loaded and executed ${fileName}.${this.fileType}`);
        if (!this.cache[cacheKey]) {
          this.cache[cacheKey] = {};
        }
        this.cache[cacheKey].script = script;
        this.cache[cacheKey].time = Date.now();
        return script;
      } catch (error) {
        retries++;
        if (retries <= this.maxRetries) {
          this.log(`Failed to load ${fileName}.${this.fileType} (Attempt ${retries}/${this.maxRetries})`, error);
        } else {
          this.log(`Failed to load ${fileName}.${this.fileType} after ${this.maxRetries} attempts`, error);
        }
      }
    }

    return null;
  }

  static withConfiguration(apiEndpoint, fileType, maxRetries = 3, cacheDuration = 60) {
    return new ScriptLoader(apiEndpoint, fileType, maxRetries, cacheDuration);
  }
}

// Usage
const scriptLoader = ScriptLoader.withConfiguration('https://api.example.com/scripts', 'js');
scriptLoader.loadScripts(['script1', 'script2', 'script3']).then(() => {
  console.log('All scripts loaded and executed successfully');
}).catch((error) => {
  console.error('Failed to load one or more scripts', error);
});
