import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;

public class SessionIDGenerator {

    private static final SecureRandom secureRandom = new SecureRandom();
    private static final ConcurrentHashMap<String, Long> lastGeneratedTime = new ConcurrentHashMap<>();

    public static String generateSessionId(String userId) {
        long currentTime = System.currentTimeMillis();
        long uniqueNumber = secureRandom.nextLong();

        // Combine user ID, current time, and a unique number to create the session ID
        String sessionId = userId + "_" + currentTime + "_" + uniqueNumber;

        // Log the session ID generation time for performance analysis
        logSessionIdGenerationTime(userId, System.currentTimeMillis() - currentTime);

        return sessionId;
    }

    private static void logSessionIdGenerationTime(String userId, long timeTaken) {
        // Efficiently log the time taken to generate a session ID
        System.out.println("User: " + userId + ", Session ID Generation Time: " + timeTaken + " ms");
    }

    public static void main(String[] args) {
        // Example usage of the session ID generator
        String userId = "user123";
        String sessionId = generateSessionId(userId);
        System.out.println("Generated Session ID for User " + userId + ": " + sessionId);
    }
}
```

