        try {
            URI uri = new URI(urlString);
            for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
                long backoffMillis = (long) (INITIAL_BACKOFF_MILLIS * Math.pow(BACKOFF_FACTOR, attempt));
                HttpResponse<String> response = httpClient.send(
                    HttpRequest.newBuilder()
                        .uri(uri)
                        .timeout(Duration.ofSeconds(5))
                        .build(),
                    HttpResponse.BodyHandlers.ofString());

                if (response.statusCode() == 200) {
                    return true;
                }

                Thread.sleep(backoffMillis);
            }
        } catch (Exception e) {
            // Log error details here
        }
        return false;
    }

    public static void main(String[] args) {
        String testURL = "https://www.example.com";
        if (isValidPublicURL(testURL)) {
            System.out.println("Valid URL: " + testURL);
        } else {
            System.out.println("Invalid or inaccessible URL: " + testURL);
        }
    }
}
