    if (isset($_SERVER['HTTP_USER_AGENT']) && $_SERVER['HTTP_USER_AGENT'] === $newData['userAgent']) {
        $isValidRequest = true;
    }

    if (isset($_SESSION['lastRequestTime']) && time() - $_SESSION['lastRequestTime'] < 5) {
        // Prevent replay attacks
        $isValidRequest = false;
    }

    // Fetch user details from external API
    $apiUrl = "https://api.example.com/user/details/$userId";
    $response = file_get_contents($apiUrl);
    if ($response === FALSE || !isset(json_decode($response)->id)) {
        return "Error: Failed to fetch user details.";
    }

    // Update database with new data
    $dbConnection = new mysqli("localhost", "username", "password", "database");
    if ($dbConnection->connect_error) {
        return "Error: Database connection failed.";
    }

    $stmt = $dbConnection->prepare("UPDATE users SET last_ip = ?, user_agent = ?, last_modified = ? WHERE id = ?");
    $stmt->bind_param("sssi", $_SERVER['REMOTE_ADDR'], $newData['userAgent'], date('Y-m-d H:i:s'), $userId);

    if ($stmt->execute() === TRUE) {
        // Close statement and database connection
        $stmt->close();
        $dbConnection->close();

        return "Profile updated successfully.";
    } else {
        // Close statement and database connection
        $stmt->close();
        $dbConnection->close();

        return "Error: Failed to update profile.";
    }
}

