const axios = require('axios');
const fs = require('fs');
const { PassThrough } = require('stream');

async function fetchPrivateKeyAndCertificate(url) {
  try {
    const response = await axios.get(url, {
      responseType: 'stream',
      headers: {
        'Content-Type': 'application/x-pem-file'
      }
    });

    return new Promise((resolve, reject) => {
      const fileStream = fs.createWriteStream('private_key.pem');
      let dataBuffer = '';

      response.data.on('data', (chunk) => {
        dataBuffer += chunk.toString();
      });

      response.data.on('end', () => {
        try {
          // Validate and write the PEM file
          fs.writeFileSync('private_key.pem', dataBuffer);
          resolve('PEM file saved successfully');
        } catch (error) {
          reject(error);
        }
      });

      response.data.on('error', (error) => {
        reject(error);
      });
    });
  } catch (error) {
    console.error(`Error fetching private key and certificate: ${error.message}`);
    throw error;
  }
}

module.exports = fetchPrivateKeyAndCertificate;
