#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <resolv.h>
#include <curl/curl.h>

#define MAX_HOSTNAME_LEN 256
#define MAX_TOKEN_LEN 1024

typedef struct {
    char access_token[MAX_TOKEN_LEN];
} AuthToken;

static int resolve_dns(const char *hostname, char *ip_addr) {
    struct hostent *he;
    if ((he = gethostbyname(hostname)) == NULL) {
        herror("gethostbyname");
        return -1;
    }
    strcpy(ip_addr, inet_ntoa(*(struct in_addr *)he->h_addr));
    return 0;
}

static size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    // Assuming a buffer for JSON response
    char *response = (char *)userdata;
    size_t total_size = size * nmemb;
    if (total_size > MAX_TOKEN_LEN - 1) {
        fprintf(stderr, "Response too large\n");
        return -1;
    }
    strcat(response, ptr);
    return total_size;
}

static int fetch_access_token(const char *api_url, const char *client_id, const char *client_secret, AuthToken *token) {
    CURL *curl;
    CURLcode res;
    char post_data[256];
    char buffer[MAX_TOKEN_LEN] = {0};

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        snprintf(post_data, sizeof(post_data), "grant_type=client_credentials&client_id=%s&client_secret=%s", client_id, client_secret);

        curl_easy_setopt(curl, CURLOPT_URL, api_url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, post_data);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, buffer);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            return -1;
        }

        // Parse the JSON response and extract access token
        sscanf(buffer, "{\"access_token\":\"%[^\"]\",", token->access_token);

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();

    return 0;
}

static void fetch_user_info(const char *api_url, const AuthToken *token) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Authorization: Bearer ");
        headers = curl_slist_append(headers, token->access_token);

        curl_easy_setopt(curl, CURLOPT_URL, api_url);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_perform(curl);

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
}

AuthToken *auth_user(const char *hostname, const char *api_url, const char *client_id, const char *client_secret) {
    AuthToken *token = (AuthToken *)malloc(sizeof(AuthToken));
    if (!token) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    char ip_addr[MAX_HOSTNAME_LEN];
    if (resolve_dns(hostname, ip_addr) == -1) {
        free(token);
        return NULL;
    }

    if (fetch_access_token(api_url, client_id, client_secret, token) == -1) {
        free(token);
        return NULL;
    }

    fetch_user_info("https://api.example.com/user", token);

    return token;
}

int main() {
    AuthToken *token = auth_user("example.com", "https://auth.example.com/token", "client_id", "client_secret");
    if (token) {
        printf("Access Token: %s\n", token->access_token);
        free(token);
    }
    return 0;
}
```

