#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define WINDOW_SIZE 10 // 10 milliseconds

typedef struct {
    unsigned int identifier;
    time_t timestamp;
} Packet;

typedef struct {
    Packet *packets;
    int count;
    int capacity;
    time_t window_start;
    int unique_packets;
    double total_interval;
    int interval_count;
} PacketProcessor;

void initialize_processor(PacketProcessor *processor, int initial_capacity) {
    processor->packets = (Packet *)malloc(initial_capacity * sizeof(Packet));
    processor->count = 0;
    processor->capacity = initial_capacity;
    processor->window_start = time(NULL);
    processor->unique_packets = 0;
    processor->total_interval = 0.0;
    processor->interval_count = 0;
}

void add_packet(PacketProcessor *processor, Packet packet) {
    if (processor->count >= processor->capacity) {
        processor->packets = (Packet *)realloc(processor->packets, processor->capacity * 2 * sizeof(Packet));
        processor->capacity *= 2;
    }
    processor->packets[processor->count++] = packet;
}

int process_packets(PacketProcessor *processor) {
    time_t now = time(NULL);
    if ((now - processor->window_start) >= WINDOW_SIZE / 1000.0) {
        processor->window_start = now;
        processor->unique_packets = 0;
        processor->total_interval = 0.0;
        processor->interval_count = 0;
    }

    for (int i = 0; i < processor->count; i++) {
        Packet current_packet = processor->packets[i];
        if ((now - current_packet.timestamp) >= WINDOW_SIZE / 1000.0) {
            processor->unique_packets++;
            processor->total_interval += (now - current_packet.timestamp);
            processor->interval_count++;
            // Shuffle logic here
            int swap_index = rand() % processor->count;
            Packet temp = processor->packets[i];
            processor->packets[i] = processor->packets[swap_index];
            processor->packets[swap_index] = temp;
        }
    }

    processor->count = 0; // Clear the buffer after processing
    return processor->unique_packets;
}

int main() {
    srand(time(NULL));
    PacketProcessor processor;
    initialize_processor(&processor, 100);

    // Simulate packet reception and processing
    for (int i = 0; i < 500; i++) {
        Packet packet;
        packet.identifier = i;
        packet.timestamp = time(NULL);
        add_packet(&processor, packet);
    }

    int processed_packets = process_packets(&processor);
    printf("Processed %d unique packets\n", processed_packets);

    free(processor.packets);
    return 0;
}
