using System;
using System.Threading;

public class ValueGenerator
{
    private float _minValue;
    private float _maxValue;
    private Random _random;

    public ValueGenerator(float minValue = 0.0f, float maxValue = 1.0f)
    {
        SetRange(minValue, maxValue);
        _random = new Random();
    }

    public void SetRange(float minValue, float maxValue)
    {
        if (minValue >= maxValue)
            throw new ArgumentException("Minimum value must be less than maximum value.");

        _minValue = minValue;
        _maxValue = maxValue;
    }

    public void ResetToDefault()
    {
        SetRange(0.0f, 1.0f);
    }

    public float GenerateRandomFloatInclusive()
    {
        return (float)(_random.NextDouble() * (_maxValue - _minValue) + _minValue);
    }

    public float GenerateRandomFloatExclusive()
    {
        return (float)(_random.NextDouble() * (_maxValue - _minValue) + _minValue + 1e-6f);
    }

    public int GenerateRandomInt()
    {
        if (_minValue == _maxValue)
            return Convert.ToInt32(_minValue);

        float randomFloat = GenerateRandomFloatInclusive();
        return Convert.ToInt32(randomFloat);
    }
}
