function asyncReduce(numbers, initialValue, reducerCallback) {
  return new Promise((resolve, reject) => {
    let current = initialValue;
    const totalIterations = numbers.length;

    function processNext(index) {
      if (index >= totalIterations) {
        resolve(current);
        return;
      }

      setTimeout(() => {
        try {
          current = reducerCallback(current, numbers[index], index, numbers);
          processNext(index + 1);
        } catch (error) {
          reject(error);
        }
      }, Math.random() * 500); // Random delay between 0 and 500ms
    }

    processNext(0);
  });
}

// Example usage:
asyncReduce([1, 2, 3, 4], 0, (acc, val) => acc + val)
  .then(result => console.log('Reduced result:', result))
  .catch(error => console.error('Error during reduction:', error));
```

