        if (node == NULL) {
            return;
        }

        // Create new string by appending the current node's text content
        size_t newLength = strlen(currentString) + strlen(node->textContent);
        char* newString = (char*)malloc(newLength + 1);
        snprintf(newString, newLength + 1, "%s%s", currentString, node->textContent);

        // Check if the selector matches and call the callback
        if (isMatch(selector, node)) {
            Action action;
            callback(node->textContent, newString, &action);
            if (action == TERMINATE_PROCESS) {
                free(newString);
