CacheEntry cache[CACHE_SIZE];
int cache_size = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void* process_file(void* file_name) {
    FILE* file = fopen(file_name, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, file)) {
        // Process the line and update it with the average of the last two numeric fields
    }

    fclose(file);
    pthread_exit(NULL);
}

void* cache_get(void* key) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(cache[i].key, key) == 0) {
            cache[i].access_count++;
            pthread_mutex_unlock(&cache_lock);
            return &cache[i];
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return NULL;
}

void cache_set(void* key, int value) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(cache[i].key, key) == 0) {
            cache[i].value = value;
            cache[i].access_count++;
            pthread_mutex_unlock(&cache_lock);
            return;
        }
    }

    if (cache_size >= CACHE_SIZE) {
        int min_access = INT_MAX;
        int min_index = -1;
        for (int i = 0; i < cache_size; i++) {
            if (cache[i].access_count < min_access) {
                min_access = cache[i].access_count;
                min_index = i;
            }
        }

        free(cache[min_index].key);
        cache[min_index] = (CacheEntry){.key = strdup(key), .value = value, .access_count = 1};
    } else {
        cache[cache_size++] = (CacheEntry){.key = strdup(key), .value = value, .access_count = 1};
    }

    pthread_mutex_unlock(&cache_lock);
}

