    if (filename[0] == 'T') return "text";
    // Add more file type checks as needed
    return NULL;
}

int is_valid_filename(const char* filename) {
    return filename != NULL && strlen(filename) > 0;
}

void generate_new_filename(const char* existing_filename, const char* file_type, char* new_filename, size_t max_length) {
    if (!is_valid_filename(existing_filename)) {
        new_filename[0] = '\0';
        return;
    }

    const char* type = get_file_type(existing_filename);
    if (type == NULL) {
        new_filename[0] = '\0';
        return;
    }

    size_t len = strlen(existing_filename);
    int sequence_number = rand() % 10000; // Generate a random sequence number

    snprintf(new_filename, max_length, "%.*s_%d.%s", (int)len - strlen(type), existing_filename, sequence_number, type);

    if (strlen(new_filename) >= max_length) {
        new_filename[max_length - 1] = '\0';
    }
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    char existing_filename[] = "I2023_report.txt";
    char file_type[] = "report";
    char new_filename[MAX_FILENAME_LENGTH];

    generate_new_filename(existing_filename, file_type, new_filename, MAX_FILENAME_LENGTH);

    printf("New Filename: %s\n", new_filename);

    return 0;
}
