#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_COMMANDS 1024
#define MAX_COMMAND_LENGTH 256
#define MAX_LOG_ENTRIES 1024

typedef struct {
    char command[MAX_COMMAND_LENGTH];
} Command;

typedef struct {
    char log_message[MAX_LOG_ENTRIES][MAX_COMMAND_LENGTH];
    int count;
} Log;

int validate_command(const char *command) {
    // Predefined list of allowed commands
    const char *allowed_commands[] = {"ls", "pwd", "echo"};
    for (size_t i = 0; i < sizeof(allowed_commands) / sizeof(allowed_commands[0]); i++) {
        if (strcmp(command, allowed_commands[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

void execute_command(const char *command) {
    int result = system(command);
    if (result != 0) {
        printf("Error executing command: %s\n", command);
    } else {
        printf("Command executed successfully: %s\n", command);
    }
}

void log_error(Log *log, const char *message) {
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);
    pthread_mutex_lock(&mutex);
    if (log->count < MAX_LOG_ENTRIES) {
        strncpy(log->log_message[log->count], message, MAX_COMMAND_LENGTH - 1);
        log->log_count++;
    }
    pthread_mutex_unlock(&mutex);
    pthread_mutex_destroy(&mutex);
}

void *background_logger(void *arg) {
    Log *log = (Log *)arg;
    for (int i = 0; i < log->count; i++) {
        // Simulate sending logs to external service
        printf("Logging: %s\n", log->log_message[i]);
    }
    free(log);
    return NULL;
}

int process_commands(const char *config_file_path, const char *log_file_path, int verbose) {
    FILE *config_file = fopen(config_file_path, "r");
    if (!config_file) {
        printf("Error opening configuration file: %s\n", config_file_path);
        return -1;
    }

    Command commands[MAX_COMMANDS];
    Log log = {0};
    char buffer[MAX_COMMAND_LENGTH];

    int command_count = 0;
    while (fgets(buffer, sizeof(buffer), config_file)) {
        buffer[strcspn(buffer, "\n")] = '\0'; // Remove newline character
        if (validate_command(buffer)) {
            strncpy(commands[command_count].command, buffer, MAX_COMMAND_LENGTH - 1);
            command_count++;
        } else {
            log_error(&log, buffer);
        }
    }

    fclose(config_file);

    pthread_t logger_thread;
    pthread_create(&logger_thread, NULL, background_logger, &log);

    int all_commands_success = 1;
    for (int i = 0; i < command_count; i++) {
        execute_command(commands[i].command);
        if (!verbose) {
            usleep(1000 * 1000); // Sleep for 1 second to simulate execution time
        }
    }

    pthread_join(logger_thread, NULL);

    return all_commands_success;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        printf("Usage: %s <config_file_path> <log_file_path>\n", argv[0]);
        return -1;
    }

    int verbose = 1; // Default to verbose mode
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-v") == 0) {
            verbose = 1;
        } else if (strcmp(argv[i], "-q") == 0) {
            verbose = 0;
        }
    }

    int result = process_commands(argv[1], argv[2], verbose);
    return result;
}
