using System;
using System.Diagnostics;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading;

public class WebsiteManager
{
    public static string AddAndStartSite(string directoryPath, string siteName)
    {
        // Validate directory path and site name for security
        if (!IsValidPath(directoryPath) || !IsValidSiteName(siteName))
        {
            return null;
        }

        // Check for web.config file
        string configFilePath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(configFilePath))
        {
            Log("Error: No web.config file found in the specified directory.", true);
            return null;
        }

        try
        {
            // Construct command to start the website securely
            ProcessStartInfo startInfo = new ProcessStartInfo();
            startInfo.FileName = "cmd.exe";
            startInfo.Arguments = $"/c {Path.Combine(directoryPath, "start.bat")}";
            startInfo.RedirectStandardOutput = true;
            startInfo.RedirectStandardError = true;
            startInfo.UseShellExecute = false;
            startInfo.CreateNoWindow = true;

            using (Process process = new Process { StartInfo = startInfo })
            {
                // Set a timeout for the process to manage resource usage
                process.Start();
                if (!process.WaitForExit(5000)) // 5 seconds timeout
                {
                    process.Kill();
                    Log("Error: Website start command timed out.", true);
                    return null;
                }

                string output = process.StandardOutput.ReadToEnd();
                string error = process.StandardError.ReadToEnd();

                if (string.IsNullOrEmpty(error))
                {
                    Log($"Website started successfully. Output: {output}", false);
                    return siteName;
                }
                else
                {
                    Log($"Error starting website. Error: {error}", true);
                    return null;
                }
            }
        }
        catch (Exception ex)
        {
            Log($"Unexpected error: {ex.Message}", true);
            return null;
        }
    }

    private static bool IsValidPath(string path)
    {
        // Simple check for invalid characters and sequences
        return !path.ContainsAny(Path.GetInvalidPathChars());
    }

    private static bool IsValidSiteName(string siteName)
    {
        // Simple check for invalid characters and sequences
        return !siteName.ContainsAny(Path.GetInvalidFileNameChars());
    }

    private static void Log(string message, bool isError)
    {
        // Placeholder for actual logging logic
        Console.WriteLine($"{DateTime.Now} - {(isError ? "ERROR: " : "")}{message}");
    }
}
