import java.io.File;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class DirectoryLister {
    private static final Logger logger = LoggerFactory.getLogger(DirectoryLister.class);
    private static final ExecutorService executorService = Executors.newFixedThreadPool(10);

    public static void main(String[] args) {
        List<String> directoriesToCheck = Arrays.asList("/path/to/directory1", "/path/to/directory2");
        int timeoutSeconds = 5;

        for (String directory : directoriesToCheck) {
            executorService.submit(() -> listDirectoryContents(directory, timeoutSeconds));
        }

        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(timeoutSeconds, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

    private static void listDirectoryContents(String directoryPath, int timeoutSeconds) {
        File directory = new File(directoryPath);
        try {
            if (!directory.exists() || !directory.isDirectory()) {
                logger.error("Directory does not exist or is not a directory: {}", directoryPath);
                return;
            }

            List<String> contents = Arrays.asList(directory.list((dir, name) -> !name.startsWith(".")));
            logger.info("Contents of {}:\n{}", directoryPath, String.join("\n", contents));
        } catch (Exception e) {
            logger.error("Error accessing directory: {}", directoryPath, e);
        } finally {
            try {
                executorService.submit(() -> {
                    try {
                        Thread.sleep(100); // Simulate resource cleanup
                    } catch (InterruptedException ie) {
                        logger.warn("Interrupted during resource cleanup");
                    }
                }).get(timeoutSeconds, TimeUnit.SECONDS);
            } catch (Exception e) {
                logger.error("Error during resource cleanup for directory: {}", directoryPath, e);
            }
        }
    }
}
