using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;

public class CsvDecryptor
{
    private readonly string _csvFilePath;
    private readonly Func<string, byte[], byte[], byte[]> _decryptFunction;

    public CsvDecryptor(string csvFilePath)
    {
        _csvFilePath = csvFilePath;
        _decryptFunction = DecryptTripleDES;
    }

    public List<string> ProcessCsvFile()
    {
        var decryptedMessages = new List<string>();

        try
        {
            using (var reader = new StreamReader(_csvFilePath))
            {
                while (!reader.EndOfStream)
                {
                    var line = reader.ReadLine();
                    var parts = line.Split(',');

                    if (parts.Length != 3)
                    {
                        LogWarning("Invalid line format: " + line);
                        continue;
                    }

                    var messageBase64 = parts[0];
                    var keyBase64 = parts[1];
                    var ivBase64 = parts[2];

                    try
                    {
                        var encryptedBytes = Convert.FromBase64String(messageBase64);
                        var keyBytes = Convert.FromBase64String(keyBase64);
                        var ivBytes = Convert.FromBase64String(ivBase64);

                        var decryptedBytes = _decryptFunction(encryptedBytes, keyBytes, ivBytes);
                        var decryptedMessage = Encoding.UTF8.GetString(decryptedBytes);

                        decryptedMessages.Add(decryptedMessage);
                    }
                    catch (Exception ex)
                    {
                        LogError("Decryption error: " + line, ex);
                    }
                }
            }
        }
        catch (IOException ex)
        {
            LogError("IO Error processing file: " + _csvFilePath, ex);
        }

        return decryptedMessages;
    }

    private byte[] DecryptTripleDES(byte[] encryptedData, byte[] key, byte[] iv)
    {
        using (var des = new TripleDESCryptoServiceProvider())
        {
            des.Key = key;
            des.IV = iv;
            des.Mode = CipherMode.CBC;

            using (var decryptor = des.CreateDecryptor(des.Key, des.IV))
            using (var memoryStream = new MemoryStream(encryptedData))
            using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
            {
                return cryptoStream.ToArray();
            }
        }
    }

    private void LogWarning(string message)
    {
        Console.WriteLine($"WARNING: {message}");
        // Consider integrating a more robust logging mechanism here
    }

    private void LogError(string message, Exception ex)
    {
        Console.WriteLine($"ERROR: {message} - {ex.Message}");
        // Consider integrating a more robust logging mechanism here
    }
}
