using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public enum AlgorithmType
{
    Legacy,
    Modern
}

public class TokenGenerator
{
    private HttpClient _httpClient;
    private Dictionary<AlgorithmType, Func<string, string>> _algorithms;

    public TokenGenerator()
    {
        _httpClient = new HttpClient();
        InitializeAlgorithms();
    }

    private void InitializeAlgorithms()
    {
        _algorithms = new Dictionary<AlgorithmType, Func<string, string>>
        {
            { AlgorithmType.Legacy, LegacyTokenGeneration },
            { AlgorithmType.Modern, ModernTokenGeneration }
        };
    }

    public async Task<string> GenerateTokenAsync(AlgorithmType algorithmType, string input)
    {
        if (!_algorithms.ContainsKey(algorithmType))
        {
            throw new ArgumentException("Invalid algorithm type");
        }

        var token = _algorithms[algorithmType](input);
        await SendTokenToAPIAsync(token);
        return token;
    }

    private async Task SendTokenToAPIAsync(string token)
