using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Logging;

public class AesCbcDecryptor
{
    private readonly ILogger _logger;
    private readonly Dictionary<string, byte[]> _keyCache = new Dictionary<string, byte[]>();
    private readonly Dictionary<string, byte[]> _ivCache = new Dictionary<string, byte[]>();

    public AesCbcDecryptor(ILogger logger)
    {
        _logger = logger;
    }

    public byte[] Decrypt(string algorithmName, string ciphertextBase64, string keyBase64, string ivBase64)
    {
        var keyBytes = GetKey(algorithmName, keyBase64);
        var ivBytes = GetIv(algorithmName, ivBase64);

        try
        {
            using (var aes = Aes.Create())
            {
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;
                aes.Key = keyBytes;
                aes.IV = ivBytes;

                var ciphertextBytes = Convert.FromBase64String(ciphertextBase64);
                var macLength = 32; // SHA-256 MAC length
                var macBytes = new byte[macLength];
                Array.Copy(ciphertextBytes, ciphertextBytes.Length - macLength, macBytes, 0, macLength);
                var plaintextBytes = new byte[ciphertextBytes.Length - macLength];

                Array.Copy(ciphertextBytes, 0, plaintextBytes, 0, plaintextBytes.Length);

                using (var hmacSHA256 = HMACSHA256.Create())
                {
                    hmacSHA256.Key = keyBytes;
                    var computedMac = hmacSHA256.ComputeHash(plaintextBytes);
                    if (!computedMac.SequenceEqual(macBytes))
                    {
                        _logger.LogError("MAC verification failed. Decryption aborted.");
                        throw new CryptographicException("MAC verification failed.");
                    }
                }

                using (var ms = new MemoryStream(ciphertextBytes, 0, plaintextBytes.Length))
                using (var cs = new CryptoStream(ms, aes.CreateDecryptor(), CryptoStreamMode.Read))
                {
                    var decryptedData = new byte[plaintextBytes.Length];
                    int bytesRead;
                    while ((bytesRead = cs.Read(decryptedData, 0, decryptedData.Length)) > 0)
                    {
                        // Process the decrypted data as needed
                    }
                    return decryptedData;
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Decryption failed.");
            throw new CryptographicException("Decryption failed.", ex);
        }
    }

    private byte[] GetKey(string algorithmName, string keyBase64)
    {
        if (!_keyCache.ContainsKey(algorithmName))
        {
            var keyBytes = Convert.FromBase64String(keyBase64);
            _keyCache[algorithmName] = keyBytes;
        }
        return _keyCache[algorithmName];
    }

    private byte[] GetIv(string algorithmName, string ivBase64)
    {
        if (!_ivCache.ContainsKey(algorithmName))
        {
            var ivBytes = Convert.FromBase64String(ivBase64);
            _ivCache[algorithmName] = ivBytes;
        }
        return _ivCache[algorithmName];
    }
}
