// app.js
const express = require('express');
const bodyParser = require('body-parser');
const fs = require('fs');
const path = require('path');

const app = express();
app.use(bodyParser.json());

// Load user-defined functions from a directory
const functionDir = path.join(__dirname, 'functions');
fs.readdirSync(functionDir).forEach(file => {
    if (file.endsWith('.js')) {
        const funcName = file.replace('.js', '');
        require(path.join(functionDir, file))[funcName] = require(path.join(functionDir, file));
    }
});

// Endpoint to execute user-defined functions
app.post('/execute', async (req, res) => {
    try {
        const { functionName, jsonData } = req.body;
        if (!functionName || !jsonData) {
            return res.status(400).json({ error: 'Missing function name or JSON data' });
        }

        if (!(functionName in global.functions)) {
            return res.status(404).json({ error: `Function ${functionName} not found` });
        }

        const result = await global.functions[functionName](jsonData);
        res.json(result);
    } catch (error) {
        console.error('Error executing function:', error);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
```

