#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

int process_input(int argc, char *argv[]) {
    if (argc <= 2) {
        fprintf(stderr, "Usage: %s <integer1> <integer2> ... <integerN>\n", argv[0]);
        return -1;
    }

    int *input_integers = NULL;
    NFAPI_CRC_INDICATION_PDU_T *crc_indications = NULL;
    CRC_INDICATION_REL8_TAG *crc_flags = NULL;
    size_t total_size = 0;

    // Calculate the total size required
    for (int i = 1; i < argc; ++i) {
        int value = atoi(argv[i]);
        if (value <= 0) {
            fprintf(stderr, "Invalid input: %s\n", argv[i]);
            free(input_integers);
            return -1;
        }
        total_size += sizeof(NFAPI_CRC_INDICATION_PDU_T) + sizeof(CRC_INDICATION_REL8_TAG);
    }

    // Allocate memory
    input_integers = malloc((argc - 1) * sizeof(int));
    crc_indications = malloc(total_size);
    crc_flags = (CRC_INDICATION_REL8_TAG *)(((char *)crc_indications) + (argc - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!input_integers || !crc_indications || !crc_flags) {
        fprintf(stderr, "Memory allocation failed\n");
        free(input_integers);
        free(crc_indications);
        return -1;
    }

    // Populate structures
    int largest_integer = 0;
    for (int i = 1; i < argc; ++i) {
        input_integers[i - 1] = atoi(argv[i]);
        if (input_integers[i - 1] > largest_integer) {
            largest_integer = input_integers[i - 1];
        }
        crc_indications[i - 1].RX_UE_INFORMATION_TAG = i;
        crc_indications[i - 1].RNTI = (uint16_t)i * 100;
        crc_flags[i - 1].CRCFLAG = (uint8_t)(rand() % 2); // Random CRC flag
    }

    // Free allocated memory
    free(input_integers);
    free(crc_indications);

    return largest_integer;
}

int main(int argc, char *argv[]) {
    int result = process_input(argc, argv);
    if (result != -1) {
        printf("Largest integer: %d\n", result);
    }
    return 0;
}
