#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct {
    int width;
    int height;
    unsigned char *pixels;
} ImageData;

ImageData* create_image(int width, int height) {
    if (width <= 0 || height <= 0) return NULL;

    ImageData *image = malloc(sizeof(ImageData));
    if (!image) return NULL;

    size_t pixel_count = (size_t)width * height * sizeof(unsigned char);
    image->pixels = malloc(pixel_count);
    if (!image->pixels) {
        free(image);
        return NULL;
    }

    image->width = width;
    image->height = height;
    memset(image->pixels, 0, pixel_count);

    return image;
}

void destroy_image(ImageData *image) {
