typedef struct {
    int width;
    int height;
} ImageDimensions;

typedef struct {
    unsigned char *pixelData;
    size_t dataSize;
} ImageData;

ImageData* allocateImageData(const ImageDimensions* dimensions, size_t maxMemoryUsage) {
    if (dimensions->width <= 0 || dimensions->height <= 0) {
        return NULL; // Invalid dimensions
    }

    size_t totalPixels = (size_t)dimensions->width * dimensions->height;
    if (totalPixels > INT_MAX / sizeof(unsigned char)) {
        return NULL; // Integer overflow risk
    }

    ImageData* imageData = (ImageData*)malloc(sizeof(ImageData));
    if (!imageData) {
        return NULL; // Memory allocation failed
    }

    size_t totalMemoryNeeded = totalPixels * sizeof(unsigned char);
    if (totalMemoryNeeded > maxMemoryUsage) {
        free(imageData);
        return NULL; // Exceeds maximum memory usage limit
    }

    imageData->pixelData = (unsigned char*)malloc(totalMemoryNeeded);
    if (!imageData->pixelData) {
        free(imageData);
        return NULL; // Pixel data allocation failed
    }

    imageData->dataSize = totalMemoryNeeded;
    return imageData;
}

void freeImageData(ImageData* imageData) {
    if (imageData && imageData->pixelData) {
        free(imageData->pixelData);
        imageData->pixelData = NULL;
    }
    free(imageData);
}
