    class RandomNumberGenerator {
    public:
        RandomNumberGenerator() : gen(std::random_device{}()) {}
        int getValidInteger(int min, int max) {
            std::uniform_int_distribution<> dis(min, max);
            return dis(gen);
        }
    private:
        std::mt19937 gen;
    };

    static RandomNumberGenerator rng;

    void processInput() {
        std::vector<int> validIntegers;
        int num;
        while (std::cin >> num) {
            if (num >= -1000 && num <= 1000) {
                validIntegers.push_back(num);
            } else {
                std::cerr << "Invalid number: " << num << ". Must be between -1000 and 1000." << std::endl;
            }
        }

        if (validIntegers.empty()) {
            std::cout << "No valid integers entered." << std::endl;
            return;
        }

        for (int i = 0; i < validIntegers.size(); ++i) {
            int index = rng.getValidInteger(0, i);
            std::swap(validIntegers[i], validIntegers[index]);
        }

        for (const auto& num : validIntegers) {
            std::cout << num << " ";
        }
        std::cout << std::endl;
    }
}

int main() {
    NumberProcessor::processInput();
    return 0;
}
