typedef struct {
    int parent;
    int rank;
} UnionFind;

UnionFind* createUnionFind(int size) {
    UnionFind* uf = (UnionFind*)malloc(size * sizeof(UnionFind));
    for (int i = 0; i < size; ++i) {
        uf[i].parent = i;
        uf[i].rank = 0;
    }
    return uf;
}

int find(UnionFind* uf, int u) {
    if (uf[u].parent != u)
        uf[u].parent = find(uf, uf[u].parent);
    return uf[u].parent;
}

void unionElements(UnionFind* uf, int u, int v) {
    int pu = find(uf, u);
    int pv = find(uf, v);
    if (pu == pv) return;
    if (uf[pu].rank > uf[pv].rank)
        uf[pv].parent = pu;
    else {
        uf[pu].parent = pv;
        if (uf[pu].rank == uf[pv].rank)
            ++uf[pv].rank;
    }
}

void createNfapiPduList(int N, const char* baseUrl, bool disableValidation) {
    if (N > MAX_N) {
        fprintf(stderr, "Error: Maximum number of structures exceeded.\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* pduList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduList) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return;
    }

    srand(time(NULL));

    for (int i = 0; i < N; ++i) {
        pduList[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        pduList[i].RNTI = rand() % 2048;
        pduList[i].CRC_INDICATION_REL8_TAG = (rand() % 2 == 0);
    }

    UnionFind* uf = createUnionFind(N);
    clock_t start, end;

    for (int i = 0; i < N - 1; ++i) {
        start = clock();
        unionElements(uf, rand() % N, rand() % N);
        end = clock();
        printf("Time taken to check pair: %ld ms\n", (end - start) * 1000 / CLOCKS_PER_SEC);
    }

    free(pduList);
    free(uf);

    // Implement HTTP client creation and request
    // This part is not shown as it depends on the specific HTTP library being used
}

int main() {
    createNfapiPduList(10, "http://example.com", false);
    return 0;
