    if (size < MIN_PACKET_SIZE || size > MAX_PACKET_SIZE) {
        return 0; // Invalid packet size
    }
    return 1; // Valid packet size
}

Packet* allocate_packets(size_t packet_count, size_t total_payload_size) {
    Packet* packets = malloc(packet_count * sizeof(Packet));
    if (!packets) {
        return NULL; // Memory allocation failed
    }

    for (size_t i = 0; i < packet_count; i++) {
        packets[i].payload_size = total_payload_size / packet_count;
        if (total_payload_size % packet_count != 0 && i == packet_count - 1) {
            packets[i].payload_size += total_payload_size % packet_count;
        }

        packets[i].payload = malloc(packets[i].payload_size * sizeof(char));
        if (!packets[i].payload) {
            // Free previously allocated memory in case of failure
            for (size_t j = 0; j < i; j++) {
                free(packets[j].payload);
            }
            free(packets);
            return NULL; // Memory allocation failed
        }
    }

    return packets;
}

void process_packets(Packet* packets, size_t packet_count) {
    if (!packets || !packet_count) {
        return; // No packets to process
    }

    for (size_t i = 0; i < packet_count; i++) {
        log_packet_info(packets[i]);
        // Process the payload here

        free(packets[i].payload); // Free allocated memory
    }

    free(packets); // Free array of packets
}

int main() {
