        (*nfapi_structs)[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        (*nfapi_structs)[i].RNTI = rand() % 65535;
        (*nfapi_structs)[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    return 1;
}

