    NFAPI_CRC_INDICATION_PDU_T** pool = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (int i = 0; i < N; i++) {
        pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    return pool;
}

// Function to populate the array with random data
void populate_array(NFAPI_CRC_INDICATION_PDU_T** pool, int size) {
    for (int i = 0; i < size; i++) {
        pool[i]->RX_UE_INFORMATION_TAG = rand() % 1000; // Example range
        pool[i]->RNTI = (unsigned short)(rand() % 65536); // Example range
        if (!RAND_bytes((unsigned char*)&pool[i]->CRC_INDICATION_REL8_TAG, sizeof(pool[i]->CRC_INDICATION_REL8_TAG))) {
