NFAPI_CRC_INDICATION_PDU_T* create_nfaip_crc_pdu_list(int count) {
    if (count < 1 || count > MAX_STRUCTS) {
        // Handle invalid input
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu_list == NULL) {
        // Handle allocation failure
        return NULL;
    }

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    for (int i = 0; i < count; i++) {
        pthread_mutex_lock(&mutex);
        if (num_created_structs >= MAX_STRUCTS) {
            pthread_mutex_unlock(&mutex);
            // Handle buffer overflow
            free(pdu_list);
            return NULL;
        }
        num_created_structs++;
        pthread_mutex_unlock(&mutex);

        // Populate pdu_list[i] with valid data here
        pdu_list[i].rx_ue_info = create_rx_ue_information_tag();
        pdu_list[i].rnti = create_rnti();
        pdu_list[i].crc_ind_rel8.crcflag = rand() % 2; // Randomly set CRCFLAG
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    double time_taken = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
    total_time_taken += time_taken;

    return pdu_list;
}

void log_metrics() {
    printf("Number of successfully created structs: %d\n", num_created_structs);
    printf("Total time taken: %.6f seconds\n", total_time_taken);
}

