#include <openssl/evp.h>
#include <openssl/rand.h>
#include <semaphore.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

sem_t crypto_semaphore;
FILE *log_file;

void log_operation(const char *operation, const char *status) {
    time_t now = time(NULL);
    fprintf(log_file, "%s - %s: %s\n", ctime(&now), operation, status);
}

EVP_CIPHER_CTX* process_string_with_openssl(const char *input, const char *command_line_option) {
    sem_wait(&crypto_semaphore);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        log_operation("Cipher context creation", "Failed");
        sem_post(&crypto_semaphore);
        return NULL;
    }

    int key_len, iv_len;
    unsigned char key[EVP_MAX_KEY_LENGTH], iv[EVP_MAX_IV_LENGTH];
    memset(key, 0, sizeof(key));
    memset(iv, 0, sizeof(iv));

    if (RAND_bytes(key, EVP_CIPHER_key_length(EVP_aes_256_cbc())) != 1 ||
        RAND_bytes(iv, EVP_CIPHER_iv_length(EVP_aes_256_cbc())) != 1) {
        log_operation("Random bytes generation", "Failed");
        EVP_CIPHER_CTX_free(ctx);
        sem_post(&crypto_semaphore);
        return NULL;
    }

    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        log_operation("Encryption initialization", "Failed");
        EVP_CIPHER_CTX_free(ctx);
        sem_post(&crypto_semaphore);
        return NULL;
    }

    int output_len = 0;
    unsigned char *output = (unsigned char *)malloc(strlen(input) + EVP_CIPHER_block_size(EVP_aes_256_cbc()));
    if (!output) {
        log_operation("Memory allocation", "Failed");
        EVP_CIPHER_CTX_free(ctx);
        sem_post(&crypto_semaphore);
        return NULL;
    }

    if (!EVP_EncryptUpdate(ctx, output, &output_len, (unsigned char *)input, strlen(input))) {
        log_operation("Encryption update", "Failed");
        free(output);
        EVP_CIPHER_CTX_free(ctx);
        sem_post(&crypto_semaphore);
        return NULL;
    }

    int final_output_len = 0;
    if (!EVP_EncryptFinal_ex(ctx, output + output_len, &final_output_len)) {
        log_operation("Encryption final", "Failed");
        free(output);
        EVP_CIPHER_CTX_free(ctx);
        sem_post(&crypto_semaphore);
        return NULL;
    }

    *output_len += final_output_len;
    EVP_CIPHER_CTX_free(ctx);

    log_operation("Operation completed", "Success");

    sem_post(&crypto_semaphore);

    return (EVP_CIPHER_CTX *)output; // Return the encrypted data as cipher context for demonstration
}

void initialize_logging() {
    log_file = fopen("operation_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void cleanup_logging() {
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    sem_init(&crypto_semaphore, 0, 1); // Initialize semaphore

    initialize_logging();

    const char *input = "Hello, OpenSSL!";
    const char *command_line_option = "-encrypt";

    EVP_CIPHER_CTX *cipher_ctx = process_string_with_openssl(input, command_line_option);

    if (cipher_ctx) {
        // Use cipher_ctx for further processing
        free(cipher_ctx);
    }

    cleanup_logging();

    return 0;
}
```

This code snippet demonstrates a function `process_string_with_openssl` that processes a string input using OpenSSL's encryption capabilities. It includes thread synchronization with a semaphore, logging operations to a file, and error handling to ensure resource safety and stability. The main function initializes the logging system and invokes the processing function, followed by cleanup of resources.']

