void* allocate_crc_indication_pdu(int num_structures, size_t padding_size[], pthread_mutex_t* mutex) {
    pthread_mutex_lock(mutex);

    if (num_structures <= STACK_LIMIT) {
        // Use stack allocation
        NFAPI_CRC_INDICATION_PDU_T local_array[num_structures];
        for (int i = 0; i < num_structures; i++) {
            local_array[i].RX_UE_INFORMATION_TAG = rand() % 100;
            local_array[i].RNTI = rand() % 65536;
            local_array[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        }
        pthread_mutex_unlock(mutex);
        return local_array;
    } else {
        // Use heap allocation
        NFAPI_CRC_INDICATION_PDU_T* array;
        size_t total_size = num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T) + 
                            num_structures * padding_size;
        array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(total_size);
        if (!array) {
            pthread_mutex_unlock(mutex);
            return NULL; // Handle error
        }
        for (int i = 0; i < num_structures; i++) {
            array[i].RX_UE_INFORMATION_TAG = rand() % 100;
            array[i].RNTI = rand() % 65536;
            array[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        }
        pthread_mutex_unlock(mutex);
        return array;
    }
}

int main() {
