#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>

#define MAX_IMAGES 10000
#define MIN_IMAGE_SIZE 10 * 1024 * 1024 // 10MB

typedef struct {
    char** image_paths;
    size_t* image_sizes;
    size_t count;
    size_t capacity;
} ImageStorage;

void init_image_storage(ImageStorage* storage) {
    storage->image_paths = NULL;
    storage->image_sizes = NULL;
    storage->count = 0;
    storage->capacity = 0;
}

int add_image(ImageStorage* storage, const char* path) {
    struct stat file_stat;
    if (stat(path, &file_stat) != 0) {
        perror("Failed to get file stats");
        return -1;
    }

    size_t new_size = file_stat.st_size;

    if (new_size < MIN_IMAGE_SIZE) {
        printf("Image size too small: %zu bytes\n", new_size);
        return -1;
    }

    if (storage->count >= storage->capacity) {
        if (!resize_image_storage(storage, storage->capacity == 0 ? 1 : storage->capacity * 2)) {
            return -1;
        }
    }

    storage->image_paths[storage->count] = strdup(path);
    storage->image_sizes[storage->count] = new_size;
    storage->count++;

    return 0;
}

int resize_image_storage(ImageStorage* storage, size_t new_capacity) {
    char** new_paths = realloc(storage->image_paths, new_capacity * sizeof(char*));
    if (!new_paths) {
        perror("Failed to reallocate image paths");
        return -1;
    }

    size_t* new_sizes = realloc(storage->image_sizes, new_capacity * sizeof(size_t));
    if (!new_sizes) {
        perror("Failed to reallocate image sizes");
        free(new_paths);
        return -1;
    }

    storage->image_paths = new_paths;
    storage->image_sizes = new_sizes;
    storage->capacity = new_capacity;

    return 0;
}

void cleanup_image_storage(ImageStorage* storage) {
    for (size_t i = 0; i < storage->count; i++) {
        free(storage->image_paths[i]);
    }
    free(storage->image_paths);
    free(storage->image_sizes);
    storage->count = 0;
    storage->capacity = 0;
}

int main() {
    ImageStorage image_storage;
    init_image_storage(&image_storage);

    DIR* dir = opendir(".");
    if (!dir) {
        perror("Failed to open directory");
        cleanup_image_storage(&image_storage);
        return -1;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG && strlen(entry->d_name) > 4 &&
            !strcmp(entry->d_name + strlen(entry->d_name) - 4, ".jpg")) {
            char path[256];
            snprintf(path, sizeof(path), "%s", entry->d_name);
            if (add_image(&image_storage, path) != 0) {
                closedir(dir);
                cleanup_image_storage(&image_storage);
                return -1;
            }
        }
    }

    closedir(dir);

    printf("Total images: %zu\n", image_storage.count);
    for (size_t i = 0; i < image_storage.count; i++) {
        printf("Image %zu: %s, Size: %zu bytes\n", i + 1, image_storage.image_paths[i], image_storage.image_sizes[i]);
    }

    cleanup_image_storage(&image_storage);
    return 0;
}
