#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

typedef struct CipherObject {
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher;
    unsigned char key[32];
    unsigned char iv[16];
} CipherObject;

CipherObject* create_cipher_object(const char *algorithm, int mode) {
    CipherObject *cipher_obj = (CipherObject*)malloc(sizeof(CipherObject));
    if (!cipher_obj) return NULL;

    cipher_obj->ctx = EVP_CIPHER_CTX_new();
    if (!cipher_obj->ctx) {
        free(cipher_obj);
        return NULL;
    }

    const EVP_CIPHER *cipher_type = EVP_get_cipherbyname(algorithm);
    if (!cipher_type) {
        EVP_CIPHER_CTX_free(cipher_obj->ctx);
        free(cipher_obj);
        return NULL;
    }
    cipher_obj->cipher = cipher_type;

    if (RAND_bytes(cipher_obj->key, cipher_obj->cipher->key_length) != 1 ||
        RAND_bytes(cipher_obj->iv, cipher_obj->cipher->block_size) != 1) {
        EVP_CIPHER_CTX_free(cipher_obj->ctx);
        free(cipher_obj);
        return NULL;
    }

    if (EVP_CipherInit_ex(cipher_obj->ctx, cipher_type, NULL, cipher_obj->key, cipher_obj->iv, mode) != 1) {
        EVP_CIPHER_CTX_free(cipher_obj->ctx);
        free(cipher_obj);
        return NULL;
    }

    return cipher_obj;
}

void destroy_cipher_object(CipherObject *cipher_obj) {
    if (cipher_obj) {
        EVP_CIPHER_CTX_free(cipher_obj->ctx);
        free(cipher_obj);
    }
}

int encrypt_data(CipherObject *cipher_obj, const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    int ciphertext_len = 0;
    if (EVP_EncryptUpdate(cipher_obj->ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len) != 1 ||
        EVP_EncryptFinal_ex(cipher_obj->ctx, ciphertext + ciphertext_len, &ciphertext_len) != 1) {
        return -1;
    }
    return ciphertext_len;
}

int decrypt_data(CipherObject *cipher_obj, const unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    int plaintext_len = 0;
    if (EVP_DecryptUpdate(cipher_obj->ctx, plaintext, &plaintext_len, ciphertext, ciphertext_len) != 1 ||
        EVP_DecryptFinal_ex(cipher_obj->ctx, plaintext + plaintext_len, &plaintext_len) != 1) {
        return -1;
    }
    return plaintext_len;
}

int main(int argc, char *argv[]) {
    if (argc < 5) {
        fprintf(stderr, "Usage: %s <algorithm> <mode> <input_file> <output_file>\n", argv[0]);
        return 1;
    }

    const char *algorithm = argv[1];
    int mode = strcmp(argv[2], "-e") == 0 ? EVP_ENCRYPT : EVP_DECRYPT;
    FILE *in_file = fopen(argv[3], "rb");
    FILE *out_file = fopen(argv[4], "wb");

    if (!in_file || !out_file) {
        perror("File error");
        return 1;
    }

    CipherObject *cipher_obj = create_cipher_object(algorithm, mode);
    if (!cipher_obj) {
        fprintf(stderr, "Failed to create cipher object\n");
        fclose(in_file);
        fclose(out_file);
        return 1;
    }

    unsigned char buffer[4096];
    int num_bytes_read;

    while ((num_bytes_read = fread(buffer, 1, sizeof(buffer), in_file)) > 0) {
        if (mode == EVP_ENCRYPT) {
            int ciphertext_len = encrypt_data(cipher_obj, buffer, num_bytes_read, buffer);
            if (ciphertext_len < 0) {
                fprintf(stderr, "Encryption error\n");
                break;
            }
            fwrite(buffer, 1, ciphertext_len, out_file);
        } else {
            int plaintext_len = decrypt_data(cipher_obj, buffer, num_bytes_read, buffer);
            if (plaintext_len < 0) {
                fprintf(stderr, "Decryption error\n");
                break;
            }
            fwrite(buffer, 1, plaintext_len, out_file);
        }
    }

    fclose(in_file);
    fclose(out_file);
    destroy_cipher_object(cipher_obj);

    return 0;
}
