void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

NFAPI_CRC_INDICATION_PDU_T* create_batch(int N, int max_pdu_count, int log_enabled) {
    static NFAPI_CRC_INDICATION_PDU_T* batch = NULL;
    static size_t allocated_size = 0;

    if (N > max_pdu_count || N < 1) {
        fprintf(stderr, "Invalid batch size: %d\n", N);
        return NULL;
    }

    if (allocated_size < N * sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        allocated_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        free(batch);
        batch = allocate_memory(allocated_size);
    }

    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        batch[i].RX_UE_INFORMATION_TAG = rand() % max_pdu_count;
        batch[i].RNTI = rand() % max_pdu_count;
        batch[i].CRC_INDICATION_REL8_TAG = rand() % max_pdu_count;
        batch[i].CRCFLAG = rand() % 2;

        if (log_enabled) {
            fprintf(stderr, "RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
                    batch[i].RX_UE_INFORMATION_TAG, batch[i].RNTI, batch[i].CRC_INDICATION_REL8_TAG, batch[i].CRCFLAG);
        }
    }

    return batch;
}

int main() {
    int max_pdu_count = MAX_NFAPI_PDU_COUNT;
    int log_enabled = 1;

    NFAPI_CRC_INDICATION_PDU_T* batch = create_batch(5, max_pdu_count, log_enabled);

    if (batch != NULL) {
        // Process the batch
        for (int i = 0; i < 5; i++) {
            printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
                   batch[i].RX_UE_INFORMATION_TAG, batch[i].RNTI, batch[i].CRC_INDICATION_REL8_TAG, batch[i].CRCFLAG);
        }
    }

    free(batch);

    return 0;
}
