    (*pdus)->RNTI = rand() % 65536; // Random RNTI
    (*pdus)->CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG

    return 0;
}

void resize_buffer(int new_length, NFAPI_CRC_INDICATION_PDU_T** pdus, int* pdu_count) {
    if (new_length < MIN_BUFFER_SIZE) return;

    *pdus = realloc(*pdus, new_length * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdus == NULL) return; // Memory reallocation failure

    for (int i = *pdu_count; i < new_length; i++) {
        (*pdus)[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Random RX_UE_INFORMATION_TAG
