// Function to create a new image node
ImageNode* create_image_node(const void* data, size_t size) {
    ImageNode* newNode = (ImageNode*)malloc(sizeof(ImageNode));
    if (!newNode) return NULL; // Handle memory allocation failure

    newNode->data = (char*)malloc(size);
    if (!newNode->data) {
        free(newNode); // Free previously allocated memory
        return NULL;
    }
    memcpy(newNode->data, data, size);
    newNode->size = size;
    newNode->next = NULL;

    return newNode;
}

// Function to add an image node to the linked list
void add_image_node(ImageNode** head, const void* data, size_t size) {
    ImageNode* newNode = create_image_node(data, size);
    if (!newNode) return; // Handle memory allocation failure

    newNode->next = *head;
    *head = newNode;
}

