        sqlite3_finalize(stmt);
        sqlite3_close(db);
        free(metadataList);
        return;
    }

    // Execute the query and process results
    while ((sqlite3_step(stmt)) == SQLITE_ROW) {
        const unsigned char *name = sqlite3_column_text(stmt, 0);
        const unsigned char *department = sqlite3_column_text(stmt, 1);

        printf("Employee Name: %s, Department: %s\n", name, department);
    }

    // Clean up
    sqlite3_finalize(stmt);
    sqlite3_close(db);
    free(metadataList);
}

