int fetch_employee_info(int supervisor_id, EmployeeInfo *info) {
    pthread_mutex_lock(&db_mutex);

    if (db_connection == NULL || sqlite3_db_status(db_connection, SQLITE_DBSTATUS_CACHE_SIZE, &info->address, 0, 0)) {
        pthread_mutex_unlock(&db_mutex);
        return -1; // Database connection error
    }

    char query[256];
    snprintf(query, sizeof(query), "SELECT employee_name, city, address FROM Employees WHERE supervisor_id = %d", supervisor_id);

    sqlite3_stmt *stmt;
    if (sqlite3_prepare_v2(db_connection, query, -1, &stmt, 0) != SQLITE_OK) {
        pthread_mutex_unlock(&db_mutex);
        return -2; // SQL preparation error
    }

    if (sqlite3_step(stmt) == SQLITE_ROW) {
        info->employee_name = strdup((char *)sqlite3_column_text(stmt, 0));
        info->city = strdup((char *)sqlite3_column_text(stmt, 1));
        info->address = strdup((char *)sqlite3_column_text(stmt, 2));
    } else {
        sqlite3_finalize(stmt);
        pthread_mutex_unlock(&db_mutex);
        return -3; // No data found
    }

    sqlite3_finalize(stmt);
    pthread_mutex_unlock(&db_mutex);

    return 0; // Success
}

void close_database_connection() {
    if (db_connection != NULL) {
        sqlite3_close(db_connection);
        db_connection = NULL;
    }
}

int main() {
    const char *connection_string = "YourConnectionStringHere";
    if (!validate_connection_string(connection_string)) {
        printf("Invalid connection string.\n");
        return 1;
    }

    int N = 10; // Number of structures to create
    NFAPI_CRC_INDICATION_PDU_T *structures;
    if (populate_nfaapi_structures(&structures, N) != 0) {
        printf("Failed to populate structures.\n");
        free(structures);
        return 1;
    }

    EmployeeInfo info;
    memset(&info, 0, sizeof(info));
    int supervisor_id = rand() % 100; // Example supervisor ID
    if (fetch_employee_info(supervisor_id, &info) != 0) {
        printf("Failed to fetch employee information.\n");
