        return 1;
    }

    printf("Employee Name: %s\n", info.employee_name);
    printf("City: %s\n", info.city);
    printf("Address: %s\n", info.address);

    free(structures);
    free(info.employee_name);
    free(info.city);
    free(info.address);

    close_database_connection();

    return 0;
}
