    if (buffer == NULL) return NULL;

    buffer->data = (uint8_t*)malloc(initial_capacity);
    if (buffer->data == NULL) {
        free(buffer);
        return NULL;
    }

    buffer->length = 0;
    buffer->capacity = initial_capacity;
    pthread_mutex_init(&buffer->lock, NULL);

    return buffer;
}

void destroy_audio_buffer(AudioBuffer* buffer) {
    if (buffer != NULL) {
        free(buffer->data);
        pthread_mutex_destroy(&buffer->lock);
        free(buffer);
    }
}

int resize_audio_buffer(AudioBuffer* buffer, size_t new_capacity) {
    uint8_t* new_data = (uint8_t*)realloc(buffer->data, new_capacity);
    if (new_data == NULL) return -1;

    buffer->data = new_data;
    buffer->capacity = new_capacity;

    return 0;
}

void audio_buffer_push(AudioBuffer* buffer, uint8_t sample) {
    pthread_mutex_lock(&buffer->lock);

    if (buffer->length >= buffer->capacity) {
        size_t new_capacity = buffer->capacity == 0 ? MAX_SAMPLE_LENGTH : buffer->capacity * 2;
        if (resize_audio_buffer(buffer, new_capacity) != 0) {
            // Handle error
        }
    }

    buffer->data[buffer->length++] = sample;

    pthread_mutex_unlock(&buffer->lock);
}

size_t audio_buffer_size(AudioBuffer* buffer) {
    return buffer->length;
}
