#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_HOSTNAME_LEN 256
#define INITIAL_POOL_SIZE 1024
#define POOL_BLOCK_SIZE 1024

typedef struct {
    char hostname[MAX_HOSTNAME_LEN];
    struct in_addr ip;
} dns_entry;

typedef struct {
    dns_entry *entries;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} memory_pool;

memory_pool pool;

void init_memory_pool() {
    pool.entries = malloc(INITIAL_POOL_SIZE * sizeof(dns_entry));
    if (!pool.entries) {
        fprintf(stderr, "Failed to initialize memory pool\n");
        exit(EXIT_FAILURE);
    }
    pool.size = 0;
    pool.capacity = INITIAL_POOL_SIZE;
    pthread_mutex_init(&pool.lock, NULL);
}

void *allocate_memory(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_memory(void *ptr) {
    free(ptr);
}

dns_entry *pool_alloc() {
    dns_entry *entry;
    pthread_mutex_lock(&pool.lock);
    if (pool.size == pool.capacity) {
        size_t new_capacity = pool.capacity + POOL_BLOCK_SIZE;
        dns_entry *new_entries = realloc(pool.entries, new_capacity * sizeof(dns_entry));
        if (!new_entries) {
            fprintf(stderr, "Failed to expand memory pool\n");
            exit(EXIT_FAILURE);
        }
        pool.entries = new_entries;
        pool.capacity = new_capacity;
    }
    entry = &pool.entries[pool.size++];
    pthread_mutex_unlock(&pool.lock);
    return entry;
}

void pool_free(dns_entry *entry) {
    pthread_mutex_lock(&pool.lock);
    for (size_t i = 0; i < pool.size; ++i) {
        if (&pool.entries[i] == entry) {
            pool.entries[i] = pool.entries[--pool.size];
            break;
        }
    }
    pthread_mutex_unlock(&pool.lock);
}

void *dns_lookup(void *arg) {
    char *hostname = (char *)arg;
    dns_entry *entry = pool_alloc();
    int ret = gethostbyname_r(hostname, &entry->ip, entry->hostname, sizeof(entry->hostname), NULL, 1);
    if (ret != 0) {
        fprintf(stderr, "DNS lookup failed for %s\n", hostname);
        pool_free(entry);
        return NULL;
    }
    return entry;
}

int main() {
    init_memory_pool();

    pthread_t threads[5];
    char *hostnames[] = {"google.com", "github.com", "nonexistentdomain1234567890.com", "example.org"};

    for (size_t i = 0; i < 5; ++i) {
        if (pthread_create(&threads[i], NULL, dns_lookup, hostnames[i]) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&pool.lock);
    free(pool.entries);

    return 0;
}
```

This code provides a basic structure for a thread-safe DNS resolver library in C. It includes a memory pool, concurrent handling of DNS queries using threads, and error management. The actual DNS lookup logic is left to the `dns_lookup` function, which should be expanded with appropriate network communication to resolve hostnames to IP addresses.

This example demonstrates how to manage shared resources (like the memory pool) in a thread-safe manner and handle errors gracefully. It also shows how to integrate the resolver into an application by creating threads for concurrent DNS queries.']

