#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define MAX_PACKET_SIZE 1500 // Typical MTU size
#define HEADER_OVERHEAD 20

typedef struct PacketBuffer {
    uint8_t data[MAX_PACKET_SIZE + HEADER_OVERHEAD];
    struct PacketBuffer* next;
} PacketBuffer;

PacketBuffer* buffer_pool = NULL;
size_t available_buffers = 0;
size_t total_buffers = 1000; // Initial pool size

void initialize_buffer_pool() {
    for (size_t i = 0; i < total_buffers; ++i) {
        PacketBuffer* new_buffer = (PacketBuffer*)malloc(sizeof(PacketBuffer));
        if (new_buffer == NULL) {
            // Handle allocation failure
            exit(1);
        }
        new_buffer->next = buffer_pool;
        buffer_pool = new_buffer;
        available_buffers++;
    }
}

PacketBuffer* allocate_buffer() {
    if (available_buffers == 0) {
        return NULL; // No buffers available
    }
    PacketBuffer* buffer = buffer_pool;
    buffer_pool = buffer->next;
    available_buffers--;
    return buffer;
}

void release_buffer(PacketBuffer* buffer) {
    buffer->next = buffer_pool;
    buffer_pool = buffer;
    available_buffers++;
}

int process_packet_header(const uint8_t* header, size_t header_size) {
    if (header_size < 4 || (header[0] & 0xF0) != 0x40) {
        // Invalid IP header or too small to be a valid packet
        return -1;
    }

    size_t packet_length = ntohs(*(uint16_t*)(header + 2));

    if (packet_length > MAX_PACKET_SIZE) {
        // Packet is too large to handle
        return -1;
    }

    PacketBuffer* buffer = allocate_buffer();
    if (buffer == NULL) {
        // Handle no available buffers
        return -1;
    }

    memcpy(buffer->data + HEADER_OVERHEAD, header, packet_length);
    buffer->data[0] = 0x45; // IP version and header length
    buffer->data[2] = (packet_length >> 8) & 0xFF;
    buffer->data[3] = packet_length & 0xFF;

    // Process the packet data here

    release_buffer(buffer);
    return 0;
}

int main() {
    initialize_buffer_pool();

    // Simulate receiving packet headers
    uint8_t test_header1[] = {0x45, 0x00, 0x00, 0x3C, 0x00, 0x00, 0x00, 0x00, 0x40, 0x11, 0x23, 0x45, 0xC0, 0xA8, 0x01, 0x64, 0xC0, 0xA8, 0x01, 0x0A};
    process_packet_header(test_header1, sizeof(test_header1));

    uint8_t test_header2[] = {0x45, 0x00, 0x00, 0x7C, 0x00, 0x00, 0x00, 0x00, 0x40, 0x11, 0x23, 0x45, 0xC0, 0xA8, 0x01, 0x64, 0xC0, 0xA8, 0x01, 0x0A};
    process_packet_header(test_header2, sizeof(test_header2));

    return 0;
}
