#define MAX_FILE_PATH 256

typedef struct {
    int file_index;
    int roi_id;
    int x_min, y_min, x_max, y_max; // Bounding box coordinates
} ROI_Data;

ROI_Data* process_image_directory(const char* directory_path, int* total_rois) {
    DIR *dir;
    struct dirent *ent;
    FILE *file;
    char file_path[MAX_FILE_PATH];
    int file_index = 0;
    int count = 0;

    dir = opendir(directory_path);
    if (dir == NULL) {
        perror("opendir");
        return NULL;
    }

    // Estimate initial allocation size based on a rough average number of ROIs per file
    int estimate_rois_per_file = 100; // Change this estimate based on actual data
    ROI_Data *rois = (ROI_Data *)malloc(estimate_rois_per_file * sizeof(ROI_Data));
    if (rois == NULL) {
        perror("malloc");
        closedir(dir);
        return NULL;
    }

    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) {
            continue; // Skip current and parent directories
        }
        snprintf(file_path, MAX_FILE_PATH, "%s/%s", directory_path, ent->d_name);

        file = fopen(file_path, "r");
        if (file == NULL) {
            perror("fopen");
            continue;
        }

        // Assume each line represents a ROI with coordinates in the format: roi_id x_min y_min x_max y_max
        int roi_id, x_min, y_min, x_max, y_max;
        while (fscanf(file, "%d %d %d %d %d", &roi_id, &x_min, &y_min, &x_max, &y_max) == 5) {
            if (count >= estimate_rois_per_file) {
                // Reallocate memory in chunks to minimize reallocations
                int new_size = (count + estimate_rois_per_file) * sizeof(ROI_Data);
                rois = realloc(rois, new_size);
                if (rois == NULL) {
                    perror("realloc");
                    fclose(file);
                    closedir(dir);
                    return NULL;
                }
                estimate_rois_per_file *= 2; // Increase estimation for future files
            }

            rois[count].file_index = file_index;
            rois[count].roi_id = roi_id;
            rois[count].x_min = x_min;
            rois[count].y_min = y_min;
            rois[count].x_max = x_max;
            rois[count].y_max = y_max;
            count++;
        }

        fclose(file);
    }

    closedir(dir);

    // Resize the array to exactly fit the data
    ROI_Data *new_rois = realloc(rois, count * sizeof(ROI_Data));
    if (new_rois != NULL) {
        rois = new_rois;
    } else {
        perror("realloc");
    }

    *total_rois = count;
    return rois;
}
```
