#include <string.h>

#define MAX_PACKET_SIZE 1024
#define MAX_MEMORY_BUDGET 10000

typedef struct PacketNode {
    char payload[MAX_PACKET_SIZE];
    int length;
    struct PacketNode* next;
} PacketNode;

PacketNode* packet_pool = NULL;
int pool_size = 0;
int used_memory = 0;

void initialize_packet_pool(int budget) {
    max_memory_budget = budget;
    pool_size = budget / sizeof(PacketNode);
    packet_pool = (PacketNode*)malloc(pool_size * sizeof(PacketNode));
    if (!packet_pool) {
        fprintf(stderr, "Memory allocation for packet pool failed\n");
        exit(1);
    }
    for (int i = 0; i < pool_size; i++) {
        packet_pool[i].next = packet_pool + (i + 1) % pool_size;
    }
}

PacketNode* allocate_packet() {
    if (used_memory >= max_memory_budget) {
        fprintf(stderr, "Memory allocation failed: budget exceeded\n");
        return NULL;
    }
    PacketNode* node = packet_pool;
    packet_pool = packet_pool->next;
    used_memory += sizeof(PacketNode);
    return node;
}

void free_packet(PacketNode* node) {
    node->next = packet_pool;
    packet_pool = node;
    used_memory -= sizeof(PacketNode);
}

PacketNode* process_network_packet(char* payload, int length) {
    PacketNode* node = allocate_packet();
    if (!node) {
        return NULL; // Handle allocation failure
    }
    memcpy(node->payload, payload, length);
    node->length = length;
    // Process packet logic here
    return node;
}

int main() {
    initialize_packet_pool(MAX_MEMORY_BUDGET);
    char payload[MAX_PACKET_SIZE];
    int length;

    while (1) {
        // Simulate receiving a network packet
        length = recv_network_data(payload, MAX_PACKET_SIZE);
        if (length < 0) break; // Exit on error or end of data

        PacketNode* processed_packet = process_network_packet(payload, length);
        if (!processed_packet) continue; // Skip processing on failure

        // Handle the packet as needed
        free_packet(processed_packet); // Free the packet after processing
    }

    return 0;
}
```

