#include <iostream>
#include <forward_list>
#include <string>

void insertAfterTarget(std::forward_list<std::string>& myList, const std::string& target, const std::string& toInsert) {
    auto it = myList.begin();
    bool found = false;

    while (it != myList.end()) {
        if (*it == target) {
            myList.insert_after(it, toInsert);
            found = true;
            break;
        }
        ++it;
    }

    if (!found) {
        myList.push_back(toInsert);
    }
}

int main() {
    std::forward_list<std::string> myList = {"apple", "banana", "cherry"};

    insertAfterTarget(myList, "banana", "grape");

    for (const auto& item : myList) {
        std::cout << item << " ";
    }

    return 0;
}
```

