import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.SecretKeySpec;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;
import java.util.logging.Logger;

public class EncryptionUtil {
    private static final Logger logger = Logger.getLogger(EncryptionUtil.class.getName());
    private static SecretKey legacyKey;
    private static SecretKey modernKey;

    static {
        try {
            KeyGenerator keyGen = KeyGenerator.getInstance("AES");
            keyGen.init(128);
            modernKey = keyGen.generateKey();

            // Legacy key generation for DES
            KeyGenerator desKeyGen = KeyGenerator.getInstance("DES");
            desKeyGen.init(56);
            legacyKey = desKeyGen.generateKey();
        } catch (NoSuchAlgorithmException e) {
            logger.severe("Failed to initialize encryption keys: " + e.getMessage());
        }
    }

    public static String encryptString(String data, boolean useLegacy) throws Exception {
        SecretKey key = useLegacy ? legacyKey : modernKey;
        Cipher cipher = Cipher.getInstance(useLegacy ? "DES/ECB/PKCS5Padding" : "AES/ECB/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE, key);
        byte[] encryptedBytes = cipher.doFinal(data.getBytes());
        return Base64.getEncoder().encodeToString(encryptedBytes);
    }

    public static void logEncryption(String data, boolean useLegacy) {
        logger.info("Encrypted data: " + data + ", using legacy method: " + useLegacy);
    }
}
