function refreshDialogFields(dialogFieldNames, resourceId, apiUrl, maxRetries = 3) {
    dialogFieldNames.forEach(fieldName => {
        fetch(apiUrl + resourceId)
            .then(response => response.json())
            .then(data => {
                if (data[fieldName]) {
                    parent.postMessage({ field: fieldName, value: data[fieldName] }, '*');
                }
            })
            .catch(error => {
                console.error(`Error fetching ${fieldName}:`, error);
                if (maxRetries > 0) {
                    refreshDialogFields([fieldName], resourceId, apiUrl, maxRetries - 1);
                } else {
                    parent.postMessage({ field: fieldName, value: 'API Error' }, '*');
                }
            });
    });
}

// Example usage:
refreshDialogFields(['name', 'email'], '12345', 'https://api.example.com/data/');
