<?php

namespace SecurityLibrary;

class SecureUtils {
    private $characterSet;
    private $hashingAlgorithm;

    public function __construct($characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', $hashingAlgorithm = PASSWORD_DEFAULT) {
        $this->characterSet = $characterSet;
        $this->hashingAlgorithm = $hashingAlgorithm;
    }

    public static function generateRandomString($length, $charset = null) {
        if ($charset === null) {
            $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
        }
        $charactersLength = strlen($charset);
        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $charset[rand(0, $charactersLength - 1)];
        }
        return $randomString;
    }

    public function hashPassword($password, $salt = null) {
        if ($salt === null) {
            $salt = $this->generateRandomString(22);
        }
        return password_hash($password . $salt, $this->hashingAlgorithm);
    }

    public function verifyPassword($attemptedPassword, $hashedPassword, $salt = null) {
        if ($salt === null) {
            // Assume salt is embedded in the hash
            return password_verify($attemptedPassword, $hashedPassword);
        }
        return password_verify($attemptedPassword . $salt, $hashedPassword);
    }

    public static function logError($message) {
        error_log($message, 3, '/path/to/error.log');
    }

    public function setHashingAlgorithm($algorithm) {
        $this->hashingAlgorithm = $algorithm;
    }
}

class ExternalAuthService {
    private $apiUrl;

    public function __construct($apiUrl) {
        $this->apiUrl = $apiUrl;
    }

    public function verifyUser($userId, $token) {
        try {
            $ch = curl_init();
            curl_setopt($ch, CURLOPT_URL, $this->apiUrl . "/verify?user_id=" . urlencode($userId) . "&token=" . urlencode($token));
            curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
            $response = curl_exec($ch);
            if (curl_errno($ch)) {
                throw new Exception('External API error: ' . curl_error($ch));
            }
            curl_close($ch);
            return json_decode($response, true);
        } catch (Exception $e) {
            SecureUtils::logError("External API verification failed: " . $e->getMessage());
            // Retry logic can be added here
            return false;
        }
    }
}

