#include <stdlib.h>
#include <pthread.h>

#define BUFFER_OVERHEAD 20
#define ALIGNMENT_PADDING 16

typedef struct {
    size_t total_size;
    size_t used_size;
    char *buffer_pool;
    pthread_mutex_t pool_lock;
} BufferPool;

BufferPool* create_buffer_pool(size_t buffer_count, size_t packet_max_size) {
    BufferPool *pool = (BufferPool *)malloc(sizeof(BufferPool));
    if (!pool) return NULL;

    pool->total_size = buffer_count * (BUFFER_OVERHEAD + ALIGNMENT_PADDING + packet_max_size);
    pool->used_size = 0;
    pool->buffer_pool = (char *)calloc(pool->total_size, sizeof(char));
    if (!pool->buffer_pool) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->pool_lock, NULL);

    return pool;
}

void destroy_buffer_pool(BufferPool *pool) {
    pthread_mutex_destroy(&pool->pool_lock);
    free(pool->buffer_pool);
    free(pool);
}

char* allocate_buffer(BufferPool *pool, size_t packet_size) {
    if (packet_size > MAX_PACKET_SIZE) return NULL;

    char *buffer = NULL;
    pthread_mutex_lock(&pool->pool_lock);

    if ((pool->used_size + BUFFER_OVERHEAD + ALIGNMENT_PADDING + packet_size) <= pool->total_size) {
        buffer = pool->buffer_pool + pool->used_size;
        pool->used_size += BUFFER_OVERHEAD + ALIGNMENT_PADDING + packet_size;
    }

    pthread_mutex_unlock(&pool->pool_lock);

    return buffer;
}

void deallocate_buffer(BufferPool *pool, char *buffer) {
    pthread_mutex_lock(&pool->pool_lock);
    // Implement logic to deallocate a buffer and adjust used_size
    pthread_mutex_unlock(&pool->pool_lock);
}
