['```c
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define MAX_FILENAME_LEN 256
#define MAX_EXT_LEN 5

typedef struct {
    char originalFilename[MAX_FILENAME_LEN];
    char newExtension[6]; // Including space for null terminator
    int numDigits;
} FileRenameRequest;

typedef struct {
    pthread_mutex_t mutex;
    // Add other necessary fields for the distributed file processing system
} DistributedFileSystem;

void* renameFile(void* arg) {
    FileRenameRequest* request = (FileRenameRequest*)arg;
    DistributedFileSystem* dfs = (DistributedFileSystem*)request->dfs;

    pthread_mutex_lock(&dfs->mutex);

    char newFilename[MAX_FILENAME_LEN];
    strncpy(newFilename, request->originalFilename, MAX_FILENAME_LEN);
    newFilename[MAX_FILENAME_LEN - 1] = '\0'; // Ensure null termination

    char* lastDot = strrchr(newFilename, '.');
    if (lastDot == NULL || strlen(lastDot) > 1) {
        pthread_mutex_unlock(&dfs->mutex);
        return NULL; // Invalid filename
    }

    *lastDot = '\0';
    request->numDigits = snprintf(NULL, 0, "%d", strlen(newFilename));
    sprintf(newFilename, "%s.%*s%d%s", newFilename, MAX_EXT_LEN - request->numDigits, request->newExtension, request->numDigits, lastDot + 1);

    // Simulate file renaming in a distributed system
    printf("Renaming %s to %s\n", request->originalFilename, newFilename);

    pthread_mutex_unlock(&dfs->mutex);
    return NULL;
}

