    RX_UE_INFORMATION_TAG rx_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_RX_UE_INFO_T;

typedef struct NfaApiRxUeInfoList_ {
    NFAPI_RX_UE_INFO_T *info;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPI_RX_UE_INFO_LIST;

void nfaapi_rx_ue_info_list_init(NFAPI_RX_UE_INFO_LIST *list) {
    list->count = 0;
    list->capacity = 16; // Initial capacity
    list->info = (NFAPI_RX_UE_INFO_T *)malloc(list->capacity * sizeof(NFAPI_RX_UE_INFO_T));
    pthread_mutex_init(&list->lock, NULL);
}

void nfaapi_rx_ue_info_list_add(NFAPI_RX_UE_INFO_LIST *list, NFAPI_RX_UE_INFO_T info) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        if (new_capacity > MAX_STRUCTURES) new_capacity = MAX_STRUCTURES;
        NFAPI_RX_UE_INFO_T *new_info = (NFAPI_RX_UE_INFO_T *)realloc(list->info, new_capacity * sizeof(NFAPI_RX_UE_INFO_T));
        if (!new_info) {
            perror("Failed to reallocate memory");
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->info = new_info;
        list->capacity = new_capacity;
    }
    list->info[list->count++] = info;
    pthread_mutex_unlock(&list->lock);
}

void nfaapi_rx_ue_info_list_destroy(NFAPI_RX_UE_INFO_LIST *list) {
    free(list->info);
    pthread_mutex_destroy(&list->lock);
}

