NFAPI_CRC_INDICATION_PDU_T* deserializeNfapiIndications(const char* filename, size_t* count) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    size_t fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    NFAPI_CRC_INDICATION_PDU_T* indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(fileSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        perror("Failed to allocate memory");
        fclose(file);
        return NULL;
    }

    size_t bytesRead = fread(indications, sizeof(NFAPI_CRC_INDICATION_PDU_T), fileSize, file);
    fclose(file);

    *count = bytesRead;

