typedef struct {
    void** payloads;
    size_t capacity;
    size_t count;
} PacketData;

PacketData* create_packet_data() {
    PacketData* pd = (PacketData*)malloc(sizeof(PacketData));
    if (!pd) return NULL;

    pd->payloads = (void**)calloc(INITIAL_CAPACITY, sizeof(void*));
    if (!pd->payloads) {
        free(pd);
        return NULL;
    }

    pd->capacity = INITIAL_CAPACITY;
    pd->count = 0;

    return pd;
}

void destroy_packet_data(PacketData* pd) {
    for (size_t i = 0; i < pd->count; ++i) {
        free(pd->payloads[i]);
    }
    free(pd->payloads);
    free(pd);
}

int add_payload(PacketData* pd, void* payload, size_t size) {
    if (pd->count >= pd->capacity) {
        size_t new_capacity = pd->capacity * 2;
        void** new_payloads = (void**)realloc(pd->payloads, new_capacity * sizeof(void*));

        if (!new_payloads) return -1; // Memory allocation failed

        pd->payloads = new_payloads;
        pd->capacity = new_capacity;
    }

    pd->payloads[pd->count] = malloc(size);
    if (!pd->payloads[pd->count]) {
        return -1; // Payload allocation failed
    }

    memcpy(pd->payloads[pd->count], payload, size);
    ++pd->count;

    return 0;
}

