    for (int i = 0; i < imageCount; ++i) {
        free(images[i]->pixelData);
        free(images[i]);
    }
    free(images);

    return EXIT_SUCCESS;
}

int main(int argc, char* argv[]) {
    return processImageFiles(argc, argv);
