typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(int rx_tag, int rnti, int crc_rel8_tag, int crcflag) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->data.RX_UE_INFORMATION_TAG = rx_tag;
    new_node->data.RNTI = rnti;
    new_node->data.CRC_INDICATION_REL8_TAG = crc_rel8_tag;
    new_node->data.CRCFLAG = crcflag;
    new_node->next = NULL;
    return new_node;
}

Node* create_linked_list(int N, int rx_tag_range, int rnti_range, int crc_rel8_tag_range) {
    if (N <= 0 || rx_tag_range <= 0 || rnti_range <= 0 || crc_rel8_tag_range <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    Node* head = create_node(rand() % rx_tag_range, rand() % rnti_range, rand() % crc_rel8_tag_range, rand());
    if (!head) {
        return NULL;
    }

    Node* current = head;
    for (int i = 1; i < N; ++i) {
        Node* new_node = create_node(rand() % rx_tag_range, rand() % rnti_range, rand() % crc_rel8_tag_range, rand());
        if (!new_node) {
            // Clean up previously allocated nodes
            while (head != NULL) {
                Node* temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }
        current->next = new_node;
        current = new_node;
    }

    return head;
}

void destroy_linked_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
}

int main() {
    srand(time(NULL));

    int N = 10; // Example number of elements
    int rx_tag_range = 1000; // Example range for RX_UE_INFORMATION_TAG
    int rnti_range = 1000; // Example range for RNTI
    int crc_rel8_tag_range = 2; // Example range for CRC_INDICATION_REL8_TAG

    Node* head = create_linked_list(N, rx_tag_range, rnti_range, crc_rel8_tag_range);

    if (head != NULL) {
        printf("Linked list created successfully\n");
        destroy_linked_list(head);
    }

    return 0;
}
