    Packet* packet = malloc(sizeof(Packet));
    if (packet == NULL)
        return NULL;

    packet->data = malloc(length);
    if (packet->data == NULL) {
        free(packet);
        return NULL;
    }

    memcpy(packet->data, data, length);
    packet->length = length;
    packet->checksum = calculate_checksum(data, length); // Assume this function is defined elsewhere
    packet->next = NULL;

    return packet;
}

Packet* add_packet_to_list(Packet* head, const void* data, size_t length) {
    Packet* new_packet = create_packet(data, length);
    if (new_packet == NULL)
        return head;

    if (head == NULL)
        return new_packet;

    Packet* current = head;
    while (current->next != NULL)
        current = current->next;

    current->next = new_packet;
    return head;
}

void free_packet_list(Packet* head) {
