typedef struct ImageMetadata {
    int width;
    int height;
    FILE* filePtr;
} ImageMetadata;

typedef struct MetadataManager {
    ImageMetadata** metadataList;
    size_t count;
    size_t bufferSize;
    size_t maxBufferSize;
    pthread_mutex_t lock;
} MetadataManager;

void logMessage(const char* message, ...) {
    va_list args;
    va_start(args, message);
    vprintf(message, args);
    va_end(args);
}

MetadataManager* createMetadataManager(size_t initialSize) {
    MetadataManager* manager = (MetadataManager*)malloc(sizeof(MetadataManager));
    if (!manager) {
        logMessage("Failed to allocate metadata manager\n");
        return NULL;
    }
    manager->metadataList = (ImageMetadata**)malloc(initialSize * sizeof(ImageMetadata*));
    if (!manager->metadataList) {
        logMessage("Failed to allocate initial buffer for metadata list\n");
        free(manager);
        return NULL;
    }
    manager->count = 0;
    manager->bufferSize = initialSize;
    manager->maxBufferSize = initialSize;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroyMetadataManager(MetadataManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->metadataList[i]->filePtr) {
            fclose(manager->metadataList[i]->filePtr);
        }
        free(manager->metadataList[i]);
    }
    free(manager->metadataList);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int addMetadata(MetadataManager* manager, int width, int height, const char* filename) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->bufferSize) {
        size_t newBufferSize = manager->bufferSize * 2;
        ImageMetadata** newBuffer = (ImageMetadata**)realloc(manager->metadataList, newBufferSize * sizeof(ImageMetadata*));
        if (!newBuffer) {
            logMessage("Failed to reallocate buffer for metadata list\n");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->metadataList = newBuffer;
        manager->bufferSize = newBufferSize;
    }

    ImageMetadata* metadata = (ImageMetadata*)malloc(sizeof(ImageMetadata));
    if (!metadata) {
        logMessage("Failed to allocate metadata structure\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    metadata->width = width;
    metadata->height = height;
    metadata->filePtr = fopen(filename, "r");
    if (!metadata->filePtr) {
        logMessage("Failed to open file for image metadata\n");
        free(metadata);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    manager->metadataList[manager->count++] = metadata;
    logMessage("Successfully added image metadata\n");
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Add more functions as needed for managing the dynamic list of image metadata structures.
