// Function to safely calculate memory allocation size
size_t safeMultiply(size_t a, size_t b) {
    if (b > SIZE_MAX / a) {
        fprintf(stderr, "Memory allocation would overflow\n");
        exit(EXIT_FAILURE);
    }
    return a * b;
}

// Function to process image file paths and store metadata
ImageMetadata* processImagePaths(char** filePaths, int count, size_t maxTotalMemory) {
    ImageMetadata* metadataArray = NULL;
    size_t totalSize = safeMultiply(count, sizeof(ImageMetadata));

    // Check if the total memory exceeds the maximum allowed
    if (totalSize > maxTotalMemory) {
        fprintf(stderr, "Exceeds maximum allowed memory usage\n");
        return NULL;
    }

    // Allocate memory for metadata array
    metadataArray = (ImageMetadata*)malloc(totalSize);
    if (!metadataArray) {
        perror("Failed to allocate memory");
        return NULL;
    }

    for (int i = 0; i < count; ++i) {
        FILE* file = fopen(filePaths[i], "rb");
        if (!file) {
            fprintf(stderr, "Failed to open file: %s\n", filePaths[i]);
            continue;
        }

        // Read image metadata from file
