    pthread_mutex_t mutex;
    size_t max_buffer_size;
} DynamicList;

DynamicList* create_dynamic_list(size_t initial_capacity) {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list->mutex, NULL);
    list->count = 0;
    list->capacity = initial_capacity;
    list->max_buffer_size = DEFAULT_MAX_BUFFER_SIZE;
    return list;
}

void destroy_dynamic_list(DynamicList *list) {
    free(list->data);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_to_list(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->max_buffer_size) {
        printf("Buffer size limit exceeded.\n");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_data) {
            printf("Memory allocation failed.\n");
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }

        list->data = new_data;
        list->capacity = new_capacity;
    }

    list->data[list->count++] = *item;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

