void log_message(const char* message);

// Function to create and manage the dynamic array
NFAPI_CRC_INDICATION_PDU_T** create_dynamic_array() {
    int max_structs = get_max_structs();
    if (max_structs <= 0) {
        log_message("Invalid MAX_STRUCTS value");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T** array = malloc(max_structs * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (array == NULL) {
        log_message("Failed to allocate memory for the array");
        return NULL;
    }

    int successful_allocations = 0;
    for (int i = 0; i < max_structs; i++) {
        array[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (array[i] == NULL) {
            log_message("Failed to allocate memory for struct at index %d", i);
            break;
        }
        successful_allocations++;
    }

    // Resize the array if not all allocations were successful
    if (successful_allocations < max_structs) {
        NFAPI_CRC_INDICATION_PDU_T** new_array = realloc(array, successful_allocations * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (new_array == NULL) {
            log_message("Failed to reallocate memory for the array");
            free(array);
            return NULL;
        }
        array = new_array;
    }

    // Set random values for demonstration purposes
    srand(time(NULL));
    for (int i = 0; i < successful_allocations; i++) {
        array[i]->ueInfoTag = rand() % 1000;
        array[i]->rnti = rand() % 1000;
        array[i]->crcFlag = rand() % 2 == 0 ? CRCFLAG_OK : CRCFLAG_ERROR;
    }

    log_message("Successfully created %d structures", successful_allocations);
    return array;
}

// Function to free the dynamically allocated array
