#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    // Define the structure for packet header details
} PacketHeader;

typedef struct {
    // Define the structure for payload data
} PayloadData;

typedef struct {
    PacketHeader header;
    PayloadData *payload;
    size_t payload_length;
} PacketData;

typedef struct {
    PacketData **packet_pool;
    size_t pool_size;
    size_t packet_count;
    pthread_mutex_t lock;
} PacketManager;

void init_packet_manager(PacketManager *manager, size_t initial_size) {
    manager->packet_pool = (PacketData **)malloc(initial_size * sizeof(PacketData *));
    if (!manager->packet_pool) {
        // Handle memory allocation failure
    }
    manager->pool_size = initial_size;
    manager->packet_count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void destroy_packet_manager(PacketManager *manager) {
    for (size_t i = 0; i < manager->packet_count; ++i) {
        free(manager->packet_pool[i]->payload);
        free(manager->packet_pool[i]);
    }
    free(manager->packet_pool);
    pthread_mutex_destroy(&manager->lock);
}

PacketData *allocate_packet(PacketManager *manager, size_t payload_length) {
    PacketData *new_packet = (PacketData *)malloc(sizeof(PacketData));
    if (!new_packet) {
        // Handle memory allocation failure
    }

    new_packet->payload = (PayloadData *)malloc(payload_length * sizeof(PayloadData));
    if (!new_packet->payload) {
        free(new_packet);
        // Handle memory allocation failure
    }
    new_packet->payload_length = payload_length;

    pthread_mutex_lock(&manager->lock);
    if (manager->packet_count >= manager->pool_size) {
        size_t new_size = manager->pool_size * 2;
        PacketData **new_pool = (PacketData **)realloc(manager->packet_pool, new_size * sizeof(PacketData *));
        if (!new_pool) {
            free(new_packet->payload);
            free(new_packet);
            // Handle memory allocation failure
        }
        manager->packet_pool = new_pool;
        manager->pool_size = new_size;
    }
    manager->packet_pool[manager->packet_count++] = new_packet;
    pthread_mutex_unlock(&manager->lock);

    return new_packet;
}

void free_packet(PacketManager *manager, PacketData *packet) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->packet_count; ++i) {
        if (manager->packet_pool[i] == packet) {
            free(packet->payload);
            free(packet);
            while (i + 1 < manager->packet_count) {
                manager->packet_pool[i] = manager->packet_pool[i + 1];
                i++;
            }
            manager->packet_count--;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}
