} DynamicList;

DynamicList* handleNfapiIndications(const char* source, int useNetwork) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->data = NULL;
    list->count = 0;
    list->capacity = 0;

    FILE* file = NULL;
    if (useNetwork) {
        // Initialize network connection
    } else {
        file = fopen(source, "rb");
        if (!file) {
            free(list);
            return NULL;
        }
    }

    size_t bytesRead;
    NFAPI_CRC_INDICATION_PDU_T pdu;
    while ((bytesRead = fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) == 1) {
        if (list->count >= list->capacity) {
            size_t newCapacity = (list->capacity > 0) ? list->capacity * 2 : 1;
            NFAPI_CRC_INDICATION_PDU_T* newData = realloc(list->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!newData) {
                free(list->data);
                free(list);
                fclose(file);
                return NULL;
            }
            list->data = newData;
            list->capacity = newCapacity;
        }
        list->data[list->count++] = pdu;
    }

    if (useNetwork) {
        // Close network connection
    } else {
        fclose(file);
    }

    return list;
}
