void load_image_async(const char* file_path, void (*callback)(image_data_t*)) {
    // Simulate asynchronous loading
    FILE* file = fopen(file_path, "rb");
    if (file) {
        fseek(file, 0, SEEK_END);
        long size = ftell(file);
        fseek(file, 0, SEEK_SET);

        image_data_t* image = (image_data_t*)malloc(sizeof(image_data_t));
        if (image) {
            image->pixel_data = (char*)malloc(size);
            if (image->pixel_data) {
                fread(image->pixel_data, 1, size, file);
                image->width = 0; // Placeholder for actual width
                image->height = 0; // Placeholder for actual height

                callback(image);
            } else {
                free(image);
                printf("Memory allocation failed\n");
            }
        }
        fclose(file);
    } else {
        printf("Failed to open file: %s\n", file_path);
    }
}

// Callback function to handle loaded image data
