#define MAX_PACKETS 1000
#define HEADER_SIZE 8

typedef struct {
    uint32_t length;
    uint16_t checksum;
    char payload[1024];
} Packet;

uint16_t calculate_checksum(const Packet *packet) {
    uint32_t sum = packet->length + packet->checksum;
    while (sum >> 16) {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }
    return ~sum;
}

int process_packets(Packet packets[], int count, size_t *total_memory) {
    if (count > MAX_PACKETS) {
        fprintf(stderr, "Error: Too many packets.\n");
        return -1;
    }

    size_t memory_required = count * sizeof(Packet);
    if ((size_t)-1 == (*total_memory += memory_required)) {
        fprintf(stderr, "Error: Memory overflow.\n");
        return -1;
    }

    for (int i = 0; i < count; ++i) {
        if (calculate_checksum(&packets[i]) != packets[i].checksum) {
            fprintf(stderr, "Error: Packet %d checksum mismatch.\n", i);
            return -1;
        }
    }

    // Simulate processing time
    clock_t start = clock();
    while ((clock() - start) < CLOCKS_PER_SEC); // Process for 1 second

    return 0;
}

int main() {
    Packet packets[MAX_PACKETS];
    int count = 5; // Number of packets to process
    size_t total_memory = 0;

    // Populate packets with sample data
    for (int i = 0; i < count; ++i) {
        packets[i].length = HEADER_SIZE + rand() % 1024;
        packets[i].checksum = calculate_checksum(&packets[i]);
        strcpy(packets[i].payload, "Sample Payload");
    }

    if (process_packets(packets, count, &total_memory) == 0) {
        printf("Processed %d packets using %zu bytes of memory.\n", count, total_memory);
    }

    return 0;
}
