} Node;

typedef struct LinkedList {
    Node* head;
} LinkedList;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

LinkedList* create_linked_list(int N, uint32_t total_memory_used) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    list->head = NULL;

    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = rand() % UINT32_MAX;
        data.RNTI = rand() % 65535;
        data.crc_indication_rel8_tag = (CRC_INDICATION_REL8_TAG*)malloc(sizeof(CRC_INDICATION_REL8_TAG));
