        data.crc_indication_rel8_tag->crcflag = rand() % 2;

        Node* new_node = create_node(data);
        if (new_node == NULL) {
            // Handle memory allocation failure
            return NULL;
        }

        total_memory_used += sizeof(Node) + sizeof(NFAPI_CRC_INDICATION_PDU_T) + sizeof(CRC_INDICATION_REL8_TAG);
        if (total_memory_used > TOTAL_MEMORY_LIMIT) {
            // Handle memory limit exceeded
            return NULL;
        }

        new_node->next = list->head;
        list->head = new_node;
    }

    return list;
}

NFAPI_CRC_INDICATION_PDU_T* get_data_by_rnti(LinkedList* list, uint16_t RNTI) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            return &current->data;
        }
        current = current->next;
    }
    return NULL; // RNTI not found
}

void free_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->data.crc_indication_rel8_tag);
        free(current);
        current = next;
    }
    free(list);
}
