}

int main() {
    ImageInfo images[MAX_IMAGES];
    int num_images = 0;

    // Populate image metadata from database
    // ...

    pthread_t threads[MAX_IMAGES];

    for (int i = 0; i < num_images; i++) {
        if (pthread_create(&threads[i], NULL, process_image, &images[i]) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_images; i++) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
