#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct ImageMetadata {
    int width;
    int height;
    int pixel_count;
} ImageMetadata;

int read_image_metadata(const char* filename, ImageMetadata* metadata) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1; // File not found or cannot be opened

    fread(&metadata->width, sizeof(int), 1, file);
    fread(&metadata->height, sizeof(int), 1, file);
    fread(&metadata->pixel_count, sizeof(int), 1, file);

    fclose(file);
    return 0;
}

int process_images(const char* config_file) {
    FILE* config = fopen(config_file, "r");
    if (!config) return -1; // Config file not found or cannot be opened

    int num_images;
    fscanf(config, "%d", &num_images);

    ImageMetadata* metadata_array = (ImageMetadata*)malloc(num_images * sizeof(ImageMetadata));
    if (!metadata_array) {
        fclose(config);
        return -2; // Memory allocation failed
    }

    for (int i = 0; i < num_images; ++i) {
        char filename[256];
        fscanf(config, "%s", filename);
        if (read_image_metadata(filename, &metadata_array[i]) != 0) {
            free(metadata_array);
            fclose(config);
            return -3; // Failed to read metadata for an image
        }
    }

    // Process images based on configuration and metadata
    // ...

    free(metadata_array);
    fclose(config);

    return 0;
}

int main() {
    if (process_images("config.txt") != 0) {
        printf("Failed to process images.\n");
        return 1;
    }
    return 0;
}
```

This code provides a basic structure for reading image metadata from files and processing them based on a configuration file. It includes error handling for file operations, memory allocation, and image metadata reading. The `process_images` function reads the number of images and their filenames from the configuration file, then dynamically allocates an array to store the metadata for each image. It reads the metadata for each image using the `read_image_metadata` function.

Note: This code is a simplified example and does not include advanced features like dynamic loading of additional image formats, error handling for unsupported formats, parallel processing, or logging mechanisms. These features would require more complex implementation and additional libraries/frameworks.']

