#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // 1MB
#define TOTAL_TAG_SIZE_LIMIT 512 * 1024 // 512KB
#define MIN_N 1
#define MAX_N 1000

typedef struct {
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T** allocate_array(int N, int* successful_allocations, int* failed_allocations) {
    if (N < MIN_N || N > MAX_N) {
        printf("Error: Invalid value for N. Must be between %d and %d.\n", MIN_N, MAX_N);
        return NULL;
    }

    time_t t = time(NULL); // Current time
    srand(t);

    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!array) {
        (*failed_allocations)++;
        printf("Error: Failed to allocate memory for array. Reason: Out of memory.\n");
        return NULL;
    }

    size_t total_tag_size = 0;
    int successful_allocs_in_loop = 0;

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            (*failed_allocations)++;
            printf("Error: Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T at index %d. Reason: Out of memory.\n", i);
        } else {
            total_tag_size += sizeof(NFAPI_CRC_INDICATION_PDU_T);
            if (total_tag_size > TOTAL_TAG_SIZE_LIMIT) {
                (*failed_allocations)++;
                printf("Error: Total tag size limit exceeded. Last successful allocation at index %d.\n", successful_allocs_in_loop);
                free(pdu);
                break;
            }
            pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
            array[i] = pdu;
            (*successful_allocations)++;
        }
    }

    if (total_tag_size > TOTAL_TAG_SIZE_LIMIT) {
        for (int i = successful_allocs_in_loop; i < N; i++) {
            free(array[i]);
        }
        free(array);
        return NULL;
    }

    if ((double)total_tag_size / MAX_MEMORY > 0.9) {
        printf("Warning: Allocation size (%zu bytes) is close to maximum allowed memory (%d bytes).\n", total_tag_size, MAX_MEMORY);
    }

    return array;
}

int main() {
    int successful_allocations = 0;
    int failed_allocations = 0;

    NFAPI_CRC_INDICATION_PDU_T** array = allocate_array(500, &successful_allocations, &failed_allocations);

    if (array) {
        printf("Successfully allocated %d elements.\n", successful_allocations);
        // Use the array...

        for (int i = 0; i < successful_allocations; i++) {
            free(array[i]);
        }
        free(array);
    } else {
        printf("Failed to allocate any elements. Total failed allocations: %d\n", failed_allocations);
    }

    return 0;
}
