        new_pdu->CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG

        // Simulate processing or further population of the PDU
        // ...

        actual_count++;
        *created_count += 1;
        pthread_mutex_unlock(mutex);
    }

    *discarded_count = max_limit - actual_count;

    return 0; // Success
}

