    HEADER_BLOCK *headerBlock = NULL;
    size_t totalSize = sizeof(HEADER_BLOCK);

    if (width == 0 || height == 0 || bitCount == 0) {
        // Handle invalid input values
        return NULL;
    }

    headerBlock = (HEADER_BLOCK*)malloc(totalSize);
    if (headerBlock == NULL) {
        // Memory allocation failed
        return NULL;
    }

    headerBlock->headerSize = totalSize;
    headerBlock->numHeaders = 1; // Assuming only one header for simplicity
    headerBlock->totalBitmapFileSize = width * height * bitCount / 8;

    if (headerBlock->totalBitmapFileSize < totalSize) {
        // Potential integer overflow detected
        free(headerBlock);
        return NULL;
    }

    headerBlock->headers[0].biWidth = width;
    headerBlock->headers[0].biHeight = height;
    headerBlock->headers[0].biBitCount = bitCount;

    return headerBlock;
}

void freeBitmapHeaders(HEADER_BLOCK *headerBlock) {
    if (headerBlock != NULL) {
        free(headerBlock);
    }
