    for (int i = 0; i < size; i++) {
        array[i].RNTI = rand() % 65536; // Assuming RNTI is a 16-bit value
        for (int j = 0; j < i; j++) {
            if (array[j].RNTI == array[i].RNTI) {
                i--; // Retry if RNTI is not unique
                break;
            }
        }
    }
    return size;
}

int populate_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T **pdu_array, int N) {
    *pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);

    if (*pdu_array == NULL) {
        perror("Memory allocation failed");
        return -1;
