    for (int i = 0; i < N; i++) {
        (*pdu_array)[i].RX_UE_INFORMATION_TAG = rand() % 65536; // Assuming RX_UE_INFORMATION_TAG is a 16-bit value
        generate_unique_rnti(*pdu_array, i + 1);
