#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct PacketHeader {
    uint16_t headerSize;
    uint32_t payloadSize;
    uint8_t *payload;
    uint32_t checksum;
} PacketHeader;

PacketHeader* process_packets(PacketHeader *headers, size_t packet_count, size_t memory_limit) {
    size_t total_payload_size = 0;
    for (size_t i = 0; i < packet_count; ++i) {
        total_payload_size += headers[i].payloadSize;
    }

    if (total_payload_size > memory_limit) {
        // Handle the case where payload size exceeds available memory
        return NULL;
    }

    PacketHeader *processed_headers = (PacketHeader *)malloc(packet_count * sizeof(PacketHeader));
    if (!processed_headers) {
        return NULL; // Memory allocation failed
    }

    for (size_t i = 0; i < packet_count; ++i) {
        processed_headers[i].headerSize = headers[i].headerSize;
        processed_headers[i].payloadSize = headers[i].payloadSize;

        processed_headers[i].payload = (uint8_t *)realloc(processed_headers[i].payload, headers[i].payloadSize);
        if (!processed_headers[i].payload) {
            // Handle payload reallocation failure
            free(processed_headers);
            return NULL;
        }

        memcpy(processed_headers[i].payload, headers[i].payload, headers[i].payloadSize);

        // Recalculate checksum after processing the payload
        processed_headers[i].checksum = calculate_checksum(processed_headers[i].payload, headers[i].payloadSize);
    }

    return processed_headers;
}

uint32_t calculate_checksum(uint8_t *data, size_t length) {
    uint32_t sum = 0;
    for (size_t i = 0; i < length; ++i) {
        sum += data[i];
    }
    return sum;
}
```

