    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct slab_node {
    NFAPI_CRC_INDICATION_PDU_T data[SLAB_SIZE];
    struct slab_node *next;
} SlabNode;

SlabNode *slab_pool = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* create_nfaapi_pdu() {
    pthread_mutex_lock(&lock);
    if (slab_pool == NULL || slab_pool->data[SLAB_SIZE - 1].ue_info != RX_UE_INFORMATION_TAG_DEFAULT) {
        SlabNode *new_slab = (SlabNode*)malloc(sizeof(SlabNode));
        if (new_slab == NULL) {
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        for (int i = 0; i < SLAB_SIZE; ++i) {
            new_slab->data[i].ue_info = RX_UE_INFORMATION_TAG_DEFAULT;
            // Initialize other fields as needed
        }
        new_slab->next = slab_pool;
        slab_pool = new_slab;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_pdu = &slab_pool->data[SLAB_SIZE - 1];
    --slab_pool->data[SLAB_SIZE - 1].ue_info; // Use as indicator
    pthread_mutex_unlock(&lock);
    return new_pdu;
}

void destroy_nfaapi_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&lock);
    if (pdu == NULL || pdu->ue_info != RX_UE_INFORMATION_TAG_DEFAULT) {
        pthread_mutex_unlock(&lock);
        return;
    }
    // Reset fields as needed
    ++slab_pool->data[SLAB_SIZE - 1].ue_info; // Free the slab
    pthread_mutex_unlock(&lock);
}

void* memory_thread(void *arg) {
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = create_nfaapi_pdu();
        if (pdu == NULL) {
            // Handle allocation failure
            continue;
        }
        // Populate pdu with data
        destroy_nfaapi_pdu(pdu);
    }
    return NULL;
}

int main() {
    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, memory_thread, NULL);
    }

    // Join threads as needed
    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
