#define MAX_DIMENSION 10000
#define MIN_DIMENSION 1

typedef struct {
    int width;
    int height;
    unsigned char *pixel_data;
} ImageData;

ImageData** create_image_array(int rows, int cols, size_t max_size) {
    if (rows < MIN_DIMENSION || rows > MAX_DIMENSION ||
        cols < MIN_DIMENSION || cols > MAX_DIMENSION) {
        fprintf(stderr, "Error: Dimensions out of range.\n");
        return NULL;
    }

    size_t total_elements = (size_t)rows * (size_t)cols;
    if (total_elements == 0 || rows != total_elements / cols) {
        fprintf(stderr, "Error: Integer overflow or zero dimensions.\n");
        return NULL;
    }

    size_t required_memory = total_elements * sizeof(ImageData);
    if (required_memory > max_size) {
        fprintf(stderr, "Error: Insufficient memory available.\n");
        return NULL;
    }

    ImageData **image_array = (ImageData **)malloc(required_memory);
    if (!image_array) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < total_elements; ++i) {
        image_array[i] = (ImageData *)malloc(sizeof(ImageData));
        if (!image_array[i]) {
            fprintf(stderr, "Error: Failed to allocate memory for individual ImageData structure.\n");
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(image_array[j]);
            }
            free(image_array);
            return NULL;
        }

        image_array[i]->width = cols;
        image_array[i]->height = rows;
        image_array[i]->pixel_data = (unsigned char *)malloc(cols * rows * sizeof(unsigned char));
        if (!image_array[i]->pixel_data) {
            fprintf(stderr, "Error: Failed to allocate memory for pixel data.\n");
            // Free previously allocated memory
            for (int j = 0; j <= i; ++j) {
                free(image_array[j]->pixel_data);
                free(image_array[j]);
            }
            free(image_array);
            return NULL;
        }
    }

    return image_array;
}

void destroy_image_array(ImageData **image_array, int rows, int cols) {
    for (int i = 0; i < rows * cols; ++i) {
        free(image_array[i]->pixel_data);
        free(image_array[i]);
    }
    free(image_array);
}
