    for (uint32_t i = 0; i < num_waveforms; ++i) {
        if (waveform_lengths[i] > max_length) {
            max_length = waveform_lengths[i];
        }
    }

    // Dynamically calculate buffer size with bounds checking
    size_t buffer_size = max_length * num_waveforms;
    if (buffer_size / num_waveforms != max_length || buffer_size > UINT32_MAX - 1024) {
        return; // Handle potential integer overflow
    }

    int* processed_buffer = (int*)malloc(buffer_size);
    if (!processed_buffer) {
        return; // Handle memory allocation failure
    }

    for (uint32_t i = 0; i < num_waveforms; ++i) {
        int* waveform = sample_waveforms[i];
        int length = waveform_lengths[i];

        for (int j = 0; j < length; ++j) {
            processed_buffer[j * num_waveforms + i] = waveform[j]; // Process each sample
        }
    }

    // Free the allocated memory
    free(processed_buffer);
}

