#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int width;
    int height;
} ImageMetaData;

typedef struct {
    char filterType[50];
    float intensity;
} ImageFilterSettings;

typedef struct {
    ImageMetaData metadata;
    ImageFilterSettings settings;
} ImageProcessingTask;

typedef struct {
    size_t totalMemory;
    size_t usedMemory;
    pthread_mutex_t memoryLock;
} MemoryManager;

MemoryManager* createMemoryManager(size_t initialMemory) {
    MemoryManager* manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    manager->totalMemory = initialMemory;
    manager->usedMemory = 0;
    pthread_mutex_init(&manager->memoryLock, NULL);
    return manager;
}

int allocateTasks(MemoryManager* manager, size_t numTasks, ImageProcessingTask** tasks) {
    if (!manager || !tasks || numTasks <= 0) {
        fprintf(stderr, "Invalid input.\n");
        return -1;
    }

    pthread_mutex_lock(&manager->memoryLock);
    if (numTasks * sizeof(ImageProcessingTask) + manager->usedMemory > manager->totalMemory) {
        fprintf(stderr, "Insufficient memory available.\n");
        pthread_mutex_unlock(&manager->memoryLock);
        return -2;
    }

    *tasks = (ImageProcessingTask*)malloc(numTasks * sizeof(ImageProcessingTask));
    if (!*tasks) {
        pthread_mutex_unlock(&manager->memoryLock);
        return -3;
    }

    manager->usedMemory += numTasks * sizeof(ImageProcessingTask);
    pthread_mutex_unlock(&manager->memoryLock);
    return 0;
}

void freeTasks(MemoryManager* manager, ImageProcessingTask* tasks, size_t numTasks) {
    if (!manager || !tasks || numTasks <= 0) {
        fprintf(stderr, "Invalid input.\n");
        return;
    }

    pthread_mutex_lock(&manager->memoryLock);
    manager->usedMemory -= numTasks * sizeof(ImageProcessingTask);
    pthread_mutex_unlock(&manager->memoryLock);

    free(tasks);
}

void logMemoryUsage(MemoryManager* manager) {
    if (!manager) {
        fprintf(stderr, "Invalid input.\n");
        return;
    }

    printf("Total Memory: %zu bytes\n", manager->totalMemory);
    printf("Used Memory: %zu bytes\n", manager->usedMemory);
}

int main() {
    MemoryManager* manager = createMemoryManager(1024 * 1024); // 1MB
    if (!manager) {
        fprintf(stderr, "Failed to initialize memory manager.\n");
        return -1;
    }

    ImageProcessingTask* tasks;
    int result = allocateTasks(manager, 5, &tasks);
    if (result == 0) {
        printf("Tasks allocated successfully.\n");
        logMemoryUsage(manager);

        // Use the tasks array...

        freeTasks(manager, tasks, 5);
        printf("Tasks freed successfully.\n");
    } else {
        fprintf(stderr, "Failed to allocate tasks: %d\n", result);
    }

    logMemoryUsage(manager);
    freeManager(manager);
    return 0;
}
