#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <net/if.h>

typedef struct {
    int id;
    char mac[18];
    u_char ip[4];
} NetworkInterface;

int resolveHostname(const char *hostname, u_char **ipAddress) {
    // Use getaddrinfo to resolve the hostname
    struct addrinfo hints, *res, *p;
    int status;
    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // IPv4 only
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return -1; // Resolve error
    }

    p = res;
    struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
    *ipAddress = (u_char *)malloc(sizeof(u_char) * 4);
    if (*ipAddress == NULL) {
        freeaddrinfo(res); // Free the linked list allocated by getaddrinfo
        return -2; // Memory allocation error
    }

    memcpy(*ipAddress, &(ipv4->sin_addr), 4);

    freeaddrinfo(res);
    return 0;
}

NetworkInterface* createNetworkInterface(int id, const char *mac) {
    NetworkInterface *interface = (NetworkInterface *)malloc(sizeof(NetworkInterface));
    if (interface == NULL) {
        return NULL; // Memory allocation error
    }

    interface->id = id;
    strncpy(interface->mac, mac, 17);
    interface->mac[17] = '\0';

    u_char *ipAddress;
    if (resolveHostname("example.com", &ipAddress) == 0) {
        memcpy(interface->ip, ipAddress, 4);
        free(ipAddress);
    } else {
        memset(interface->ip, 0, 4); // Set IP to zero if resolution fails
    }

    return interface;
}

void destroyNetworkInterface(NetworkInterface *interface) {
    free(interface);
}
