// JavaScript Code: Synchronous file reading with fallback to async processing
const fs = require('fs');
const path = require('path');

function readConfigSync(filePath) {
    try {
        const stats = fs.statSync(filePath);
        if (stats.size > 1024 * 1024) { // Example size threshold of 1MB
            return readConfigAsync(filePath);
        }
        return fs.readFileSync(filePath, 'utf8');
    } catch (e) {
        console.error('Error reading file:', e.message);
        return null;
    }
}

function readConfigAsync(filePath) {
    return new Promise((resolve, reject) => {
        fs.readFile(filePath, 'utf8', (err, data) => {
            if (err) {
                console.error('Error reading file async:', err.message);
                reject(err);
            } else {
                resolve(data);
            }
        });
    });
}
