NFAPI_CRC_INDICATION_PDU_T* structure_pool[MAX_STRUCTURES];
int pool_size = 0;
int used_count = 0;

void init_structure_pool(int size) {
    if (size > MAX_STRUCTURES) {
        size = MAX_STRUCTURES;
    }
    for (int i = 0; i < size; i++) {
        structure_pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (structure_pool[i]) {
            pool_size++;
        } else {
            break;
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_structure() {
    if (used_count < pool_size) {
        NFAPI_CRC_INDICATION_PDU_T* new_struct = structure_pool[used_count++];
        new_struct->RX_UE_INFORMATION_TAG = rand();
        new_struct->RNTI = rand();
        new_struct->CRC_INDICATION_REL8_TAG = rand();
        new_struct->CRCFLAG = rand() % 2; // Randomly set to 0 or 1
        return new_struct;
    }
    return NULL;
}

void deallocate_structure(NFAPI_CRC_INDICATION_PDU_T* struct_ptr) {
    for (int i = 0; i < pool_size; i++) {
        if (structure_pool[i] == struct_ptr) {
            structure_pool[i] = NULL;
            used_count--;
            break;
        }
    }
}

void cleanup_structure_pool() {
    for (int i = 0; i < pool_size; i++) {
