#include <pthread.h>
#include <stdlib.h>
#include <time.h>

#define MAX_STRUCTURES 1000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8;
    int is_used;
    time_t last_use_time;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T pool[MAX_STRUCTURES];
int next_available = 0;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_pool() {
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        pool[i].is_used = 0;
        pthread_mutex_lock(&pool_mutex);
        if (rand() % 2 == 0) {
            pool[i].crc_ind_rel8.crcflag = 1;
        } else {
            pool[i].crc_ind_rel8.crcflag = 0;
        }
        pthread_mutex_unlock(&pool_mutex);
    }
}

NFAPI_CRC_INDICATION_PDU_T* get_structure(int requested, int *remaining) {
    pthread_mutex_lock(&pool_mutex);
    if (next_available + requested > MAX_STRUCTURES) {
        requested = MAX_STRUCTURES - next_available;
    }

    NFAPI_CRC_INDICATION_PDU_T* result = malloc(requested * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    int allocated = 0;

    for (int i = 0; i < MAX_STRUCTURES && allocated < requested; i++) {
        if (!pool[i].is_used) {
            pool[i].is_used = 1;
            pool[i].last_use_time = time(NULL);
            result[allocated++] = pool[i];
        }
    }

    *remaining = requested - allocated;
    pthread_mutex_unlock(&pool_mutex);
    return result;
}

void free_structure(NFAPI_CRC_INDICATION_PDU_T* structures, int count) {
    for (int i = 0; i < count; i++) {
        int index = &structures[i] - pool;
        if (index >= 0 && index < MAX_STRUCTURES) {
            pthread_mutex_lock(&pool_mutex);
            pool[index].is_used = 0;
            pthread_mutex_unlock(&pool_mutex);
        }
    }
    free(structures);
}

void report_usage() {
    int allocated = 0;
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        if (pool[i].is_used) {
            allocated++;
        }
    }
    printf("Current usage: %d/%d\n", allocated, MAX_STRUCTURES);
}

void* pool_thread(void* arg) {
    int requested = *(int*)arg;
    int remaining;
    NFAPI_CRC_INDICATION_PDU_T* structures = get_structure(requested, &remaining);
    printf("Allocated %d structures, %d remaining\n", requested - remaining, remaining);

    report_usage();

    // Simulate some work
    sleep(1);

    free_structure(structures, requested - remaining);

    pthread_exit(NULL);
}

int main() {
    srand(time(NULL));
    init_pool();

    pthread_t threads[10];
    int requests[] = {500, 200, 300, 400, 600, 700, 800, 900, 1000, 1100};

    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, pool_thread, &requests[i]);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

This code provides a basic implementation of a structure pool with concurrency handling and resource management. It includes functions to initialize the pool, get structures from the pool, free structures back to the pool, report usage, and simulate concurrent access using threads. The `get_structure` function attempts to reuse existing structures and handles cases where the request exceeds the maximum limit by allocating as many structures as possible. The code also includes mechanisms for memory leak prevention and scalability considerations.']

