    struct SessionNode* next;
} SessionNode;

SessionNode* sessionPool = NULL;
int sessionCount = 0;
int sessionCapacity = INITIAL_SESSION_POOL_CAPACITY;

void initializeSessionPool(int capacity) {
    if (capacity <= 0) return;
    sessionCapacity = capacity;
    sessionPool = (SessionNode*)malloc(capacity * sizeof(SessionNode));
    for (int i = 0; i < capacity; i++) {
        sessionPool[i].accessToken = NULL;
        sessionPool[i].tokenExpiry = 0;
        sessionPool[i].next = &sessionPool[(i + 1) % capacity];
    }
}

void* allocateSession() {
    if (sessionCount >= sessionCapacity) {
        // Implement memory reallocation logic here
        printf("Session pool full, reallocating...\n");
    }
    SessionNode* node = &sessionPool[sessionCount++ % sessionCapacity];
    return node;
}

void freeSession(void* sessionPtr) {
    if (sessionPtr == NULL) return;
    // Implement session deallocation logic here
    printf("Releasing session\n");
    sessionCount--;
}

