    strcpy(*token, "example_access_token");
    *expiryTime = time(NULL) + 3600; // Token expires in 1 hour
    return 0;
}

void refreshAccessTokens() {
    SessionNode* currentNode = sessionPool;
    do {
        if (currentNode->accessToken != NULL && time(NULL) > currentNode->tokenExpiry) {
            free(currentNode->accessToken);
            getOAuthToken(&currentNode->accessToken, &currentNode->tokenExpiry);
        }
        currentNode = currentNode->next;
    } while (currentNode != sessionPool);
}

int main() {
