        pdu->RNTI = rand() % 65535;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 2;

        if (i % 5 == 0) {
            // Example OAuth token refresh
            refreshAccessTokens();
        }
    }

    free(sessionPool);
    return 0;
}
