typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T* pdu_list;
    size_t max_elements;
    size_t allocated_elements;
    size_t successful_allocations;
} NFAPI_PDUDynamicList;

NFAPI_PDUDynamicList* create_pdu_dynamic_list(size_t N) {
    if (N > SIZE_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        log_err("Requested number of elements too large to prevent overflow.");
        return NULL;
    }

    NFAPI_PDUDynamicList* list = malloc(sizeof(NFAPI_PDUDynamicList));
    if (!list) {
        log_err("Failed to allocate memory for dynamic list structure.");
        return NULL;
    }

    list->max_elements = N;
    list->allocated_elements = 0;
    list->successful_allocations = 0;

    pthread_mutex_init(&list->lock, NULL);

    list->pdu_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdu_list) {
        log_err("Failed to allocate memory for PDU list.");
        free(list);
        return NULL;
    }

    return list;
}

void destroy_pdu_dynamic_list(NFAPI_PDUDynamicList* list) {
    pthread_mutex_lock(&list->lock);
    free(list->pdu_list);
    pthread_mutex_unlock(&list->lock);
    free(list);
}

int add_to_pdu_list(NFAPI_PDUDynamicList* list, RX_UE_INFORMATION_TAG ue_info, uint16_t rnti, CRC_INDICATION_REL8_TAG crc_ind) {
    pthread_mutex_lock(&list->lock);

    if (list->allocated_elements >= list->max_elements) {
        log_err("No space available in the PDU list.");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    list->pdu_list[list->allocated_elements].ue_info = ue_info;
    list->pdu_list[list->allocated_elements].rnti = rnti;
    list->pdu_list[list->allocated_elements].crc_ind.crcflag = rand() % 2; // Randomly set CRCFLAG
    list->allocated_elements++;
    list->successful_allocations++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}
