#include <stdio.h>
#include <stdlib.h>

typedef struct PacketHeader {
    int size;
    char payloadType;
} PacketHeader;

PacketHeader* process_packets(int packet_count, ...) {
    va_list args;
    va_start(args, packet_count);

    // Initialize variables for memory allocation
    int total_size = 0;
    int max_packet_size = 1460; // Example maximum packet size

    // Calculate the total required memory safely to avoid overflow
    if (__builtin_mul_overflow(packet_count, sizeof(PacketHeader), &total_size) ||
        __builtin_add_overflow(total_size, packet_count * max_packet_size, &total_size)) {
        va_end(args);
        return NULL; // Memory allocation failed due to potential overflow
    }

    // Dynamically allocate memory for packet headers and payloads
    PacketHeader* packets = (PacketHeader*)malloc(total_size);
    if (!packets) {
        va_end(args);
        return NULL; // Memory allocation failed
    }

    // Populate the allocated memory with packet headers and payloads
    int offset = 0;
    for (int i = 0; i < packet_count; i++) {
        PacketHeader* current_packet = (PacketHeader*)((char*)packets + offset);
        current_packet->size = va_arg(args, int);
        if (current_packet->size > max_packet_size) {
            free(packets);
            va_end(args);
            return NULL; // Invalid packet size
        }
        current_packet->payloadType = va_arg(args, char);
        offset += sizeof(PacketHeader) + current_packet->size;
    }

    va_end(args);
    return packets;
}

int main() {
    PacketHeader* packets = process_packets(3, 100, 'A', 200, 'B', 150, 'C');
    if (packets != NULL) {
        for (int i = 0; i < 3; i++) {
            printf("Packet %d: Size %d, Payload Type %c\n", i, packets[i].size, packets[i].payloadType);
        }
        free(packets);
    } else {
        printf("Failed to process packets.\n");
    }
    return 0;
}
