    ImageMetadata *head;
    int current_nodes;
    pthread_mutex_t lock;
} ImageProcessor;

void init_image_processor(ImageProcessor *processor) {
    processor->head = NULL;
    processor->current_nodes = 0;
    pthread_mutex_init(&processor->lock, NULL);
}

ImageMetadata* create_image_metadata(int width, int height, const char *file_path) {
    ImageMetadata *new_node = (ImageMetadata*)malloc(sizeof(ImageMetadata));
    if (new_node == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }
    new_node->width = width;
    new_node->height = height;
    strncpy(new_node->file_path, file_path, sizeof(new_node->file_path));
    new_node->next = NULL;
    return new_node;
}

void insert_image_metadata(ImageProcessor *processor, ImageMetadata *new_node) {
    pthread_mutex_lock(&processor->lock);
    if (processor->current_nodes < MAX_NODES) {
        if (processor->head == NULL) {
            processor->head = new_node;
        } else {
            ImageMetadata *temp = processor->head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = new_node;
        }
        processor->current_nodes++;
    } else {
        printf("Maximum nodes reached, cannot insert more\n");
        free(new_node);
    }
    pthread_mutex_unlock(&processor->lock);
}

