    ImageProcessor *processor = (ImageProcessor*)arg;
    while (1) {
        pthread_mutex_lock(&processor->lock);
        if (processor->current_nodes > 0) {
            ImageMetadata *image_to_process = processor->head;
            processor->head = image_to_process->next;
            processor->current_nodes--;
            pthread_mutex_unlock(&processor->lock);

            if (validate_image(image_to_process) == 0) {
                printf("Processed image: %s\n", image_to_process->file_path);
            } else {
                printf("Failed to validate image: %s\n", image_to_process->file_path);
            }

            free(image_to_process);
        } else {
            pthread_mutex_unlock(&processor->lock);
            usleep(API_REQUEST_DELAY); // Simulate API request delay
        }
    }
    return NULL;
}

int main() {
