    init_image_processor(&processor);

    // Example usage
    insert_image_metadata(&processor, create_image_metadata(1920, 1080, "path/to/image1.jpg"));
    insert_image_metadata(&processor, create_image_metadata(800, 600, "path/to/image2.png"));

