typedef struct {
    int length;
    time_t timestamp;
    char source_ip[16];
} PacketMetadata;

#define MAX_PACKETS 1000
#define MAX_PACKET_SIZE 1400
#define MAX_LOG_FILE_SIZE 1024 * 1024 * 10 // 10MB
#define LOG_FILE_PREFIX "packet_log_"
#define LOG_FILE_DATE_FORMAT "%Y%m%d"

typedef enum {
    STATUS_SUCCESS,
    STATUS_MEM_ALLOCATION_FAILED,
    STATUS_EXCESSIVE_PACKET_COUNT,
    STATUS_EXCESSIVE_PACKET_SIZE,
    STATUS_LOG_FILE_ERROR
} Status;

Status process_packets(int packet_count, PacketMetadata packets[], int max_packet_length) {
    if (packet_count > MAX_PACKETS || packet_count < 0) {
        return STATUS_EXCESSIVE_PACKET_COUNT;
    }

    for (int i = 0; i < packet_count; i++) {
        if (packets[i].length > max_packet_length || packets[i].length <= 0) {
            return STATUS_EXCESSIVE_PACKET_SIZE;
        }
    }

    // Allocate memory for the structure
    PacketMetadata *packet_metadata = malloc(packet_count * sizeof(PacketMetadata));
    if (packet_metadata == NULL) {
        return STATUS_MEM_ALLOCATION_FAILED;
    }

    // Copy packet metadata to the allocated memory
    memcpy(packet_metadata, packets, packet_count * sizeof(PacketMetadata));

    // Log metadata to a file with daily rotation and max size limit
    time_t now = time(NULL);
    char log_file_name[100];
    strftime(log_file_name, 100, LOG_FILE_PREFIX "%Y%m%d" ".log", localtime(&now));

    FILE *log_file = fopen(log_file_name, "a");
    if (log_file == NULL) {
        free(packet_metadata);
        return STATUS_LOG_FILE_ERROR;
    }

    off_t current_size = ftello(log_file);
    if (current_size > MAX_LOG_FILE_SIZE) {
        fclose(log_file);
        remove(log_file_name);

        time_t previous_day = now - 86400; // 1 day in seconds
        strftime(log_file_name, 100, LOG_FILE_PREFIX "%Y%m%d" ".log", localtime(&previous_day));
        rename(log_file_name, log_file_name);
    }

    for (int i = 0; i < packet_count; i++) {
        fprintf(log_file, "Length: %d, Timestamp: %ld, Source IP: %s\n",
                packet_metadata[i].length, packet_metadata[i].timestamp, packet_metadata[i].source_ip);
    }

    fclose(log_file);
    free(packet_metadata);

    return STATUS_SUCCESS;
}
