// Function to create a new network header
NetworkHeader* create_header(int type, int length) {
    NetworkHeader* new_header = (NetworkHeader*)malloc(sizeof(NetworkHeader));
    if (new_header == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_header->header_type = type;
    new_header->payload_length = length;
    new_header->next = NULL;
    return new_header;
}

// Function to add a header to the packet
void add_header(NetworkHeader** packet_head, int type, int length) {
    NetworkHeader* new_header = create_header(type, length);
    if (*packet_head == NULL) {
        *packet_head = new_header;
    } else {
        NetworkHeader* temp = *packet_head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_header;
    }
}

// Function to process packets and create linked list of headers
void process_packets(NetworkHeader** packet_list, int packet_count, int header_max) {
    for (int i = 0; i < packet_count; i++) {
        NetworkHeader* current_packet_head = NULL;
        int actual_headers = (rand() % header_max) + 1; // Simulate variable number of headers
        for (int j = 0; j < actual_headers; j++) {
            int random_type = rand() % 10; // Simulate different types of headers
            int random_length = rand() % 1000; // Simulate varying payload lengths
            add_header(&current_packet_head, random_type, random_length);
        }
        if (*packet_list == NULL) {
            *packet_list = current_packet_head;
        } else {
            NetworkHeader* temp = *packet_list;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = current_packet_head;
        }
    }
}

// Function to free memory allocated for the linked list
void free_headers(NetworkHeader* head) {
    while (head != NULL) {
        NetworkHeader* next = head->next;
        free(head);
        head = next;
    }
}

int main() {
    srand(time(0));
    NetworkHeader* packet_list = NULL;

    // Example usage of the function
    int packet_count = 100; // Simulated number of packets to process
    int header_max = 50;   // Maximum headers per packet

    process_packets(&packet_list, packet_count, header_max);

    // Free allocated memory
    free_headers(packet_list);

    return 0;
}
