} ImageMetadata;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

NFAPI_CRC_INDICATION_PDU_T** create_crc_ind_pdu_list(int N, int chunk_size) {
    NFAPI_CRC_INDICATION_PDU_T** list = safe_malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (int i = 0; i < N; i += chunk_size) {
        size_t allocate_count = chunk_size;
        if (i + chunk_size > N) {
            allocate_count = N - i;
        }
        list[i] = safe_malloc(allocate_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    return list;
}

ImageMetadata* read_image_metadata(const char* config_file, int* total_images) {
    FILE* fp = fopen(config_file, "r");
    if (!fp) {
        perror("Failed to open configuration file");
        exit(EXIT_FAILURE);
    }

    fscanf(fp, "%d", total_images);

    ImageMetadata* metadata = safe_malloc(*total_images * sizeof(ImageMetadata));
    for (int i = 0; i < *total_images; ++i) {
        if (fscanf(fp, "%255s %d %d", metadata[i].filename, &metadata[i].width, &metadata[i].height) != 3) {
            fprintf(stderr, "Error reading image metadata\n");
            exit(EXIT_FAILURE);
        }
        metadata[i].pixel_count = (size_t)metadata[i].width * metadata[i].height;
    }

    fclose(fp);
    return metadata;
}

