#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PACKET_SIZE 1500
#define LOG_ENTRY_LIMIT 1024
#define BATCH_SIZE 100

typedef struct {
    char header[64];
    int payload_length;
    unsigned int packet_id;
    time_t timestamp;
} PacketData;

typedef struct {
    char buffer[LOG_ENTRY_LIMIT];
    int length;
} LogEntry;

void log_message(LogEntry *log, const char *message) {
    if (strlen(message) + log->length > LOG_ENTRY_LIMIT) {
        // Split message into smaller segments
        int start = 0;
        while (start < strlen(message)) {
            int end = start + LOG_ENTRY_LIMIT - 1;
            if (end >= strlen(message))
                end = strlen(message) - 1;

            strncpy(log->buffer, message + start, end - start + 1);
            log->buffer[end - start + 1] = '\0';
            // Log the segment
            printf("Log: %s\n", log->buffer);

            start = end + 1;
        }
    } else {
        strcpy(log->buffer, message);
        log->length = strlen(message);
        printf("Log: %s\n", log->buffer);
    }
}

unsigned int calculate_checksum(const char *data, size_t length) {
    // Custom checksum algorithm
    unsigned int sum = 0;
    for (size_t i = 0; i < length; ++i) {
        sum += data[i];
    }
    return sum % 1000; // Simplified for example purposes
}

void process_packets(const char *stream, size_t stream_length, PacketData **packet_array, int *num_packets) {
    *num_packets = 0;
    size_t offset = 0;

    while (offset < stream_length) {
        if ((offset + MAX_PACKET_SIZE) > stream_length)
            break; // Not enough data for a full packet

        PacketData packet;
        memcpy(packet.header, stream + offset, sizeof(char[64]));
        packet.payload_length = *(int *)(stream + offset + 64);
        packet.packet_id = *(unsigned int *)(stream + offset + 68);
        packet.timestamp = *(time_t *)(stream + offset + 72);

        if (packet.payload_length > MAX_PACKET_SIZE) {
            log_message(&log_entry, "Invalid payload length detected");
            offset += 76; // Skip invalid packet
            continue;
        }

        unsigned int calculated_checksum = calculate_checksum(stream + offset, sizeof(char[64]) + 8 + packet.payload_length);
        if (calculated_checksum != *(unsigned int *)(stream + offset + 68 + packet.payload_length)) {
            log_message(&log_entry, "Checksum mismatch detected");
            offset += 72 + packet.payload_length; // Skip invalid packet
            continue;
        }

        *packet_array = realloc(*packet_array, (*num_packets + 1) * sizeof(PacketData));
        if (*packet_array == NULL) {
            log_message(&log_entry, "Memory allocation failed");
            break;
        }

        memcpy((*packet_array)[*num_packets].header, packet.header, sizeof(char[64]));
        (*packet_array)[*num_packets].payload_length = packet.payload_length;
        (*packet_array)[*num_packets].packet_id = packet.packet_id;
        (*packet_array)[*num_packets].timestamp = packet.timestamp;

        *num_packets += 1;
        offset += 72 + packet.payload_length; // Move to next packet
    }
}

void process_packet_batch(const char *stream, size_t stream_length) {
    PacketData *packet_array = NULL;
    int num_packets = 0;

    process_packets(stream, stream_length, &packet_array, &num_packets);

    printf("Processed %d packets\n", num_packets);
    printf("Valid packets: %d\n", num_packets);
    printf("Discarded packets: 0\n");

    free(packet_array);
}

int main() {
    const char *network_stream = "..."; // Simulated network stream
    size_t stream_length = strlen(network_stream);

    for (int i = 0; i < BATCH_SIZE; ++i) {
        process_packet_batch(network_stream, stream_length);
    }

    return 0;
}
