#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int header_length;
    char* payload;
    int payload_length;
} PacketData;

typedef struct {
    int* resources;
    int resource_count;
} ResourcePool;

typedef struct {
    PacketData** packets;
    int packet_count;
    pthread_mutex_t mutex;
} NetworkProcessor;

NetworkProcessor* create_network_processor() {
    NetworkProcessor* processor = (NetworkProcessor*)malloc(sizeof(NetworkProcessor));
    if (processor == NULL) {
        return NULL; // Handle memory allocation failure
    }
    processor->packets = NULL;
    processor->packet_count = 0;
    pthread_mutex_init(&processor->mutex, NULL);
    return processor;
}

void destroy_network_processor(NetworkProcessor* processor) {
    for (int i = 0; i < processor->packet_count; i++) {
        free(processor->packets[i]->payload);
        free(processor->packets[i]);
    }
    free(processor->packets);
    pthread_mutex_destroy(&processor->mutex);
    free(processor);
}

void add_packet(NetworkProcessor* processor, int header_length, char* payload, int payload_length) {
    PacketData* packet = (PacketData*)malloc(sizeof(PacketData));
    if (packet == NULL) {
        return; // Handle memory allocation failure
    }
    packet->header_length = header_length;
    packet->payload = (char*)malloc(payload_length * sizeof(char));
    if (packet->payload == NULL) {
        free(packet);
        return; // Handle memory allocation failure
    }
    memcpy(packet->payload, payload, payload_length);
    packet->payload_length = payload_length;

    pthread_mutex_lock(&processor->mutex);
    processor->packets = (PacketData**)realloc(processor->packets, (processor->packet_count + 1) * sizeof(PacketData*));
    if (processor->packets == NULL) {
        free(packet->payload);
        free(packet);
        pthread_mutex_unlock(&processor->mutex);
        return; // Handle memory allocation failure
    }
    processor->packets[processor->packet_count] = packet;
    processor->packet_count++;
    pthread_mutex_unlock(&processor->mutex);
}

int update_resource_pool(NetworkProcessor* processor, ResourcePool* resource_pool) {
    pthread_mutex_lock(&processor->mutex);
    for (int i = 0; i < processor->packet_count; i++) {
        if (i < resource_pool->resource_count) {
            processor->packets[i]->payload[0] = resource_pool->resources[i];
        } else {
            break; // Not enough resources for all packets
        }
    }
    pthread_mutex_unlock(&processor->mutex);
    return 0;
}

int main() {
    NetworkProcessor* processor = create_network_processor();
    if (processor == NULL) {
        fprintf(stderr, "Failed to create network processor\n");
        return 1;
    }

    ResourcePool resource_pool = { .resources = (int[]){1, 2, 3}, .resource_count = 3 };

    add_packet(processor, 4, "Packet1", 7);
    add_packet(processor, 5, "Packet2", 7);

    update_resource_pool(processor, &resource_pool);

    destroy_network_processor(processor);
    return 0;
}
