#define MAX_MESSAGE_SIZE 1024
#define MIN_BUFFER_SIZE 64

typedef struct {
    void* data;
    size_t size;
} buffer_t;

typedef struct {
    buffer_t payload;
    int metadata[5];
} NFapiMessage_t;

NFapiMessage_t** allocate_buffer(size_t num_messages, size_t max_total_size) {
    if (num_messages == 0 || max_total_size == 0) {
        return NULL; // Invalid input
    }

    size_t required_size = num_messages * sizeof(NFapiMessage_t);
    if (required_size > max_total_size || required_size / num_messages != sizeof(NFapiMessage_t)) {
        return NULL; // Integer overflow or too many messages for the limit
    }

    NFapiMessage_t** buffer = (NFapiMessage_t**)malloc(num_messages * sizeof(NFapiMessage_t*));
    if (!buffer) {
        return NULL; // Memory allocation failed
    }

    size_t total_allocated_size = 0;
    for (size_t i = 0; i < num_messages; ++i) {
        buffer[i] = (NFapiMessage_t*)malloc(sizeof(NFapiMessage_t));
        if (!buffer[i]) {
            free_buffer(buffer, i);
            return NULL; // Memory allocation failed
        }

        // Initialize payload buffer
        buffer[i]->payload.data = malloc(MAX_MESSAGE_SIZE * sizeof(uint8_t));
        if (!buffer[i]->payload.data) {
            free_buffer(buffer, i + 1);
            return NULL; // Memory allocation failed
        }
        buffer[i]->payload.size = MIN_BUFFER_SIZE;

        total_allocated_size += sizeof(NFapiMessage_t) + MAX_MESSAGE_SIZE;
        if (total_allocated_size > max_total_size) {
            free_buffer(buffer, i + 1);
            return NULL; // Exceeded the maximum limit
        }
    }

    return buffer;
}

void free_buffer(NFapiMessage_t** buffer, size_t num_messages) {
    for (size_t i = 0; i < num_messages; ++i) {
        if (buffer[i]) {
            free(buffer[i]->payload.data);
            free(buffer[i]);
        }
    }
    free(buffer);
}

void initialize_buffer(NFapiMessage_t** buffer, size_t num_messages, uint8_t* payload_data, size_t data_size) {
    for (size_t i = 0; i < num_messages && i * MAX_MESSAGE_SIZE < data_size; ++i) {
        memcpy(buffer[i]->payload.data, payload_data + i * MAX_MESSAGE_SIZE, MIN(data_size - i * MAX_MESSAGE_SIZE, MAX_MESSAGE_SIZE));
        buffer[i]->payload.size = MIN(data_size - i * MAX_MESSAGE_SIZE, MAX_MESSAGE_SIZE);
    }
}

void print_buffer(NFapiMessage_t** buffer, size_t num_messages) {
    for (size_t i = 0; i < num_messages; ++i) {
        printf("Message %zu: Payload Size %zu\n", i, buffer[i]->payload.size);
    }
}
