int allocate_and_populate_array(size_t max_elements, float packet_loss_prob, int timeout_ms, int max_memory) {
    srand(time(NULL));
    size_t total_allocated = 0;
    size_t lost_due_to_loss = 0;
    size_t lost_due_to_timeout = 0;
