            void *new_array = realloc(allocation_context.array, (allocation_context.allocated_size + MAX_PACKET_SIZE) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_array) {
                memory_allocation_errors++;
                break;
            }
            allocation_context.array = new_array;
            allocation_context.allocated_size += MAX_PACKET_SIZE;
        }

        allocation_context.array[allocation_context.used_count++] = new_struct;
        total_allocated++;

