#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

typedef struct {
    char payload[1024];
    int metadata;
} NFapiMessage_t;

typedef struct {
    u_char ip_address[4];
    // Other buffer-related fields if needed
} buffer_t;

int resolve_hostname(const char *hostname, u_char ip_address[]) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        memcpy(ip_address, &(ipv4->sin_addr), sizeof ipv4->sin_addr);
    }

    freeaddrinfo(res); // free the linked list
    return 0;
}

NFapiMessage_t* allocate_buffer(int num_messages, size_t max_size) {
    size_t total_size = num_messages * (sizeof(NFapiMessage_t));
    if (total_size > max_size) {
        fprintf(stderr, "Requested size exceeds maximum limit.\n");
        return NULL;
    }

    NFapiMessage_t* buffer = (NFapiMessage_t*)malloc(total_size);
    if (buffer == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    // Initialize each message in the buffer
    for (int i = 0; i < num_messages; i++) {
        memset(&buffer[i], 0, sizeof(NFapiMessage_t));
    }

    return buffer;
}

void free_buffer(NFapiMessage_t* buffer) {
    if (buffer != NULL) {
        free(buffer);
    }
}

int main() {
    const char *hostname = "example.com";
    u_char ip_address[4];
    if (resolve_hostname(hostname, ip_address) == 0) {
        printf("IP address for %s: %d.%d.%d.%d\n",
               hostname,
               ip_address[0], ip_address[1],
               ip_address[2], ip_address[3]);
    }

    int num_messages = 10;
    size_t max_size = 8192; // 8 KB
    NFapiMessage_t* buffer = allocate_buffer(num_messages, max_size);
    if (buffer != NULL) {
        printf("Buffer allocated successfully for %d messages.\n", num_messages);
        free_buffer(buffer);
    }

    return 0;
}
