    int buffer_size;
    int used_space;
    char *buffer;
    pthread_mutex_t mutex;
} BufferManager;

BufferManager *initialize_buffer_manager() {
    BufferManager *manager = (BufferManager *)malloc(sizeof(BufferManager));
    if (!manager) {
        fprintf(stderr, "Memory allocation failed for buffer manager\n");
        return NULL;
    }
    manager->buffer_size = INITIAL_BUFFER_SIZE;
    manager->used_space = 0;
    manager->buffer = (char *)malloc(INITIAL_BUFFER_SIZE);
    if (!manager->buffer) {
        fprintf(stderr, "Memory allocation failed for buffer\n");
        free(manager);
        return NULL;
    }
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void process_packet(BufferManager *manager, Packet *packet) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->used_space + packet->size > manager->buffer_size) {
        // Handle buffer overflow
        fprintf(stderr, "Buffer overflow detected\n");
    } else {
        memcpy(manager->buffer + manager->used_space, packet->data, packet->size);
        manager->used_space += packet->size;
    }
    pthread_mutex_unlock(&manager->mutex);
}

void free_buffer_manager(BufferManager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->mutex);
        free(manager->buffer);
        free(manager);
    }
}
```

