int allocate_image_array(int width, int height, size_t max_size, ImageData** array) {
    size_t element_size = sizeof(ImageData) + (width * height);
    if (element_size > SIZE_MAX / width) {
        // Handle integer overflow
        return -1;
    }

    size_t required_size = element_size * height;
    if (required_size > max_size) {
        // Memory exceeds maximum allowed size
        return -2;
    }

    *array = (ImageData*)malloc(required_size);
    if (*array == NULL) {
        // Memory allocation failed
        return -3;
    }

    for (int i = 0; i < height; i++) {
        (*array)[i].width = width;
        (*array)[i].height = height;
        (*array)[i].pixel_data = (unsigned char*)malloc(width * height);
        if ((*array)[i].pixel_data == NULL) {
            // Pixel data allocation failed
            for (int j = 0; j < i; j++) {
                free((*array)[j].pixel_data);
            }
            free(*array);
            return -3;
        }
    }

    return 0;
}

void free_image_array(ImageData* array, int height) {
    for (int i = 0; i < height; i++) {
        free(array[i].pixel_data);
    }
    free(array);
}
