#define MAX_THREADS 16

typedef struct {
    int x;
    int y;
    int width;
    int height;
    int color[3]; // RGB
} ROI;

typedef struct {
    char* filename;
    ROI* rois;
    size_t num_rois;
} ImageFile;

pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t pool_not_full = PTHREAD_COND_INITIALIZER;
pthread_cond_t pool_not_empty = PTHREAD_COND_INITIALIZER;
ImageFile** file_queue = NULL;
size_t queue_size = 0;
size_t max_queue_size;
size_t num_threads;
int memory_limit_per_thread;

void* process_image(void* arg) {
    while (1) {
        pthread_mutex_lock(&pool_mutex);
        while (queue_size == 0) {
            pthread_cond_wait(&pool_not_empty, &pool_mutex);
        }

        ImageFile* file = file_queue[--queue_size];
        pthread_cond_signal(&pool_not_full);
        pthread_mutex_unlock(&pool_mutex);

        // Process ROIs in the image file
        for (size_t i = 0; i < file->num_rois; ++i) {
            ROI roi = file->rois[i];
            // Perform analysis on the ROI
        }

        free(file->rois);
        free(file);
    }
}

void init_thread_pool(size_t max_queue_size, int num_threads, int memory_limit_per_thread) {
    file_queue = (ImageFile**)malloc(max_queue_size * sizeof(ImageFile*));
    queue_size = 0;
    this->max_queue_size = max_queue_size;
    this->num_threads = num_threads;
    this->memory_limit_per_thread = memory_limit_per_thread;

    pthread_t threads[MAX_THREADS];
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, process_image, NULL);
    }

    // Wait for all threads to finish initialization
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void enqueue_file(ImageFile* file) {
    pthread_mutex_lock(&pool_mutex);
    while (queue_size == max_queue_size) {
        pthread_cond_wait(&pool_not_full, &pool_mutex);
    }

    file_queue[queue_size++] = file;
    pthread_cond_signal(&pool_not_empty);
    pthread_mutex_unlock(&pool_mutex);
}

void cleanup_thread_pool() {
    pthread_mutex_lock(&pool_mutex);
    while (queue_size > 0) {
        ImageFile* file = file_queue[--queue_size];
        free(file->rois);
        free(file);
    }
    pthread_mutex_unlock(&pool_mutex);

    // Wait for all threads to finish
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(file_queue);
}

int main(int argc, char* argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <max_queue_size> <num_threads> <memory_limit_per_thread>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t max_queue_size = atoi(argv[1]);
    int num_threads = atoi(argv[2]);
    memory_limit_per_thread = atoi(argv[3]);

    if (max_queue_size == 0 || num_threads <= 0 || memory_limit_per_thread < 0) {
        fprintf(stderr, "Invalid input arguments.\n");
        return EXIT_FAILURE;
    }

    init_thread_pool(max_queue_size, num_threads, memory_limit_per_thread);

    // Example usage
    ImageFile file1 = { .filename = "image1.jpg", .num_rois = 2 };
    file1.rois = (ROI*)malloc(file1.num_rois * sizeof(ROI));
    // Initialize ROIs for file1

    enqueue_file(&file1);

    cleanup_thread_pool();

    return EXIT_SUCCESS;
}
