#define MAX_FILES 100
#define MAX_ROIS 1000

typedef struct {
    int x;
    int y;
    int width;
    int height;
    int color[3]; // RGB values
} ROI;

typedef struct {
    FILE *file;
    ROI **rois;
    int roi_count;
} ImageData;

void* process_image(void* arg) {
    ImageData* data = (ImageData*)arg;
    for (int i = 0; i < data->roi_count; ++i) {
        // Process each ROI in the image
        printf("Processing ROI %d from file %p\n", i, data);
    }
    pthread_exit(NULL);
}

void process_images(int argc, char* argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <num_files> <total_rois>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    int num_files = atoi(argv[1]);
    int total_rois = atoi(argv[2]);

    pthread_t threads[MAX_FILES];
    ImageData data[MAX_FILES];

    for (int i = 0; i < num_files; ++i) {
        char filename[256];
        snprintf(filename, sizeof(filename), "image%d.jpg", i);

        FILE *file = fopen(filename, "r");
        if (!file) {
            fprintf(stderr, "Failed to open file %s\n", filename);
            continue;
        }

        data[i].file = file;
        data[i].rois = (ROI**)malloc(sizeof(ROI*) * MAX_ROIS);
        data[i].roi_count = 0;

        // Simulate reading ROIs from the file
        for (int j = 0; j < MAX_ROIS; ++j) {
            ROI* roi = (ROI*)malloc(sizeof(ROI));
            // Initialize ROI with data read from file
            data[i].rois[data[i].roi_count++] = roi;
        }

        if (pthread_create(&threads[i], NULL, process_image, &data[i]) != 0) {
            fprintf(stderr, "Failed to create thread for file %s\n", filename);
            fclose(file);
            for (int j = 0; j < data[i].roi_count; ++j) free(data[i].rois[j]);
            free(data[i].rois);
        }
    }

    for (int i = 0; i < num_files; ++i) {
        pthread_join(threads[i], NULL);
        fclose(data[i].file);
        for (int j = 0; j < data[i].roi_count; ++j) free(data[i].rois[j]);
        free(data[i].rois);
    }
}

int main(int argc, char* argv[]) {
    process_images(argc, argv);
    return 0;
}
