#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    char sourceIP[16];
    char destinationIP[16];
    unsigned int checksum;
} PacketHeaderInfo;

typedef struct {
    PacketHeaderInfo *headers;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketBuffer;

PacketBuffer* create_packet_buffer(size_t initial_capacity) {
    PacketBuffer *buffer = malloc(sizeof(PacketBuffer));
    if (buffer == NULL) {
        perror("Failed to allocate memory for packet buffer");
        return NULL;
    }
    buffer->headers = malloc(initial_capacity * sizeof(PacketHeaderInfo));
    if (buffer->headers == NULL) {
        perror("Failed to allocate memory for packet headers");
        free(buffer);
        return NULL;
    }
    buffer->count = 0;
    buffer->capacity = initial_capacity;
    pthread_mutex_init(&buffer->lock, NULL);
    return buffer;
}

void destroy_packet_buffer(PacketBuffer *buffer) {
    if (buffer != NULL) {
        free(buffer->headers);
        free(buffer);
    }
}

int add_packet_header(PacketBuffer *buffer, PacketHeaderInfo header) {
    pthread_mutex_lock(&buffer->lock);
    if (buffer->count >= buffer->capacity) {
        size_t new_capacity = buffer->capacity == 0 ? 1 : buffer->capacity * 2;
        PacketHeaderInfo *new_headers = realloc(buffer->headers, new_capacity * sizeof(PacketHeaderInfo));
        if (new_headers == NULL) {
            perror("Failed to reallocate memory for packet headers");
            pthread_mutex_unlock(&buffer->lock);
            return -1;
        }
        buffer->headers = new_headers;
        buffer->capacity = new_capacity;
    }
    buffer->headers[buffer->count++] = header;
    pthread_mutex_unlock(&buffer->lock);
    return 0;
}

void process_network_packets(PacketBuffer *buffer, const char *network_data, size_t data_length) {
    // Simulate processing network packets
    for (size_t i = 0; i < data_length; ++i) {
        PacketHeaderInfo header;
        // Extract packet information from network_data
        // ...
        if (add_packet_header(buffer, header) != 0) {
            fprintf(stderr, "Failed to add packet header\n");
        }
    }
}

int main() {
    PacketBuffer *buffer = create_packet_buffer(10);
    if (buffer == NULL) {
        return EXIT_FAILURE;
    }

    // Simulate receiving network data
    const char *network_data = "..."; // Replace with actual network data
    size_t data_length = strlen(network_data);
    process_network_packets(buffer, network_data, data_length);

    destroy_packet_buffer(buffer);
    return EXIT_SUCCESS;
}
