#include <stdlib.h>
#include <stdint.h>
#include <string.h>

typedef struct PacketInfo {
    uint32_t id;
    uint64_t timestamp;
    size_t length;
    void* payload;
} PacketInfo;

typedef struct PacketQueue {
    PacketInfo** packets;
    size_t front;
    size_t rear;
    size_t capacity;
    size_t size;
    size_t totalSize;
} PacketQueue;

PacketQueue* createPacketQueue(size_t initialCapacity, size_t maxMemory) {
    PacketQueue* queue = (PacketQueue*)malloc(sizeof(PacketQueue));
    if (!queue) return NULL;

    queue->packets = (PacketInfo**)malloc(initialCapacity * sizeof(PacketInfo*));
    if (!queue->packets) {
        free(queue);
        return NULL;
    }

    queue->front = 0;
    queue->rear = -1;
    queue->capacity = initialCapacity;
    queue->size = 0;
    queue->totalSize = 0;
    queue->maxMemory = maxMemory;

    return queue;
}

void destroyPacketQueue(PacketQueue* queue) {
    for (size_t i = 0; i < queue->size; ++i) {
        free(queue->packets[(queue->front + i) % queue->capacity]->payload);
        free(queue->packets[(queue->front + i) % queue->capacity]);
    }
    free(queue->packets);
    free(queue);
}

int enqueuePacket(PacketQueue* queue, PacketInfo* packet) {
    if (queue->size == queue->capacity) {
        size_t newCapacity = queue->capacity * 2;
        PacketInfo** newPackets = (PacketInfo**)realloc(queue->packets, newCapacity * sizeof(PacketInfo*));
        if (!newPackets) return -1;
        memcpy(newPackets + queue->capacity, queue->packets, queue->size * sizeof(PacketInfo*));
        free(queue->packets);
        queue->packets = newPackets;
        queue->front = 0;
        queue->rear = queue->size - 1;
        queue->capacity = newCapacity;
    }

    size_t newSize = packet->length + sizeof(PacketInfo);
    if (queue->totalSize + newSize > queue->maxMemory) {
        return -1; // Memory limit exceeded
    }

    queue->rear = (queue->rear + 1) % queue->capacity;
    queue->packets[queue->rear] = packet;
    queue->size++;
    queue->totalSize += newSize;

    return 0;
}

PacketInfo* dequeuePacket(PacketQueue* queue) {
    if (queue->size == 0) return NULL;

    PacketInfo* packet = queue->packets[queue->front];
    queue->front = (queue->front + 1) % queue->capacity;
    queue->size--;
    queue->totalSize -= packet->length + sizeof(PacketInfo);

    return packet;
}
