    NFAPI_CRC_INDICATION_PDU_T *pdu;
} PacketQueueEntry;

typedef struct {
    PacketQueueEntry *queue;
    size_t capacity;
    size_t front;
    size_t rear;
    size_t count;
    size_t total_allocated_memory;
    size_t memory_limit;
} PacketQueue;

void initialize_queue(PacketQueue *q, size_t limit) {
    q->memory_limit = limit;
    q->total_allocated_memory = 0;
    q->capacity = 1; // Start with a small capacity and grow as needed
    q->queue = malloc(q->capacity * sizeof(PacketQueueEntry));
    q->front = q->rear = q->count = 0;
}

void enqueue_packet(PacketQueue *q, PacketInfo info, size_t payload_size) {
    if (q->total_allocated_memory + payload_size > q->memory_limit) {
        // Handle memory limit exceeded scenario
        return;
    }

    if ((q->rear + 1) % q->capacity == q->front) {
        // Resize the queue
        PacketQueueEntry *new_queue = realloc(q->queue, q->capacity * 2 * sizeof(PacketQueueEntry));
        if (new_queue == NULL) {
            // Handle memory allocation failure
            return;
        }
        q->queue = new_queue;

        for (size_t i = q->front; i < q->rear + 1; ++i) {
            q->queue[i].packet_info = malloc(sizeof(PacketInfo));
            q->queue[i].pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            // Initialize packet_info and pdu
        }

        q->capacity *= 2;
    }

    q->queue[q->rear].packet_info = malloc(sizeof(PacketInfo));
    q->queue[q->rear].pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    *q->queue[q->rear].packet_info = info;

    // Initialize pdu fields with valid values
    NFAPI_CRC_INDICATION_PDU_T *pdu = q->queue[q->rear].pdu;
    // Set RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG

    q->rear = (q->rear + 1) % q->capacity;
    ++q->count;
    q->total_allocated_memory += payload_size;
}

PacketInfo dequeue_packet(PacketQueue *q) {
    if (q->count == 0) {
        // Handle queue empty scenario
        PacketInfo empty_info = {0};
        return empty_info;
    }

    PacketQueueEntry entry = q->queue[q->front];
    free(entry.packet_info);
    free(entry.pdu);

    q->front = (q->front + 1) % q->capacity;
    --q->count;
    q->total_allocated_memory -= entry.packet_info->length;

    return *entry.packet_info;
}

void free_queue(PacketQueue *q) {
    for (size_t i = q->front; i < q->rear + 1; ++i) {
        free(q->queue[i].packet_info);
        free(q->queue[i].pdu);
    }
    free(q->queue);
}
