    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_ind;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list[MAX_STRUCTS];
    size_t count;
    size_t next_index;
    pthread_mutex_t mutex;
    time_t last_prune_time;
} CRC_LIST_MANAGER_T;

CRC_LIST_MANAGER_T crc_manager;

void init_crc_list_manager() {
    memset(&crc_manager, 0, sizeof(crc_manager));
    pthread_mutex_init(&crc_manager.mutex, NULL);
}

int add_to_crc_list(NFAPI_CRC_INDICATION_PDU_T *new_pdu) {
    pthread_mutex_lock(&crc_manager.mutex);

    if (crc_manager.count >= MAX_STRUCTS) {
        fprintf(stderr, "Error: List is full\n");
        pthread_mutex_unlock(&crc_manager.mutex);
        return -1;
    }

    crc_manager.list[crc_manager.next_index] = new_pdu;
    crc_manager.next_index = (crc_manager.next_index + 1) % MAX_STRUCTS;
    crc_manager.count++;

    pthread_mutex_unlock(&crc_manager.mutex);
    return 0;
}

void prune_crc_list() {
    pthread_mutex_lock(&crc_manager.mutex);

    time_t now = time(NULL);
    if (now - crc_manager.last_prune_time < 60) { // Prune every minute
        pthread_mutex_unlock(&crc_manager.mutex);
        return;
    }

    size_t to_remove = MAX_STRUCTS / 10; // Remove 10% of the list
    for (size_t i = 0; i < to_remove; i++) {
        free(crc_manager.list[i]);
        crc_manager.list[i] = NULL;
    }

    memmove(crc_manager.list, &crc_manager.list[to_remove], (MAX_STRUCTS - to_remove) * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    memset(&crc_manager.list[MAX_STRUCTS - to_remove], 0, to_remove * sizeof(NFAPI_CRC_INDICATION_PDU_T *));

    crc_manager.count -= to_remove;
    crc_manager.next_index = 0;
    crc_manager.last_prune_time = now;

    pthread_mutex_unlock(&crc_manager.mutex);
}

void *manage_crc_list(void *arg) {
    size_t num_to_add = *(size_t *)arg;

    for (size_t i = 0; i < num_to_add; i++) {
        NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdu) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            continue;
        }

        // Initialize new_pdu with valid data
        // ...

        add_to_crc_list(new_pdu);

        // Check for overflow or other errors and handle appropriately

        // Periodically prune the list
        if (crc_manager.count % 1000 == 0) {
            prune_crc_list();
        }
    }

    return NULL;
}

int main() {
    init_crc_list_manager();

    size_t num_threads = 4;
    pthread_t threads[num_threads];
    size_t workloads[num_threads];

    for (size_t i = 0; i < num_threads; i++) {
        workloads[i] = MAX_STRUCTS / num_threads;
        pthread_create(&threads[i], NULL, manage_crc_list, &workloads[i]);
    }

    for (size_t i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
