Image* resize_jpeg(const char* file_path, int max_width, int max_height) {
    FILE* file = fopen(file_path, "rb");
    if (!file) return NULL;

    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);

    jpeg_stdio_src(&cinfo, file);
    jpeg_read_header(&cinfo, TRUE);
    jpeg_start_decompress(&cinfo);

    int width = cinfo.output_width;
    int height = cinfo.output_height;

    if (width > max_width || height > max_height) {
        float scale = fmin((float)max_width / width, (float)max_height / height);
        width = (int)(width * scale);
        height = (int)(height * scale);
    }

    Image* img = malloc(sizeof(Image));
    if (!img) {
        jpeg_destroy_decompress(&cinfo);
        fclose(file);
        return NULL;
    }

    img->width = width;
    img->height = height;
    img->data = malloc(width * height * 3);
    if (!img->data) {
        free(img);
        jpeg_destroy_decompress(&cinfo);
        fclose(file);
        return NULL;
    }

    JSAMPARRAY buffer = (*cinfo.mem->alloc_sarray)((j_common_ptr)&cinfo, JPOOL_IMAGE, width * 3, 1);

    while (cinfo.output_scanline < cinfo.output_height) {
        jpeg_read_scanlines(&cinfo, buffer, 1);
        // Resize and copy pixel data here
        // ...
    }

    jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);
    fclose(file);

    return img;
}

void free_image(Image* img) {
    if (img) {
        free(img->data);
        free(img);
    }
}
