    processed_packet->length = packet_length;
    processed_packet->data = (char*)malloc(packet_length * sizeof(char));
    if (!processed_packet->data) {
        perror("Payload memory allocation failed");
        free(processed_packet);
        return NULL;
    }

    memcpy(processed_packet->data, packet_data, packet_length);

    return processed_packet;
}

void free_packet(Packet* packet) {
    if (packet) {
        if (packet->data) {
            free(packet->data);
        }
        free(packet);
    }
}

