ImageMetadata* process_images(const char** fileNames, int numFiles) {
    ImageMetadata* metadataArray = NULL;
    size_t totalSize = 0;
    int validFileCount = 0;

    for (int i = 0; i < numFiles; ++i) {
        FILE* file = fopen(fileNames[i], "rb");
        if (!file) continue;

        fseek(file, 0, SEEK_END);
        size_t fileSize = ftell(file);
        fseek(file, 0, SEEK_SET);

        // Check for potential integer overflow
        if (totalSize > SIZE_MAX - fileSize || totalSize + fileSize > MAX_MEMORY_LIMIT) {
            fclose(file);
            break;
        }

        metadataArray = realloc(metadataArray, (validFileCount + 1) * sizeof(ImageMetadata));
        if (!metadataArray) {
            fclose(file);
            break;
        }

        ImageMetadata* currentMeta = &metadataArray[validFileCount];
        // Simulate reading metadata from file
        currentMeta->width = 800;
        currentMeta->height = 600;
        strncpy(currentMeta->format, "JPEG", sizeof(currentMeta->format) - 1);
        currentMeta->fileSize = fileSize;

        totalSize += fileSize;
        validFileCount++;
        fclose(file);
    }

    if (validFileCount < numFiles && metadataArray) {
        // Resize array to fit only valid files
        ImageMetadata* resizedArray = realloc(metadataArray, validFileCount * sizeof(ImageMetadata));
        if (resizedArray) {
            metadataArray = resizedArray;
        }
    } else if (!metadataArray) {
        return NULL; // Return NULL if memory allocation fails
    }

    return metadataArray;
}

int main() {
    const char* files[] = {"image1.jpg", "image2.jpg", "image3.jpg"};
    int numFiles = sizeof(files) / sizeof(files[0]);

    ImageMetadata* metadata = process_images(files, numFiles);
    if (metadata) {
        for (int i = 0; i < numFiles && metadata[i].width != 0; ++i) {
            printf("Image %d: Width=%d, Height=%d, Format=%s, Size=%zu bytes\n",
                   i + 1, metadata[i].width, metadata[i].height, metadata[i].format, metadata[i].fileSize);
        }
        free(metadata);
    } else {
        printf("Failed to process images due to memory constraints.\n");
    }

    return 0;
}
