#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

typedef struct LinkedList {
    ListNode* head;
    pthread_mutex_t mutex;
    int size;
} LinkedList;

LinkedList* createLinkedList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->size = 0;
    return list;
}

ListNode* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    ListNode* node = (ListNode*)malloc(sizeof(ListNode));
    if (!node) return NULL;
    node->data = data;
    node->next = NULL;
    return node;
}

void populateNficIndications(LinkedList* list, int N) {
    if (N <= 0 || N > INT_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        pthread_mutex_lock(&list->mutex);
        printf("Invalid value for N: %d\n", N);
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    int retries = 5;
    while (retries--) {
        ListNode* current = list->head;
        for (int i = 0; i < N; ++i) {
            if (!current) {
                pthread_mutex_lock(&list->mutex);
                printf("Memory allocation failed, retrying...\n");
                pthread_mutex_unlock(&list->mutex);
                return;
            }
            current = current->next;
        }

        for (int i = 0; i < N; ++i) {
            ListNode* node = createNode((NFAPI_CRC_INDICATION_PDU_T){
                .RX_UE_INFORMATION_TAG = rand() % 100,
                .RNTI = rand() % 65536,
                .CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0
            });
            if (!node) {
                pthread_mutex_lock(&list->mutex);
                printf("Memory allocation failed, retrying...\n");
                pthread_mutex_unlock(&list->mutex);
                return;
            }
            node->next = list->head;
            list->head = node;
        }

        pthread_mutex_lock(&list->mutex);
        list->size += N;
        pthread_mutex_unlock(&list->mutex);

        return;
    }

    pthread_mutex_lock(&list->mutex);
    printf("Memory allocation failed after multiple retries\n");
    pthread_mutex_unlock(&list->mutex);
}

void printList(LinkedList* list) {
    ListNode* current = list->head;
    while (current) {
        printf("%d %d %d -> ", current->data.RX_UE_INFORMATION_TAG, current->data.RNTI, current->data.CRC_INDICATION_REL8_TAG);
        current = current->next;
    }
    printf("NULL\n");
}

void freeList(LinkedList* list) {
    ListNode* current = list->head;
    while (current) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}
