#include <pthread.h>
#include <stdlib.h>
#include <time.h>

#define MAX_LOG_MESSAGE_LENGTH 1024

typedef struct LogEntry {
    time_t timestamp;
    char message[MAX_LOG_MESSAGE_LENGTH];
} LogEntry;

typedef struct QueueNode {
    LogEntry entry;
    struct QueueNode* next;
} QueueNode;

typedef struct LogQueue {
    QueueNode* front;
    QueueNode* rear;
    pthread_mutex_t mutex;
    size_t totalMemoryUsage;
} LogQueue;

size_t calculateLogEntrySize(const char* message) {
    return sizeof(time_t) + strlen(message);
}

int isValidLogEntry(const LogEntry* entry, size_t* requiredSize) {
    if (entry->timestamp < 0 || entry->timestamp > time(NULL)) {
        return 0;
    }
    *requiredSize = calculateLogEntrySize(entry->message);
    return (*requiredSize <= MAX_LOG_MESSAGE_LENGTH);
}

int enqueueLogEntry(LogQueue* queue, const LogEntry* entry) {
    size_t requiredSize;
    if (!isValidLogEntry(entry, &requiredSize)) {
        return -1; // Invalid log entry
    }

    pthread_mutex_lock(&queue->mutex);

    QueueNode* newNode = (QueueNode*)malloc(sizeof(QueueNode));
    if (!newNode) {
        pthread_mutex_unlock(&queue->mutex);
        return -2; // Memory allocation failed
    }

    newNode->entry = *entry;
    newNode->next = NULL;

    if (queue->rear == NULL) {
        queue->front = queue->rear = newNode;
    } else {
        queue->rear->next = newNode;
        queue->rear = newNode;
    }

    queue->totalMemoryUsage += requiredSize;

