typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    NFAPI_CRC_INDICATION_REL8_TAG CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    int attempts[MAX_N];
} CrcIndicationArray;

int hashRNTI(uint16_t RNTI, size_t capacity) {
    return RNTI % capacity;
}

int insertCrcIndication(CrcIndicationArray *array, NFAPI_CRC_INDICATION_PDU_T indication) {
    if (array->size >= array->capacity) {
        printf("Error: Array is full\n");
        return -1;
    }

    size_t index = hashRNTI(indication.RNTI, array->capacity);
    int attempts = 0;

    while (array->array[index].RX_UE_INFORMATION_TAG != 0) {
        if (++attempts >= MAX_N) {
            printf("Error: Maximum number of attempts exceeded\n");
            return -1;
        }
        index = hashRNTI(index + 1, array->capacity);
    }

    array->array[index] = indication;
    array->size++;
    array->attempts[indication.RNTI]++;
    return 0;
}

CrcIndicationArray* createCrcIndicationArray(size_t N) {
    CrcIndicationArray *array = (CrcIndicationArray*)malloc(sizeof(CrcIndicationArray));
    if (!array) {
        printf("Error: Failed to allocate memory for array\n");
        return NULL;
    }

    array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        printf("Error: Failed to allocate memory for array elements\n");
        return NULL;
    }

    array->size = 0;
    array->capacity = N;
    memset(array->attempts, 0, sizeof(int) * MAX_N);

    srand(time(NULL));

    return array;
}

void freeCrcIndicationArray(CrcIndicationArray *array) {
    if (array) {
        free(array->array);
        free(array);
    }
}

int main() {
    size_t N = 5000;
    CrcIndicationArray *array = createCrcIndicationArray(N);

    if (!array) {
        return -1;
    }

    for (size_t i = 0; i < V; i++) {
        NFAPI_CRC_INDICATION_PDU_T indication;
        indication.RX_UE_INFORMATION_TAG = i;
        indication.RNTI = rand() % MAX_N;
        indication.CRCFLAG = (i % 2 == 0) ? NFAPI_CRC_PASS : NFAPI_CRC_FAIL;

