            freeCrcIndicationArray(array);
            return -1;
        }
    }

    for (size_t i = 0; i < MAX_N; i++) {
        if (array->attempts[i] > 0) {
            printf("RNTI %u was inserted after %d attempts\n", i, array->attempts[i]);
        }
    }

