typedef struct MemoryPool {
    void* memory;
    size_t size;
    size_t element_size;
    size_t used_elements;
} MemoryPool;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_init_array(size_t N, MemoryPool* pool, int alignment, int padding) {
    if (N == 0 || pool == NULL || alignment <= 0 || padding < 0) {
        return NULL;
    }

    size_t total_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t aligned_total_size = ((total_size + alignment - 1) / alignment) * alignment;

    if (aligned_total_size > pool->size) {
        return NULL; // Not enough memory in the pool
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)((char*)pool->memory + pool->used_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->used_elements += N;

    for (size_t i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand();
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2;
