#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t mutex;
} LinkedList;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate memory for node");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) {
        perror("Failed to allocate memory for linked list");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->mutex, NULL);
    list->head = NULL;
    return list;
}

void insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* new_node = create_node(data);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&list->mutex);
}

void free_list(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void* generate_crc_indication_list(void* arg) {
    int N = *(int*)arg;
    if (N <= 0 || N > 1000000) { // Example max value for demonstration purposes
        fprintf(stderr, "Invalid input: N must be between 1 and 1000000\n");
        return NULL;
    }

    LinkedList* list = create_linked_list();
    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = rand() % 10000;
        data.RNTI = rand() % 256;
        data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        insert_node(list, data);
    }

    free_list(list);
    return NULL;
}

int main() {
    int N = 1000; // Example value
    pthread_t thread;
    if (pthread_create(&thread, NULL, generate_crc_indication_list, &N) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }
    pthread_join(thread, NULL);
    return EXIT_SUCCESS;
}
