struct Node {
    NFAPI_CRC_INDICATION_PDU data;
    struct Node* next;
};

typedef struct LinkedList {
    struct Node* head;
    size_t maxMemoryBudget;
    size_t currentMemoryUsage;
} LinkedList;

LinkedList* createLinkedList(size_t maxMemoryBudget) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) {
        // Log allocation failure
        return NULL;
    }
    list->head = NULL;
    list->maxMemoryBudget = maxMemoryBudget;
    list->currentMemoryUsage = 0;
    return list;
}

void addNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU data) {
    if (list->currentMemoryUsage + sizeof(struct Node) > list->maxMemoryBudget) {
        // Handle memory allocation failure
        return;
    }

    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    if (newNode == NULL) {
        // Log allocation failure
        return;
    }
    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    list->currentMemoryUsage += sizeof(struct Node);
}

void processPacket(LinkedList* list, NFAPI_CRC_INDICATION_PDU packet) {
    addNode(list, packet);
    // Handle packet processing status through a callback mechanism
}

void destroyList(LinkedList* list) {
    struct Node* current = list->head;
    while (current != NULL) {
        struct Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}
