typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *structures[MAX_STRUCTURES];
    size_t count;
    pthread_mutex_t lock;
} NFAPI_CRC_ARRAY_T;

int init_nfaip_crc_array(NFAPI_CRC_ARRAY_T *array) {
    array->count = 0;
    return pthread_mutex_init(&array->lock, NULL);
}

int insert_nfaip_crc_structure(NFAPI_CRC_ARRAY_T *array, int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    pthread_mutex_lock(&array->lock);

    if (array->count >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Array is full
    }

    array->structures[array->count] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->structures[array->count]) {
        pthread_mutex_unlock(&array->lock);
        return -2; // Memory allocation failed
    }

    NFAPI_CRC_INDICATION_PDU_T *new_struct = array->structures[array->count];
    new_struct->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_struct->RNTI = RNTI;
    new_struct->CRCFLAG = CRCFLAG;

    array->count++;
    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

void free_nfaip_crc_array(NFAPI_CRC_ARRAY_T *array) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        free(array->structures[i]);
    }
    array->count = 0;

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}
