void* fetch_employee_details(void* arg) {
    int supervisor_id = *(int*)arg;
    char query[512];
    snprintf(query, sizeof(query), "SELECT name, city, address FROM Employees WHERE supervisor_id = %d", supervisor_id);

    // Simulate database retrieval
    EmployeeDetails details;
    strcpy(details.name, "John Doe");
    strcpy(details.city, "New York");
    strcpy(details.address, "123 Main St");

    pthread_mutex_lock(&lock);
    if (employee_cache == NULL) {
        employee_cache = malloc(sizeof(EmployeeDetails*) * list_size);
        for (int i = 0; i < list_size; i++) {
            employee_cache[i] = malloc(sizeof(EmployeeDetails));
        }
    }
    int cache_index = supervisor_id % list_size;
    memcpy(employee_cache[cache_index], &details, sizeof(EmployeeDetails));
    pthread_mutex_unlock(&lock);

    return NULL;
}

int main() {
    char connection_string[MAX_CONNECTION_STRING_LEN];
    printf("Enter database connection string: ");
    fgets(connection_string, sizeof(connection_string), stdin);
    connection_string[strcspn(connection_string, "\n")] = 0;

    if (strlen(connection_string) < MIN_CONNECTION_STRING_LEN || strlen(connection_string) > MAX_CONNECTION_STRING_LEN) {
        fprintf(stderr, "Invalid connection string length\n");
        return 1;
    }

    int N;
    printf("Enter the number of CRC indications: ");
    scanf("%d", &N);
    populate_crc_indications(N);

    pthread_t threads[list_size];
    int supervisor_ids[list_size];

    for (int i = 0; i < list_size; i++) {
        supervisor_ids[i] = rand() % 100;
        if (pthread_create(&threads[i], NULL, fetch_employee_details, &supervisor_ids[i]) != 0) {
            perror("Failed to create thread");
            return 1;
        }
    }

    for (int i = 0; i < list_size; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free allocated memory
    free(crc_indications);
    for (int i = 0; i < list_size; i++) {
        free(employee_cache[i]);
    }
    free(employee_cache);

    return 0;
}
