typedef struct {
    int packet_id;
    time_t timestamp;
    char* payload;
} PacketMetaData;

PacketMetaData* process_packets(int* packet_ids, time_t* timestamps, unsigned int* payload_sizes, int num_packets, size_t max_buffer_size) {
    if (num_packets > 1000 || max_buffer_size == 0) {
        return NULL; // Invalid input
    }

    PacketMetaData* metadata = (PacketMetaData*)malloc(num_packets * sizeof(PacketMetaData));
    if (!metadata) {
        return NULL; // Memory allocation failed
    }

    size_t total_payload_size = 0;
    for (int i = 0; i < num_packets; ++i) {
        size_t payload_size = payload_sizes[i];
        if (payload_size > max_buffer_size || total_payload_size + payload_size > max_buffer_size) {
            free(metadata);
            return NULL; // Payload too large
        }
        total_payload_size += payload_size;

        metadata[i].packet_id = packet_ids[i];
        metadata[i].timestamp = timestamps[i];

        metadata[i].payload = (char*)malloc(payload_size * sizeof(char));
        if (!metadata[i].payload) {
            for (int j = 0; j < i; ++j) {
                free(metadata[j].payload);
            }
            free(metadata);
            return NULL; // Payload allocation failed
        }
    }

    return metadata;
}
