} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_node(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
}

void free_list(Node** head) {
    Node* current = *head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int validate_rnti(uint16_t rnti) {
    if (rnti < 1 || rnti > 65535) {
        return -1; // Invalid RNTI
    }
    return 0; // Valid RNTI
}

void update_linked_list(Node** head, uint16_t RX_UE_INFORMATION_TAG, uint16_t RNTI, uint8_t CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T new_data = {RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG};
    if (validate_rnti(RNTI) == -1) {
        fprintf(stderr, "Invalid RNTI value\n");
        return;
    }
    insert_node(head, new_data);
}

