typedef enum {
    SUCCESS,
    MEMORY_LIMIT_EXCEEDED,
    RESOURCE_UNAVAILABLE,
    INVALID_INPUT
} ErrorCode;

ErrorCode manage_nfaapi_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T** pdu_list, int* size, int max_size) {
    // Validate input parameters
    if (size == NULL || *size < 0 || max_size <= *size) return INVALID_INPUT;

    // Calculate the number of structures to allocate based on current size and maximum allowed size
    int new_size = (*size * 2 > max_size) ? max_size : *size * 2;

    // Attempt to reallocate memory for the list
    NFAPI_CRC_INDICATION_PDU_T* new_list = realloc(*pdu_list, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (new_list == NULL) {
        // Memory allocation failed, attempt to reduce size and try again
        while (new_list == NULL && new_size > 1) {
            new_size /= 2;
            new_list = realloc(*pdu_list, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }

        if (new_list == NULL) {
            // Still failed to allocate memory
            return MEMORY_LIMIT_EXCEEDED;
        }
    } else {
        // Successfully reallocated memory
        new_list[*size].crc_indication_rel8_tag.crcflag = rand() % 2; // Randomly set CRCFLAG
        (*pdu_list) = new_list;
        *size = new_size;

        // Log the adjustment for monitoring purposes
        printf("Adjusted list size to %d\n", *size);
    }

    return SUCCESS;
}
