Packet* process_packets(uint8_t** packet_headers, size_t num_headers) {
    if (num_headers > MAX_PACKETS) {
        return NULL; // Too many packets
    }

    Packet* packets = (Packet*)malloc(num_headers * sizeof(Packet));
    if (!packets) {
        return NULL; // Memory allocation failed
    }

    for (size_t i = 0; i < num_headers; ++i) {
        uint16_t fragment_count = ntohs(*(uint16_t*)(packet_headers[i] + 2)); // Example: 2 bytes header field

        if (fragment_count == 0 || fragment_count > UINT16_MAX / MAX_FRAGMENT_SIZE) {
            free(packets);
            return NULL; // Invalid or too large fragment count
        }

        size_t total_size = fragment_count * MAX_FRAGMENT_SIZE;
        packets[i].data_fragments = (uint8_t*)malloc(total_size);
        if (!packets[i].data_fragments) {
            for (size_t j = 0; j < i; ++j) {
                free(packets[j].data_fragments);
            }
            free(packets);
            return NULL; // Memory allocation failed
        }

        packets[i].sequence_number = ntohs(*(uint32_t*)(packet_headers[i])); // Example: 4 bytes sequence number
        packets[i].fragment_count = fragment_count;

        // Populate data fragments (example)
        memcpy(packets[i].data_fragments, packet_headers[i] + 6, total_size); // Assuming data starts at offset 6
    }

    return packets;
}
