typedef struct Layer {
    int data;
} Layer;

typedef struct ImageFile {
    char filename[256];
    int numLayers;
    Layer** layers;
} ImageFile;

int readMetadata(const char* filename, int* numLayers) {
    // Simulate reading metadata from a file
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        return -1; // File not found or error opening file
    }
    fscanf(fp, "%d", numLayers);
    fclose(fp);
    return 0;
}

int allocateMemoryForLayers(ImageFile* image, int totalLayers) {
    image->layers = (Layer**)malloc(totalLayers * sizeof(Layer*));
    if (image->layers == NULL) {
        return -1; // Memory allocation failed
    }
    for (int i = 0; i < totalLayers; i++) {
        image->layers[i] = (Layer*)malloc(sizeof(Layer));
        if (image->layers[i] == NULL) {
            // Free previously allocated memory before returning error
            for (int j = 0; j < i; j++) {
                free(image->layers[j]);
            }
            free(image->layers);
            return -1;
        }
    }
    return 0;
}

void populateLayersWithRandomData(ImageFile* image) {
    for (int i = 0; i < image->numLayers; i++) {
        image->layers[i]->data = rand();
    }
}

void processImageFiles(const char* filenames[], int numFiles, int memoryLimit) {
    ImageFile images[MAX_FILES];
    int totalLayers = 0;

    for (int i = 0; i < numFiles; i++) {
        int numLayers;
        if (readMetadata(filenames[i], &numLayers) != 0) {
            printf("Error reading metadata from %s\n", filenames[i]);
            continue;
        }

        if (totalLayers + numLayers > MAX_LAYERS || totalLayers * sizeof(Layer*) + numLayers * sizeof(Layer) > memoryLimit) {
            printf("Memory limit exceeded for file %s\n", filenames[i]);
            continue;
        }

        images[i].numLayers = numLayers;
        if (allocateMemoryForLayers(&images[i], numLayers) != 0) {
            printf("Error allocating memory for layers in %s\n", filenames[i]);
            continue;
        }

        populateLayersWithRandomData(&images[i]);
    }
}

int main() {
    const char* filenames[] = {"file1.txt", "file2.txt", "file3.txt"};
    int numFiles = sizeof(filenames) / sizeof(filenames[0]);
    processImageFiles(filenames, numFiles, MAX_MEMORY_LIMIT);
    return 0;
}
