#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define packet structure
typedef struct Packet {
    int payload_length;
    char *payload_data;
} Packet;

// Function to parse packet data
Packet* parse_packet(const unsigned char *packet_data, size_t packet_size) {
    // Allocate memory for the packet structure
    Packet *packet = (Packet *)malloc(sizeof(Packet));
    if (!packet) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Validate payload length and allocate memory safely
    if (packet_size < sizeof(int)) {
        fprintf(stderr, "Invalid packet size\n");
        free(packet);
        return NULL;
    }

    memcpy(&packet->payload_length, packet_data, sizeof(int));
    packet_data += sizeof(int);

    // Calculate total payload size including data
    size_t total_payload_size = packet->payload_length + sizeof(int);
    if (total_payload_size > packet_size) {
        fprintf(stderr, "Packet size mismatch\n");
        free(packet);
        return NULL;
    }

    // Allocate memory for the payload data
    packet->payload_data = (char *)malloc(total_payload_size);
    if (!packet->payload_data) {
        fprintf(stderr, "Memory allocation failed\n");
        free(packet);
        return NULL;
    }

    memcpy(packet->payload_data, packet_data, total_payload_size);

    // Validate and log packet details
    printf("Parsed packet with payload length: %d\n", packet->payload_length);

    return packet;
}

// Function to free allocated memory for a packet
void free_packet(Packet *packet) {
    if (packet->payload_data) {
        free(packet->payload_data);
    }
    free(packet);
}

int main() {
    // Example usage
    unsigned char example_packet[] = {0, 1, 2, 3, 'a', 'b', 'c'};
    Packet *parsed_packet = parse_packet(example_packet, sizeof(example_packet));

    if (parsed_packet) {
        printf("Payload data: %.*s\n", parsed_packet->payload_length, parsed_packet->payload_data);
        free_packet(parsed_packet);
    }

    return 0;
}
```

