    img->thumbnails = (unsigned char**)malloc(count * sizeof(unsigned char*));
    if (!img->thumbnails) {
        free(img->file_path);
        free(img);
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        img->thumbnails[i] = (unsigned char*)malloc(1024); // Assuming a max thumbnail size
        if (!img->thumbnails[i]) {
            for (int j = 0; j < i; j++) free(img->thumbnails[j]);
            free(img->thumbnails);
            free(img->file_path);
            free(img);
            return NULL;
        }
    }

    return img;
}

void destroy_image(Image* img) {
    if (!img) return;

    for (int i = 0; i < img->thumbnail_count; i++) {
        free(img->thumbnails[i]);
    }
    free(img->thumbnails);
    free(img->file_path);
    free(img);
}

