    if (a && b > SIZE_MAX / a) {
        fprintf(stderr, "Memory allocation too large\n");
        exit(EXIT_FAILURE);
    }
    return a * b;
}

NetworkDataPacket* parse_packets(uint8_t** packets, uint32_t num_packets) {
    NetworkDataPacket* packet_list = malloc(safe_size_mul(num_packets, sizeof(NetworkDataPacket)));
    if (!packet_list) {
        fprintf(stderr, "Failed to allocate memory for packet list\n");
        exit(EXIT_FAILURE);
    }

    for (uint32_t i = 0; i < num_packets; ++i) {
        NetworkDataPacket* packet = &packet_list[i];
        uint8_t* data = packets[i];

        // Simulate parsing payload length and type
        packet->payload_length = *(uint16_t*)(data + 0);
        packet->packet_type = *(data + 2);

        // Allocate memory for payload dynamically
        packet->payload = malloc(packet->payload_length);
        if (!packet->payload) {
            fprintf(stderr, "Failed to allocate memory for payload\n");
            exit(EXIT_FAILURE);
        }
        memcpy(packet->payload, data + 4, packet->payload_length);
    }

    return packet_list;
}

