typedef struct {
    void* buffer;
    size_t size;
} Packet;

Packet packetPool[MAX_PACKETS];
size_t packetCount = 0;

void addPacketToBuffer(void* data, size_t dataSize) {
    if (packetCount >= MAX_PACKETS) {
        printf("Packet buffer is full. Unable to process new packet.\n");
        return;
    }

    if (dataSize == 0) {
        printf("Invalid packet size. Packet ignored.\n");
        return;
    }

    if ((size_t)-1 / 2 < dataSize) {
        printf("Potential integer overflow detected in packet size. Packet ignored.\n");
        return;
    }

    packetPool[packetCount].buffer = malloc(dataSize);
    if (packetPool[packetCount].buffer == NULL) {
        printf("Memory allocation failed for new packet buffer.\n");
        return;
    }

    memcpy(packetPool[packetCount].buffer, data, dataSize);
    packetPool[packetCount].size = dataSize;

    packetCount++;
}

void processPackets() {
    for (size_t i = 0; i < packetCount; i++) {
        // Simulate packet processing
        printf("Processing packet of size %zu\n", packetPool[i].size);
        free(packetPool[i].buffer); // Free the buffer after processing
    }

    packetCount = 0;
}

