        *error_code = -2; // Invalid format in the configuration file
        return NULL;
    }

    // Validate input values
    if (packet_count > UINT_MAX / sizeof(PacketMetadata)) {
        fclose(file);
        *error_code = -3; // Potential integer overflow
        return NULL;
    }
    size_t total_size = packet_count * sizeof(PacketMetadata);

    PacketMetadata* metadata_array = malloc(total_size);
    if (!metadata_array) {
        fclose(file);
        *error_code = -4; // Memory allocation failed
        return NULL;
    }

    for (size_t i = 0; i < packet_count; ++i) {
        if (fscanf(file, "%zu", &metadata_array[i].payload_size) != 1) {
            free(metadata_array);
            fclose(file);
            *error_code = -5; // Invalid format in the configuration file
            return NULL;
        }
        // Additional validation for payload_size can be added here
    }

    fclose(file);
    *error_code = 0; // Success
    return metadata_array;
