    NFAPI_CRC_INDICATION_PDU_T new_element = {1, 2, rand()};
    array[array_size++] = new_element;
    printf("Added element: %d\n", array_size);
    pthread_cond_signal(&queue_not_empty);
    pthread_mutex_unlock(&queue_lock);
    return NULL;
}

