        printf("Error: Configured size exceeds 1 MB limit.\n");
        return 1;
    }

    // Allocate memory for the array
    array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_array_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        printf("Error: Failed to allocate memory.\n");
        return 1;
    }

    // Initialize the thread pool and start threads
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, enqueue_thread, NULL);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free the allocated memory
