Image_MetaData* image_list = NULL;
int capacity = INITIAL_CAPACITY;
int size = 0;
pthread_mutex_t mutex;

void init_image_list() {
    pthread_mutex_init(&mutex, NULL);
}

void resize_image_list(int new_capacity) {
    if (new_capacity <= capacity)
        return;

    Image_MetaData* new_list = realloc(image_list, new_capacity * sizeof(Image_MetaData));
    if (!new_list) {
        perror("Failed to reallocate memory for image list");
        exit(EXIT_FAILURE);
    }
    image_list = new_list;
    capacity = new_capacity;
}

void add_image(const char* filename, int width, int height) {
    pthread_mutex_lock(&mutex);
    if (size == capacity)
        resize_image_list(capacity * 2);
    strcpy(image_list[size].filename, filename);
    image_list[size].width = width;
    image_list[size].height = height;
    size++;
    pthread_mutex_unlock(&mutex);
}

void read_images_from_file(const char* filename) {
    // Simulate file operation with thread safety
    for (int i = 0; i < 5; i++) { // Example: Reading 5 images from a file
        add_image("image%d.jpg", 1920, 1080);
        pthread_yield(); // Simulate concurrent access
    }
}

void* image_list_manager(void* arg) {
    int N = *(int*)arg;
    if (N <= 0 || N > INT_MAX / sizeof(Image_MetaData)) {
        fprintf(stderr, "Invalid number of elements: %d\n", N);
        return NULL;
    }

    init_image_list();
    read_images_from_file("image_data.txt");

    // Additional logic for caching, error handling, logging, and compatibility can be added here

    return NULL;
}

int main() {
    int N = 10; // Example number of elements
    pthread_t thread;
    pthread_create(&thread, NULL, image_list_manager, &N);
    pthread_join(thread, NULL);

    for (int i = 0; i < size; i++) {
        printf("Filename: %s, Width: %d, Height: %d\n", image_list[i].filename, image_list[i].width, image_list[i].height);
    }

    free(image_list);
    pthread_mutex_destroy(&mutex);

    return 0;
}
