#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

// Define constants for buffer management
#define MIN_BUFFER_SIZE 256
#define GROWTH_FACTOR 1.5

typedef struct {
    uint8_t *payload;
    size_t capacity;
    size_t length;
} PacketBuffer;

PacketBuffer* create_packet_buffer() {
    PacketBuffer *buffer = (PacketBuffer*)malloc(sizeof(PacketBuffer));
    if (!buffer) return NULL;

    buffer->payload = (uint8_t*)malloc(MIN_BUFFER_SIZE);
    if (!buffer->payload) {
        free(buffer);
        return NULL;
    }

    buffer->capacity = MIN_BUFFER_SIZE;
    buffer->length = 0;

    return buffer;
}

void destroy_packet_buffer(PacketBuffer *buffer) {
    if (buffer) {
        free(buffer->payload);
        free(buffer);
    }
}

int resize_packet_buffer(PacketBuffer *buffer, size_t new_capacity) {
    if (!buffer || new_capacity <= buffer->capacity) return -1;

    uint8_t *new_payload = (uint8_t*)realloc(buffer->payload, new_capacity);
    if (!new_payload) return -2;

    buffer->payload = new_payload;
    buffer->capacity = new_capacity;

    return 0;
}

int process_packet(PacketBuffer *buffer, const uint8_t *data, size_t data_size) {
    // Check for integer overflow
    if (data_size > SIZE_MAX - buffer->length) return -1;

    // Ensure there is enough capacity in the buffer
    while (buffer->capacity < buffer->length + data_size) {
        size_t new_capacity = (size_t)(buffer->capacity * GROWTH_FACTOR);
        if (resize_packet_buffer(buffer, new_capacity) != 0) return -2;
    }

    // Copy data into buffer
    memcpy(buffer->payload + buffer->length, data, data_size);
    buffer->length += data_size;

    return 0;
}

int main() {
    PacketBuffer *buffer = create_packet_buffer();
    if (!buffer) {
        fprintf(stderr, "Failed to create packet buffer\n");
        return -1;
    }

    uint8_t packet_data[] = "Hello, world!";
    if (process_packet(buffer, packet_data, strlen((char*)packet_data)) != 0) {
        fprintf(stderr, "Failed to process packet\n");
        destroy_packet_buffer(buffer);
        return -1;
    }

    printf("Packet processed successfully. Payload length: %zu\n", buffer->length);

    destroy_packet_buffer(buffer);
    return 0;
}
```

This code defines a `PacketBuffer` structure to manage the payload of network packets and provides functions to create, resize, and process packets. The `process_packet` function includes checks for integer overflow and dynamically resizes the buffer as needed. Comments are provided to explain key design choices and trade-offs.']

