void populateNFAPIList(NFAPI_CRC_INDICATION_PDU_T** list, int* size, const char* connectionString, int supervisorId) {
    if (!validateConnectionString(connectionString)) {
        fprintf(stderr, "Invalid connection string\n");
        return;
    }

    MYSQL* conn = mysql_init(NULL);
    if (!mysql_real_connect(conn, NULL, NULL, NULL, connectionString, 0, NULL, 0)) {
        fprintf(stderr, "%s\n", mysql_error(conn));
        mysql_close(conn);
        return;
    }

    pthread_mutex_lock(&dbMutex);

    EmployeeData employees[MAX_EMPLOYEES];
    int employeeCount = 0;

    char query[SQL_QUERY_LENGTH];
    snprintf(query, sizeof(query), "SELECT id, rxUeInfoTag, rnti, crcIndicationRel8 FROM Employees WHERE supervisorId = %d", supervisorId);

    if (mysql_query(conn, query)) {
        fprintf(stderr, "%s\n", mysql_error(conn));
    } else {
        MYSQL_RES* result = mysql_store_result(conn);
        while ((MYSQL_ROW row = mysql_fetch_row(result))) {
            if (employeeCount >= MAX_EMPLOYEES) break;

            employees[employeeCount].rxUeInfoTag = atoi(row[1]);
            employees[employeeCount].rnti = atoi(row[2]);
            employees[employeeCount].crcIndicationRel8 = atoi(row[3]);
            employeeCount++;
        }
        mysql_free_result(result);
    }

    *size = employeeCount;
    *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < *size; i++) {
        (*list)[i].crcFlag = rand() % 2; // Randomly set CRCFLAG
    }

    pthread_mutex_unlock(&dbMutex);
    mysql_close(conn);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* list;
    int size;

    populateNFAPIList(&list, &size, "your_connection_string", 123);

    for (int i = 0; i < size; i++) {
        printf("CRCFLAG: %d\n", list[i].crcFlag);
    }

    free(list);
    return 0;
}
