typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    time_t timestamp;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int generate_checksum(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    return pdu->RX_UE_INFORMATION_TAG + pdu->RNTI + pdu->CRC_INDICATION_REL8_TAG + (int)pdu->timestamp + pdu->CRCFLAG;
}

int create_and_populate_pdus(int N, NFAPI_CRC_INDICATION_PDU_T **pdus) {
    if (N <= 0 || pdus == NULL) return -1;

    *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdus == NULL) {
        perror("Failed to allocate memory");
        return -2;
    }

    srand(time(NULL));

    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &(*pdus)[i];
        pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu->RNTI = rand() % 500;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 200;
        time(&pdu->timestamp);
        pdu->CRCFLAG = (rand() % 2) == 0 ? 1 : 0;

        if (generate_checksum(pdu) != 0) {
            free(*pdus);
            *pdus = NULL;
            return -3;
        }
    }

    return N;
}

void log_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, int index) {
    printf("PDU %d: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d, Timestamp=%ld, CRCFLAG=%d\n",
           index, pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG, (long)pdu->timestamp, pdu->CRCFLAG);
}

int validate_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus, int N) {
    for (int i = 0; i < N; ++i) {
        if (generate_checksum(&pdus[i]) != 0) return 0;
    }
    return 1;
}

int main() {
    int N = 10;
    NFAPI_CRC_INDICATION_PDU_T *pdus = NULL;

    int result = create_and_populate_pdus(N, &pdus);
    if (result < 0) {
        fprintf(stderr, "Failed to create and populate PDUs: %d\n", result);
        return 1;
    }

    for (int i = 0; i < N; ++i) {
        log_pdu(&pdus[i], i);
    }

    if (!validate_pdus(pdus, N)) {
        fprintf(stderr, "Validation failed!\n");
        free(pdus);
        return 1;
    }

    free(pdus);
    return 0;
}
