#define MAX_NF_API_CRC_INDICATION_PDU_T 1000000

typedef struct {
    // Define the structure fields here
    RX_UE_INFORMATION_TAG ue_info_tag;
    int RNTI;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_array;
    size_t array_size;
    pthread_mutex_t mutex;
} NFCI_Array;

NFCI_Array* allocate_nfc_array(size_t N) {
    if (N > MAX_NF_API_CRC_INDICATION_PDU_T) {
        // Handle error: too large request
        return NULL;
    }

    NFCI_Array *array = (NFCI_Array *)malloc(sizeof(NFCI_Array));
    if (array == NULL) {
        // Handle memory allocation failure
        return NULL;
    }

    array->pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array->pdu_array == NULL) {
        free(array);
        // Handle memory allocation failure
        return NULL;
    }

    array->array_size = N;

    if (pthread_mutex_init(&array->mutex, NULL) != 0) {
        free(array->pdu_array);
        free(array);
        // Handle mutex initialization failure
        return NULL;
    }

    return array;
}

void free_nfc_array(NFCI_Array *array) {
    if (array == NULL) {
        return;
    }

    pthread_mutex_lock(&array->mutex);
    free(array->pdu_array);
    array->pdu_array = NULL;
    array->array_size = 0;
    pthread_mutex_unlock(&array->mutex);

    pthread_mutex_destroy(&array->mutex);
    free(array);
}

// Example usage:
