    size_t N = 100000; // Example input
    NFCI_Array *nfc_array = allocate_nfc_array(N);
    if (nfc_array != NULL) {
        // Use the array for processing
        // ...
        free_nfc_array(nfc_array);
    }
    return 0;
}
