#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define RX_UE_INFORMATION_TAG 1
#define RNTI 2
#define CRC_INDICATION_REL8_TAG 3

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int tag;
    int value;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void append_to_list(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
}

void populate_list(Node** head, int n) {
    if (n <= 0) {
        fprintf(stderr, "Invalid input: n must be greater than zero\n");
        return;
    }

    srand(time(NULL));

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.tag = RX_UE_INFORMATION_TAG + rand() % 10; // Random tag
        data.value = RNTI + rand() % 10; // Random value for CRCFLAG
        append_to_list(head, data);
    }
}

void free_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    int n = 10; // Example value
    Node* head = NULL;

    populate_list(&head, n);

    // Use the list...

    free_list(head);

    return 0;
}
