        handle_memory_error(); // Implement error handling for memory allocation failures
        return;
    }

    // Copy the payload data into the allocated buffer
    memcpy(new_node->payload, packet_buffer + sizeof(int), payload_size);

    // Add the new node to the linked list
    if (packet_list_head == NULL) {
        packet_list_head = new_node;
    } else {
        packet_list_tail->next = new_node;
    }
    packet_list_tail = new_node;

    // Update total payload size for reference counting or memory tracking
    total_payload_size += payload_size;
}

void* get_packet_data(int packet_id, size_t* data_size) {
    PacketData* current = packet_list_head;
    while (current != NULL) {
        if (current->id == packet_id) {
            *data_size = current->payload_size;
            return current->payload;
        }
        current = current->next;
    }
    *data_size = 0;
    return NULL; // Packet not found
}

void free_packet_data() {
    PacketData* current = packet_list_head;
    while (current != NULL) {
        PacketData* next = current->next;
        free(current->payload);
        free(current);
        current = next;
    }
    packet_list_head = packet_list_tail = NULL;
    total_payload_size = 0;
}

