#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_FILES 1000
#define TOTAL_MEMORY_LIMIT (5 * 1024 * 1024) // 5MB

typedef struct {
    char fileName[256];
    int width;
    int height;
} ImageMetadata;

void logError(const char* message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

int safeMultiply(int a, int b, int* result) {
    *result = (long long)a * b / b == a ? a * b : -1;
    return *result != -1;
}

int processImageMetadata(const char* fileName, ImageMetadata** metadataArray, int* count) {
    if (*count >= MAX_FILES) {
        logError("Maximum file limit reached");
        return -1;
    }

    FILE* file = fopen(fileName, "r");
    if (!file) {
        logError("Failed to open file");
        return -1;
    }

    ImageMetadata metadata;
    if (fscanf(file, "%255s %d %d", metadata.fileName, &metadata.width, &metadata.height) != 3) {
        fclose(file);
        logError("Invalid file format");
        return -1;
    }

    size_t newMemorySize = (*count + 1) * sizeof(ImageMetadata);
    if (!safeMultiply(newMemorySize, 1, &newMemorySize)) {
        fclose(file);
        logError("Integer overflow in memory calculation");
        return -1;
    }

    if (newMemorySize > TOTAL_MEMORY_LIMIT || newMemorySize <= (*count) * sizeof(ImageMetadata)) {
        fclose(file);
        logError("Memory limit exceeded or no change in size");
        return -1;
    }

    *metadataArray = realloc(*metadataArray, newMemorySize);
    if (!*metadataArray) {
        fclose(file);
        logError("Failed to reallocate memory");
        return -1;
    }

    (*metadataArray)[*count] = metadata;
    *count += 1;

    fclose(file);
    return 0;
}

int main() {
    ImageMetadata* metadataArray = NULL;
    int count = 0;

    clock_t start = clock();
    for (int i = 0; i < MAX_FILES; i++) {
        char fileName[256];
        sprintf(fileName, "image_%d.txt", i);
        if (processImageMetadata(fileName, &metadataArray, &count) != 0) {
            break;
        }
    }

    clock_t end = clock();
    double timeTaken = ((double)(end - start)) / CLOCKS_PER_SEC;

    printf("Time taken: %f seconds\n", timeTaken);
    free(metadataArray);

    return 0;
}
