u_char* resolve_dns(const char* hostname, int* ip_length) {
    u_char* ip_address = NULL;
    struct in_addr addr;
    int retries = 0;

    while (retries < MAX_DNS_RETRIES) {
        if (gethostbyname_r(hostname, &addr, (char*)&ip_address, INET_ADDRSTRLEN, &ip_address, &h_errno) == NULL) {
            retries++;
            continue;
        }
        *ip_length = strlen(ip_address);
        return ip_address;
    }

    *ip_length = strlen(BACKUP_IP);
    ip_address = (u_char*)malloc(*ip_length);
    if (ip_address != NULL) {
        strcpy((char*)ip_address, BACKUP_IP);
    } else {
        fprintf(stderr, "Failed to allocate memory for backup IP address\n");
    }
    return ip_address;
}

void populate_nfa_list(NFAPI_CRC_INDICATION_PDU_T* list, int N, const char* hostname) {
    u_char* ip_address = NULL;
    int ip_length = 0;

    ip_address = resolve_dns(hostname, &ip_length);
    if (ip_address == NULL) {
        return;
    }

    for (int i = 0; i < N; i++) {
        list[i].RX_UE_INFORMATION_TAG = i + 1;
        list[i].RNTI = rand() % 1024;
        list[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0;
    }

    if (ip_address != NULL && ip_address != (u_char*)BACKUP_IP) {
        free(ip_address);
    }
}
