} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PacketNode {
    NetworkPacket packet;
    struct PacketNode* next;
} PacketNode;

typedef struct MemoryPool {
    void* pool;
    size_t block_size;
    size_t num_blocks;
    size_t free_block_index;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) {
        fprintf(stderr, "Failed to allocate memory for memory pool\n");
        return NULL;
    }
    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->free_block_index = 0;
    pool->pool = malloc(block_size * num_blocks);
    if (!pool->pool) {
        fprintf(stderr, "Failed to allocate memory for memory pool\n");
        free(pool);
        return NULL;
    }
    return pool;
}

void* memory_pool_alloc(MemoryPool* pool) {
    if (pool->free_block_index >= pool->num_blocks) {
        fprintf(stderr, "Memory pool out of blocks\n");
        return NULL;
    }
    void* block = ((char*)pool->pool) + (pool->block_size * pool->free_block_index);
    pool->free_block_index++;
    return block;
}

void memory_pool_free(MemoryPool* pool, void* block) {
    size_t index = ((char*)block - (char*)pool->pool) / pool->block_size;
    if (index >= pool->num_blocks || index < pool->free_block_index) {
        fprintf(stderr, "Invalid block pointer\n");
        return;
    }
    pool->free_block_index--;
}

PacketNode* create_packet_node(NetworkPacket packet) {
    PacketNode* node = (PacketNode*)memory_pool_alloc(packet_pool);
    if (!node) {
        return NULL;
    }
    node->packet = packet;
    node->next = NULL;
    return node;
}

void free_packet_node(PacketNode* node) {
    memory_pool_free(packet_pool, node);
}

