#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int payload_size;
    char* payload;
} Packet;

void process_packets(Packet** packets, int num_packets) {
    if (num_packets <= 0) {
        printf("No packets to process.\n");
        return;
    }

    // Calculate total size required for buffer
    size_t total_size = 0;
    for (int i = 0; i < num_packets; i++) {
        total_size += sizeof(int) + packets[i]->payload_size;
    }

    // Check for integer overflow
    if ((total_size / sizeof(int)) != (size_t)(total_size / sizeof(int))) {
        printf("Integer overflow detected.\n");
        return;
    }

    // Allocate buffer
    char* buffer = (char*)malloc(total_size);
    if (buffer == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Aggregate payloads into buffer
    size_t offset = 0;
    for (int i = 0; i < num_packets; i++) {
        memcpy(buffer + offset, &packets[i]->payload_size, sizeof(int));
        memcpy(buffer + offset + sizeof(int), packets[i]->payload, packets[i]->payload_size);
        offset += sizeof(int) + packets[i]->payload_size;
    }

    // Process buffer
    for (int i = 0; i < num_packets; i++) {
        int payload_size;
        memcpy(&payload_size, buffer + i * (sizeof(int) + packets[i]->payload_size), sizeof(int));
        printf("Packet %d: Payload size - %d\n", i, payload_size);
    }

    // Free allocated memory
    free(buffer);

    printf("All packets processed.\n");
}
```

