#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T** pool;
    size_t pool_size;
    size_t pool_index;
    pthread_mutex_t lock;
} NFAPI_LINKED_LIST_MANAGER_T;

NFAPI_LINKED_LIST_MANAGER_T* nfaapi_linked_list_manager_create(size_t initial_capacity) {
    NFAPI_LINKED_LIST_MANAGER_T* manager = (NFAPI_LINKED_LIST_MANAGER_T*)malloc(sizeof(NFAPI_LINKED_LIST_MANAGER_T));
    if (!manager) return NULL;

    manager->pool_size = initial_capacity;
    manager->pool_index = 0;
    manager->pool = (NFAPI_CRC_INDICATION_PDU_T**)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!manager->pool) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);

    for (size_t i = 0; i < initial_capacity; ++i) {
        manager->pool[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!manager->pool[i]) {
            for (size_t j = 0; j < i; ++j) free(manager->pool[j]);
            free(manager->pool);
            pthread_mutex_destroy(&manager->lock);
            free(manager);
            return NULL;
        }
    }

    return manager;
}

void nfaapi_linked_list_manager_destroy(NFAPI_LINKED_LIST_MANAGER_T* manager) {
    for (size_t i = 0; i < manager->pool_index; ++i) free(manager->pool[i]);
    free(manager->pool);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

NFAPI_CRC_INDICATION_PDU_T* nfaapi_linked_list_manager_allocate(NFAPI_LINKED_LIST_MANAGER_T* manager, int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    if (RX_UE_INFORMATION_TAG < 0 || RX_UE_INFORMATION_TAG > INT_MAX) return NULL;
    if (RNTI < 0 || RNTI > INT_MAX) return NULL;
    if (CRCFLAG < 0 || CRCFLAG > INT_MAX) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* node = NULL;
    pthread_mutex_lock(&manager->lock);
    if (manager->pool_index > 0) {
        node = manager->pool[--manager->pool_index];
    }
    pthread_mutex_unlock(&manager->lock);

    if (!node) {
        node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!node) return NULL;
    }

    node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    node->RNTI = RNTI;
    node->CRCFLAG = CRCFLAG;
    node->next = NULL;

    return node;
}

void nfaapi_linked_list_manager_deallocate(NFAPI_LINKED_LIST_MANAGER_T* manager, NFAPI_CRC_INDICATION_PDU_T* node) {
    pthread_mutex_lock(&manager->lock);
    if (manager->pool_index < manager->pool_size) {
        manager->pool[manager->pool_index++] = node;
    }
    pthread_mutex_unlock(&manager->lock);
}
