#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct PacketData {
    int header;
    size_t payload_length;
    void* payload_data;
} PacketData;

typedef struct ListNode {
    PacketData* packet;
    struct ListNode* next;
} ListNode;

typedef struct LinkedList {
    ListNode* head;
    ListNode* tail;
    size_t total_packets;
    size_t total_payload_size;
} LinkedList;

// Function to calculate the hash of a packet for integrity verification
size_t calculate_packet_hash(PacketData* packet) {
    // Simple hash function, can be replaced with more complex algorithms
    return (packet->header * 31 + packet->payload_length) % 1024;
}

// Function to verify the integrity of the packet data using a hash
int verify_packet_integrity(PacketData* packet, size_t expected_hash) {
    size_t actual_hash = calculate_packet_hash(packet);
    return actual_hash == expected_hash ? 1 : 0;
}

// Function to allocate memory for a new packet and its payload
PacketData* create_packet(int header, size_t payload_length, void* payload_data) {
    PacketData* packet = (PacketData*)malloc(sizeof(PacketData));
    if (!packet) {
        return NULL; // Handle memory allocation failure
    }
    packet->header = header;
    packet->payload_length = payload_length;
    packet->payload_data = malloc(payload_length);
    if (!packet->payload_data) {
        free(packet);
        return NULL; // Handle payload data allocation failure
    }
    memcpy(packet->payload_data, payload_data, payload_length);
    size_t hash = calculate_packet_hash(packet); // Store the hash for later verification
    packet->hash = hash;
    return packet;
}

// Function to insert a new packet into the linked list
void insert_packet(LinkedList* list, PacketData* packet) {
    ListNode* node = (ListNode*)malloc(sizeof(ListNode));
    if (!node) {
        free(packet);
        return; // Handle memory allocation failure
    }
    node->packet = packet;
    node->next = NULL;

    if (list->tail == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }

    list->total_packets++;
    list->total_payload_size += packet->payload_length;
}

// Function to process incoming network packets and store them in a linked list
void process_packets(LinkedList* list, PacketData** packets, int num_packets) {
    for (int i = 0; i < num_packets; i++) {
        PacketData* packet = create_packet(packets[i]->header, packets[i]->payload_length, packets[i]->payload_data);
        if (packet && verify_packet_integrity(packet, packets[i]->hash)) {
            insert_packet(list, packet);
        } else {
            free(packet); // Free the packet if it's invalid
        }
    }
}

// Function to clean up memory used by the linked list and its packets
void cleanup(LinkedList* list) {
    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* next = current->next;
        free(current->packet->payload_data);
        free(current->packet);
        free(current);
        current = next;
    }
    list->head = list->tail = NULL;
    list->total_packets = 0;
    list->total_payload_size = 0;
}
