    *num_images = 0;

    for (int i = 0; i < max_num_images; ++i) {
        size_t metadata_size_kb = rand() % (10 - 1 + 1) + 1; // Generate a random metadata size between 1KB and 10MB
        size_t metadata_size = metadata_size_kb * 1024; // Convert to bytes

        if ((SIZE_MAX - total_size) < metadata_size) {
            fprintf(stderr, "Memory allocation failed due to integer overflow.\n");
            return -1;
        }

        total_size += metadata_size;
        if (total_size > 1073741824) { // Check if total memory exceeds 1GB
            break;
        }
        (*num_images)++;
    }

    *metadata = malloc(*num_images * sizeof(ImageMetaData));
    if (*metadata == NULL) {
        fprintf(stderr, "Memory allocation failed for ImageMetaData array.\n");
        return -1;
    }

    int index = 0;
    size_t cumulative_size = 0;

    for (int i = 0; i < max_num_images; ++i) {
        if (cumulative_size + metadata[i].metadata_size > total_size) {
            break;
        }
        (*metadata)[index].id = i + 1;
        (*metadata)[index].metadata_size = metadata[i].metadata_size;
        cumulative_size += metadata[i].metadata_size;
        index++;
    }

    return *num_images;
}
