int process_images(int max_files, char *file_names[], layer_data_t **layers) {
    size_t total_metadata_size = 0;
    size_t total_raw_data_size = 0;

    // Calculate total sizes
    for (int i = 0; i < max_files; i++) {
        FILE *file = fopen(file_names[i], "rb");
        if (!file) {
            return -1; // Handle file open error
        }

        // Simulate reading metadata and raw data size from the file
        // Assuming these values are read correctly
        size_t metadata_size, raw_data_size;
        fread(&metadata_size, sizeof(size_t), 1, file);
        fread(&raw_data_size, sizeof(size_t), 1, file);

        total_metadata_size += metadata_size;
        total_raw_data_size += raw_data_size;

        fclose(file);
    }

    // Allocate memory for layers
    *layers = (layer_data_t *)malloc(max_files * sizeof(layer_data_t));
    if (!*layers) {
        return -1; // Handle memory allocation failure
    }

    // Initialize and allocate memory for each layer's data
    for (int i = 0; i < max_files; i++) {
        (*layers)[i].metadata = (metadata_t *)malloc(total_metadata_size);
        if (!(*layers)[i].metadata) {
            // Handle memory allocation failure for metadata
            free_layers(max_files, *layers);
            return -1;
        }

        (*layers)[i].raw_data = malloc(total_raw_data_size);
        if (!(*layers)[i].raw_data) {
            // Handle memory allocation failure for raw data
            free_layer_metadata(max_files, *layers);
            free((*layers)[i].metadata);
            free_layers(max_files, *layers);
            return -1;
