        (*layers)[i].metadata_size = total_metadata_size;
        (*layers)[i].raw_data_size = total_raw_data_size;

        // Simulate reading metadata and raw data from files
        // Assuming these values are read correctly
        FILE *file = fopen(file_names[i], "rb");
        fread((*layers)[i].metadata, sizeof(metadata_t), 1, file);
        fread((*layers)[i].raw_data, sizeof(char), total_raw_data_size, file);

        fclose(file);
    }

    return 0;
}

void free_layers(int max_files, layer_data_t *layers) {
    for (int i = 0; i < max_files; i++) {
        if (layers[i].metadata) {
            free(layers[i].metadata);
        }
        if (layers[i].raw_data) {
            free(layers[i].raw_data);
        }
    }
    free(layers);
}

