typedef struct {
    uint32_t width;
    uint32_t height;
    uint8_t* pixels;
} PixelData;

typedef struct {
    char* metadata;
    uint64_t pixel_size;
    PixelData pixel_data;
} ImageData;

#define MAX_CACHE_SIZE 100

ImageData image_cache[MAX_CACHE_SIZE];
int cache_count = 0;

pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

ImageData* get_image_from_cache(uint64_t hash) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_count; i++) {
        if (hash == image_cache[i].metadata) {
            pthread_mutex_unlock(&cache_lock);
            return &image_cache[i];
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return NULL;
}

void add_image_to_cache(ImageData* img, uint64_t hash) {
    pthread_mutex_lock(&cache_lock);
    if (cache_count < MAX_CACHE_SIZE) {
        image_cache[cache_count++] = *img;
    } else {
        // Cache full, replace the oldest entry
        int oldest_index = 0;
        for (int i = 1; i < cache_count; i++) {
            if (image_cache[i].metadata > image_cache[oldest_index].metadata) {
                oldest_index = i;
            }
        }
        image_cache[oldest_index] = *img;
    }
    pthread_mutex_unlock(&cache_lock);
}

ImageData* allocate_image_data(uint64_t metadata_size, uint64_t pixel_size) {
    ImageData* img = get_image_from_cache(metadata_size);
    if (img != NULL) {
        return img;
    }

    img = malloc(sizeof(ImageData));
    if (img == NULL) {
        return NULL; // Handle memory allocation failure
    }

    img->metadata = malloc(metadata_size);
    if (img->metadata == NULL) {
        free(img);
        return NULL; // Handle metadata allocation failure
    }

    img->pixel_data.pixels = malloc(pixel_size * sizeof(uint8_t));
    if (img->pixel_data.pixels == NULL) {
        free(img->metadata);
        free(img);
        return NULL; // Handle pixel data allocation failure
    }

    img->pixel_data.width = 0;
    img->pixel_data.height = 0;
    img->pixel_size = pixel_size;

    add_image_to_cache(img, metadata_size);

    return img;
}

void deallocate_image_data(ImageData* img) {
    if (img == NULL) {
        return; // Handle null pointer
    }

    free(img->metadata);
    free(img->pixel_data.pixels);
    free(img);
}

