        printf("Enter pixel size for image %lu: ", i);
        scanf("%lu", &pixel_size);

        ImageData* img = allocate_image_data(metadata_size, pixel_size);
        if (img == NULL) {
            printf("Failed to allocate memory for image %lu\n", i);
            continue; // Handle allocation failure
        }

        // Initialize metadata and pixel data...

        deallocate_image_data(img);
    }

    return 0;
}
