double processTransactions(Transaction* transactions, int transactionCount) {
    static Transaction window[10000];
    static int windowSize = 0;
    static time_t lastWindowStart = 0;

    if (transactions[transactionCount - 1].timestamp > lastWindowStart + 3) {
        // New 3-second window starts
        windowSize = 0;
        lastWindowStart = transactions[transactionCount - 1].timestamp;
    }

    double totalVolume = 0.0;
    for (int i = transactionCount - 1; i >= 0 && transactions[i].timestamp >= lastWindowStart; --i) {
        if (i + windowSize >= 10000) {
            // Resize the window if necessary
            memmove(window, &window[1], windowSize * sizeof(Transaction));
            windowSize--;
        }
        window[windowSize++] = transactions[i];
        totalVolume += transactions[i].amount;
    }

    return totalVolume;
}

int main() {
