#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

#define MAX_PACKETS 1024
#define MAX_PAYLOAD_SIZE (1 * 1024 * 1024) // 1GB

typedef struct {
    int id;
    long timestamp;
    size_t payload_size;
} PacketMetadata;

typedef struct {
    PacketMetadata *packets[MAX_PACKETS];
    int count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int max_threads;
} PacketProcessingPipeline;

PacketProcessingPipeline *pipeline;

void* process_packet(void *arg) {
    PacketMetadata *packet = (PacketMetadata *)arg;
    // Process the packet
    free(packet);
    pthread_mutex_lock(&pipeline->mutex);
    pipeline->count--;
    pthread_cond_signal(&pipeline->cond);
    pthread_mutex_unlock(&pipeline->mutex);
    return NULL;
}

void enqueue_packet(int id, long timestamp, size_t payload_size) {
    if (payload_size > MAX_PAYLOAD_SIZE || payload_size == 0) {
        fprintf(stderr, "Invalid payload size\n");
        return;
    }

    PacketMetadata *packet = malloc(sizeof(PacketMetadata));
    if (!packet) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    packet->id = id;
    packet->timestamp = timestamp;
    packet->payload_size = payload_size;

    pthread_mutex_lock(&pipeline->mutex);
    while (pipeline->count >= pipeline->max_threads) {
        pthread_cond_wait(&pipeline->cond, &pipeline->mutex);
    }
    pipeline->packets[pipeline->count++] = packet;
    pthread_cond_signal(&pipeline->cond);
    pthread_mutex_unlock(&pipeline->mutex);

    pthread_t thread;
    pthread_create(&thread, NULL, process_packet, packet);
    pthread_detach(thread);
}

void init_pipeline(int max_threads) {
    pipeline = malloc(sizeof(PacketProcessingPipeline));
    if (!pipeline) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    pipeline->count = 0;
    pthread_mutex_init(&pipeline->mutex, NULL);
    pthread_cond_init(&pipeline->cond, NULL);
    pipeline->max_threads = max_threads;

    for (int i = 0; i < MAX_PACKETS; i++) {
        pipeline->packets[i] = NULL;
    }
}

void destroy_pipeline() {
    pthread_mutex_lock(&pipeline->mutex);
    while (pipeline->count > 0) {
        pthread_cond_wait(&pipeline->cond, &pipeline->mutex);
    }
    pthread_mutex_unlock(&pipeline->mutex);

    for (int i = 0; i < MAX_PACKETS; i++) {
        if (pipeline->packets[i]) {
            free(pipeline->packets[i]);
        }
    }

    free(pipeline);
}

int main() {
    init_pipeline(16); // Example with 16 threads

    // Simulate packet processing
    for (int i = 0; i < 50; i++) {
        enqueue_packet(i, time(NULL), rand() % MAX_PAYLOAD_SIZE);
    }

    destroy_pipeline();
    return 0;
}
