// Define a structure to hold thumbnail data
typedef struct {
    unsigned int width;
    unsigned int height;
    unsigned char* pixels; // Pointer to the pixel data
    void* metadata;        // Pointer to additional metadata (e.g., EXIF data)
} Thumbnail;

// Function to create a new thumbnail with initial size and allocate memory for it
Thumbnail* create_thumbnail(unsigned int width, unsigned int height) {
    Thumbnail* thumb = malloc(sizeof(Thumbnail));
    if (!thumb) return NULL; // Handle memory allocation failure

    // Calculate the required pixel buffer size
    size_t pixels_size = width * height * sizeof(unsigned char);
    if (pixels_size == 0 || pixels_size / (width * height) != sizeof(unsigned char)) {
        free(thumb); // Prevent integer overflow
        return NULL;
    }

    thumb->width = width;
    thumb->height = height;
    thumb->pixels = malloc(pixels_size);
    if (!thumb->pixels) {
        free(thumb); // Free allocated structure on failure
        return NULL;
    }

    thumb->metadata = NULL; // Initialize metadata to NULL

    return thumb;
}

// Function to set thumbnail data (e.g., from a file or another source)
void set_thumbnail_data(Thumbnail* thumb, unsigned char* new_pixels) {
    if (!thumb || !new_pixels) return;

    size_t pixels_size = thumb->width * thumb->height * sizeof(unsigned char);
    free(thumb->pixels); // Free old pixel data
    thumb->pixels = malloc(pixels_size);
    if (thumb->pixels) {
        memcpy(thumb->pixels, new_pixels, pixels_size);
    }
}

// Function to set metadata for a thumbnail
void set_thumbnail_metadata(Thumbnail* thumb, void* new_metadata) {
    if (!thumb) return;

    free(thumb->metadata); // Free old metadata
    thumb->metadata = malloc(sizeof(new_metadata));
    if (thumb->metadata) {
        memcpy(thumb->metadata, new_metadata, sizeof(new_metadata));
    }
}

// Function to destroy a thumbnail and free its memory
void destroy_thumbnail(Thumbnail* thumb) {
    if (!thumb) return;

    free(thumb->pixels);
    free(thumb->metadata);
    free(thumb);
}
