#define MAX_HEADERS_PER_PACKET 10000

typedef struct Header {
    void* data;
    size_t size;
} Header;

typedef struct PacketMetadata {
    Header** headers;
    int headerCount;
    // Other packet metadata fields can be added here
} PacketMetadata;

PacketMetadata* processBatchOfPackets(int packetCount, size_t maxMemoryUsage) {
    PacketMetadata* packetList = malloc(packetCount * sizeof(PacketMetadata));
    if (packetList == NULL) {
        perror("Failed to allocate memory for packet list");
        return NULL;
    }

    size_t totalAllocatedMemory = 0;

    for (int i = 0; i < packetCount; i++) {
        packetList[i].headerCount = rand() % (MAX_HEADERS_PER_PACKET + 1); // Simulate random number of headers
        packetList[i].headers = malloc(packetList[i].headerCount * sizeof(Header*));
        if (packetList[i].headers == NULL) {
            perror("Failed to allocate memory for headers");
            free(packetList);
            return NULL;
        }

        size_t packetMemoryUsage = 0;

        for (int j = 0; j < packetList[i].headerCount; j++) {
            packetList[i].headers[j] = malloc(sizeof(Header));
            if (packetList[i].headers[j] == NULL) {
                perror("Failed to allocate memory for header");
                // Clean up previously allocated memory
                for (int k = 0; k < j; k++) {
                    free(packetList[i].headers[k]);
                }
                free(packetList[i].headers);
                free(packetList);
                return NULL;
            }

            packetList[i].headers[j]->size = rand() % 1024 + 1; // Simulate random header size
            packetList[i].headers[j]->data = malloc(packetList[i].headers[j]->size * sizeof(char));
            if (packetList[i].headers[j]->data == NULL) {
                perror("Failed to allocate memory for header data");
                // Clean up previously allocated memory
                free(packetList[i].headers[j]);
                for (int k = 0; k < j; k++) {
                    free(packetList[i].headers[k]);
                }
                free(packetList[i].headers);
                free(packetList);
                return NULL;
            }

            packetMemoryUsage += sizeof(Header) + packetList[i].headers[j]->size * sizeof(char);

            if (totalAllocatedMemory + packetMemoryUsage > maxMemoryUsage) {
                fprintf(stderr, "Exceeded memory usage limit\n");
                // Clean up previously allocated memory
                for (int k = 0; k < j; k++) {
                    free(packetList[i].headers[k]->data);
                    free(packetList[i].headers[k]);
                }
                free(packetList[i].headers);
                free(packetList);
                return NULL;
            }

            totalAllocatedMemory += packetMemoryUsage;
        }
    }

    return packetList;
}

int main() {
    int packetCount = 10; // Example packet count
    size_t maxMemoryUsage = 5 * 1024 * 1024; // Example maximum memory usage (5MB)

    PacketMetadata* packetList = processBatchOfPackets(packetCount, maxMemoryUsage);
    if (packetList != NULL) {
        printf("Successfully processed %d packets\n", packetCount);
        // Clean up allocated memory
        for (int i = 0; i < packetCount; i++) {
            for (int j = 0; j < packetList[i].headerCount; j++) {
                free(packetList[i].headers[j]->data);
                free(packetList[i].headers[j]);
            }
            free(packetList[i].headers);
        }
        free(packetList);
    }

    return 0;
}
