int resolve_hostname(char* hostname, char* ip) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // or AF_UNSPEC to allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in* h = (struct sockaddr_in*)p->ai_addr;
        inet_ntop(p->ai_family, &h->sin_addr, ip, MAX_IP_LEN);
        break;
    }

    freeaddrinfo(res);

    return 0;
}

int main() {
    int n = 10; // Number of elements in the list
    char hostname[] = "example.com";
    char ip[MAX_IP_LEN];
    int retry_count = 3;

    pthread_t thread;
    int* arg = (int*)malloc(sizeof(int));
    *arg = n;

    if (pthread_create(&thread, NULL, populate_list, arg) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        return -1;
    }

    for (int i = 0; i < retry_count; i++) {
        if (resolve_hostname(hostname, ip) == 0) {
            break;
        }
    }

    if (i == retry_count) {
        // Fallback to predefined list of backup IPs
        char* backup_ips[] = {"192.168.1.1", "192.168.1.2"};
        for (int j = 0; j < sizeof(backup_ips) / sizeof(backup_ips[0]); j++) {
            if (resolve_hostname(backup_ips[j], ip) == 0) {
                break;
            }
        }

        if (j == sizeof(backup_ips) / sizeof(backup_ips[0])) {
            fprintf(stderr, "DNS resolution failed and no backup IPs available\n");
            return -1;
        }
    }

    // Continue with the operation using the resolved IP address

    pthread_join(thread, NULL);
    free(arg);

    return 0;
}
