#include <stdio.h>
#include <stdlib.h>

#define MAX_STRUCTS 10000
#define BATCH_SIZE 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t length;
    size_t capacity;
} LinkedList;

LinkedList* createLinkedList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    list->length = 0;
    list->capacity = BATCH_SIZE;
    return list;
}

int addElement(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->length >= list->capacity) {
        // Resize the linked list
        size_t newCapacity = list->capacity + BATCH_SIZE;
        Node** newArray = realloc(list->head, newCapacity * sizeof(Node));
        if (!newArray) return -1; // Memory allocation failed
        list->head = newArray;
        list->capacity = newCapacity;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -1; // Memory allocation failed

    newNode->data = data;
    newNode->next = NULL;

    if (list->length == 0) {
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    list->length++;
    return 0; // Success
}

void freeLinkedList(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}
```

