void init_mem_pool(MEM_POOL_T *pool, size_t initial_size) {
    pool->memory_pool = malloc(initial_size);
    if (pool->memory_pool == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pool->pool_size = initial_size;
    pool->used_memory = 0;
