void* allocate_from_pool(MEM_POOL_T *pool, size_t size) {
    size_t aligned_size = (size + 15) & ~15; // Align to 16-byte boundary
    if (pool->used_memory + aligned_size > pool->pool_size) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    void* mem = (char*)pool->memory_pool + pool->used_memory;
    pool->used_memory += aligned_size;
    return mem;
}

int process_packet_headers(PACKET_HEADER_T *headers, size_t num_packets) {
