typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t size;
    void* memory_pool;
    size_t pool_size;
} LinkedList;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data, void** memory_pool, size_t* pool_size) {
    if (*pool_size < sizeof(Node)) return NULL;

    Node* new_node = (Node*)*memory_pool;
    *memory_pool += sizeof(Node);
    *pool_size -= sizeof(Node);

    new_node->data = data;
    new_node->next = NULL;

    return new_node;
}

bool append_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data, &list->memory_pool, &list->pool_size);
    if (!new_node) return false;

    if (list->size == 0) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    list->size++;

    return true;
}

void initialize_list(LinkedList* list, void* memory_pool, size_t pool_size) {
    list->head = NULL;
    list->size = 0;
    list->memory_pool = memory_pool;
    list->pool_size = pool_size;
}

