    time_t now = time(NULL);
    printf("[%s] Action: %s, Node ID: %lu\n", ctime(&now), action, node_id);
}

void garbage_collection(LinkedList* list) {
    Node* current = list->head;
    Node* prev = NULL;

    while (current != NULL) {
        if (!current->data.critical_flag && list_size(list) > 1000) { // Example condition for garbage collection
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }

            void* old_node_memory = current;
            current = current->next;
            list->pool_size += sizeof(Node);
        } else {
            prev = current;
            current = current->next;
        }
    }
}

size_t list_size(LinkedList* list) {
    return list->size;
}
