#define MAX_PACKET_SIZE 1024 * 1024 // 1 megabyte
#define BUFFER_INCREMENT 1024 * 1024 // Increase buffer by 1MB when needed

typedef struct {
    size_t payload_size;
    char* payload_data;
} NetworkPacket;

int process_packets(NetworkPacket* packets, int packet_count) {
    char* output_buffer = NULL;
    size_t total_payload_size = 0;
    size_t buffer_size = 0;

    for (int i = 0; i < packet_count; i++) {
        // Calculate the new total payload size
        size_t new_total_size = total_payload_size + packets[i].payload_size;

        // Check if we need to resize the output buffer
        if (new_total_size > buffer_size) {
            while (new_total_size > buffer_size) {
                buffer_size += BUFFER_INCREMENT;
                void* new_buffer = realloc(output_buffer, buffer_size);
                if (new_buffer == NULL) {
                    fprintf(stderr, "Failed to reallocate memory: %s\n", strerror(errno));
                    free(output_buffer);
                    return -1; // Memory allocation failure
                }
                output_buffer = new_buffer;
            }
        }

        // Copy the payload into the output buffer
        memcpy(output_buffer + total_payload_size, packets[i].payload_data, packets[i].payload_size);
        total_payload_size = new_total_size;

        // Log discrepancies between expected and actual sizes if necessary
        if (packets[i].payload_size != expected_sizes[i]) {
            fprintf(stderr, "Payload size discrepancy at packet %d: Expected %zu, got %zu\n", i, expected_sizes[i], packets[i].payload_size);
        }
    }

    // Process the output buffer as needed
    // ...

    free(output_buffer);
    return 0; // Success
}
