void populateLinkedList(NFAPI_CRC_INDICATION_PDU_T **head, int *count, int N, int MAX_STRUCTURES) {
    srand(time(NULL));
    for (int i = 0; i < N; ++i) {
        if (*count >= MAX_STRUCTURES) break;

        NFAPI_CRC_INDICATION_PDU_T *newNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newNode) {
            printf("Memory allocation failed.\n");
            continue;
        }

        newNode->RX_UE_INFORMATION_TAG = rand() % 100; // Assuming a range for simplicity
        int rnti = rand() % 4096; // Range based on typical RNTI values
        while (!isRntiUnique(*head, *count, rnti)) {
            rnti = rand() % 4096;
        }
        newNode->RNTI = rnti;

        newNode->CRC_INDICATION_REL8_TAG = rand() % 100; // Assuming a range for simplicity
        newNode->CRCFLAG = (unsigned char)(rand() % 16);

        newNode->next = NULL;
        if (*head == NULL) {
            *head = newNode;
        } else {
            NFAPI_CRC_INDICATION_PDU_T *temp = *head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = newNode;
        }

        (*count)++;
    }
}

