    printf("Enter the maximum allowed structures: ");
    scanf("%d", &MAX_STRUCTURES);

    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    int count = 0;

    populateLinkedList(&head, &count, N, MAX_STRUCTURES);

    // Free allocated memory
    while (head != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = head;
        head = head->next;
        free(temp);
    }

    return 0;
}
