#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct PacketSegment {
    int id;
    size_t length;
    unsigned char* data;
} PacketSegment;

typedef struct Packet {
    PacketSegment** segments;
    size_t segment_count;
    size_t max_segments;
    pthread_mutex_t mutex;
} Packet;

Packet* create_packet(size_t max_segments) {
    Packet* packet = (Packet*)malloc(sizeof(Packet));
    if (!packet) return NULL;

    packet->segments = (PacketSegment**)malloc(max_segments * sizeof(PacketSegment*));
    if (!packet->segments) {
        free(packet);
        return NULL;
    }

    memset(packet->segments, 0, max_segments * sizeof(PacketSegment*));
    packet->segment_count = 0;
    packet->max_segments = max_segments;
    pthread_mutex_init(&packet->mutex, NULL);

    return packet;
}

int add_segment_to_packet(Packet* packet, int id, size_t length, unsigned char* data) {
    pthread_mutex_lock(&packet->mutex);
    if (packet->segment_count >= packet->max_segments) {
        pthread_mutex_unlock(&packet->mutex);
        return -1; // Packet is full
    }

    PacketSegment* segment = (PacketSegment*)malloc(sizeof(PacketSegment));
    if (!segment) {
        pthread_mutex_unlock(&packet->mutex);
        return -2; // Memory allocation failed
    }

    segment->id = id;
    segment->length = length;
    segment->data = (unsigned char*)malloc(length * sizeof(unsigned char));
    if (!segment->data) {
        free(segment);
        pthread_mutex_unlock(&packet->mutex);
        return -3; // Memory allocation failed
    }
    memcpy(segment->data, data, length);

    packet->segments[packet->segment_count++] = segment;
    pthread_mutex_unlock(&packet->mutex);
    return 0;
}

void free_packet(Packet* packet) {
    pthread_mutex_lock(&packet->mutex);
    for (size_t i = 0; i < packet->segment_count; ++i) {
        if (packet->segments[i]) {
            free(packet->segments[i]->data);
            free(packet->segments[i]);
        }
    }
    free(packet->segments);
    pthread_mutex_unlock(&packet->mutex);
    pthread_mutex_destroy(&packet->mutex);
    free(packet);
}
