    struct LinkedListNode* next;
} LinkedListNode;

LinkedListNode* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    LinkedListNode* new_node = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    if (new_node == NULL) {
        return NULL; // Handle memory allocation failure
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

int insert_node(LinkedListNode** head, NFAPI_CRC_INDICATION_PDU_T data, int max_elements, int* current_size) {
    if (*current_size >= max_elements) {
        printf("Maximum number of elements reached. Cannot insert more.\n");
        return -1; // Maximum size exceeded
    }
    LinkedListNode* new_node = create_node(data);
    if (new_node == NULL) {
        return -2; // Memory allocation failure
    }
    if (*head == NULL) {
        *head = new_node;
    } else {
        LinkedListNode* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
    (*current_size)++;
    return 0; // Insertion successful
}

int delete_list(LinkedListNode** head, int* current_size) {
    LinkedListNode* current = *head;
    LinkedListNode* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
    *current_size = 0;
    return 0; // List deletion successful
}

int get_current_size(LinkedListNode* head) {
    int count = 0;
    LinkedListNode* temp = head;
    while (temp != NULL) {
        count++;
        temp = temp->next;
    }
    return count;
}
