#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define RX_UE_INFORMATION_TAG 0x12345678
#define RNTI 1234
#define CRC_INDICATION_REL8_TAG 0x9ABCDEF0

typedef struct {
    uint32_t tag;
    uint16_t rnti;
    uint32_t crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    size_t block_size;
    size_t num_blocks;
    void** blocks;
    size_t free_index;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->blocks = (void**)malloc(num_blocks * sizeof(void*));
    if (!pool->blocks) {
        free(pool);
        return NULL;
    }

    for (size_t i = 0; i < num_blocks; ++i) {
        pool->blocks[i] = malloc(block_size);
        if (!pool->blocks[i]) {
            for (size_t j = 0; j < i; ++j) free(pool->blocks[j]);
            free(pool->blocks);
            free(pool);
            return NULL;
        }
    }

    pool->free_index = 0;
    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    for (size_t i = 0; i < pool->num_blocks; ++i) free(pool->blocks[i]);
    free(pool->blocks);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(MemoryPool* pool) {
    if (pool->free_index >= pool->num_blocks) return NULL;
    NFAPI_CRC_INDICATION_PDU_T* block = (NFAPI_CRC_INDICATION_PDU_T*)pool->blocks[pool->free_index++];
    return block;
}

void deallocate_to_pool(MemoryPool* pool, void* block) {
    for (size_t i = 0; i < pool->num_blocks; ++i) {
        if (pool->blocks[i] == block) {
            pool->blocks[--pool->free_index] = block;
            return;
        }
    }
}

int populate_crc_indications(size_t num_structures, size_t MAX_MEMORY_SIZE) {
    const size_t STRUCT_SIZE = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (num_structures == 0 || MAX_MEMORY_SIZE < num_structures * STRUCT_SIZE) return -1;

    MemoryPool* pool = create_memory_pool(STRUCT_SIZE, num_structures);
    if (!pool) return -1;

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (size_t i = 0; i < num_structures; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_from_pool(pool);
        if (!pdu) break;

        pthread_mutex_lock(&mutex);
        pdu->tag = RX_UE_INFORMATION_TAG;
        pdu->rnti = RNTI;
        pdu->crc_flag = rand() % 2; // Randomly set CRCFLAG
        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);
    destroy_memory_pool(pool);

    return 0;
}
