    for (size_t i = 0; i < library->count; i++) {
        Image* img = library->images[i];
        free(img->data);
        free(img);
    }

    free(library->images);
    free(library);
}

int add_image_to_library(ImageLibrary* library, const char* filepath, int width, int height) {
    if (library->count >= library->capacity) {
        size_t new_capacity = library->capacity * 2; // Doubling the capacity
        Image** new_images = realloc(library->images, new_capacity * sizeof(Image*));
        if (new_images == NULL) {
            return -1; // Handle memory allocation failure
        }
        library->images = new_images;
        library->capacity = new_capacity;
    }

    Image* img = malloc(sizeof(Image));
    if (img == NULL) {
        return -1; // Handle memory allocation failure
    }

    img->data = malloc(width * height); // Assuming raw data is continuous and of known size
    if (img->data == NULL) {
        free(img);
        return -1; // Handle memory allocation failure
    }

    strncpy(img->filepath, filepath, sizeof(img->filepath));
    img->width = width;
    img->height = height;

    library->images[library->count++] = img;

    return 0;
}

// Example usage:
int main() {
    ImageLibrary* lib = create_image_library(10);
    if (lib == NULL) {
        fprintf(stderr, "Failed to create image library\n");
        return 1;
    }

    if (add_image_to_library(lib, "/path/to/image.jpg", 800, 600) != 0) {
        fprintf(stderr, "Failed to add image to library\n");
        destroy_image_library(lib);
        return 1;
    }

    // Clean up
    destroy_image_library(lib);

    return 0;
}
```

### Explanation:
- **Image Structure**: Contains metadata (`filepath`, `width`, `height`) and a pointer to the raw image data.
- **ImageLibrary Structure**: Manages an array of Image pointers, tracking the current count and capacity.
- **Memory Allocation**: Uses `malloc` and `realloc` for dynamic memory management. Handles potential integer overflows by ensuring sufficient capacity when reallocating.
- **Error Handling**: Checks for successful memory allocations and returns errors if allocation fails.

This implementation provides a basic framework that can be expanded with additional features like image loading from files, metadata parsing, and more advanced memory management techniques as needed.']

