            allocation_errors++;
            continue;
        }

        new_packet->payload = malloc(received_packet_size);
        if (!new_packet->payload) {
            free(new_packet);
            allocation_errors++;
            continue;
        }

        // Simulate packet payload processing
        memset(new_packet->payload, 0, received_packet_size);
        new_packet->length = received_packet_size;

        packets[i] = new_packet;
        total_allocated++;

        if (rand() % timeout_ms == 0) {
            lost_due_to_timeout++;
            free(new_packet->payload);
            free(new_packet);
            total_allocated--;
        }
    }

