typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *buffer;
    size_t buffer_size;
    size_t used_memory;
    size_t head;
    size_t tail;
    size_t count;
} BufferPool;

BufferPool* create_buffer_pool(size_t max_requests) {
    BufferPool *pool = (BufferPool*)malloc(sizeof(BufferPool));
    pool->buffer = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_requests * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->buffer_size = max_requests * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pool->used_memory = 0;
    pool->head = 0;
    pool->tail = 0;
    pool->count = 0;
    return pool;
}

bool buffer_pool_allocate(BufferPool *pool) {
    if (pool->used_memory + sizeof(NFAPI_CRC_INDICATION_PDU_T) > MAX_MEM_SIZE) {
        return false; // Memory limit exceeded
    }
    if (pool->count >= pool->buffer_size / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return false; // Buffer pool full
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &pool->buffer[pool->tail];
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000; // Random tag example
    pdu->RNTI = rand() % 4096; // Random RNTI example
    pdu->CRC_INDICATION_REL8_TAG = (rand() % 2) == 0; // Random CRC flag

    pool->tail = (pool->tail + 1) % pool->buffer_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pool->used_memory += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pool->count++;
    return true;
}

size_t buffer_pool_count(BufferPool *pool) {
    return pool->count;
}

void destroy_buffer_pool(BufferPool *pool) {
    free(pool->buffer);
    free(pool);
}
