['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1024

typedef struct Packet {
    int length;
    char data[MAX_PACKET_SIZE];
    struct Packet* next;
} Packet;

typedef struct PacketPool {
    Packet* free_packets;
    size_t max_memory_usage;
    size_t current_memory_usage;
    pthread_mutex_t mutex;
} PacketPool;

Packet* create_packet(int length) {
    if (length <= 0 || length > MAX_PACKET_SIZE) {
        return NULL;
    }
    Packet* packet = (Packet*)malloc(sizeof(Packet));
    if (packet == NULL) {
        return NULL;
    }
    packet->length = length;
    memset(packet->data, 0, length);
    packet->next = NULL;
    return packet;
}

void free_packet(Packet* packet) {
    if (packet != NULL) {
        free(packet);
    }
}

PacketPool* create_pool(size_t max_memory_usage) {
    PacketPool* pool = (PacketPool*)malloc(sizeof(PacketPool));
    if (pool == NULL) {
        return NULL;
    }
    pool->max_memory_usage = max_memory_usage;
    pool->current_memory_usage = 0;
    pool->free_packets = NULL;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

void destroy_pool(PacketPool* pool) {
    if (pool != NULL) {
        Packet* current = pool->free_packets;
        while (current != NULL) {
            Packet* next = current->next;
            free_packet(current);
            current = next;
        }
        pthread_mutex_destroy(&pool->mutex);
        free(pool);
    }
}

Packet* allocate_packet(PacketPool* pool, int length) {
    if (length <= 0 || length > MAX_PACKET_SIZE) {
        return NULL;
    }
    Packet* packet = NULL;
    pthread_mutex_lock(&pool->mutex);
    if (pool->current_memory_usage + length <= pool->max_memory_usage) {
        if (pool->free_packets != NULL) {
            packet = pool->free_packets;
            pool->free_packets = pool->free_packets->next;
        } else {
            packet = create_packet(length);
        }
        if (packet != NULL) {
            pool->current_memory_usage += length;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
    return packet;
}

void deallocate_packet(PacketPool* pool, Packet* packet) {
    if (packet != NULL) {
        pthread_mutex_lock(&pool->mutex);
        if (pool->current_memory_usage >= packet->length) {
            packet->next = pool->free_packets;
            pool->free_packets = packet;
            pool->current_memory_usage -= packet->length;
        }
        pthread_mutex_unlock(&pool->mutex);
    }
}

void reclaim_memory(PacketPool* pool, size_t target_usage) {
    if (target_usage <= 0 || target_usage >= pool->max_memory_usage) {
        return;
    }
    pthread_mutex_lock(&pool->mutex);
    while (pool->current_memory_usage > target_usage && pool->free_packets != NULL) {
        Packet* packet = pool->free_packets;
        pool->free_packets = pool->free_packets->next;
        free_packet(packet);
        pool->current_memory_usage -= packet->length;
    }
    pthread_mutex_unlock(&pool->mutex);
}

void* thread_function(void* arg) {
    PacketPool* pool = (PacketPool*)arg;
    int lengths[] = {100, 200, 300, 400, 500};
    for (int i = 0; i < 5; i++) {
        Packet* packet = allocate_packet(pool, lengths[i]);
        if (packet != NULL) {
            printf("Allocated packet of size %d\n", packet->length);
            deallocate_packet(pool, packet);
        } else {
            printf("Failed to allocate packet of size %d\n", lengths[i]);
        }
    }
    return NULL;
}

int main() {
    PacketPool* pool = create_pool(1024 * 1024); // 1 MB
    if (pool != NULL) {
        pthread_t threads[5];
        for (int i = 0; i < 5; i++) {
            pthread_create(&threads[i], NULL, thread_function, pool);
        }
        for (int i = 0; i < 5; i++) {
            pthread_join(threads[i], NULL);
        }
        reclaim_memory(pool, 512 * 1024); // Reclaim to 50% of max memory usage
        destroy_pool(pool);
    }
    return 0;
}
