#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEM_SIZE 1048576 // 1MB

typedef struct {
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    size_t max_size;
    pthread_mutex_t mutex;
} Pool;

Pool* create_pool(size_t N, float crc_prob) {
    if (N > MAX_MEM_SIZE / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fprintf(stderr, "Error: Requested pool size exceeds maximum memory limit.\n");
        return NULL;
    }

    Pool* pool = (Pool*)malloc(sizeof(Pool));
    if (!pool) {
        perror("Failed to allocate memory for pool.");
        return NULL;
    }

    pool->head = NULL;
    pool->count = 0;
    pool->max_size = N;
    pthread_mutex_init(&pool->mutex, NULL);

    Node* current = NULL;
    for (size_t i = 0; i < N; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            perror("Failed to allocate memory for node.");
            destroy_pool(pool);
            return NULL;
        }

        new_node->data.CRCFLAG = ((float)rand() / RAND_MAX < crc_prob);
        new_node->next = NULL;

        if (current == NULL) {
            pool->head = current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    return pool;
}

void destroy_pool(Pool* pool) {
    pthread_mutex_lock(&pool->mutex);
    Node* current = pool->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&pool->mutex);

    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

void* get_node(Pool* pool) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->count == 0) {
        pthread_mutex_unlock(&pool->mutex);
        return NULL;
    }

    Node* node = pool->head;
    pool->head = node->next;
    --pool->count;

    pthread_mutex_unlock(&pool->mutex);
    return &node->data;
}

void free_node(Pool* pool, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->count == pool->max_size) {
        pthread_mutex_unlock(&pool->mutex);
        return; // Pool is full
    }

    Node* node = (Node*)((char*)data - offsetof(Node, data));
    node->next = pool->head;
    pool->head = node;
    ++pool->count;

    pthread_mutex_unlock(&pool->mutex);
}

void log_node_operation(Pool* pool, const char* operation, double time_taken) {
    // Custom logging mechanism implementation
    printf("Operation: %s, Time Taken: %.6f seconds\n", operation, time_taken);
}
```

