NFAPI_CRC_INDICATION_PDU_T* populate_nfaip_pdu_array(const char* filename, size_t* num_structs) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open input file");
        return NULL;
    }

    // Read the number of structures from the file
    size_t num_elements;
    if (fread(&num_elements, sizeof(size_t), 1, file) != 1) {
        perror("Failed to read number of elements");
        fclose(file);
        return NULL;
    }

    *num_structs = num_elements;

    // Validate the number of structures
    if (num_elements == 0 || num_elements > 10000) {
        fprintf(stderr, "Invalid number of structures: %zu\n", num_elements);
        fclose(file);
        return NULL;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("Memory allocation failed");
        fclose(file);
        return NULL;
    }

    // Populate the array with data from the file
    size_t elements_read = fread(pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T), num_elements, file);
    if (elements_read != num_elements) {
        fprintf(stderr, "Failed to read all structures: %zu/%zu\n", elements_read, num_elements);
        free(pdus);
        fclose(file);
        return NULL;
    }

    // Close the file
    fclose(file);

    return pdus;
}

// Example usage
