    NFAPI_CRC_INDICATION_PDU_T* pdus = populate_nfaip_pdu_array("input.bin", &num_structs);
    if (pdus) {
        printf("Successfully populated %zu structures\n", num_structs);
        // Process the structures as needed
        free(pdus);
    }
    return 0;
}
