    Packet packets[MAX_PACKETS];
    int count;
    pthread_mutex_t lock;
} PacketQueue;

PacketQueue packetQueue;

void initPacketQueue() {
    memset(&packetQueue, 0, sizeof(PacketQueue));
    pthread_mutex_init(&packetQueue.lock, NULL);
}

void enqueuePacket(Packet *packet) {
    pthread_mutex_lock(&packetQueue.lock);
    if (packetQueue.count < MAX_PACKETS) {
        memcpy(&packetQueue.packets[packetQueue.count], packet, sizeof(Packet));
        packetQueue.count++;
    } else {
        fprintf(stderr, "Error: Packet queue is full\n");
    }
    pthread_mutex_unlock(&packetQueue.lock);
}

Packet dequeuePacket() {
    Packet packet;
    pthread_mutex_lock(&packetQueue.lock);
    if (packetQueue.count > 0) {
        memcpy(&packet, &packetQueue.packets[packetQueue.count - 1], sizeof(Packet));
        packetQueue.count--;
    } else {
        fprintf(stderr, "Error: Packet queue is empty\n");
        memset(&packet, 0, sizeof(Packet));
    }
    pthread_mutex_unlock(&packetQueue.lock);
    return packet;
}

void processPacketHeaders() {
    for (int i = 0; i < packetQueue.count; i++) {
        Packet packet = dequeuePacket();
        if (isValidPacketHeader(packet)) {
