#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 * 5 // Example: 5MB limit

typedef struct Thumbnail {
    void* data;
    size_t size;
} Thumbnail;

typedef struct ThumbnailManager {
    Thumbnail** thumbnails;
    size_t count;
    size_t capacity;
    size_t allocated_memory;
} ThumbnailManager;

void initThumbnailManager(ThumbnailManager* manager) {
    manager->thumbnails = NULL;
    manager->count = 0;
    manager->capacity = 16; // Initial capacity
    manager->allocated_memory = 0;
}

void freeThumbnailManager(ThumbnailManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->thumbnails[i]->data);
        free(manager->thumbnails[i]);
    }
    free(manager->thumbnails);
    manager->thumbnails = NULL;
    manager->count = 0;
    manager->capacity = 0;
    manager->allocated_memory = 0;
}

void addThumbnail(ThumbnailManager* manager, const void* data, size_t size) {
    if (manager->allocated_memory + size > MAX_MEMORY_LIMIT) {
        printf("Memory limit exceeded\n");
        return;
    }

    Thumbnail* newThumbnail = (Thumbnail*)malloc(sizeof(Thumbnail));
    newThumbnail->data = malloc(size);
    memcpy(newThumbnail->data, data, size);
    newThumbnail->size = size;

    if (manager->count >= manager->capacity) {
        manager->capacity *= 2;
        manager->thumbnails = realloc(manager->thumbnails, sizeof(Thumbnail*) * manager->capacity);
    }

    manager->thumbnails[manager->count++] = newThumbnail;
    manager->allocated_memory += size;
}

void removeThumbnail(ThumbnailManager* manager, size_t index) {
    if (index >= manager->count) return;

    free(manager->thumbnails[index]->data);
    free(manager->thumbnails[index]);

    for (size_t i = index; i < manager->count - 1; ++i) {
        manager->thumbnails[i] = manager->thumbnails[i + 1];
    }

    --manager->count;
}

// Example usage
int main() {
    ThumbnailManager manager;
    initThumbnailManager(&manager);

    // Simulate adding and removing thumbnails
    addThumbnail(&manager, "image_data_1", 1024 * 1024); // 1MB image data
    removeThumbnail(&manager, 0);

    freeThumbnailManager(&manager);
    return 0;
}
