#include <pthread.h>

typedef struct {
    // Define your RX_UE_INFORMATION_TAG structure here
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint16_t value;
} RNTI;

typedef struct {
    uint8_t CRCFLAG;
