typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxueinfo;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcindicationrel8;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPoolNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct MemoryPoolNode* next;
} MemoryPoolNode;

typedef struct MemoryPool {
    MemoryPoolNode* freeList;
    size_t nodeSize;
    size_t poolSize;
    size_t growthIncrement;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* createMemoryPool(size_t initialSize, size_t growthIncrement) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->nodeSize = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pool->poolSize = initialSize;
    pool->growthIncrement = growthIncrement;
    pool->freeList = NULL;
    pthread_mutex_init(&pool->lock, NULL);

    for (size_t i = 0; i < initialSize; ++i) {
        MemoryPoolNode* newNode = (MemoryPoolNode*)malloc(pool->nodeSize + sizeof(MemoryPoolNode));
        if (!newNode) break;

        newNode->next = pool->freeList;
        pool->freeList = newNode;
    }

    return pool;
}

NFAPI_CRC_INDICATION_PDU_T* allocateFromPool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    MemoryPoolNode* node = pool->freeList;
    if (!node && pool->growthIncrement > 0) {
        for (size_t i = 0; i < pool->growthIncrement; ++i) {
            MemoryPoolNode* newNode = (MemoryPoolNode*)malloc(pool->nodeSize + sizeof(MemoryPoolNode));
            if (!newNode) break;

            newNode->next = pool->freeList;
            pool->freeList = newNode;
        }
    }

    if (pool->freeList) {
        node = pool->freeList;
        pool->freeList = node->next;
    }

    pthread_mutex_unlock(&pool->lock);
    return (NFAPI_CRC_INDICATION_PDU_T*)(node + 1);
}

void deallocateToPool(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&pool->lock);

    MemoryPoolNode* node = (MemoryPoolNode*)data;
    node->next = pool->freeList;
    pool->freeList = node;

    pthread_mutex_unlock(&pool->lock);
}

void destroyMemoryPool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    while (pool->freeList) {
        MemoryPoolNode* temp = pool->freeList;
        pool->freeList = temp->next;
        free(temp);
    }

    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}
