#include <stdlib.h>

typedef struct {
    unsigned long timestamp;
    size_t length;
    void *data;
    size_t padding;
} FrameInfo;

FrameInfo* allocate_frames(size_t num_frames, size_t max_frame_size) {
    if (num_frames == 0 || max_frame_size == 0) return NULL;

    // Calculate the total memory required for all frames and metadata
    size_t total_memory = num_frames * sizeof(FrameInfo);
    total_memory += num_frames * max_frame_size;
    total_memory += num_frames * sizeof(size_t); // Additional memory for padding calculation

    // Check for integer overflow during multiplication
    if (total_memory / sizeof(FrameInfo) != num_frames ||
        total_memory / max_frame_size != num_frames ||
        total_memory / sizeof(size_t) != num_frames) {
        return NULL; // Integer overflow detected
    }

    // Allocate memory for the FrameInfo array and frame data
    FrameInfo *frames = (FrameInfo *)malloc(total_memory);
    if (!frames) return NULL;

    // Initialize pointers to frame data within the allocated memory
    char *frame_data_start = ((char *)frames) + num_frames * sizeof(FrameInfo);
    size_t *padding_info = (size_t *)(frame_data_start + num_frames * max_frame_size);

    for (size_t i = 0; i < num_frames; ++i) {
        frames[i].data = frame_data_start + i * max_frame_size;
        frames[i].length = max_frame_size;

        // Calculate required padding to align data
        size_t current_padding = ((size_t)(frames[i].data - (char *)frames)) % 64;
        if (current_padding == 0) {
            current_padding = 64; // Minimum alignment requirement
        }
        frames[i].padding = current_padding;

        padding_info[i] = current_padding;
    }

    return frames;
}
