        return NULL; // Memory allocation failed
    }

    // Initialize the packet headers and payloads
    size_t current_offset = 0;
    for (size_t i = 0; i < num_packets; ++i) {
        headers[i].payload_size = ((PacketHeader*)packet_data)[i].payload_size;
        if (headers[i].payload_size == 0) {
            headers[i].payload = NULL;
            continue;
        }

        // Calculate the required payload size and allocate memory
        headers[i].payload = malloc(headers[i].payload_size);
        if (!headers[i].payload) {
            // Handle memory allocation failure for a specific packet
            for (size_t j = 0; j < i; ++j) {
                free(headers[j].payload);
            }
