#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    sem_t lock;
    NFAPI_CRC_INDICATION_PDU_T** pool;
    size_t capacity;
    size_t count;
} NFAPICRCQueue;

NFAPICRCQueue* create_queue(size_t initial_capacity) {
    NFAPICRCQueue* queue = (NFAPICRCQueue*)malloc(sizeof(NFAPICRCQueue));
    if (!queue) return NULL;

    queue->pool = (NFAPI_CRC_INDICATION_PDU_T**)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!queue->pool) {
        free(queue);
        return NULL;
    }

    sem_init(&queue->lock, 0, 1);
    queue->capacity = initial_capacity;
    queue->count = 0;

    for (size_t i = 0; i < initial_capacity; ++i) {
        queue->pool[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!queue->pool[i]) {
            while (i-- > 0) free(queue->pool[i]);
            free(queue->pool);
            free(queue);
            return NULL;
        }
    }

    return queue;
}

void destroy_queue(NFAPICRCQueue* queue) {
    sem_wait(&queue->lock);

    for (size_t i = 0; i < queue->count; ++i) {
        free(queue->pool[i]);
    }

    free(queue->pool);
    sem_destroy(&queue->lock);
    free(queue);
}

int enqueue(NFAPICRCQueue* queue, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    sem_wait(&queue->lock);

    if (queue->count >= queue->capacity) {
        size_t new_capacity = queue->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T** new_pool = (NFAPI_CRC_INDICATION_PDU_T**)realloc(queue->pool, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!new_pool) {
            sem_post(&queue->lock);
            return -1; // Memory allocation failed
        }

        queue->pool = new_pool;
        queue->capacity = new_capacity;

        for (size_t i = queue->count; i < queue->capacity; ++i) {
            queue->pool[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!queue->pool[i]) {
                while (i-- > queue->count) free(queue->pool[i]);
                sem_post(&queue->lock);
                return -1; // Memory allocation failed
            }
        }
    }

    queue->pool[queue->count++] = pdu;
    sem_post(&queue->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* dequeue(NFAPICRCQueue* queue) {
    sem_wait(&queue->lock);

    if (queue->count == 0) {
        sem_post(&queue->lock);
        return NULL; // Queue is empty
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = queue->pool[--queue->count];
    sem_post(&queue->lock);
    return pdu;
}
