NFAPI_CRC_INDICATION_PDU_T* create_and_populate_pdus(int requested_count) {
    if (requested_count <= 0) {
        fprintf(stderr, "Error: Invalid number of structures requested.\n");
        return NULL;
    }

    unsigned long long available_memory = sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE);
    unsigned long long max_allowed_memory = available_memory * MAX_MEMORY_USAGE;

    size_t structure_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    int actual_count = requested_count;

    if (actual_count * structure_size > max_allowed_memory) {
        fprintf(stderr, "Warning: Insufficient memory. Reducing number of structures.\n");
        actual_count = max_allowed_memory / structure_size;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(actual_count * structure_size);
    if (pdus == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < actual_count; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = rand();
        pdus[i].RNTI = rand() % 65535; // Valid RNTI range is 0-65534
        pdus[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
    }

    return pdus;
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <number_of_structures>\n", argv[0]);
        return 1;
