#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_FILENAME_LENGTH 256
#define MAX_EXTENSION_LENGTH 5

typedef struct {
    char old_filename[MAX_FILENAME_LENGTH];
    char new_extension[MAX_EXTENSION_LENGTH];
    pthread_mutex_t lock;
} FileRenameTask;

void init_file_rename_task(FileRenameTask *task, const char *old_filename, const char *new_extension) {
    strncpy(task->old_filename, old_filename, MAX_FILENAME_LENGTH - 1);
    task->old_filename[MAX_FILENAME_LENGTH - 1] = '\0';
    strncpy(task->new_extension, new_extension, MAX_EXTENSION_LENGTH - 1);
    task->new_extension[MAX_EXTENSION_LENGTH - 1] = '\0';
    pthread_mutex_init(&task->lock, NULL);
}

int get_unique_identifier(const char *filename) {
    int identifier = 0;
    const char *ext = strrchr(filename, '.');
    if (ext != NULL && ext > filename + strlen(filename) - MAX_FILENAME_LENGTH) {
        identifier = strlen(filename) - (ext - filename);
    }
    return identifier;
}

void rename_file(FileRenameTask *task, char *new_filename) {
    pthread_mutex_lock(&task->lock);
    int identifier = get_unique_identifier(task->old_filename);
    snprintf(new_filename, MAX_FILENAME_LENGTH, "%.*s_%d.%s", (int)(strrchr(task->old_filename, '.') - task->old_filename), task->old_filename, identifier, task->new_extension);
    pthread_mutex_unlock(&task->lock);
}

void cleanup_file_rename_task(FileRenameTask *task) {
    pthread_mutex_destroy(&task->lock);
}
