int process_image_metadata(FILE *input_stream, ImageMetaData **meta_data, size_t *num_images) {
    if (input_stream == NULL || meta_data == NULL || num_images == NULL) {
        return -1; // Invalid input
    }

    *num_images = 0;
    while (!feof(input_stream)) {
        ImageMetaData img;
        char filename[256];
        int width, height;
        size_t file_size;

        if (fscanf(input_stream, "%s %d %d %zu", filename, &width, &height, &file_size) != 4) {
            break; // End of input or invalid format
        }

        if (*num_images >= MAX_MEM_SIZE / sizeof(ImageMetaData)) {
            return -2; // Memory limit exceeded
        }

        strncpy(img.filename, filename, sizeof(img.filename));
        img.width = width;
        img.height = height;
        img.file_size = file_size;

        meta_data[*num_images] = malloc(sizeof(ImageMetaData));
        if (meta_data[*num_images] == NULL) {
            return -3; // Memory allocation failed
        }

        memcpy(meta_data[*num_images], &img, sizeof(ImageMetaData));
        (*num_images)++;
    }

    return 0; // Success
