int add_image(ImageCollection* collection, char* data, int size) {
    if (collection->total_size + size > collection->allocated_size) {
        return -1; // Not enough space
    }

    for (int i = 0; i < collection->count; ++i) {
        if (!collection->images[i].data) {
            collection->images[i].data = malloc(size);
            if (!collection->images[i].data) {
                return -1; // Memory allocation failed
            }
            memcpy(collection->images[i].data, data, size);
            collection->images[i].size = size;
            collection->total_size += size + sizeof(ImageData);
            return 0; // Success
        }
    }

    // No free slot found, need to reallocate
    ImageCollection new_collection;
    if (allocate_buffer(&new_collection, collection->count + 1) < 0) {
        return -1; // Reallocation failed
    }

    memcpy(new_collection.images, collection->images, collection->total_size);
    new_collection.images[new_collection.count].data = malloc(size);
    if (!new_collection.images[new_collection.count].data) {
        free_buffer(&new_collection);
        return -1; // Memory allocation failed
    }
    memcpy(new_collection.images[new_collection.count].data, data, size);
    new_collection.images[new_collection.count].size = size;
    new_collection.total_size += size + sizeof(ImageData);

    *collection = new_collection;
    return 0; // Success
}

int main() {
    ImageCollection collection;
    if (allocate_buffer(&collection, MAX_IMAGES) < 0) {
        printf("Failed to allocate buffer\n");
        return 1;
    }

    char image_data[MAX_IMAGE_SIZE];
    // Populate image_data with actual image data

    for (int i = 0; i < 5; ++i) {
        if (add_image(&collection, image_data, MAX_IMAGE_SIZE) < 0) {
            printf("Failed to add image\n");
            free_buffer(&collection);
            return 1;
        }
    }

    free_buffer(&collection);
    return 0;
}
