} ValueGenerator;

void initializeValueGenerator(ValueGenerator* vg, int min, int max) {
    vg->min = min;
    vg->max = max;
}

int generateRandomInt(ValueGenerator* vg) {
    return vg->min + rand() % (vg->max - vg->min + 1);
}

NFAPI_CRC_INDICATION_PDU_T* populateNFAPICRCIndications(int numEntries, ValueGenerator* vg) {
    if (numEntries <= 0) {
        fprintf(stderr, "Invalid number of entries: %d\n", numEntries);
        return NULL;
