    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T** current = &head;

    for (int i = 0; i < numEntries; i++) {
        *current = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (*current == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return head;
        }

        (*current)->RX_UE_INFORMATION_TAG = generateRandomInt(vg);
        (*current)->RNTI = generateRandomInt(vg);
        (*current)->CRCFLAG = generateRandomInt(vg);
        (*current)->next = NULL;

        current = &(*current)->next;
    }

