#include <string.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void populate_crc_indication_list(int N, NFAPI_CRC_INDICATION_PDU_T** list) {
    if (N <= 0) {
        fprintf(stderr, "Invalid number of elements: %d\n", N);
        return;
    }

    size_t required_memory = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (required_memory / N != sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fprintf(stderr, "Integer overflow detected when calculating memory requirements.\n");
        return;
    }

    *list = malloc(required_memory);
    if (*list == NULL) {
        fprintf(stderr, "Memory allocation failed for %d elements.\n", N);
        return;
    }

    srand(time(NULL));
    int valid_count = 0;

    for (int i = 0; i < N; ++i) {
        (*list)[i].RX_UE_INFORMATION_TAG = rand();
        unsigned short rnti = (unsigned short)rand() % 65536;
        if (rnti > 0 && rnti < 65536) {
            (*list)[i].RNTI = rnti;
            (*list)[i].CRC_INDICATION_REL8_TAG = rand();
            ++valid_count;
        }
    }

    // Resize the array to only include valid elements
    NFAPI_CRC_INDICATION_PDU_T* new_list = realloc(*list, valid_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_list == NULL) {
        fprintf(stderr, "Memory reallocation failed.\n");
        free(*list);
        *list = NULL;
        return;
    }
    *list = new_list;

    // Function to write the list to a file
    void write_to_file(const char* filename, NFAPI_CRC_INDICATION_PDU_T* data, int count) {
        FILE* file = fopen(filename, "w");
        if (file == NULL) {
            fprintf(stderr, "Failed to open file for writing: %s\n", filename);
            return;
        }

        for (int i = 0; i < count; ++i) {
            fprintf(file, "RX_UE_INFORMATION_TAG: %d, RNTI: %u, CRC_INDICATION_REL8_TAG: %d\n",
                    data[i].RX_UE_INFORMATION_TAG, data[i].RNTI, data[i].CRC_INDICATION_REL8_TAG);
        }

        fclose(file);
    }

    // Example usage
    write_to_file("crc_indication_list.txt", *list, valid_count);

    free(*list);
}
