#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>
#include <stdint.h>

#define MAX_N 1000

typedef struct {
    uint64_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    void* (*allocate)(size_t size, const char* file, int line);
    void (*free)(void* ptr, const char* file, int line);
    void (*log)(const char* format, ...);
} MemoryManagerT;

NFAPI_CRC_INDICATION_PDU_T* populate_crc_indications(int N, uint32_t seed, size_t max_memory, MemoryManagerT* mem_mgr) {
    if (N > MAX_N) {
        mem_mgr->log("Error: N exceeds maximum allowed value of %d\n", MAX_N);
        return NULL;
    }

    size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t required_memory = N * struct_size;

    if (required_memory > max_memory) {
        mem_mgr->log("Error: Required memory exceeds maximum available memory\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* crc_indications = mem_mgr->allocate(required_memory, __FILE__, __LINE__);
    if (!crc_indications) {
        mem_mgr->log("Memory allocation failed\n");
        return NULL;
    }

    bool* used_tags = mem_mgr->allocate(N * sizeof(bool), __FILE__, __LINE__);
    if (!used_tags) {
        mem_mgr->free(crc_indications, __FILE__, __LINE__);
        mem_mgr->log("Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < N; ) {
        uint64_t tag = rand() % MAX_N + 1;
        if (!used_tags[tag]) {
            used_tags[tag] = true;
            crc_indications[i].rx_ue_information_tag = tag;
            crc_indications[i].rnti = rand() % 1024 + 1;

            unsigned int random_number;
            srand(seed);
            random_number = rand();
            crc_indications[i].crc_flag = (random_number & 0x1);

            mem_mgr->log("Allocated and populated CRC indication at index %d\n", i);
            i++;
        }
    }

    mem_mgr->free(used_tags, __FILE__, __LINE__);

    return crc_indications;
}

void cleanup_crc_indications(NFAPI_CRC_INDICATION_PDU_T* crc_indications, int N, MemoryManagerT* mem_mgr) {
    if (crc_indications) {
        mem_mgr->free(crc_indications, __FILE__, __LINE__);
        mem_mgr->log("Memory for CRC indications freed\n");
    }
}

void iterate_crc_indications(NFAPI_CRC_INDICATION_PDU_T* crc_indications, int N, MemoryManagerT* mem_mgr) {
    for (int i = 0; i < N; i++) {
        mem_mgr->log("CRC Indication %d: Tag=%llu, RNTI=%u, CRC Flag=%u\n", i, crc_indications[i].rx_ue_information_tag, crc_indications[i].rnti, crc_indications[i].crc_flag);
    }
}
