#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_FRAMES 1024
#define MAX_FILE_SIZE 10 * 1024 * 1024 // 10MB

typedef struct {
    int frame_count;
    unsigned char** frames_data;
} ImageBatch;

void* process_image_batch(void* arg) {
    ImageBatch* batch = (ImageBatch*)arg;
    for (int i = 0; i < batch->frame_count; i++) {
        // Convert and compress each frame
        // ...
    }
    return NULL;
}

void process_images(const char* file_paths[], int num_files) {
    pthread_t threads[num_files];
    for (int i = 0; i < num_files; i++) {
        FILE* file = fopen(file_paths[i], "rb");
        if (!file) {
            perror("Failed to open file");
            continue;
        }

        fseek(file, 0, SEEK_END);
        long file_size = ftell(file);
        fseek(file, 0, SEEK_SET);

        if (file_size > MAX_FILE_SIZE) {
            printf("File size exceeds limit\n");
            fclose(file);
            continue;
        }

        ImageBatch batch;
        batch.frame_count = file_size / sizeof(unsigned char*);
        batch.frames_data = (unsigned char**)malloc(batch.frame_count * sizeof(unsigned char*));

        if (!batch.frames_data) {
            perror("Failed to allocate memory for frames");
            fclose(file);
            continue;
        }

        for (int j = 0; j < batch.frame_count; j++) {
            batch.frames_data[j] = (unsigned char*)malloc(sizeof(unsigned char));
            fread(batch.frames_data[j], sizeof(unsigned char), 1, file);
        }
        fclose(file);

        if (pthread_create(&threads[i], NULL, process_image_batch, &batch) != 0) {
            perror("Failed to create thread");
            for (int k = 0; k < j; k++) {
                free(batch.frames_data[k]);
            }
            free(batch.frames_data);
            continue;
        }

        pthread_join(threads[i], NULL);
        for (int k = 0; k < batch.frame_count; k++) {
            free(batch.frames_data[k]);
        }
        free(batch.frames_data);
    }
}

int main() {
    const char* file_paths[] = {"image1.bin", "image2.bin"};
    process_images(file_paths, sizeof(file_paths) / sizeof(file_paths[0]));
    return 0;
}
