NFAPI_CRC_INDICATION_PDU_T* create_and_populate_pdus(int num_pdus, int max_memory_kb) {
    // Check for valid input
    if (num_pdus <= 0 || max_memory_kb <= 0) {
        return NULL;
    }

    // Calculate the size of each PDU structure in bytes
    size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);

    // Calculate the total memory required for all PDUs
    size_t total_memory_required = num_pdus * struct_size;

    // Check if the total memory exceeds the maximum allowed
    if (total_memory_required > max_memory_kb * 1024) {
        return NULL;
    }

    // Allocate memory for the array of PDUs
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(total_memory_required);
    if (!pdus) {
        return NULL;  // Memory allocation failed
    }

    // Populate the PDUs with valid data
    for (int i = 0; i < num_pdus; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = i + 1;
        pdus[i].RNTI = i * 2;
        pdus[i].CRC_INDICATION_REL8_TAG = i % 3;
