typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t count;
    pthread_mutex_t mutex;
} LinkedList;

LinkedList* create_linked_list(size_t max_size) {
    if (max_size == 0) return NULL;

    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void free_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (pthread_mutex_lock(&list->mutex)) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int remove_from_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (pthread_mutex_lock(&list->mutex)) return -1;

    Node** current = &list->head;
    while (*current) {
        if ((*current)->data == data) {
            Node* temp = *current;
            *current = (*current)->next;
            free(temp);
            list->count--;
            break;
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Function to update list from external data source
int update_list_from_source(LinkedList* list, ExternalDataSource* source) {
    // Assume source provides the latest data and updates are frequent
    NFAPI_CRC_INDICATION_PDU_T new_data;
    while (source->has_next()) {
        if (source->get_next(&new_data) == 0) {
            remove_from_list(list, new_data); // Remove old data
            add_to_list(list, new_data); // Add new data
        }
    }

    return 0;
}
