void initialize_packet_pool() {
    memset(packet_pool, 0, sizeof(packet_pool));
}

Packet* allocate_packet() {
    if (packet_count >= MAX_PACKETS) {
        return NULL; // Pool is full
    }
    return &packet_pool[pool_index++];
}

void deallocate_packet(Packet* packet) {
    int index = packet - packet_pool;
    if (index >= 0 && index < MAX_PACKETS) {
        pool_index = index;
        packet_count--;
    } else {
        printf("Error: Invalid packet pointer\n");
    }
}

size_t calculate_total_memory(size_t payload_size, size_t num_packets) {
    size_t total_memory = num_packets * (HEADER_SIZE + payload_size);
    // Check for integer overflow
    if (total_memory / num_packets != HEADER_SIZE + payload_size) {
        printf("Error: Integer overflow in memory calculation\n");
        return 0;
    }
    return total_memory;
}

void process_packets(size_t payload_size, size_t num_packets) {
    size_t total_memory = calculate_total_memory(payload_size, num_packets);
    if (total_memory == 0) {
        return;
    }

    Packet* packets[MAX_PACKETS];
    for (size_t i = 0; i < num_packets; i++) {
