    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    NFAPI_CRC_INDICATION_PDU_T CRCFLAG;
} PacketMetadata;

// Function to create a new packet metadata
PacketMetadata* create_packet_metadata(int unique_id, size_t payload_size) {
    PacketMetadata *metadata = (PacketMetadata *)malloc(sizeof(PacketMetadata));
    if (!metadata) return NULL;

    metadata->unique_id = unique_id;
    metadata->timestamp = time(NULL);
    metadata->payload_size = payload_size;
    metadata->payload = (char *)calloc(payload_size, sizeof(char));
    if (!metadata->payload) {
        free(metadata);
        return NULL;
    }
    metadata->RX_UE_INFORMATION_TAG = 0; // Initialize to zero or appropriate default
    metadata->RNTI = 0; // Initialize to zero or appropriate default
    memset(&metadata->CRCFLAG, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    return metadata;
}

// Function to free packet metadata
void free_packet_metadata(PacketMetadata *metadata) {
    if (metadata->payload) {
        free(metadata->payload);
    }
    free(metadata);
}

// Function to process a network packet stream
void process_packet_stream(PacketMetadata **packet_array, size_t array_size) {
    for (size_t i = 0; i < array_size; ++i) {
        PacketMetadata *current_packet = packet_array[i];
        if (!current_packet) continue;

        // Process each packet (e.g., log, store in database)
        printf("Processing packet %d at timestamp %ld with payload size %zu\n",
               current_packet->unique_id, current_packet->timestamp, current_packet->payload_size);

        // Example: Store packet metadata in an external database
        // store_packet_in_database(current_packet);
    }
}

// Function to dynamically manage packet metadata array
void manage_packets() {
    PacketMetadata **packet_array = NULL;
    size_t current_size = 0;
    size_t max_size = 10; // Initial capacity

    while (/* receive new packet */ 1) {
        if (current_size >= max_size) {
            max_size *= 2;
            packet_array = realloc(packet_array, max_size * sizeof(PacketMetadata *));
            if (!packet_array) {
                fprintf(stderr, "Memory allocation failed\n");
                break;
            }
        }

        // Receive new packet metadata
        int unique_id = /* get unique ID */;
        size_t payload_size = /* get payload size */;
        PacketMetadata *new_packet = create_packet_metadata(unique_id, payload_size);
        if (!new_packet) {
            fprintf(stderr, "Failed to create packet metadata\n");
            break;
        }

        // Store new packet in array
        packet_array[current_size++] = new_packet;
    }

    // Process all received packets
    process_packet_stream(packet_array, current_size);

    // Free allocated memory
    for (size_t i = 0; i < current_size; ++i) {
        free_packet_metadata(packet_array[i]);
    }
    free(packet_array);
}
