Packet* process_packet_batch(int batch_size, const char* payloads[], int payload_sizes[]) {
    if (batch_size <= 0) {
        return NULL;
    }

    // Calculate total memory needed
    size_t total_memory = batch_size * sizeof(Packet);
    for (int i = 0; i < batch_size; i++) {
        if (payload_sizes[i] > MAX_PACKET_SIZE) {
            // Handle error or return NULL if payload size exceeds limit
            return NULL;
        }
        total_memory += payload_sizes[i];
    }

    // Allocate memory for the packet array
    Packet* packets = (Packet*)malloc(total_memory);
    if (!packets) {
        return NULL; // Memory allocation failed
    }

    // Populate each packet with the payload data
    size_t current_offset = batch_size * sizeof(Packet);
    for (int i = 0; i < batch_size; i++) {
        packets[i].payload_size = payload_sizes[i];
        memcpy(packets[i].payload, payloads[i], payload_sizes[i]);
        current_offset += payload_sizes[i];
    }

    return packets;
}

// Example usage
int main() {
    const char* payloads[] = {"Hello", "World"};
    int payload_sizes[] = {5, 5};
    int batch_size = sizeof(payloads) / sizeof(payloads[0]);

    Packet* packet_batch = process_packet_batch(batch_size, payloads, payload_sizes);
    if (packet_batch) {
        for (int i = 0; i < batch_size; i++) {
            printf("Packet %d: Payload Size = %d, Payload = %s\n", i, packet_batch[i].payload_size, packet_batch[i].payload);
        }
        free(packet_batch);
    }

    return 0;
}
