#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define HEADER_SIZE 256
#define MAX_PAYLOAD_SIZE 4096
#define MAX_PACKETS 1024
#define BUFFER_POOL_SIZE 2048

typedef struct Packet {
    char header[HEADER_SIZE];
    char payload[MAX_PAYLOAD_SIZE];
    int size;
    struct Packet* next;
} Packet;

typedef struct BufferPool {
    Packet* buffer[BUFFER_POOL_SIZE];
    sem_t semaphore;
    pthread_mutex_t lock;
} BufferPool;

typedef struct PacketQueue {
    Packet* front;
    Packet* rear;
    int size;
    sem_t semaphore;
    pthread_mutex_t lock;
} PacketQueue;

BufferPool buffer_pool;
PacketQueue packet_queue;
pthread_cond_t queue_not_full;
pthread_cond_t queue_not_empty;
sem_t processing_semaphore;
int shutdown_flag = 0;

void init_buffer_pool() {
    sem_init(&buffer_pool.semaphore, 0, BUFFER_POOL_SIZE);
    pthread_mutex_init(&buffer_pool.lock, NULL);
}

void init_packet_queue() {
    packet_queue.front = packet_queue.rear = NULL;
    packet_queue.size = 0;
    sem_init(&packet_queue.semaphore, 0, 0);
    pthread_mutex_init(&packet_queue.lock, NULL);
    pthread_cond_init(&queue_not_full, NULL);
    pthread_cond_init(&queue_not_empty, NULL);
}

Packet* allocate_packet() {
    Packet* packet = (Packet*)sem_wait(&buffer_pool.semaphore);
    if (!packet) return NULL;
    pthread_mutex_lock(&buffer_pool.lock);
    sem_post(&buffer_pool.semaphore);
    return packet;
}

void free_packet(Packet* packet) {
    pthread_mutex_lock(&buffer_pool.lock);
    sem_wait(&buffer_pool.semaphore);
    packet->next = buffer_pool.buffer[sem_getvalue(&buffer_pool.semaphore)];
    buffer_pool.buffer[sem_getvalue(&buffer_pool.semaphore)] = packet;
    sem_post(&buffer_pool.semaphore);
    pthread_mutex_unlock(&buffer_pool.lock);
}

void enqueue_packet(Packet* packet) {
    sem_wait(&packet_queue.semaphore);
    pthread_mutex_lock(&packet_queue.lock);
    if (packet_queue.rear == NULL) {
        packet_queue.front = packet_queue.rear = packet;
    } else {
        packet_queue.rear->next = packet;
        packet_queue.rear = packet;
    }
    packet_queue.size++;
    pthread_cond_signal(&queue_not_empty);
    pthread_mutex_unlock(&packet_queue.lock);
}

Packet* dequeue_packet() {
    sem_wait(&packet_queue.semaphore);
    pthread_mutex_lock(&packet_queue.lock);
    if (packet_queue.front == NULL) {
        pthread_cond_wait(&queue_not_full, &packet_queue.lock);
    }
    Packet* packet = packet_queue.front;
    packet_queue.front = packet->next;
    if (packet_queue.front == NULL) {
        packet_queue.rear = NULL;
    }
    packet_queue.size--;
    sem_post(&packet_queue.semaphore);
    pthread_mutex_unlock(&packet_queue.lock);
    return packet;
}

void* packet_processing_thread(void* arg) {
    while (!shutdown_flag) {
        Packet* packet = dequeue_packet();
        if (packet != NULL) {
            // Process the packet
            free_packet(packet);
        }
    }
    return NULL;
}

void start_processing() {
    pthread_t threads[MAX_PACKETS];
    for (int i = 0; i < MAX_PACKETS; i++) {
        pthread_create(&threads[i], NULL, packet_processing_thread, NULL);
    }
}

void stop_processing() {
    shutdown_flag = 1;
    for (int i = 0; i < MAX_PACKETS; i++) {
        pthread_join(threads[i], NULL);
    }
}
