#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define MAX_MEMORY_BUDGET 1024 * 1024  // Example budget of 1MB

typedef struct Packet {
    uint32_t data_length;
    char* data;
    struct Packet* next;
} Packet;

Packet* parse_packets(char* buffer, size_t buffer_size) {
    if (buffer == NULL || buffer_size == 0) {
        return NULL;
    }

    Packet* head = NULL;
    Packet** current_packet = &head;

    while (buffer < buffer + buffer_size) {
        uint32_t length;
        memcpy(&length, buffer, sizeof(uint32_t));
        buffer += sizeof(uint32_t);

        if (length > MAX_MEMORY_BUDGET) {
            fprintf(stderr, "Packet size exceeds memory budget\n");
            break;
        }

        *current_packet = (Packet*)malloc(sizeof(Packet));
        if (*current_packet == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }
        (*current_packet)->data_length = length;
        (*current_packet)->data = (char*)malloc(length);
        if ((*current_packet)->data == NULL) {
            fprintf(stderr, "Memory allocation for data failed\n");
            free(*current_packet);
            *current_packet = NULL;
            break;
        }

        memcpy((*current_packet)->data, buffer, length);
        buffer += length;

        (*current_packet)->next = NULL;
        current_packet = &(*current_packet)->next;
    }

    return head;
}

void free_packets(Packet* packet) {
    Packet* temp;
    while (packet != NULL) {
        temp = packet;
        packet = packet->next;
        free(temp->data);
        free(temp);
    }
}
