typedef struct SensorMetadata {
    int sensorID;
    time_t timestamp;
    float temperature;
    float humidity;
    float pressure;
    int flagged;
    char qualityFlag;
} SensorMetadata;

SensorMetadata** dynamicArray = NULL;
int arraySize = 0;
int currentCount = 0;

void initializeDynamicArray(int initialCapacity) {
    arraySize = initialCapacity;
    dynamicArray = (SensorMetadata**)malloc(arraySize * sizeof(SensorMetadata*));
    if (dynamicArray == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
}

void resizeDynamicArray() {
    arraySize *= 2;
    SensorMetadata** newArray = (SensorMetadata**)realloc(dynamicArray, arraySize * sizeof(SensorMetadata*));
    if (newArray == NULL) {
        fprintf(stderr, "Memory reallocation failed.\n");
        exit(EXIT_FAILURE);
    }
    dynamicArray = newArray;
}

void addSensorReading(int sensorID, time_t timestamp, float temperature, float humidity, float pressure, int flagged, char qualityFlag) {
    if (currentCount >= arraySize) {
        resizeDynamicArray();
    }
    dynamicArray[currentCount] = (SensorMetadata*)malloc(sizeof(SensorMetadata));
    if (dynamicArray[currentCount] == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    dynamicArray[currentCount]->sensorID = sensorID;
    dynamicArray[currentCount]->timestamp = timestamp;
    dynamicArray[currentCount]->temperature = temperature;
    dynamicArray[currentCount]->humidity = humidity;
    dynamicArray[currentCount]->pressure = pressure;
    dynamicArray[currentCount]->flagged = flagged;
    dynamicArray[currentCount]->qualityFlag = qualityFlag;
    currentCount++;
}

void processSensorReadings() {
    for (int i = 0; i < currentCount; i++) {
        // Process each sensor reading
        printf("Processing sensor ID: %d, Timestamp: %ld\n", 
               dynamicArray[i]->sensorID, dynamicArray[i]->timestamp);
    }
}

void cleanUpDynamicArray() {
    for (int i = 0; i < currentCount; i++) {
        free(dynamicArray[i]);
    }
    free(dynamicArray);
}

int main() {
    initializeDynamicArray(10); // Initial capacity of the dynamic array
    addSensorReading(1, time(NULL), 23.5, 45.0, 1013.25, 0, 'A');
    addSensorReading(2, time(NULL) + 60, 24.0, 44.5, 1012.75, 1, 'B');
    processSensorReadings();
    cleanUpDynamicArray();
    return 0;
}
