#include <stdio.h>
#include <stdlib.h>

typedef struct State {
    int id;
    struct State* next;
} State;

typedef struct FSA {
    State* stateList;
    int currentStateId;
} FSA;

int createAndPopulateStateList(int N, int maxListSize, FSA* fsa, int lastState) {
    if (N < 0 || maxListSize <= 0 || lastState < 0) {
        printf("Error: Invalid input values.\n");
        return -1;
    }

    State** statePool = malloc(maxListSize * sizeof(State*));
    if (!statePool) {
        perror("Failed to allocate memory for state pool.");
        return -1;
    }

    for (int i = 0; i < maxListSize; i++) {
        statePool[i] = malloc(sizeof(State));
        if (!statePool[i]) {
            perror("Failed to allocate memory for a state.");
            free(statePool);
            return -1;
        }
        statePool[i]->id = -1;
        statePool[i]->next = NULL;
    }

    State* currentState = fsa->stateList;
    int addedStates = 0;

    for (int i = 0; i < N && addedStates < maxListSize; i++) {
        int newId = lastState + i + 1;
        if (currentState) {
            while (currentState->next) {
                currentState = currentState->next;
            }
            currentState->next = statePool[i];
        } else {
            fsa->stateList = statePool[i];
        }
        statePool[i]->id = newId;
        addedStates++;
    }

    fsa->lastState->next = fsa->stateList;

    for (int i = N; i < maxListSize; i++) {
        free(statePool[i]);
    }
    free(statePool);

    printf("Added %d states to the state list.\n", addedStates);
    return 0;
}
