#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_N 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    bool CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RxPduList;

void createRxPduList(size_t N, RxPduList** list) {
    if (N < 1 || N > MAX_N) {
        fprintf(stderr, "Invalid number of PDUs. Adjusting to %zu.\n", MAX_N);
        N = MAX_N;
    }

    size_t memory_required = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (memory_required / N != sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fprintf(stderr, "Memory overflow detected. Adjusting N.\n");
        N = (size_t)(-1) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    *list = malloc(sizeof(RxPduList));
    if (*list == NULL) {
        perror("Failed to allocate memory for RxPduList.");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&(*list)->lock, NULL);
    (*list)->capacity = N;
    (*list)->size = 0;
    (*list)->pdus = malloc(memory_required);
    if ((*list)->pdus == NULL) {
        perror("Failed to allocate memory for PDUs.");
        free(*list);
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (size_t i = 0; i < N; ++i) {
        (*list)->pdus[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        (*list)->pdus[i].RNTI = rand() % 4096;
        (*list)->pdus[i].CRC_INDICATION_REL8_TAG = (rand() % 2) == 0;
        (*list)->pdus[i].CRCFLAG = (rand() % 2) == 0;
    }

    pthread_mutex_lock(&(*list)->lock);
    (*list)->size = N;
    pthread_mutex_unlock(&(*list)->lock);
}

void resizeRxPduList(RxPduList* list, size_t new_size) {
    if (new_size < list->size) {
        pthread_mutex_lock(&list->lock);
        list->size = new_size;
        pthread_mutex_unlock(&list->lock);
        return;
    }

    size_t new_memory_required = new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T* new_pdus = realloc(list->pdus, new_memory_required);
    if (new_pdus == NULL) {
        perror("Failed to reallocate memory for PDUs.");
        return;
    }

    list->pdus = new_pdus;
    list->capacity = new_size;

    srand(time(NULL));
    for (size_t i = list->size; i < new_size; ++i) {
        list->pdus[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        list->pdus[i].RNTI = rand() % 4096;
        list->pdus[i].CRC_INDICATION_REL8_TAG = (rand() % 2) == 0;
        list->pdus[i].CRCFLAG = (rand() % 2) == 0;
    }

    pthread_mutex_lock(&list->lock);
    list->size = new_size;
    pthread_mutex_unlock(&list->lock);
}

void updateCrcFlag(RxPduList* list, size_t index, bool new_flag) {
    if (index >= list->size) {
        fprintf(stderr, "Invalid index for updating CRCFLAG.\n");
        return;
    }

    pthread_mutex_lock(&list->lock);
    list->pdus[index].CRCFLAG = new_flag;
    pthread_mutex_unlock(&list->lock);
}

void freeRxPduList(RxPduList* list) {
    if (list != NULL) {
        pthread_mutex_destroy(&list->lock);
        free(list->pdus);
        free(list);
    }
}
