#include <pthread.h>

#define MAX_PACKET_SIZE 1024
#define MEMORY_LIMIT (10 * 1024 * 1024) // 10MB

typedef struct {
    uint32_t payload_length;
} PacketHeader;

uint8_t** process_packets(PacketHeader* headers, size_t num_headers, size_t max_payload_size, size_t* total_memory_used) {
    uint8_t** payloads = (uint8_t**)malloc(num_headers * sizeof(uint8_t*));
    if (!payloads) {
        return NULL;
    }

    *total_memory_used = 0;

    for (size_t i = 0; i < num_headers; ++i) {
        if (headers[i].payload_length > max_payload_size) {
            continue; // Skip packets with invalid payload lengths
        }

        size_t required_memory = headers[i].payload_length;
        if (*total_memory_used + required_memory > MEMORY_LIMIT) {
            break; // Stop processing if memory limit is exceeded
        }

        uint8_t* payload = (uint8_t*)malloc(required_memory);
        if (!payload) {
            // Handle memory allocation failure gracefully
            for (size_t j = 0; j < i; ++j) {
                free(payloads[j]);
            }
            free(payloads);
            return NULL;
        }

        payloads[i] = payload;
        *total_memory_used += required_memory;
    }

    return payloads;
}

// Example usage with thread safety
pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

void* process_packets_thread(void* arg) {
    PacketHeader* headers = (PacketHeader*)arg;
    size_t num_headers = 1000; // Example number of headers
    size_t max_payload_size = MAX_PACKET_SIZE;
    size_t total_memory_used;

    uint8_t** payloads = process_packets(headers, num_headers, max_payload_size, &total_memory_used);
    if (payloads) {
        pthread_mutex_lock(&memory_lock);
        for (size_t i = 0; i < num_headers; ++i) {
            free(payloads[i]);
        }
        free(payloads);
        pthread_mutex_unlock(&memory_lock);
    }

    return NULL;
}
