#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

#define MAX_PACKET_SIZE 1024 * 1024 * 1 // 1GB
#define MAX_MEMORY_USAGE (1024 * 1024 * 1024) // 1GB

typedef struct {
    int id;
    long timestamp;
    size_t payload_size;
    void* payload;
} PacketMetadata;

PacketMetadata** packet_metadata_array = NULL;
size_t max_packets = 0;
size_t current_memory_usage = 0;
pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

void process_packet(PacketMetadata* metadata) {
    // Process the packet's payload here
    printf("Processing packet ID: %d\n", metadata->id);
}

void* packet_processor(void* arg) {
    while (1) {
        pthread_mutex_lock(&memory_lock);
        if (current_memory_usage < MAX_MEMORY_USAGE) {
            size_t i = 0;
            for (; i < max_packets; ++i) {
                PacketMetadata* metadata = packet_metadata_array[i];
                if (metadata->payload_size > 0 && metadata->payload == NULL) {
                    // Allocate memory for the payload
                    metadata->payload = malloc(metadata->payload_size);
                    if (metadata->payload != NULL) {
                        current_memory_usage += metadata->payload_size;
                        process_packet(metadata);
                        free(metadata->payload);
                        metadata->payload = NULL;
                    } else {
                        printf("Memory allocation failed\n");
                        break;
                    }
                }
            }
        } else {
            // Prioritize critical packets or skip additional packets
            printf("Memory usage limit reached, skipping packet processing\n");
        }
        pthread_mutex_unlock(&memory_lock);
    }
    return NULL;
}

void add_packet_metadata(PacketMetadata* metadata) {
    if (max_packets == 0) {
        max_packets = 1024; // Initial capacity
        packet_metadata_array = malloc(max_packets * sizeof(PacketMetadata*));
    } else if (max_packets <= current_memory_usage / MAX_MEMORY_USAGE * max_packets) {
        // Increase the capacity of the packet metadata array
        max_packets *= 2;
        packet_metadata_array = realloc(packet_metadata_array, max_packets * sizeof(PacketMetadata*));
    }
    packet_metadata_array[current_memory_usage / MAX_MEMORY_USAGE] = metadata;
}

void init_packet_processor() {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, packet_processor, NULL);
    pthread_detach(thread_id);
}

int main() {
    // Initialize the packet processor
    init_packet_processor();

    // Example usage: Add packet metadata to be processed
    PacketMetadata metadata1 = {1, 1633072800, 512 * 1024}; // 512KB payload
