['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Packet {
    int payload_length;
    char *payload;
    struct Packet *next;
} Packet;

typedef struct PacketQueue {
    Packet *front;
    Packet *rear;
    int total_payload_size;
    int max_buffer_size;
} PacketQueue;

Packet* create_packet(int length, const char *data) {
    Packet *new_packet = (Packet*)malloc(sizeof(Packet));
    new_packet->payload_length = length;
    new_packet->payload = (char*)malloc(length);
    strncpy(new_packet->payload, data, length);
    new_packet->next = NULL;
    return new_packet;
}

void enqueue_packet(PacketQueue *queue, Packet *packet) {
    if (queue->total_payload_size + packet->payload_length > queue->max_buffer_size) {
        while (queue->front && queue->total_payload_size + packet->payload_length > queue->max_buffer_size) {
            Packet *temp = queue->front;
            queue->front = queue->front->next;
            free(temp->payload);
            free(temp);
            queue->total_payload_size -= temp->payload_length;
        }
    }
    if (queue->rear == NULL) {
        queue->front = queue->rear = packet;
    } else {
        queue->rear->next = packet;
        queue->rear = packet;
    }
    queue->total_payload_size += packet->payload_length;
}

Packet* dequeue_packet(PacketQueue *queue) {
    if (queue->front == NULL) return NULL;
    Packet *temp = queue->front;
    queue->front = queue->front->next;
    if (queue->front == NULL) queue->rear = NULL;
    int payload_size = temp->payload_length;
    free(temp->payload);
    free(temp);
    queue->total_payload_size -= payload_size;
    return temp;
}

void initialize_queue(PacketQueue *queue, int max_buffer_size) {
    queue->front = queue->rear = NULL;
    queue->total_payload_size = 0;
    queue->max_buffer_size = max_buffer_size;
}

void destroy_queue(PacketQueue *queue) {
    while (queue->front != NULL) {
        Packet *temp = queue->front;
        queue->front = queue->front->next;
        free(temp->payload);
        free(temp);
    }
    queue->rear = NULL;
    queue->total_payload_size = 0;
}
