// Define the structure for packet metadata
typedef struct PacketMetadata {
    void* payload;
    size_t payload_length;
    time_t timestamp;
    struct PacketMetadata* next;
} PacketMetadata;

// Function to create a new packet metadata node
PacketMetadata* create_packet_metadata(void* payload, size_t payload_length) {
    PacketMetadata* node = (PacketMetadata*)malloc(sizeof(PacketMetadata));
    if (!node) return NULL; // Handle memory allocation failure

    node->payload = payload;
    node->payload_length = payload_length;
    node->timestamp = time(NULL);
    node->next = NULL;

    return node;
}

// Function to add a packet metadata node to the linked list
PacketMetadata* add_packet_to_list(PacketMetadata** head, void* payload, size_t payload_length) {
    PacketMetadata* new_node = create_packet_metadata(payload, payload_length);
    if (!new_node) return *head; // Handle memory allocation failure

    if (*head == NULL) {
        *head = new_node;
    } else {
        PacketMetadata* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }

    return *head;
}

// Function to free the linked list
void free_packet_list(PacketMetadata** head) {
    PacketMetadata* current = *head;
    PacketMetadata* next;

    while (current != NULL) {
        next = current->next;
        free(current->payload);
        free(current);
        current = next;
    }

    *head = NULL;
}

// Example usage
int main() {
    PacketMetadata* packet_list_head = NULL;

    // Simulate receiving packets and adding them to the list
    char payload1[] = "Hello, Packet 1!";
    add_packet_to_list(&packet_list_head, payload1, sizeof(payload1) - 1);

    char payload2[] = "Packet 2 with a longer payload";
    add_packet_to_list(&packet_list_head, payload2, sizeof(payload2) - 1);

    // Free the linked list when done
    free_packet_list(&packet_list_head);

    return 0;
}
```

