typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdu;
    int length;
} BatchSubmission;

pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;
BatchSubmission submission_queue[MAX_SYSTEM_WIDE_LIMIT];
int queue_head = 0, queue_tail = 0, queue_size = 0;

void* worker_thread(void* arg) {
    while (1) {
        pthread_mutex_lock(&queue_lock);
        if (queue_size > 0) {
            BatchSubmission batch = submission_queue[queue_head];
            queue_head = (queue_head + 1) % MAX_SYSTEM_WIDE_LIMIT;
            queue_size--;
            pthread_mutex_unlock(&queue_lock);

            // Process the batch
            process_batch(batch.pdu, batch.length);
        } else {
            pthread_mutex_unlock(&queue_lock);
            pthread_exit(NULL);
        }
    }
}

void enqueue_batch(BatchSubmission batch) {
    pthread_mutex_lock(&queue_lock);
    if (queue_size < MAX_SYSTEM_WIDE_LIMIT) {
        submission_queue[queue_tail] = batch;
        queue_tail = (queue_tail + 1) % MAX_SYSTEM_WIDE_LIMIT;
        queue_size++;
    } else {
        // Handle the error, e.g., log it or drop the batch
        fprintf(stderr, "Queue is full, dropping batch\n");
    }
    pthread_mutex_unlock(&queue_lock);
}

void* input_thread(void* arg) {
    while (1) {
        // Simulate user input for NFAPI_CRC_INDICATION_PDU_T structures
        BatchSubmission batch = create_batch();
        if (batch.length > 0) {
            enqueue_batch(batch);
        }

        // Rate-limit submissions
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        ts.tv_sec += TIME_TO_PROCESS_THRESHOLD;
        pthread_cond_timedwait(&input_cv, &input_mutex, &ts);
    }
}

void* log_thread(void* arg) {
    while (1) {
        // Log the submission queue status and other relevant information
        printf("Queue size: %d\n", queue_size);
        sleep(5);  // Log every 5 seconds
    }
}

int main() {
    pthread_t worker, input, log;
    pthread_create(&worker, NULL, worker_thread, NULL);
    pthread_create(&input, NULL, input_thread, NULL);
    pthread_create(&log, NULL, log_thread, NULL);

    pthread_join(worker, NULL);
    pthread_join(input, NULL);
    pthread_join(log, NULL);

    return 0;
}
