#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKETS_PER_SECOND 100000
#define MIN_PAYLOAD_SIZE 1024
#define MAX_PAYLOAD_SIZE 65535

typedef struct {
    uint32_t ip;
    size_t payload_size;
} PacketMetadata;

typedef struct {
    PacketMetadata *metadata_list;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t mutex;
} PacketList;

void initialize_packet_list(PacketList *list) {
    list->allocated_size = 1024; // Initial allocation
    list->used_size = 0;
    list->metadata_list = (PacketMetadata *)malloc(list->allocated_size * sizeof(PacketMetadata));
    pthread_mutex_init(&list->mutex, NULL);
}

void resize_packet_list(PacketList *list) {
    size_t new_size = list->allocated_size * 2;
    if (new_size > MAX_PACKETS_PER_SECOND) {
        new_size = MAX_PACKETS_PER_SECOND;
    }
    PacketMetadata *new_metadata_list = (PacketMetadata *)realloc(list->metadata_list, new_size * sizeof(PacketMetadata));
    if (new_metadata_list == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->allocated_size = new_size;
    list->metadata_list = new_metadata_list;
}

void add_packet_to_list(PacketList *list, uint32_t ip, size_t payload_size) {
    pthread_mutex_lock(&list->mutex);
    if (list->used_size >= list->allocated_size) {
        resize_packet_list(list);
    }
    list->metadata_list[list->used_size].ip = ip;
    list->metadata_list[list->used_size].payload_size = payload_size;
    list->used_size++;
    pthread_mutex_unlock(&list->mutex);
}

void finalize_packet_list(PacketList *list) {
    pthread_mutex_destroy(&list->mutex);
    free(list->metadata_list);
}

int main() {
    PacketList packet_list;
    initialize_packet_list(&packet_list);

    // Simulate processing of network packets
    for (size_t i = 0; i < MAX_PACKETS_PER_SECOND; i++) {
        uint32_t ip = rand();
        size_t payload_size = MIN_PAYLOAD_SIZE + rand() % (MAX_PAYLOAD_SIZE - MIN_PAYLOAD_SIZE);
        add_packet_to_list(&packet_list, ip, payload_size);
    }

    finalize_packet_list(&packet_list);
    return 0;
}
