#include <time.h>

typedef struct ImageMetadata {
    void* imageData;
    size_t dataLength;
    time_t fileTimestamp;
    struct ImageMetadata* next;
} ImageMetadata;

ImageMetadata* createImageNode(void* imageData, size_t dataLength, time_t timestamp) {
    ImageMetadata* newNode = (ImageMetadata*)malloc(sizeof(ImageMetadata));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    newNode->imageData = malloc(dataLength);
    if (newNode->imageData == NULL) {
        free(newNode);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    memcpy(newNode->imageData, imageData, dataLength);
    newNode->dataLength = dataLength;
    newNode->fileTimestamp = timestamp;
    newNode->next = NULL;
    return newNode;
}

void insertImageMetadata(ImageMetadata** head, void* imageData, size_t dataLength, time_t timestamp) {
    ImageMetadata* newNode = createImageNode(imageData, dataLength, timestamp);
    if (newNode != NULL) {
        newNode->next = *head;
        *head = newNode;
    }
}

void freeImageMetadataList(ImageMetadata** head) {
    while (*head != NULL) {
        ImageMetadata* temp = *head;
        free(temp->imageData);
        *head = temp->next;
        free(temp);
    }
}

int main() {
    ImageMetadata* imageList = NULL;

    // Example usage
    void* imageData1 = malloc(1024); // Dummy image data
    time_t timestamp1 = time(NULL);
    insertImageMetadata(&imageList, imageData1, 1024, timestamp1);

    void* imageData2 = malloc(2048); // Dummy image data
    time_t timestamp2 = time(NULL) + 60;
    insertImageMetadata(&imageList, imageData2, 2048, timestamp2);

    freeImageMetadataList(&imageList);
    return 0;
}
