#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // 1MB

typedef struct Segment {
    void* data;
    size_t length;
    struct Segment* next;
} Segment;

typedef struct Packet {
    Segment* head;
    size_t total_length;
    pthread_mutex_t mutex;
} Packet;

typedef struct NetworkStreamProcessor {
    Packet packet_buffer;
    size_t current_memory_usage;
    pthread_mutex_t memory_lock;
} NetworkStreamProcessor;

void initialize_processor(NetworkStreamProcessor* processor) {
    memset(processor, 0, sizeof(*processor));
    pthread_mutex_init(&processor->memory_lock, NULL);
    pthread_mutex_init(&processor->packet_buffer.mutex, NULL);
}

Segment* allocate_segment(size_t size) {
    Segment* new_segment = (Segment*)malloc(sizeof(Segment));
    if (!new_segment) return NULL;
    new_segment->data = malloc(size);
    if (!new_segment->data) {
        free(new_segment);
        return NULL;
    }
    new_segment->length = size;
    new_segment->next = NULL;
    return new_segment;
}

void free_segment(Segment* segment) {
    if (segment) {
        free(segment->data);
        free(segment);
    }
}

void insert_segment(Packet* packet, Segment* segment) {
    pthread_mutex_lock(&packet->mutex);
    segment->next = packet->head;
    packet->head = segment;
    packet->total_length += segment->length;
    pthread_mutex_unlock(&packet->mutex);
}

int process_packet(NetworkStreamProcessor* processor, void* data, size_t length) {
    if (length > MAX_MEMORY_USAGE - processor->current_memory_usage) return -1; // Check for memory overflow
    Segment* new_segment = allocate_segment(length);
    if (!new_segment) return -2; // Allocation failed

    pthread_mutex_lock(&processor->memory_lock);
    memcpy(new_segment->data, data, length);
    insert_segment(&processor->packet_buffer, new_segment);
    processor->current_memory_usage += length;
    pthread_mutex_unlock(&processor->memory_lock);

    return 0; // Success
}

void clean_up_processor(NetworkStreamProcessor* processor) {
    pthread_mutex_lock(&processor->memory_lock);
    Segment* current = processor->packet_buffer.head;
    while (current) {
        Segment* next = current->next;
        free_segment(current);
        current = next;
    }
    processor->packet_buffer.head = NULL;
    processor->packet_buffer.total_length = 0;
    pthread_mutex_unlock(&processor->memory_lock);

    pthread_mutex_destroy(&processor->packet_buffer.mutex);
    pthread_mutex_destroy(&processor->memory_lock);
}
