typedef struct {
    int width;
    int height;
    unsigned char *data;
} ImageFrame;

ImageFrame** allocateImageFrames(int numFrames, int maxFrameWidth, int maxFrameHeight) {
    if (numFrames <= 0 || maxFrameWidth <= 0 || maxFrameHeight <= 0) {
        return NULL; // Invalid input
    }

    ImageFrame **frames = (ImageFrame **)malloc(numFrames * sizeof(ImageFrame *));
    if (!frames) {
        perror("Failed to allocate memory for frame pointers");
        return NULL;
    }

    int totalPixels = 0;
    for (int i = 0; i < numFrames; ++i) {
        frames[i] = (ImageFrame *)malloc(sizeof(ImageFrame));
        if (!frames[i]) {
            perror("Failed to allocate memory for ImageFrame structure");
            // Free previously allocated structures
            for (int j = 0; j < i; ++j) {
                free(frames[j]);
            }
            free(frames);
            return NULL;
        }

        frames[i]->width = rand() % maxFrameWidth + 1;
        frames[i]->height = rand() % maxFrameHeight + 1;
        totalPixels += frames[i]->width * frames[i]->height;

        frames[i]->data = (unsigned char *)malloc(totalPixels * sizeof(unsigned char));
        if (!frames[i]->data) {
            perror("Failed to allocate memory for pixel data");
            // Free previously allocated structures and pixel data
            for (int j = 0; j <= i; ++j) {
                free(frames[j]->data);
                free(frames[j]);
            }
            free(frames);
            return NULL;
        }

        // Initialize pixel data with random values
        for (int y = 0; y < frames[i]->height; ++y) {
            for (int x = 0; x < frames[i]->width; ++x) {
                frames[i]->data[y * frames[i]->width + x] = rand() % 256;
            }
        }
    }

    return frames;
}

void freeImageFrames(ImageFrame **frames, int numFrames) {
    if (frames) {
        for (int i = 0; i < numFrames; ++i) {
            if (frames[i]) {
                if (frames[i]->data) {
                    free(frames[i]->data);
                }
                free(frames[i]);
            }
        }
        free(frames);
    }
}

int main() {
    int numFrames = 10;
    int maxFrameWidth = 500;
    int maxFrameHeight = 300;

    ImageFrame **frames = allocateImageFrames(numFrames, maxFrameWidth, maxFrameHeight);
    if (frames) {
        // Use the allocated frames
        freeImageFrames(frames, numFrames);
    }

    return 0;
}
