#include <stdlib.h>
#include <stdio.h>

typedef struct Packet {
    size_t payload_length;
    void* payload;
} Packet;

typedef struct PayloadManager {
    size_t max_payload_size;
    size_t total_memory_allocated;
    size_t memory_limit;
    Packet** packets;
    int packet_count;
    int packet_capacity;
    // Add any other necessary fields here
} PayloadManager;

PayloadManager* create_payload_manager(size_t max_payload_size, size_t memory_limit) {
    PayloadManager* manager = (PayloadManager*)malloc(sizeof(PayloadManager));
    if (!manager) return NULL;

    manager->max_payload_size = max_payload_size;
    manager->memory_limit = memory_limit;
    manager->total_memory_allocated = 0;
    manager->packet_count = 0;
    manager->packet_capacity = 16; // Initial capacity
    manager->packets = (Packet**)malloc(manager->packet_capacity * sizeof(Packet*));

    if (!manager->packets) {
        free(manager);
        return NULL;
    }

    return manager;
}

void destroy_payload_manager(PayloadManager* manager) {
    for (int i = 0; i < manager->packet_count; ++i) {
        free(manager->packets[i]->payload);
        free(manager->packets[i]);
    }
    free(manager->packets);
    free(manager);
}

Packet* process_packet_header(PayloadManager* manager, size_t payload_length) {
    if (payload_length > manager->max_payload_size || payload_length == 0) {
        return NULL;
    }

    Packet* packet = (Packet*)malloc(sizeof(Packet));
    if (!packet) {
        return NULL; // Handle memory allocation failure
    }

    packet->payload_length = payload_length;
    packet->payload = malloc(payload_length);
    if (!packet->payload) {
        free(packet);
        return NULL; // Handle memory allocation failure
    }

    manager->total_memory_allocated += payload_length;

    if (manager->total_memory_allocated > manager->memory_limit) {
        free(packet->payload);
        free(packet);
        packet = NULL; // Skip the packet and continue processing
    } else {
        if (manager->packet_count == manager->packet_capacity) {
            int new_capacity = manager->packet_capacity * 2;
            Packet** new_packets = realloc(manager->packets, new_capacity * sizeof(Packet*));
            if (!new_packets) {
                free(packet->payload);
                free(packet);
                return NULL; // Handle memory allocation failure
            }
            manager->packets = new_packets;
            manager->packet_capacity = new_capacity;
        }
        manager->packets[manager->packet_count++] = packet;
    }

    return packet;
}

// Example usage:
int main() {
    PayloadManager* manager = create_payload_manager(1024, 1024 * 1024); // Max payload size of 1KB, memory limit of 1MB
    if (!manager) return -1;

    Packet* packet = process_packet_header(manager, 512);
    if (packet) {
        // Process the packet
        free(packet->payload);
        free(packet);
    }

    destroy_payload_manager(manager);
    return 0;
}
