void load_image(ImageLoader* loader, const char* file_path, size_t file_size) {
    pthread_mutex_lock(&loader->mutex);
    if (loader->total_memory_used + file_size > loader->memory_limit) {
        printf("Warning: Memory usage approaching limit.\n");
        // Implement memory balancing strategy here
    }
    if (file_size > SIZE_MAX - loader->total_memory_used) {
        printf("Error: Integer overflow in memory calculation.\n");
        pthread_mutex_unlock(&loader->mutex);
        return;
    }
    ImageFile* new_image = realloc(loader->images, (loader->num_images + 1) * sizeof(ImageFile));
    if (!new_image) {
        printf("Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&loader->mutex);
        return;
    }
    loader->images = new_image;
    strcpy(loader->images[loader->num_images].file_path, file_path);
    loader->images[loader->num_images].file_size = file_size;
    loader->total_memory_used += file_size;
    loader->num_images++;
