        printf("Error: Memory allocation failed.\n");
        exit(1);
    }
    loader->num_images = 0;
    loader->total_memory_used = 0;
    loader->memory_limit = MEMORY_LIMIT;
    pthread_mutex_init(&loader->mutex, NULL);
