#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define HEADER_SIZE 8
#define MAX_MEMORY_USAGE 0.9

typedef struct {
    char header[HEADER_SIZE];
    size_t payload_length;
    unsigned char *payload_data;
} PacketData;

PacketData* parse_packets(unsigned char *network_data, size_t data_length) {
    // Calculate the maximum number of packets that can fit in the available memory
    size_t max_packets = (size_t)(MAX_MEMORY_USAGE * system_memory);

    // Allocate memory for the array of PacketData structures
    PacketData *packet_list = malloc(max_packets * sizeof(PacketData));
    if (!packet_list) {
        perror("Failed to allocate memory for packet list");
        return NULL;
    }

    size_t current_position = 0;
    size_t packet_count = 0;

    while (current_position < data_length && packet_count < max_packets) {
        // Extract the header from the network data
        memcpy(packet_list[packet_count].header, network_data + current_position, HEADER_SIZE);
        current_position += HEADER_SIZE;

        // Parse the payload length from the header
        size_t payload_length = parse_payload_length_from_header(packet_list[packet_count].header);
        if (payload_length == SIZE_MAX) {
            fprintf(stderr, "Error parsing payload length\n");
            free_packet_list(packet_list, packet_count);
            return NULL;
        }

        // Calculate the total memory required for the current packet
        size_t total_memory_required = HEADER_SIZE + payload_length;

        // Check if adding this packet would exceed the maximum allowed memory usage
        if (total_memory_required > (size_t)(MAX_MEMORY_USAGE * system_memory)) {
            fprintf(stderr, "Packet too large to process\n");
            free_packet_list(packet_list, packet_count);
            return NULL;
        }

        // Allocate memory for the payload data
        packet_list[packet_count].payload_data = malloc(payload_length);
        if (!packet_list[packet_count].payload_data) {
            perror("Failed to allocate memory for payload data");
            free_packet_list(packet_list, packet_count);
            return NULL;
        }

        // Extract the payload data from the network data
        memcpy(packet_list[packet_count].payload_data, network_data + current_position, payload_length);
        current_position += payload_length;

        // Set the payload length in the PacketData structure
        packet_list[packet_count].payload_length = payload_length;

        // Increment the packet count
        packet_count++;
    }

    // Resize the packet list to match the actual number of packets processed
    PacketData *resized_packet_list = realloc(packet_list, packet_count * sizeof(PacketData));
    if (!resized_packet_list) {
        perror("Failed to resize packet list");
        free_packet_list(packet_list, packet_count);
        return NULL;
    }

