typedef struct Tag {
    int header_size;
    char payload[1024]; // Example payload size, adjust as needed
} Tag;

typedef struct Packet {
    int num_tags;
    Tag *tags;
    size_t total_memory_allocated;
} Packet;

Packet* process_packet(const unsigned char *packet_data, size_t packet_length) {
    Packet *p = (Packet *)malloc(sizeof(Packet));
    if (!p) {
        perror("Failed to allocate memory for Packet");
        return NULL;
    }

    p->num_tags = 0;
    p->tags = NULL;
    p->total_memory_allocated = 0;

    // Simulate processing packet and adding tags
    // For demonstration, we assume a fixed tag size
    const size_t tag_size = sizeof(Tag) + 1024; // Adjust based on actual tag structure

    for (size_t i = 0; i < packet_length;) {
        if ((packet_length - i) < tag_size) {
            break; // Not enough data left to form a full tag
        }

        p->num_tags++;
        void *new_mem = realloc(p->tags, p->num_tags * sizeof(Tag));
        if (!new_mem) {
            perror("Failed to reallocate memory for tags");
            free(p);
            return NULL;
        }
        p->tags = (Tag *)new_mem;

        // Simulate reading tag header and payload
        memcpy(&p->tags[p->num_tags - 1].header_size, packet_data + i, sizeof(int));
        memcpy(p->tags[p->num_tags - 1].payload, packet_data + i + sizeof(int), 1024);
        i += tag_size;

        // Update total memory allocated
        p->total_memory_allocated = (p->num_tags * sizeof(Tag)) + (p->num_tags * 1024); // Simplified calculation
    }

    return p;
}

int main() {
    const unsigned char packet_data[] = { /* Example packet data */ };
    size_t packet_length = sizeof(packet_data) / sizeof(packet_data[0]);

    Packet *packet = process_packet(packet_data, packet_length);
    if (packet) {
        printf("Processed %d tags\n", packet->num_tags);
        free(packet->tags);
        free(packet);
    }

    return 0;
}
