    unsigned char* data;
    int size;  // Size in bytes
} PixelData;

typedef struct ImageSegment {
    ImageMetadata metadata;
    PixelData pixelData;
} ImageSegment;

typedef struct FileProcessingContext {
    pthread_mutex_t lock;
    bool running;
    FILE** files;
    int file_count;
    size_t max_memory;
    size_t total_allocated_memory;
    int retry_threshold;
} FileProcessingContext;

void* process_file(void* arg) {
    FileProcessingContext* context = (FileProcessingContext*)arg;
    for (int i = 0; i < context->file_count && context->running; ++i) {
        FILE* file = context->files[i];
        if (!file) continue;

        // Parse file header to determine segment count
        int segment_count;
        if (fread(&segment_count, sizeof(segment_count), 1, file) != 1) {
            fprintf(stderr, "Error reading segment count from file.\n");
            continue;
        }

        for (int j = 0; j < segment_count && context->running; ++j) {
            ImageSegment* segment = malloc(sizeof(ImageSegment));
            if (!segment) {
                fprintf(stderr, "Memory allocation failed for segment.\n");
                break;
            }

            // Parse metadata from file
            if (fread(&segment->metadata, sizeof(ImageMetadata), 1, file) != 1) {
                free(segment);
                fprintf(stderr, "Error reading metadata from file.\n");
                continue;
            }

            // Allocate memory for pixel data
            size_t required_memory = segment->metadata.width * segment->metadata.height;
            if (required_memory > context->max_memory - context->total_allocated_memory) {
                free(segment);
                fprintf(stderr, "Memory allocation exceeds max limit.\n");
                break;
            }
            segment->pixelData.data = malloc(required_memory);
            segment->pixelData.size = required_memory;

            if (!segment->pixelData.data) {
                free(segment);
                fprintf(stderr, "Memory allocation failed for pixel data.\n");
                continue;
            }

            // Read pixel data from file
            size_t read_bytes = fread(segment->pixelData.data, 1, required_memory, file);
            if (read_bytes != required_memory) {
                free(segment->pixelData.data);
                free(segment);
                fprintf(stderr, "Error reading pixel data from file.\n");
                continue;
            }

            // Process segment
            // ...

            // Free resources
            free(segment->pixelData.data);
            free(segment);

            context->total_allocated_memory += required_memory;
        }
    }
    return NULL;
}

int main() {
    FileProcessingContext context = {0};
    context.max_memory = 1024 * 1024 * 1024;  // 1GB
    context.retry_threshold = 3;

    // Initialize file context and other resources
    // ...

    pthread_t* threads = malloc(context.file_count * sizeof(pthread_t));
    if (!threads) {
        fprintf(stderr, "Memory allocation failed for thread array.\n");
        return 1;
    }

    for (int i = 0; i < context.file_count; ++i) {
        if (pthread_create(&threads[i], NULL, process_file, &context)) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            goto cleanup;
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < context.file_count; ++i) {
        pthread_join(threads[i], NULL);
    }

cleanup:
    free(threads);
    // Clean up other resources
    // ...

    return 0;
}
