#define MAX_ALLOC_SIZE 1024

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T *head;
    size_t count;
} NFAPI_LIST_T;

int validate_allocation(size_t requested, size_t available) {
    if (requested > available || requested == 0) {
        return -1; // Allocation not possible
    }
    return 0; // Allocation possible
}

NFAPI_LIST_T* create_list() {
    NFAPI_LIST_T *list = (NFAPI_LIST_T*)malloc(sizeof(NFAPI_LIST_T));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }
    pthread_mutex_init(&list->mutex, NULL);
    list->head = NULL;
    list->count = 0;
    return list;
}

int add_to_list(NFAPI_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *new_node) {
    if (!list || !new_node) {
        return -1; // Invalid input
    }
    pthread_mutex_lock(&list->mutex);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

NFAPI_CRC_INDICATION_PDU_T* create_new_node() {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        return NULL;
    }
    // Initialize new_node fields
    new_node->RX_UE_INFORMATION_TAG = rand() % 1000; // Example initialization
    new_node->RNTI = rand() % 1000; // Example initialization
    new_node->CRC_INDICATION_REL8_TAG = rand() % 1000; // Example initialization
    new_node->CRCFLAG = (rand() % 2) == 0 ? 0 : 1; // Random CRCFLAG
    return new_node;
}

void clean_list(NFAPI_LIST_T *list) {
    if (!list) {
        return;
    }
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->mutex);
}

void destroy_list(NFAPI_LIST_T *list) {
    if (!list) {
        return;
    }
    clean_list(list);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}
