        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    NetworkPacket *packets = NULL;
    size_t total_size = (size_t)num_packets * sizeof(NetworkPacket) + (size_t)num_packets * max_packet_size;

    if (total_size / num_packets != max_packet_size || total_size / sizeof(NetworkPacket) != num_packets) {
        fprintf(stderr, "Potential integer overflow detected.\n");
        return NULL;
    }

    packets = malloc(total_size);
    if (!packets) {
        perror("Memory allocation failed");
        return NULL;
