#include <string.h>
#include <stdint.h>

#define MAX_PROFILES 1024
#define MIN_METADATA_SIZE 32
#define RETRY_COUNT 5

typedef struct UserProfile {
    uint32_t id;
    size_t metadata_size;
    char* metadata;
    char* data;
} UserProfile;

UserProfile profiles[MAX_PROFILES];
uint32_t profile_count = 0;

int add_profile(uint32_t id, const char* metadata, size_t metadata_size, const char* data) {
    if (profile_count >= MAX_PROFILES) return -1; // Check for overflow

    if (metadata_size < MIN_METADATA_SIZE || metadata_size > SIZE_MAX) return -2; // Validate metadata size
    if (data == NULL && metadata_size != 0) return -3; // Ensure data is provided if metadata exists

    UserProfile* new_profile = &profiles[profile_count];
    new_profile->id = id;
    new_profile->metadata_size = metadata_size;

    new_profile->metadata = malloc(metadata_size);
    if (new_profile->metadata == NULL) return -4; // Handle memory allocation failure
    memcpy(new_profile->metadata, metadata, metadata_size);

    if (data != NULL) {
        new_profile->data = malloc(strlen(data) + 1);
        if (new_profile->data == NULL) {
            free(new_profile->metadata); // Free allocated metadata on error
            return -5; // Handle memory allocation failure
        }
        strcpy(new_profile->data, data);
    } else {
        new_profile->data = NULL;
    }

    profile_count++;
    return 0;
}

UserProfile* get_profile(uint32_t id) {
    for (uint32_t i = 0; i < profile_count; i++) {
        if (profiles[i].id == id) {
            return &profiles[i];
        }
    }
    return NULL;
}

int update_profile_data(uint32_t id, const char* data) {
    UserProfile* profile = get_profile(id);
    if (profile == NULL) return -1; // Profile not found

    free(profile->data); // Free existing data
    profile->data = malloc(strlen(data) + 1);
    if (profile->data == NULL) return -2; // Handle memory allocation failure

    strcpy(profile->data, data);
    return 0;
}

void free_profiles() {
    for (uint32_t i = 0; i < profile_count; i++) {
        free(profiles[i].metadata);
        free(profiles[i].data);
    }
}
