#define MAX_PACKET_SIZE 1024 * 1024 // Example max packet size

typedef struct Packet {
    void* header;
    void* payload;
} Packet;

typedef struct Image {
    void* metadata;
    void* pixel_data;
} Image;

// Function to safely allocate memory with overflow checks
void* safe_malloc(size_t size) {
    if (size == 0 || size > INT_MAX / 2) {
        fprintf(stderr, "Memory allocation too large or zero\n");
        exit(EXIT_FAILURE);
    }
    void* ptr = malloc(size);
    if (!ptr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Function to process packets
void process_packets(int packet_count, ...) {
    va_list args;
    va_start(args, packet_count);

    Packet* packets = safe_malloc(packet_count * sizeof(Packet));

    for (int i = 0; i < packet_count; i++) {
        packets[i].header = va_arg(args, void*);
        packets[i].payload = va_arg(args, void*);
        // Process each packet here
    }

    va_end(args);
    free(packets);
}

// Function to process images
void process_images(int image_count, ...) {
    va_list args;
    va_start(args, image_count);

    Image* images = safe_malloc(image_count * sizeof(Image));

    for (int i = 0; i < image_count; i++) {
        images[i].metadata = va_arg(args, void*);
        images[i].pixel_data = va_arg(args, void*);
        // Process each image here
    }

    va_end(args);
    free(images);
}

int main() {
    // Example usage of process_packets and process_images
    Packet packet1_header = { /* Initialize header */ };
    void* packet1_payload = safe_malloc(MAX_PACKET_SIZE); // Allocate payload

    Image image1_metadata = { /* Initialize metadata */ };
    void* image1_pixel_data = safe_malloc(1024 * 768 * 3); // Allocate pixel data

    process_packets(1, &packet1_header, packet1_payload);
    process_images(1, &image1_metadata, image1_pixel_data);

    free(packet1_payload);
    free(image1_pixel_data);

    return 0;
}
