            fprintf(stderr, "Error: Packet length exceeds maximum allowed (%d).\n", MAX_PACKET_LENGTH);
            continue;
        }

        // Allocate memory for the data buffer
        uint8_t *data_buffer = malloc(packet_length);
        if (!data_buffer) {
            fprintf(stderr, "Error: Failed to allocate memory for packet of length %d.\n", packet_length);
            continue;
        }

        // Log successful allocation
        printf("Allocated buffer of size %zu bytes for packet with length %d.\n", packet_length, packet_length);

        // Simulate processing the packet data (e.g., filling the buffer)
        // For demonstration purposes, we'll just zero out the buffer
        memset(data_buffer, 0, packet_length);

        // Free the allocated memory after processing
        free(data_buffer);
    }
}

