typedef struct {
    int width;
    int height;
    char path[MAX_PATH_LENGTH];
} ImageMetaData;

ImageMetaData* process_image_metadata(int num_records, ...) {
    va_list args;
    va_start(args, num_records);

    size_t total_size = sizeof(ImageMetaData) * (size_t)num_records;
    if (total_size / num_records != sizeof(ImageMetaData)) {
        // Handle potential integer overflow
        fprintf(stderr, "Error: Integer overflow in calculating memory size.\n");
        va_end(args);
        return NULL;
    }

    ImageMetaData* metadata = (ImageMetaData*)malloc(total_size);
    if (!metadata) {
        fprintf(stderr, "Error: Failed to allocate memory for image metadata.\n");
        va_end(args);
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        ImageMetaData* current = &metadata[i];
        current->width = va_arg(args, int);
        current->height = va_arg(args, int);

        if (current->width <= 0 || current->height <= 0) {
            // Handle invalid metadata values
            fprintf(stderr, "Warning: Invalid image dimensions, using fallback values.\n");
            current->width = 1;
            current->height = 1;
        }

        char* path = va_arg(args, char*);
        strncpy(current->path, path, MAX_PATH_LENGTH - 1);
        current->path[MAX_PATH_LENGTH - 1] = '\0'; // Ensure null-termination
    }

    va_end(args);
    return metadata;
}

void free_image_metadata(ImageMetaData* metadata) {
    if (metadata) {
        free(metadata);
    }
}
