} IMAGE_PROCESSING_STRUCT_T;

IMAGE_PROCESSING_STRUCT_T* process_image_directory(const char* directory_path, size_t* out_count) {
    DIR* dir = opendir(directory_path);
    if (!dir) {
        perror("Failed to open directory");
        return NULL;
    }

    struct dirent* ent;
    size_t count = 0;

    // First pass: Count the number of image files
    while ((ent = readdir(dir)) != NULL) {
        if (strstr(ent->d_name, ".jpg") || strstr(ent->d_name, ".png")) {
            count++;
        }
    }

    closedir(dir);

    // Allocate memory for the array
    IMAGE_PROCESSING_STRUCT_T* images = malloc(count * sizeof(IMAGE_PROCESSING_STRUCT_T));
    if (!images) {
        perror("Failed to allocate memory");
        return NULL;
    }

    dir = opendir(directory_path);
    if (!dir) {
        perror("Failed to open directory");
        free(images);
        return NULL;
    }

    size_t index = 0;

    // Second pass: Populate the array with image metadata
    while ((ent = readdir(dir)) != NULL) {
        if (strstr(ent->d_name, ".jpg") || strstr(ent->d_name, ".png")) {
            snprintf(images[index].path, sizeof(images[index].path), "%s/%s", directory_path, ent->d_name);
            // Initialize other metadata fields as needed
            index++;
        }
    }

    closedir(dir);

    *out_count = count;
    return images;
}

void free_image_processing_struct(IMAGE_PROCESSING_STRUCT_T* images, size_t count) {
    free(images);
}
