void resize_and_save_jpeg(const char* input_path, const char* output_path, int max_width, int max_height) {
    struct jpeg_decompress_struct cinfo;
    struct jpeg_compress_struct jcs;
    struct jpeg_error_mgr jerr;

    FILE* infile = fopen(input_path, "rb");
    if (!infile) {
        fprintf(stderr, "Error opening input file: %s\n", input_path);
        return;
    }

    FILE* outfile = fopen(output_path, "wb");
    if (!outfile) {
        fprintf(stderr, "Error opening output file: %s\n", output_path);
        fclose(infile);
        return;
    }

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);
    jpeg_stdio_src(&cinfo, infile);
    jpeg_read_header(&cinfo, TRUE);

    int input_width = cinfo.output_width;
    int input_height = cinfo.output_height;

    if (validate_dimensions(input_width, input_height, max_width, max_height) != 0) {
        fprintf(stderr, "Error: Input image dimensions are invalid.\n");
        fclose(infile);
        fclose(outfile);
        jpeg_destroy_decompress(&cinfo);
        return;
    }

    struct jpeg_compress_struct jcs;
    struct jpeg_error_mgr jerr;

    jpeg_create_compress(&jcs);
    jpeg_stdio_dest(&jcs, outfile);

    int output_width = input_width;
    int output_height = input_height;

    if (output_width > max_width || output_height > max_height) {
        double ratio_w = (double)max_width / input_width;
        double ratio_h = (double)max_height / input_height;
        double ratio = ratio_w < ratio_h ? ratio_w : ratio_h;
        output_width = (int)(input_width * ratio);
        output_height = (int)(input_height * ratio);
    }

    jcs.image_width = output_width;
    jcs.image_height = output_height;
    jcs.input_components = 3;
    jcs.in_color_space = JCS_RGB;

    jpeg_set_defaults(&jcs);
    jpeg_set_quality(&jcs, 90, TRUE);

    jpeg_start_compress(&jcs, TRUE);

    JSAMPROW row_pointer[1];
    int row_stride = output_width * 3;

    while (cinfo.output_scanline < cinfo.output_height) {
        row_pointer[0] = (JSAMPROW)malloc(row_stride);
        jpeg_read_scanlines(&cinfo, row_pointer, 1);

        for (int i = 0; i < output_height; ++i) {
            // Resize logic here
            // This is a placeholder for actual resizing logic
        }

        free(row_pointer[0]);
    }

    jpeg_finish_compress(&jcs);
    jpeg_destroy_decompress(&cinfo);
    jpeg_destroy_compress(&jcs);

    fclose(infile);
    fclose(outfile);
}

int validate_dimensions(int width, int height, int max_width, int max_height) {
    if (width < 0 || height < 0 || max_width <= 0 || max_height <= 0) {
        return -1;
    }

    if (max_width < width || max_height < height) {
        return -1;
    }

    return 0;
}

struct jpeg_decompress_struct* read_jpeg_metadata(const char* path) {
    struct jpeg_decompress_struct* cinfo = malloc(sizeof(struct jpeg_decompress_struct));
    struct jpeg_error_mgr jerr;

    FILE* infile = fopen(path, "rb");
    if (!infile) {
        free(cinfo);
        return NULL;
    }

    cinfo->err = jpeg_std_error(&jerr);
    jpeg_create_decompress(cinfo);
    jpeg_stdio_src(cinfo, infile);

    jpeg_read_header(cinfo, FALSE);
    jpeg_destroy_decompress(cinfo);
    fclose(infile);
    free(cinfo);

    return cinfo;
}
