#include <time.h>
#include <unistd.h>

#define MAX_CONNECTION_ATTEMPTS 5
#define MAX_LIST_SIZE 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list[MAX_LIST_SIZE];
    time_t timestamps[MAX_LIST_SIZE];
    int size;
    int head;
} LRU_CACHE;

void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

LRU_CACHE* create_cache() {
    LRU_CACHE *cache = safe_malloc(sizeof(LRU_CACHE));
    cache->size = 0;
    cache->head = -1;
    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        cache->list[i] = NULL;
        cache->timestamps[i] = 0;
    }
    return cache;
}

void* get_connection() {
    // Placeholder for retrieving connection from database
    return safe_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

int connect_to_database(void *connection) {
    // Placeholder for connecting to database with exponential backoff
    static int attempt = 0;
    if (attempt >= MAX_CONNECTION_ATTEMPTS) {
        fprintf(stderr, "Failed to connect to database after %d attempts\n", attempt);
        return -1;
    }
    sleep((1 << attempt)); // Exponential backoff
    attempt++;
    // Simulate successful connection
    return 0;
}

void add_to_cache(LRU_CACHE *cache, void *connection) {
    if (cache->size >= MAX_LIST_SIZE) {
        int oldest_index = cache->head;
        cache->head = (cache->head + 1) % MAX_LIST_SIZE;
        free(cache->list[oldest_index]);
    } else {
        cache->size++;
    }
    cache->list[cache->head] = connection;
    time(&cache->timestamps[cache->head]);
}

void* get_from_cache(LRU_CACHE *cache, int RX_UE_INFORMATION_TAG) {
    for (int i = 0; i < cache->size; i++) {
        if (cache->list[i]->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            time_t now;
            time(&now);
            time_t diff = now - cache->timestamps[i];
            printf("Cache hit for tag %d, age: %ld seconds\n", RX_UE_INFORMATION_TAG, diff);
            memmove(cache->list + i, cache->list + i + 1, sizeof(void*) * (cache->size - i - 1));
            memmove(cache->timestamps + i, cache->timestamps + i + 1, sizeof(time_t) * (cache->size - i - 1));
            cache->head = (cache->head + 1) % MAX_LIST_SIZE;
            add_to_cache(cache, connection);
            return cache->list[0];
        }
    }
    return get_connection();
}

void* manage_list(LRU_CACHE *cache, int RX_UE_INFORMATION_TAG) {
    void *connection = get_from_cache(cache, RX_UE_INFORMATION_TAG);
    if (connect_to_database(connection) != 0) {
        free(connection);
        connection = safe_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    return connection;
}

int main() {
    srand(time(NULL));
    LRU_CACHE *cache = create_cache();
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = 12345;
    pdu.RNTI = 67890;
    pdu.CRC_INDICATION_REL8_TAG = 11111;
    pdu.CRCFLAG = rand() % 2;

    void *connection = manage_list(cache, pdu.RX_UE_INFORMATION_TAG);
    free(connection);

    free(cache);
    return 0;
}
