        while (retryCount < retryLimit) {
            // Simulate a brief delay to handle resource contention
            usleep(1000 * (1 << retryCount));
            pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(requiredMemory);
            if (pdus) {
                break;
            }
            retryCount++;
        }
        if (!pdus) {
            return NULL; // Memory allocation failed after retries
        }
    }

    srand(time(NULL)); // Seed the random number generator

