#define MAX_STRUCTS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    char CRC_INDICATION_REL8_TAG[256];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void free_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <number_of_structures>\n", argv[0]);
        return EXIT_FAILURE;
    }

    long num_structs;
    char* end_ptr;

    num_structs = strtol(argv[1], &end_ptr, 10);

    if (*end_ptr != '\0' || num_structs < 0) {
        fprintf(stderr, "Invalid number of structures.\n");
        return EXIT_FAILURE;
    }

    if (num_structs > MAX_STRUCTS) {
        num_structs = MAX_STRUCTS;
        fprintf(stderr, "Maximum number of structures set to %d.\n", MAX_STRUCTS);
    }

    Node* head = NULL;

    for (long i = 0; i < num_structs; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % INT_MAX;
        pdu.RNTI = (unsigned short)(rand() % USHRT_MAX);
        snprintf(pdu.CRC_INDICATION_REL8_TAG, sizeof(pdu.CRC_INDICATION_REL8_TAG), "Tag_%ld", i);
        pdu.CRCFLAG = rand() % 2;

        Node* new_node = create_node(pdu);
        if (head == NULL) {
            head = new_node;
        } else {
            Node* temp = head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = new_node;
        }
    }

    // Process the list as needed

    free_list(head);

    return EXIT_SUCCESS;
}
