    ImageNode* newNode = (ImageNode*)malloc(sizeof(ImageNode));
    if (newNode == NULL) {
        perror("Failed to allocate memory for image node");
        exit(EXIT_FAILURE);
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
