// Function to add an image node to the linked list
void addImageNode(ImageNode** head, ImageData* data) {
    if (head == NULL || data == NULL) {
        fprintf(stderr, "Invalid input for adding image node\n");
        return;
    }
    ImageNode* newNode = createImageNode(data);
    newNode->next = *head;
    *head = newNode;
}

