void processImageMetadata(ImageData** imageDataArray, int numEntries) {
    if (imageDataArray == NULL || numEntries <= 0) {
        fprintf(stderr, "Invalid input for processing image metadata\n");
        return;
    }

    ImageNode* head = NULL;

    for (int i = 0; i < numEntries; ++i) {
        addImageNode(&head, imageDataArray[i]);
