        current = current->next;
    }

    // Clean up the allocated memory
    while (head != NULL) {
        ImageNode* temp = head;
        head = head->next;
        free(temp->data->filename); // Free the filename string if dynamically allocated
        free(temp->data);           // Free the image data struct
        free(temp);                 // Free the node itself
    }
