        {"image1.jpg", 800, 600, NULL, 0},
        {"image2.png", 1920, 1080, NULL, 0}
    };
    int numEntries = sizeof(images) / sizeof(images[0]);

    processImageMetadata(images, numEntries);

    return 0;
}
