#define LOG_FILE "network_packets.log"

typedef struct Packet {
    int header_size;
    char *data;
    struct Packet *next;
} Packet;

void log_message(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log != NULL) {
        fprintf(log, "%s\n", message);
        fclose(log);
    } else {
        printf("Failed to open log file.\n");
    }
}

Packet* create_packet(int header_size, const char *data) {
    Packet *packet = malloc(sizeof(Packet));
    if (packet == NULL) {
        log_message("Memory allocation error for packet.");
        return NULL;
    }

    packet->header_size = header_size;
    packet->data = malloc(header_size + strlen(data));
    if (packet->data == NULL) {
        free(packet);
        log_message("Memory allocation error for packet data.");
        return NULL;
    }

    memcpy(packet->data, data, header_size);
    strcpy(packet->data + header_size, data);
    packet->next = NULL;

    return packet;
}

void process_packets(Packet *head) {
    Packet *current = head;
    while (current != NULL) {
        // Process each packet here
        printf("Processing packet with header size: %d\n", current->header_size);

        // Free the packet after processing
        free(current->data);
        free(current);
        current = next;

        // Log packet processed
        log_message("Packet processed.");
    }
}

void *packet_processor(void *arg) {
    Packet *head = arg;
    process_packets(head);
    return NULL;
}

int main() {
    Packet *head = NULL; // Head of the packet linked list

    // Simulate receiving packets
    for (int i = 0; i < 10; i++) {
        int header_size = rand() % MAX_PACKET_SIZE + 1; // Random header size
        char data[MAX_PACKET_SIZE];
        snprintf(data, sizeof(data), "Packet %d", i);

        Packet *new_packet = create_packet(header_size, data);
        if (new_packet != NULL) {
            new_packet->next = head;
            head = new_packet;
        }
    }

    pthread_t thread;
    pthread_create(&thread, NULL, packet_processor, head);
    pthread_join(thread, NULL);

    return 0;
}
