typedef struct MemoryPool {
    size_t chunk_size;
    void *buffer;
    size_t used;
    size_t allocated;
} MemoryPool;

MemoryPool *create_memory_pool(size_t chunk_size) {
    MemoryPool *pool = (MemoryPool *)malloc(sizeof(MemoryPool));
    pool->chunk_size = chunk_size;
    pool->buffer = malloc(chunk_size);
    pool->used = 0;
    pool->allocated = chunk_size;
    return pool;
}

void free_memory_pool(MemoryPool *pool) {
    free(pool->buffer);
    free(pool);
}

void *memory_pool_alloc(MemoryPool *pool, size_t size) {
    if (size > pool->chunk_size - pool->used) {
        return NULL; // Not enough space in the current chunk
    }
    void *ptr = (char *)pool->buffer + pool->used;
    pool->used += size;
    return ptr;
}

ImageProcessingTask *allocate_image_tasks(size_t num_tasks, MemoryPool *pool) {
    if (num_tasks == 0 || pool == NULL) {
        return NULL; // Invalid input
    }

    ImageProcessingTask *tasks = (ImageProcessingTask *)memory_pool_alloc(pool, num_tasks * sizeof(ImageProcessingTask));
    if (tasks == NULL) {
        return NULL; // Memory allocation failed
    }

    for (size_t i = 0; i < num_tasks; ++i) {
        tasks[i].metadata = (ImageMetadata *)memory_pool_alloc(pool, sizeof(ImageMetadata));
        if (tasks[i].metadata == NULL) {
            // Cleanup allocated tasks and free the pool
            for (size_t j = 0; j < i; ++j) {
                memory_pool_alloc(pool, -(sizeof(ImageMetadata)));
            }
            memory_pool_alloc(pool, -(num_tasks * sizeof(ImageProcessingTask)));
            return NULL; // Memory allocation failed
        }

        // Initialize metadata here, e.g., tasks[i].metadata->filename = "example.jpg";
    }

    return tasks;
}

void free_image_tasks(ImageProcessingTask *tasks, size_t num_tasks, MemoryPool *pool) {
    if (tasks == NULL || pool == NULL) {
        return; // Invalid input
    }

    for (size_t i = 0; i < num_tasks; ++i) {
        memory_pool_alloc(pool, -(sizeof(ImageMetadata)));
    }
    memory_pool_alloc(pool, -(num_tasks * sizeof(ImageProcessingTask)));

    free_memory_pool(pool);
}

int main() {
    MemoryPool pool = create_memory_pool(1024 * 1024); // 1MB chunk size
