#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_FILENAME_LENGTH 256
#define MIN_BUFFER_SIZE 1024

typedef struct {
    char filename[MAX_FILENAME_LENGTH];
    int width;
    int height;
    unsigned char* imageData;
} ImageStruct;

typedef struct {
    unsigned char* headerData;
    int length;
    // Other network packet fields
} PacketHeaderInfo;

typedef struct {
    ImageStruct** images;
    PacketHeaderInfo** packets;
    size_t imageCount;
    size_t packetCount;
    size_t bufferSize;
    pthread_mutex_t lock;
} ImagePacketBuffer;

ImagePacketBuffer* createBuffer(size_t initialSize) {
    if (initialSize < MIN_BUFFER_SIZE) {
        return NULL; // Error: Initial buffer size too small
    }
    ImagePacketBuffer* buffer = (ImagePacketBuffer*)malloc(sizeof(ImagePacketBuffer));
    if (!buffer) {
        return NULL; // Memory allocation failed
    }
    buffer->images = (ImageStruct**)malloc(initialSize * sizeof(ImageStruct*));
    buffer->packets = (PacketHeaderInfo**)malloc(initialSize * sizeof(PacketHeaderInfo*));
    if (!(buffer->images && buffer->packets)) {
        free(buffer);
        return NULL; // Memory allocation failed
    }
    memset(buffer->images, 0, initialSize * sizeof(ImageStruct*));
    memset(buffer->packets, 0, initialSize * sizeof(PacketHeaderInfo*));
    buffer->imageCount = 0;
    buffer->packetCount = 0;
    buffer->bufferSize = initialSize;
    pthread_mutex_init(&buffer->lock, NULL);
    return buffer;
}

void destroyBuffer(ImagePacketBuffer* buffer) {
    for (size_t i = 0; i < buffer->imageCount; ++i) {
        free(buffer->images[i]->imageData);
        free(buffer->images[i]);
    }
    for (size_t i = 0; i < buffer->packetCount; ++i) {
        free(buffer->packets[i]->headerData);
        free(buffer->packets[i]);
    }
    pthread_mutex_destroy(&buffer->lock);
    free(buffer->images);
    free(buffer->packets);
    free(buffer);
}

void* processImageData(void* arg) {
    ImagePacketBuffer* buffer = (ImagePacketBuffer*)arg;
    // Implement data processing logic here
    return NULL;
}

// Example usage:
int main() {
    ImagePacketBuffer* buffer = createBuffer(1024);
    if (!buffer) {
        fprintf(stderr, "Failed to create buffer\n");
        return 1;
    }
    // Simulate adding image and packet data to the buffer
    // ...

    pthread_t thread;
    if (pthread_create(&thread, NULL, processImageData, buffer)) {
        fprintf(stderr, "Failed to create processing thread\n");
        destroyBuffer(buffer);
        return 1;
    }

    // Wait for the processing thread to finish
    pthread_join(thread, NULL);

    destroyBuffer(buffer);
    return 0;
}
