// Define NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

// Define linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define linked list
typedef struct LinkedList {
    Node* head;
    size_t total_size;
    size_t max_size;
    pthread_mutex_t mutex;
} LinkedList;

// Function to create and populate the linked list
LinkedList* create_populate_linked_list(size_t N, size_t max_memory) {
    if (N == 0 || max_memory == 0) return NULL;

    LinkedList* list = malloc(sizeof(LinkedList));
    if (!list) {
        perror("Failed to allocate memory for LinkedList");
        return NULL;
    }

    list->head = NULL;
    list->total_size = 0;
    list->max_size = max_memory;
    pthread_mutex_init(&list->mutex, NULL);

    size_t node_size = sizeof(Node);
    for (size_t i = 0; i < N && list->total_size + node_size <= list->max_size; ++i) {
        Node* new_node = malloc(node_size);
        if (!new_node) {
            perror("Failed to allocate memory for new node");
            break;
        }

        // Populate the data here
        // ...

        new_node->next = list->head;
        list->head = new_node;

        list->total_size += node_size;
    }

    return list;
}

// Function to safely destroy the linked list
void destroy_linked_list(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->total_size = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

// Function to add a new node to the linked list (thread-safe)
void thread_safe_add_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->total_size += sizeof(Node);

    pthread_mutex_unlock(&list->mutex);
}

// Function to remove a node from the linked list (thread-safe)
void thread_safe_remove_node(LinkedList* list, Node* target) {
    pthread_mutex_lock(&list->mutex);
    if (target == list->head) {
        list->head = target->next;
        free(target);
        list->total_size -= sizeof(Node);
    } else {
        Node* current = list->head;
        while (current && current->next != target) {
            current = current->next;
        }
        if (current) {
            current->next = target->next;
            free(target);
            list->total_size -= sizeof(Node);
        }
    }
    pthread_mutex_unlock(&list->mutex);
}
```

This code snippet provides a basic structure for creating and populating a linked list of `NFAPI_CRC_INDICATION_PDU_T` structures. It includes functions to create the linked list, add nodes safely (considering concurrency), remove nodes safely, and destroy the entire list when it is no longer needed. The use of mutexes ensures thread safety, preventing data races in a multi-threaded environment.']

