// Function to safely calculate memory size avoiding integer overflow
size_t safeCalculateMemorySize(size_t packets, size_t headerSize) {
    if (packets > SIZE_MAX / headerSize) {
        fprintf(stderr, "Error: Integer overflow detected.\n");
        exit(EXIT_FAILURE);
    }
    return packets * headerSize;
}

