#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1500

typedef struct NFapiPacket {
    int headerSize;
    char* payload;
    struct NFapiPacket* next;
} NFapiPacket;

typedef struct {
    pthread_mutex_t lock;
    NFapiPacket* head;
    size_t allocatedMemory;
} NFAPI_PacketPool;

void initPacketPool(NFAPI_PacketPool* pool) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->head = NULL;
    pool->allocatedMemory = 0;
}

NFapiPacket* allocatePacketFromPool(NFAPI_PacketPool* pool, int headerSize, int payloadSize) {
    pthread_mutex_lock(&pool->lock);

    NFapiPacket* packet = pool->head;
    while (packet != NULL) {
        if (packet->next == NULL) {
            break;
        }
        packet = packet->next;
    }

    if (packet == NULL || packet->next == NULL) {
        packet = malloc(sizeof(NFapiPacket));
        packet->next = NULL;

        int totalSize = sizeof(NFapiPacket) + headerSize + payloadSize;
        if (totalSize <= MAX_PACKET_SIZE) {
            packet->payload = malloc(headerSize);
            packet->headerSize = headerSize;
            pool->allocatedMemory += totalSize;

            pthread_mutex_unlock(&pool->lock);
            return packet;
        } else {
            free(packet);
        }
    }

    NFapiPacket* newPacket = packet->next;
    packet->next = newPacket->next;
    pool->allocatedMemory -= sizeof(NFapiPacket) + newPacket->headerSize + payloadSize;

    pthread_mutex_unlock(&pool->lock);
    return newPacket;
}

void deallocatePacketToPool(NFAPI_PacketPool* pool, NFapiPacket* packet) {
    pthread_mutex_lock(&pool->lock);

    int totalSize = sizeof(NFapiPacket) + packet->headerSize + payloadSize;
    if (totalSize <= MAX_PACKET_SIZE) {
        packet->next = pool->head;
        pool->head = packet;
        pool->allocatedMemory += totalSize;
    } else {
        free(packet);
    }

    pthread_mutex_unlock(&pool->lock);
}

void processPackets(NFAPI_PacketPool* pool, int N, RX_UE_INFORMATION_TAG rxUeTag, RNTI rnti) {
    for (int i = 0; i < N; ++i) {
        NFapiPacket* packet = allocatePacketFromPool(pool, sizeof(RX_UE_INFORMATION_TAG), sizeof(RNTI));
        if (packet != NULL) {
            memcpy(packet->payload, &rxUeTag, sizeof(RX_UE_INFORMATION_TAG));
            *(RNTI*)(packet->payload + sizeof(RX_UE_INFORMATION_TAG)) = rnti;
            packet->next = NULL;

            // Process packet...

            deallocatePacketToPool(pool, packet);
        } else {
            // Log allocation error...
        }
    }
}
