#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef struct Packet {
    size_t payload_size;
    char* payload;
} Packet;

typedef struct PacketManager {
    Packet** packets;
    size_t packet_count;
    size_t max_packets;
} PacketManager;

PacketManager* create_packet_manager(size_t initial_capacity) {
    if (initial_capacity == 0) {
        return NULL; // Invalid initial capacity
    }

    PacketManager* manager = (PacketManager*)malloc(sizeof(PacketManager));
    if (!manager) {
        return NULL; // Memory allocation failed
    }

    manager->packets = (Packet**)calloc(initial_capacity, sizeof(Packet*));
    if (!manager->packets) {
        free(manager);
        return NULL; // Memory allocation failed
    }

    manager->packet_count = 0;
    manager->max_packets = initial_capacity;

    return manager;
}

void destroy_packet_manager(PacketManager* manager) {
    if (manager) {
        for (size_t i = 0; i < manager->packet_count; ++i) {
            free(manager->packets[i]->payload);
            free(manager->packets[i]);
        }
        free(manager->packets);
        free(manager);
    }
}

int add_packet(PacketManager* manager, size_t payload_size) {
    if (!manager || payload_size == 0) {
        return -1; // Invalid input
    }

    if (manager->packet_count >= manager->max_packets) {
        size_t new_capacity = manager->max_packets * 2;
        Packet** new_packets = (Packet**)realloc(manager->packets, new_capacity * sizeof(Packet*));
        if (!new_packets) {
            return -1; // Memory allocation failed
        }
        manager->packets = new_packets;
        manager->max_packets = new_capacity;
    }

    Packet* packet = (Packet*)malloc(sizeof(Packet));
    if (!packet) {
        return -1; // Memory allocation failed
    }

    packet->payload_size = payload_size;
    packet->payload = (char*)malloc(payload_size);
    if (!packet->payload) {
        free(packet);
        return -1; // Memory allocation failed
    }

    manager->packets[manager->packet_count++] = packet;

    return 0; // Success
}

size_t total_memory_usage(PacketManager* manager) {
    size_t total_size = sizeof(PacketManager);
    for (size_t i = 0; i < manager->packet_count; ++i) {
        total_size += sizeof(Packet) + manager->packets[i]->payload_size;
    }
    return total_size;
}
```

