#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *prev, *next;
} NFAPI_CRC_INDICATION_PDU;

typedef struct {
    NFAPI_CRC_INDICATION_PDU *head, *tail;
    size_t count;
    pthread_mutex_t lock;
} DoublyLinkedList;

void initializeList(DoublyLinkedList *list) {
    list->head = list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void insertNode(DoublyLinkedList *list, NFAPI_CRC_INDICATION_PDU *node) {
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = list->tail = node;
    } else {
        node->prev = list->tail;
        list->tail->next = node;
        list->tail = node;
    }
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU *createNode(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU *node = (NFAPI_CRC_INDICATION_PDU *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed: Requested %zu bytes, available memory insufficient.\n", sizeof(NFAPI_CRC_INDICATION_PDU));
        return NULL;
    }
    node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    node->RNTI = RNTI;
    node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    node->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    node->prev = node->next = NULL;
    return node;
}

void freeList(DoublyLinkedList *list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU *current = list->head, *temp;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }
    list->head = list->tail = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
}

int main() {
    DoublyLinkedList list;
    initializeList(&list);

    // Example usage
    NFAPI_CRC_INDICATION_PDU *node1 = createNode(1, 256, 3);
    if (node1 != NULL) insertNode(&list, node1);

    freeList(&list);

    return 0;
}
