#include <stdlib.h>
#include <string.h>
#include <errno.h>

#define MAX_PACKET_SIZE 4096

typedef struct Packet {
    char payload[MAX_PACKET_SIZE];
    size_t payload_size;
    struct Packet* next;
    struct Packet* prev;
} Packet;

typedef struct PacketQueue {
    Packet* head;
    Packet* tail;
    size_t total_memory_used;
    size_t max_capacity;
    size_t memory_limit;
} PacketQueue;

Packet* create_packet(const char* payload, size_t payload_size) {
    if (payload_size > MAX_PACKET_SIZE) return NULL;
    Packet* new_packet = (Packet*)malloc(sizeof(Packet));
    if (!new_packet) return NULL;
    memcpy(new_packet->payload, payload, payload_size);
    new_packet->payload_size = payload_size;
    new_packet->next = NULL;
    new_packet->prev = NULL;
    return new_packet;
}

int enqueue_packet(PacketQueue* queue, const char* payload, size_t payload_size) {
    if (queue->total_memory_used + payload_size > queue->memory_limit) {
        errno = ENOMEM;
        return -1;
    }
    Packet* new_packet = create_packet(payload, payload_size);
    if (!new_packet) {
        errno = ENOMEM;
        return -1;
    }
    if (queue->head == NULL) {
        queue->head = new_packet;
        queue->tail = new_packet;
    } else {
        queue->tail->next = new_packet;
        new_packet->prev = queue->tail;
        queue->tail = new_packet;
    }
    queue->total_memory_used += payload_size;
    return 0;
}

PacketQueue* create_queue(size_t max_capacity, size_t memory_limit) {
    PacketQueue* queue = (PacketQueue*)malloc(sizeof(PacketQueue));
    if (!queue) return NULL;
    queue->head = NULL;
    queue->tail = NULL;
    queue->total_memory_used = 0;
    queue->max_capacity = max_capacity;
    queue->memory_limit = memory_limit;
    return queue;
}

void destroy_queue(PacketQueue* queue) {
    while (queue->head != NULL) {
        Packet* temp = queue->head;
        queue->head = queue->head->next;
        free(temp);
    }
    free(queue);
}
