function copyBuffer(dataChunks, byteOffset, byteLength) {
    const newBuffer = Buffer.allocUnsafe(byteLength);
    let bytesRead = 0;
    dataChunks.forEach(chunk => {
        if (bytesRead >= byteLength) return;
        const chunkBytesToCopy = Math.min(byteLength - bytesRead, chunk.length);
        chunk.copy(newBuffer, bytesRead, 0, chunkBytesToCopy);
        bytesRead += chunkBytesToCopy;
    });
    return newBuffer.slice(0, byteLength); // Return only the copied bytes
}
```

