#include <stdint.h>
#include <time.h>

typedef struct PacketMetaData {
    uint32_t packetID;
    time_t timestamp;
    uint8_t *payload;
    size_t payloadSize;
} PacketMetaData;

typedef struct StreamBuffer {
    PacketMetaData **packets;
    size_t capacity;
    size_t count;
    size_t bufferLimit;
    size_t totalPayloadSize;
} StreamBuffer;

int processPacket(StreamBuffer *buffer, uint32_t packetID, time_t timestamp, const uint8_t *payload, size_t payloadSize) {
    if (buffer == NULL || payload == NULL || payloadSize == 0)
        return -1; // Invalid input

    if (buffer->totalPayloadSize + payloadSize > buffer->bufferLimit)
        return -2; // Buffer limit exceeded

    PacketMetaData *packet = malloc(sizeof(PacketMetaData));
    if (packet == NULL)
        return -3; // Memory allocation failed

    packet->packetID = packetID;
    packet->timestamp = timestamp;
    packet->payloadSize = payloadSize;

    packet->payload = malloc(payloadSize);
    if (packet->payload == NULL) {
        free(packet);
        return -4; // Memory allocation failed
    }

    memcpy(packet->payload, payload, payloadSize);

    buffer->packets[buffer->count++] = packet;
    buffer->totalPayloadSize += payloadSize;

    return 0; // Success
}

void freePacket(PacketMetaData *packet) {
    if (packet != NULL) {
        free(packet->payload);
        free(packet);
    }
}

void freeStreamBuffer(StreamBuffer *buffer) {
    if (buffer != NULL) {
        for (size_t i = 0; i < buffer->count; ++i)
            freePacket(buffer->packets[i]);

        free(buffer->packets);
        free(buffer);
    }
}
