void init_crc_indication_list(CRC_Indication_List* list, size_t max_memory) {
    list->head = NULL;
    list->total_memory_used = 0;
    list->max_allowed_memory = max_memory;
    pthread_mutex_init(&list->mutex, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_pdu() {
    NFAPI_CRC_INDICATION_PDU_T* new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_pdu == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    return new_pdu;
}

void add_crc_pdu_to_list(CRC_Indication_List* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->total_memory_used + sizeof(NFAPI_CRC_INDICATION_PDU_T) > list->max_allowed_memory) {
        // Handle memory limit exceeded
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    pdu->next = list->head;
    list->head = pdu;
    list->total_memory_used += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pthread_mutex_unlock(&list->mutex);
}

void delete_crc_pdu_from_list(CRC_Indication_List* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->mutex);
    if (pdu == list->head) {
        list->head = pdu->next;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* current = list->head;
        while (current != NULL && current->next != pdu) {
            current = current->next;
        }
        if (current != NULL) {
            current->next = pdu->next;
        }
    }
    list->total_memory_used -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
    free(pdu);
    pthread_mutex_unlock(&list->mutex);
}

void clear_crc_indication_list(CRC_Indication_List* list) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->total_memory_used = 0;
}

void destroy_crc_indication_list(CRC_Indication_List* list) {
    pthread_mutex_destroy(&list->mutex);
    clear_crc_indication_list(list);
}
