#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node** bucket;
    size_t size;
    size_t capacity;
    size_t (*hash)(NFAPI_CRC_INDICATION_PDU_T);
} DynamicCollection;

size_t hashFunction(NFAPI_CRC_INDICATION_PDU_T data) {
    return (data.RX_UE_INFORMATION_TAG * 31 + data.RNTI) % capacity;
}

DynamicCollection* createCollection(size_t initialCapacity) {
    if (initialCapacity == 0 || initialCapacity > SIZE_MAX / sizeof(Node*)) {
        errno = EOVERFLOW;
        return NULL;
    }

    DynamicCollection* collection = malloc(sizeof(DynamicCollection));
    if (!collection) {
        return NULL;
    }

    collection->head = NULL;
    collection->bucket = calloc(initialCapacity, sizeof(Node*));
    if (!collection->bucket) {
        free(collection);
        return NULL;
    }

    collection->size = 0;
    collection->capacity = initialCapacity;
    collection->hash = hashFunction;

    return collection;
}

void destroyCollection(DynamicCollection* collection) {
    Node* current = collection->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    free(collection->bucket);
    free(collection);
}

int addPDU(DynamicCollection* collection, NFAPI_CRC_INDICATION_PDU_T pdu) {
    size_t index = collection->hash(pdu);

    if (collection->size >= collection->capacity / 2) {
        // Resize the bucket
        size_t newCapacity = collection->capacity * 2;
        Node** newBucket = realloc(collection->bucket, newCapacity * sizeof(Node*));
        if (!newBucket) {
            return -1; // Allocation failed
        }

        memset(newBucket + collection->capacity, 0, (newCapacity - collection->capacity) * sizeof(Node*));

        // Rehash existing elements
        Node* current = collection->head;
        while (current) {
            size_t newIndex = collection->hash(current->data);
            Node* temp = current->next;
            current->next = newBucket[newIndex];
            newBucket[newIndex] = current;
            current = temp;
        }

        free(collection->bucket);
        collection->bucket = newBucket;
        collection->capacity = newCapacity;
    }

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        return -1; // Allocation failed
    }

    newNode->data = pdu;
    newNode->next = collection->bucket[index];
    collection->bucket[index] = newNode;

    collection->size++;
    return 0;
}

int main() {
    DynamicCollection* collection = createCollection(16);
    if (!collection) {
        perror("Failed to create collection");
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 2, 3, rand() % 2};
    if (addPDU(collection, pdu) != 0) {
        perror("Failed to add PDU to collection");
        destroyCollection(collection);
        return EXIT_FAILURE;
    }

    // Additional operations...

    destroyCollection(collection);
    return EXIT_SUCCESS;
}
