typedef struct PacketNode {
    int id;
    char *data;
    size_t data_size;
    struct PacketNode *next;
} PacketNode;

PacketNode* create_packet_node(int id, const void *data, size_t data_size) {
    if (id <= 0 || !data || data_size == 0) return NULL; // Error handling for invalid inputs

    PacketNode *node = (PacketNode*)malloc(sizeof(PacketNode));
    if (!node) return NULL; // Handle memory allocation failure

    node->id = id;
    node->data_size = data_size;

    // Allocate memory for data payload
    node->data = (char*)malloc(data_size);
    if (!node->data) {
        free(node); // Clean up on error
        return NULL;
    }
    memcpy(node->data, data, data_size);

    node->next = NULL;
    return node;
}

void insert_packet_node(PacketNode **head, PacketNode *new_node) {
    if (!head || !new_node) return; // Error handling for invalid inputs

    // Prevent duplicate entries
    if (*head && (*head)->id == new_node->id) {
        free(new_node->data);
        free(new_node); // Clean up on error
        return;
    }

    new_node->next = *head;
    *head = new_node;
}

void free_packet_list(PacketNode **head) {
    PacketNode *current, *temp;
    if (!head || !*head) return; // Error handling for invalid inputs

    current = *head;
    while (current) {
        temp = current;
        current = current->next;

        // Free the data payload and the node itself
        free(temp->data);
        free(temp);
    }

    *head = NULL;
}

// Example usage:
int main() {
    PacketNode *packet_list = NULL;

    // Simulate packet reception
    int id = 1;
    char data[] = "Hello, world!";
    size_t data_size = strlen(data);

    PacketNode *new_node = create_packet_node(id, data, data_size);
    if (new_node) {
        insert_packet_node(&packet_list, new_node);
    }

    // Clean up
    free_packet_list(&packet_list);

    return 0;
}
