#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} CRCList;

void initCRCList(CRCList *list, size_t initialCapacity) {
    list->data = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->size = 0;
    list->capacity = initialCapacity;
    pthread_mutex_init(&list->lock, NULL);
}

void freeCRCList(CRCList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->data);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int addCRCEntry(CRCList *list, int RX_UE_INFORMATION_TAG, unsigned int RNTI, int CRCFLAG, size_t memoryThreshold) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        size_t newCapacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *newData = realloc(list->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newData) {
            fprintf(stderr, "Memory reallocation failed\n");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->data = newData;
        list->capacity = newCapacity;
    }

    NFAPI_CRC_INDICATION_PDU_T entry = {RX_UE_INFORMATION_TAG, RNTI, CRCFLAG};
    list->data[list->size++] = entry;

    if (list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T) > memoryThreshold) {
        fprintf(stderr, "Memory threshold exceeded\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int main() {
    CRCList crcList;
    initCRCList(&crcList, 10);

    int result = addCRCEntry(&crcList, 12345, 1001, 1, 100 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (result == 0) {
        printf("CRC entry added successfully\n");
    } else {
        printf("Failed to add CRC entry\n");
    }

    freeCRCList(&crcList);
    return 0;
}
```

