typedef struct {
    size_t total_memory_allocated;
    pthread_mutex_t memory_lock;
} MemoryManager;

MemoryManager memory_manager = {0, PTHREAD_MUTEX_INITIALIZER};

void* allocate_packet_payload(size_t payload_size) {
    if (payload_size > SIZE_MAX - memory_manager.total_memory_allocated) {
        return NULL; // Integer overflow check
    }

    size_t new_total_memory = memory_manager.total_memory_allocated + payload_size;
    if (new_total_memory > MAX_MEMORY_LIMIT) {
        return NULL; // Memory limit exceeded
    }

    pthread_mutex_lock(&memory_manager.memory_lock);
    void* payload = malloc(payload_size);
    if (payload != NULL) {
        memory_manager.total_memory_allocated = new_total_memory;
    }
    pthread_mutex_unlock(&memory_manager.memory_lock);

    return payload;
}

void free_packet_payload(void* payload, size_t payload_size) {
    pthread_mutex_lock(&memory_manager.memory_lock);
    free(payload);
    memory_manager.total_memory_allocated -= payload_size;
    pthread_mutex_unlock(&memory_manager.memory_lock);
}
