// Function to process batch of packets and store in dynamically allocated buffer
char* process_packets(PacketHeader** headers, void** payloads, int num_packets) {
    if (num_packets > INT_MAX / sizeof(PacketHeader*) || 
        num_packets * MAX_PACKET_SIZE > INT_MAX - sizeof(char*)) {
        // Handle error: Integer overflow detected
        return NULL;
    }

    // Calculate total buffer size needed
    size_t total_size = num_packets * sizeof(PacketHeader*);
    for (int i = 0; i < num_packets; ++i) {
        if (payloads[i] == NULL || strlen(payloads[i]) > MAX_PACKET_SIZE) {
            // Handle error: Invalid payload or oversized packet
            return NULL;
        }
        total_size += strlen(payloads[i]);
    }

    // Allocate buffer for storing packet pointers and payloads
    char* buffer = malloc(total_size);
    if (buffer == NULL) {
        // Handle error: Memory allocation failed
        return NULL;
    }

    // Copy packet headers into the buffer
    char* buffer_ptr = buffer;
    for (int i = 0; i < num_packets; ++i) {
        memcpy(buffer_ptr, &headers[i], sizeof(PacketHeader*));
        buffer_ptr += sizeof(PacketHeader*);
    }

    // Concatenate payloads to the buffer after headers
    for (int i = 0; i < num_packets; ++i) {
        size_t payload_size = strlen(payloads[i]) + 1; // Include null terminator
        memcpy(buffer_ptr, payloads[i], payload_size);
        buffer_ptr += payload_size;
    }

    return buffer;
}
