#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>

#define MAX_PACKETS 100
#define HEADER_SIZE 8
#define PAYLOAD_MAX_SIZE 4096

typedef struct PacketHeader {
    unsigned long timestamp;
    int protocol_type;
    char *payload;
} PacketHeader;

PacketHeader** process_packets(int packet_count, ...) {
    va_list args;
    va_start(args, packet_count);

    if (packet_count > MAX_PACKETS) {
        fprintf(stderr, "Error: Too many packets.\n");
        return NULL;
    }

    PacketHeader **headers = malloc(packet_count * sizeof(PacketHeader *));
    for (int i = 0; i < packet_count; ++i) {
        headers[i] = malloc(sizeof(PacketHeader));
        memset(headers[i], 0, sizeof(PacketHeader));

        unsigned long timestamp = va_arg(args, unsigned long);
        int protocol_type = va_arg(args, int);

        if ((timestamp & ~0UL) != timestamp || (protocol_type < 1 || protocol_type > 255)) {
            fprintf(stderr, "Error: Malformed packet.\n");
            for (int j = 0; j <= i; ++j) free(headers[j]);
            free(headers);
            return NULL;
        }

        headers[i]->timestamp = timestamp;
        headers[i]->protocol_type = protocol_type;

        int payload_size = va_arg(args, int);
        if (payload_size < 1 || payload_size > PAYLOAD_MAX_SIZE) {
            fprintf(stderr, "Error: Malformed packet.\n");
            for (int j = 0; j <= i; ++j) free(headers[j]->payload), free(headers[j]);
            free(headers);
            return NULL;
        }

        headers[i]->payload = malloc(payload_size);
        if (!headers[i]->payload) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            for (int j = 0; j <= i; ++j) free(headers[j]->payload), free(headers[j]);
            free(headers);
            return NULL;
        }

        memset(headers[i]->payload, 0, payload_size); // Initialize payload to zero
    }
    va_end(args);

    return headers;
}

void free_headers(PacketHeader **headers, int packet_count) {
    for (int i = 0; i < packet_count; ++i) {
        free(headers[i]->payload);
        free(headers[i]);
    }
    free(headers);
}

int main() {
    PacketHeader **headers = process_packets(3,
                                           123456789, 1, 10,
                                           987654321, 2, 20,
                                           111111111, 3, 30);
    if (headers) {
        for (int i = 0; i < 3; ++i) {
            printf("Packet %d: Timestamp=%lu, Protocol=%d, Payload Size=%zu\n",
                   i + 1, headers[i]->timestamp, headers[i]->protocol_type,
                   strlen(headers[i]->payload));
            free(headers[i]->payload);
            free(headers[i]);
        }
        free(headers);
    }

    return 0;
}
```

This C code snippet defines a function `process_packets` that processes a variable number of network packets. Each packet is expected to have a timestamp, protocol type, and a payload size. The function constructs a list of `PacketHeader` structures, each containing the parsed information from the packet. It includes checks for malformed packets and prevents buffer overflows by dynamically allocating memory for the payload based on the parsed header.

The `free_headers` function is provided to properly free the allocated memory when done with the headers. The `main` function demonstrates how to use the `process_packets` function and clean up the resources.

This code assumes that the input parameters are valid and well-formed, but in a real-world scenario, additional error handling and validation would be necessary to ensure robustness against unexpected inputs.']

