int readNFromConfigFile(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        fprintf(stderr, "Error opening configuration file: %s\n", filename);
        return 10; // Default to 10 if file is not found
    }

    int N;
    char buffer[256];
    if (fgets(buffer, sizeof(buffer), file)) {
        sscanf(buffer, "%d", &N);
    } else {
        fprintf(stderr, "Configuration file is empty or invalid.\n");
        fclose(file);
        return 10; // Default to 10
    }

    fclose(file);

    if (N < 1 || N > 1000) {
        fprintf(stderr, "N out of safe range. Clamping to 10.\n");
        N = 10;
    }

    return N;
}

void initializePDUs(NFAPI_CRC_INDICATION_PDU_T* pdus, int N) {
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = i + 1; // Example initialization
        pdus[i].RNTI = rand() % 4096; // Random RNTI between 0 and 4095

        // Prevent duplicate RNTIs
        for (int j = 0; j < i; j++) {
            while (pdus[j].RNTI == pdus[i].RNTI) {
                pdus[i].RNTI = rand() % 4096;
            }
        }

        pdus[i].CRC_INDICATION_REL8_TAG = i + 1; // Example initialization
        pdus[i].CRCFLAG = (rand() % 2); // Randomly set CRCFLAG to 0 or 1
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocateAndInitializePDUs(const char* configFilename) {
    int N = readNFromConfigFile(configFilename);
    if (N <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdus == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    initializePDUs(pdus, N);

    return pdus;
}

void freePDUs(NFAPI_CRC_INDICATION_PDU_T* pdus, int N) {
    free(pdus);
}
