#include <string.h>

#define MAX_PACKET_ID 1000

typedef struct {
    int id;
    size_t payload_length;
    time_t arrival_timestamp;
} Packet;

typedef struct {
    Packet** packets;
    size_t capacity;
    size_t size;
    size_t total_memory_used;
    size_t memory_limit;
} PacketBuffer;

PacketBuffer* init_packet_buffer(size_t max_packets, size_t memory_limit) {
    PacketBuffer* buffer = (PacketBuffer*)malloc(sizeof(PacketBuffer));
    if (!buffer) {
        fprintf(stderr, "Failed to allocate memory for packet buffer\n");
        return NULL;
    }
    buffer->packets = (Packet**)malloc(max_packets * sizeof(Packet*));
    if (!buffer->packets) {
        free(buffer);
        fprintf(stderr, "Failed to allocate memory for packets array\n");
        return NULL;
    }
    memset(buffer->packets, 0, max_packets * sizeof(Packet*));
    buffer->capacity = max_packets;
    buffer->size = 0;
    buffer->total_memory_used = 0;
    buffer->memory_limit = memory_limit;
    return buffer;
}

void free_packet_buffer(PacketBuffer* buffer) {
    for (size_t i = 0; i < buffer->size; ++i) {
        if (buffer->packets[i]) {
            free(buffer->packets[i]);
        }
    }
    free(buffer->packets);
    free(buffer);
}

int add_packet(PacketBuffer* buffer, Packet* packet) {
    if (buffer->total_memory_used + sizeof(Packet) > buffer->memory_limit ||
        buffer->size >= buffer->capacity) {
        fprintf(stderr, "Memory limit exceeded or buffer full\n");
        return -1;
    }
    buffer->packets[buffer->size++] = packet;
    buffer->total_memory_used += sizeof(Packet);
    return 0;
}

// Example usage
int main() {
    PacketBuffer* buffer = init_packet_buffer(10, 1024 * 1024); // Buffer for 10 packets with a 1MB memory limit
    if (!buffer) {
        return EXIT_FAILURE;
    }

    // Simulate adding packets
    Packet packet1 = {1, 500, time(NULL)};
    add_packet(buffer, &packet1);

    Packet packet2 = {2, 600, time(NULL)};
    add_packet(buffer, &packet2);

    free_packet_buffer(buffer);
    return EXIT_SUCCESS;
}
