// Define ImageMetadata structure
typedef struct {
    char* filePath;
    int width;
    int height;
} ImageMetadata;

// Function to allocate and initialize an array of ImageMetadata structures
ImageMetadata* createImageMetadataArray(int numImages, const char** filePaths, int* resolutions, int numResolutions) {
    if (numImages <= 0 || !filePaths || numResolutions != numImages * 2) {
        return NULL;
    }

    ImageMetadata* imageMetadata = (ImageMetadata*)malloc(numImages * sizeof(ImageMetadata));
    if (!imageMetadata) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < numImages; ++i) {
        // Allocate memory for filePath
        int filePathLength = strlen(filePaths[i]) + 1;
        imageMetadata[i].filePath = (char*)malloc(filePathLength * sizeof(char));
        if (!imageMetadata[i].filePath) {
            perror("Memory allocation failed");
            // Free previously allocated memory before returning NULL
            for (int j = 0; j < i; ++j) {
                free(imageMetadata[j].filePath);
            }
            free(imageMetadata);
            return NULL;
        }
        strcpy(imageMetadata[i].filePath, filePaths[i]);

        // Validate and assign width and height
        int width = resolutions[2 * i];
        int height = resolutions[2 * i + 1];

        // Check for integer overflow
        if (width < 0 || height < 0 || ((width > INT_MAX / height) && (height != 0))) {
            fprintf(stderr, "Integer overflow detected\n");
            // Free previously allocated memory before returning NULL
            free(imageMetadata[i].filePath);
            for (int j = 0; j <= i; ++j) {
                free(imageMetadata[j].filePath);
            }
            free(imageMetadata);
            return NULL;
        }

        imageMetadata[i].width = width;
        imageMetadata[i].height = height;
    }

    return imageMetadata;
}

// Function to free the allocated memory for ImageMetadata array
void freeImageMetadataArray(ImageMetadata* metadata, int numImages) {
    if (metadata && numImages > 0) {
        for (int i = 0; i < numImages; ++i) {
            free(metadata[i].filePath);
        }
        free(metadata);
    }
}
