#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

typedef struct {
    uint32_t packet_size;
    uint8_t* data_segments;
} NetworkPacket;

typedef struct {
    size_t buffer_size;
    size_t used_size;
    pthread_mutex_t lock;
} PacketBuffer;

PacketBuffer* create_packet_buffer(size_t initial_size) {
    PacketBuffer* buffer = malloc(sizeof(PacketBuffer));
    if (!buffer) return NULL;

    buffer->buffer_size = initial_size;
    buffer->used_size = 0;
    if (pthread_mutex_init(&buffer->lock, NULL) != 0) {
        free(buffer);
        return NULL;
    }

    buffer->data_segments = malloc(initial_size);
    if (!buffer->data_segments) {
        pthread_mutex_destroy(&buffer->lock);
        free(buffer);
        return NULL;
    }

    return buffer;
}

void destroy_packet_buffer(PacketBuffer* buffer) {
    if (buffer->data_segments) free(buffer->data_segments);
    pthread_mutex_destroy(&buffer->lock);
    free(buffer);
}

int process_packets(NetworkPacket* packets, size_t packet_count, PacketBuffer* buffer) {
    pthread_mutex_lock(&buffer->lock);

    // Calculate total required buffer size
    size_t total_size = 0;
    for (size_t i = 0; i < packet_count; ++i) {
        total_size += packets[i].packet_size;
    }

    // Resize buffer if necessary
    while (total_size > buffer->buffer_size) {
        size_t new_size = buffer->buffer_size * 2;
        uint8_t* new_data = realloc(buffer->data_segments, new_size);
        if (!new_data) {
            pthread_mutex_unlock(&buffer->lock);
            return -1; // Resize failed
        }

        buffer->buffer_size = new_size;
        buffer->data_segments = new_data;
    }

    // Copy packet data to buffer
    for (size_t i = 0; i < packet_count; ++i) {
        memcpy(buffer->data_segments + buffer->used_size, packets[i].data_segments, packets[i].packet_size);
        buffer->used_size += packets[i].packet_size;
    }

    pthread_mutex_unlock(&buffer->lock);
    return 0;
}
