        return NULL; // Too many files to handle
    }

    clock_t start = clock();
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T** tail = &head;

    for (int i = 0; i < numFiles; i++) {
        // Simulate reading and parsing JSON file
