        fclose(file);
        printf("Processed %d PDUs from file: %s\n", count, configFiles[i]);
    }

    clock_t end = clock();
    double timeTaken = (double)(end - start) / CLOCKS_PER_SEC;
    printf("Average time per PDU: %.6f seconds\n", timeTaken / (*tail == NULL ? 1 : *tail->data));

    return head;
