#define MAX_MEMORY 1048576 // Example maximum memory limit

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t count;
    size_t capacity;
    size_t max_capacity;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* dynamic_list_create(size_t initial_size) {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (list == NULL) {
        return NULL;
    }
    list->data = realloc(NULL, initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->data == NULL) {
        free(list);
        return NULL;
    }
    list->count = 0;
    list->capacity = initial_size;
    list->max_capacity = MAX_MEMORY / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void dynamic_list_destroy(DynamicList* list) {
    pthread_mutex_lock(&list->mutex);
    free(list->data);
    pthread_mutex_unlock(&list->mutex);
    free(list);
}

int dynamic_list_add(DynamicList* list) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= 1.5 * list->capacity && list->count < list->max_capacity) {
        size_t new_capacity = list->capacity * 2;
        if (new_capacity > list->max_capacity) {
            new_capacity = list->max_capacity;
        }
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data == NULL) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Allocation failed
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    // Set random values for demonstration purposes
    list->data[list->count].RX_UE_INFORMATION_TAG = rand();
    list->data[list->count].RNTI = rand();
    list->data[list->count].CRC_INDICATION_REL8_TAG = rand();
    list->data[list->count].CRCFLAG = rand() % 2;
    list->count++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Additional functions for accessing and managing the list can be added here
