ImageData* createImage(unsigned int width, unsigned int height) {
    if (width == 0 || height == 0) {
        fprintf(stderr, "Error: Width and height must be greater than zero.\n");
        return NULL;
    }

    // Calculate total size needed for pixel data
    size_t requiredSize = width * height * sizeof(char);
    if (requiredSize / width != height) {
        fprintf(stderr, "Error: Integer overflow detected in pixel data size calculation.\n");
        return NULL;
    }

    ImageData *image = malloc(sizeof(ImageData));
    if (image == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for ImageData structure.\n");
        return NULL;
    }

    image->width = width;
    image->height = height;

    // Allocate memory for pixel data
    image->pixelData = malloc(requiredSize);
    if (image->pixelData == NULL) {
        free(image); // Free the allocated ImageData structure to avoid memory leak
        fprintf(stderr, "Error: Failed to allocate memory for pixel data.\n");
        return NULL;
    }

    return image;
}

void destroyImage(ImageData *image) {
    if (image != NULL) {
        free(image->pixelData);
        free(image);
    }
}

int main() {
    unsigned int width = 1024;
    unsigned int height = 768;

    ImageData *img = createImage(width, height);
    if (img != NULL) {
        printf("Image created successfully with dimensions: %u x %u\n", img->width, img->height);
        destroyImage(img);
    }

    return 0;
}
