    int width;
    int height;
    float compressionRatio;
} ImageMetadata;

typedef struct FileList {
    char** paths;
    size_t count;
} FileList;

ImageMetadata* extract_metadata(FileList* fileList, pthread_mutex_t* mutex) {
    if (!fileList || !mutex) {
        return NULL;
    }

    // Calculate the total memory needed
    size_t totalSize = sizeof(ImageMetadata) * fileList->count;
    ImageMetadata* metadata = (ImageMetadata*)malloc(totalSize);
    if (!metadata) {
        perror("Failed to allocate memory for metadata");
        return NULL;
    }

    pthread_mutex_lock(mutex);

    // Process each file and store metadata
    for (size_t i = 0; i < fileList->count; ++i) {
        metadata[i].path = strdup(fileList->paths[i]);
        if (!metadata[i].path) {
            perror("Failed to allocate memory for path");
            free(metadata);
            pthread_mutex_unlock(mutex);
            return NULL;
        }

        // Simulate metadata extraction
        metadata[i].width = 1920; // Example width
        metadata[i].height = 1080; // Example height
        metadata[i].compressionRatio = 0.75f; // Example compression ratio

        if (i > 0) {
            // Simulate integer overflow check for memory allocation
            size_t nextSize = totalSize + sizeof(ImageMetadata);
            if (nextSize < totalSize || nextSize == 0) {
                fprintf(stderr, "Integer overflow detected during memory allocation\n");
                free(metadata);
                pthread_mutex_unlock(mutex);
                return NULL;
            }
        }
    }

    pthread_mutex_unlock(mutex);

    return metadata;
}

int main() {
    // Example usage
    FileList fileList = {.paths = (char*[]){"/path/to/image1.jpg", "/path/to/image2.jpg"}, .count = 2};
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    ImageMetadata* metadata = extract_metadata(&fileList, &mutex);
    if (metadata) {
        for (size_t i = 0; i < fileList.count; ++i) {
            printf("Path: %s, Dimensions: %dx%d, Compression Ratio: %.2f\n", 
                   metadata[i].path, metadata[i].width, metadata[i].height, metadata[i].compressionRatio);
            free(metadata[i].path);
        }
        free(metadata);
    }

    return 0;
}
