        fprintf(stderr, "Error: Integer overflow in allocation\n");
        exit(EXIT_FAILURE);
    }

    PacketMetadata* metadata = (PacketMetadata*)malloc(count * sizeof(PacketMetadata));
    if (metadata == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    return metadata;
}

// Function to free allocated memory
void free_packet_metadata(PacketMetadata* metadata) {
    if (metadata != NULL) {
        free(metadata);
    }
}

// Thread-safe function to add packet metadata
void add_packet_metadata(pthread_mutex_t* lock, PacketMetadata** metadata, size_t* count, const PacketMetadata* new_data) {
    pthread_mutex_lock(lock);

    // Check if more memory is needed
    if (*count == 0 || *metadata == NULL) {
        *metadata = allocate_packet_metadata(1);
        *count = 1;
    } else if (*count >= SIZE_MAX / sizeof(PacketMetadata)) {
        fprintf(stderr, "Error: Integer overflow in allocation\n");
        pthread_mutex_unlock(lock);
        return;
    }

    // Resize metadata array
    PacketMetadata* new_metadata = allocate_packet_metadata(*count + 1);
    for (size_t i = 0; i < *count; ++i) {
        new_metadata[i] = (*metadata)[i];
    }
    new_metadata[*count] = *new_data;
    free_packet_metadata(*metadata);
    *metadata = new_metadata;
    ++*count;

    pthread_mutex_unlock(lock);
}

// Example usage
int main() {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    PacketMetadata* metadata = NULL;
    size_t count = 0;

    // Simulate adding packet metadata from multiple threads
    for (size_t i = 0; i < 1000; ++i) {
        PacketMetadata new_data = {i, "TCP", i * 100, time(NULL)};
        add_packet_metadata(&lock, &metadata, &count, &new_data);
    }

    // Free allocated memory
    free_packet_metadata(metadata);

    return 0;
}
