#define MAX_PDUS 1000000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
};

struct Node* create_crc_indications_list(const char* config_file, double crc_prob) {
    FILE* file = fopen(config_file, "r");
    if (file == NULL) {
        perror("Failed to open configuration file");
        return NULL;
    }

    int num_pdus;
    if (fscanf(file, "%d", &num_pdus) != 1) {
        fprintf(stderr, "Invalid format in configuration file\n");
        fclose(file);
        return NULL;
    }

    if (num_pdus <= 0 || num_pdus > MAX_PDUS) {
        fprintf(stderr, "Number of PDUs out of valid range (1-%d)\n", MAX_PDUS);
        fclose(file);
        return NULL;
    }

    struct Node* head = NULL;
    struct Node** current = &head;

    for (int i = 0; i < num_pdus; ++i) {
        if (((*current) = malloc(sizeof(struct Node))) == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            fclose(file);
            // Free previously allocated nodes
            while (head != NULL) {
                struct Node* temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }

        (*current)->data.RX_UE_INFORMATION_TAG = rand() % 1000; // Example range
        (*current)->data.RNTI = rand() % 500 + 1; // Example range
        if ((double)rand() / RAND_MAX < crc_prob) {
            (*current)->data.CRCFLAG = 1;
        } else {
            (*current)->data.CRCFLAG = 0;
        }
        (*current)->next = NULL;

        current = &(*current)->next;
    }

    fclose(file);
    return head;
}

void print_list(struct Node* head) {
    struct Node* current = head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.CRCFLAG);
        current = current->next;
    }
}

void free_list(struct Node* head) {
    struct Node* current = head;
    while (current != NULL) {
        struct Node* temp = current;
        current = current->next;
        free(temp);
    }
}

int main() {
    srand(time(NULL));
    const char* config_file = "config.txt";
    double crc_prob = 0.75;

    struct Node* list = create_crc_indications_list(config_file, crc_prob);
    if (list != NULL) {
        print_list(list);
        free_list(list);
    }

    return 0;
}
