                break;
            }

            // Allocate memory for new structure
            NFAPI_CRC_INDICATION_PDU_T* newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!newNode) {
                overflowCount++;
                continue;
            }
            newNode->data = data;
            newNode->next = NULL;

            // Add to the linked list
            if (tail == NULL) {
                head = tail = newNode;
            } else {
                tail->next = newNode;
                tail = newNode;
            }

            totalStructures++;
        }

        fclose(file);
    }

