    free(list->items);
    free(list);
}

int add_image_metadata(IMAGE_LIST_T* list, IMAGE_METADATA_T metadata) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity && list->buffer_end + sizeof(IMAGE_METADATA_T) > MAX_MEMORY) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        IMAGE_METADATA_T* new_items = (IMAGE_METADATA_T*)realloc(list->items, new_capacity * sizeof(IMAGE_METADATA_T));
        if (!new_items) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->items = new_items;
        list->capacity = new_capacity;
    }

    list->items[list->size++] = metadata;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

