#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define HEADER_SIZE 4 // Example header size that specifies payload length

typedef struct Packet {
    uint32_t payload_length;
    void* payload;
} Packet;

typedef struct PacketQueue {
    Packet** packets;
    size_t capacity;
    size_t size;
    size_t front;
} PacketQueue;

void initPacketQueue(PacketQueue* queue, size_t initial_capacity) {
    queue->capacity = initial_capacity;
    queue->size = 0;
    queue->front = 0;
    queue->packets = (Packet**)malloc(initial_capacity * sizeof(Packet*));
}

void enqueuePacket(PacketQueue* queue, Packet* packet) {
    if (queue->size == queue->capacity) {
        // Double the capacity
        queue->capacity *= 2;
        queue->packets = (Packet**)realloc(queue->packets, queue->capacity * sizeof(Packet*));
    }
    queue->packets[(queue->front + queue->size++) % queue->capacity] = packet;
}

Packet* dequeuePacket(PacketQueue* queue) {
    if (queue->size == 0) return NULL;
    Packet* packet = queue->packets[queue->front];
    queue->front = (queue->front + 1) % queue->capacity;
    queue->size--;
    return packet;
}

void freePacketQueue(PacketQueue* queue) {
    for (size_t i = 0; i < queue->size; ++i) {
        Packet* packet = dequeuePacket(queue);
        if (packet) {
            free(packet->payload);
            free(packet);
        }
    }
    free(queue->packets);
}

void processPackets(PacketQueue* queue) {
    while (Packet* packet = dequeuePacket(queue)) {
        // Process the packet payload
        printf("Processing packet with payload length: %zu\n", packet->payload_length);
        // Free the packet after processing
        free(packet->payload);
        free(packet);
    }
}

int main() {
    PacketQueue queue;
    initPacketQueue(&queue, 10);

    // Simulate receiving packets
    for (size_t i = 0; i < 20; ++i) {
        Packet* packet = (Packet*)malloc(sizeof(Packet));
        packet->payload_length = (uint32_t)i * 10; // Example payload length
        packet->payload = malloc(packet->payload_length); // Allocate memory for payload
        memset(packet->payload, 'A', packet->payload_length); // Fill payload with example data

        enqueuePacket(&queue, packet);
    }

    processPackets(&queue);

    freePacketQueue(&queue);
    return 0;
}
```

