#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "packet_processing_framework.h"

#define MIN_CONCURRENT_PROCESSES 1
#define MAX_CONCURRENT_PROCESSES 32
#define DEFAULT_CONCURRENT_PROCESSES 4

typedef struct {
    char payload[MAX_PACKET_SIZE];
} PacketData;

typedef struct {
    int num_packets;
    PacketData *packets;
    pthread_mutex_t lock;
} PacketQueue;

PacketQueue packet_queue = {0};
int concurrent_processes = DEFAULT_CONCURRENT_PROCESSES;

void* process_packet(void* arg) {
    int packet_index;
    while (1) {
        pthread_mutex_lock(&packet_queue.lock);
        if (packet_queue.num_packets > 0) {
            packet_index = packet_queue.num_packets - 1;
            packet_queue.num_packets--;
        } else {
            pthread_mutex_unlock(&packet_queue.lock);
            break;
        }
        pthread_mutex_unlock(&packet_queue.lock);

        // Process the packet
        PacketData *packet = &packet_queue.packets[packet_index];
        process_packet_payload(packet->payload, sizeof(packet->payload));

        // Free the packet memory using the custom allocator
        free_custom_memory(packet);
    }
    return NULL;
}

int initialize_packet_processing(int max_packets) {
    if (max_packets <= 0) {
        fprintf(stderr, "Error: Invalid maximum packets value\n");
        return -1;
    }

    packet_queue.packets = malloc(max_packets * sizeof(PacketData));
    if (!packet_queue.packets) {
        fprintf(stderr, "Error: Unable to allocate memory for packet queue\n");
        return -1;
    }
    packet_queue.num_packets = 0;
    pthread_mutex_init(&packet_queue.lock, NULL);

    // Initialize the custom memory allocator
    init_custom_memory_allocator();

    return 0;
}

void enqueue_packet(const char *payload, int payload_size) {
    if (payload_size <= 0 || payload_size > MAX_PACKET_SIZE) {
        fprintf(stderr, "Error: Invalid packet size\n");
        return;
    }

    pthread_mutex_lock(&packet_queue.lock);
    if (packet_queue.num_packets >= MAX_PACKETS) {
        pthread_mutex_unlock(&packet_queue.lock);
        fprintf(stderr, "Warning: Packet dropped due to queue overflow\n");
        log_packet_dropped("Queue Overflow");
        return;
    }
    PacketData *packet = &packet_queue.packets[packet_queue.num_packets++];
    memcpy(packet->payload, payload, payload_size);
    pthread_mutex_unlock(&packet_queue.lock);

    // Allocate memory for the packet using the custom allocator
    allocate_custom_memory(packet, sizeof(PacketData));
}

void start_processing() {
    int i;
    for (i = 0; i < concurrent_processes; i++) {
        pthread_t thread_id;
        if (pthread_create(&thread_id, NULL, process_packet, NULL) != 0) {
            fprintf(stderr, "Error: Unable to create processing thread\n");
            break;
        }
        pthread_detach(thread_id);
    }
}

void set_concurrent_processes(int new_value) {
    if (new_value < MIN_CONCURRENT_PROCESSES || new_value > MAX_CONCURRENT_PROCESSES) {
        fprintf(stderr, "Warning: Invalid concurrent processes value, using default\n");
        new_value = DEFAULT_CONCURRENT_PROCESSES;
    }
    concurrent_processes = new_value;
}

void log_packet_dropped(const char *reason) {
    // Asynchronously log the dropped packet and reason
    printf("Packet dropped: %s\n", reason);
}
