typedef struct ImageFile {
    int width;
    int height;
    size_t size;
    void* data;
    struct ImageFile* next;
} ImageFile;

typedef struct Queue {
    ImageFile* front;
    ImageFile* rear;
} Queue;

Queue* createQueue() {
    Queue* q = (Queue*)malloc(sizeof(Queue));
    if (!q) return NULL;
    q->front = q->rear = NULL;
    return q;
}

void enqueue(Queue* q, int width, int height, size_t size, void* data) {
    ImageFile* newNode = (ImageFile*)malloc(sizeof(ImageFile));
    if (!newNode) return;

    newNode->width = width;
    newNode->height = height;
    newNode->size = size;
    newNode->data = data;
    newNode->next = NULL;

    if (q->rear == NULL) {
        q->front = q->rear = newNode;
        return;
    }

    q->rear->next = newNode;
    q->rear = newNode;
}

ImageFile* dequeue(Queue* q) {
    if (q->front == NULL) return NULL;

    ImageFile* temp = q->front;
    q->front = q->front->next;

    if (q->front == NULL) q->rear = NULL;

    return temp;
}

void freeQueue(Queue* q) {
    while (q->front != NULL) {
        ImageFile* temp = q->front;
        q->front = q->front->next;
        free(temp);
    }
    free(q);
}
