void nfapi_crc_list_destroy(NFAPI_CRC_LIST_T* list) {
    pthread_mutex_lock(&list->mutex);
    free(list->pdus);
    list->pdus = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

void nfapi_crc_list_add(NFAPI_CRC_LIST_T* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T* new_pdus = realloc(list->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdus) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&list->mutex);
            exit(EXIT_FAILURE);
        }
        list->pdus = new_pdus;
        list->capacity = new_capacity;
    }
    list->pdus[list->count++] = *pdu;
    pthread_mutex_unlock(&list->mutex);
}

void nfapi_crc_list_process(NFAPI_CRC_LIST_T* list) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        // Process each PDU
        printf("Processing PDU: RNTI=%d, CRCFLAG=%d\n", list->pdus[i].rnti, list->pdus[i].crc_indication.crcflag);
    }
    pthread_mutex_unlock(&list->mutex);
}

int main() {
    NFAPI_CRC_LIST_T crc_list;
    nfapi_crc_list_init(&crc_list, 10);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.ue_info = ...; // Initialize UE info
    pdu.rnti = ...;    // Set RNTI
    pdu.crc_indication.crcflag = ...; // Randomly set CRCFLAG

    nfapi_crc_list_add(&crc_list, &pdu);
    nfapi_crc_list_process(&crc_list);

    nfapi_crc_list_destroy(&crc_list);
    return 0;
}
