DynamicList* create_list(size_t initial_capacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    free(list->data);
    pthread_mutex_unlock(&list->lock);
    free(list);
}

int resize_list(DynamicList* list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* newData = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
