#include <stdlib.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1000
#define MIN_CRF 0
#define MAX_CRF 255

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

typedef struct PoolAllocator {
    ListNode* freeList;
    int poolSize;
    pthread_mutex_t lock;
} PoolAllocator;

PoolAllocator allocator = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

ListNode* allocateNode() {
    pthread_mutex_lock(&allocator.lock);
    if (allocator.freeList) {
        ListNode* node = allocator.freeList;
        allocator.freeList = node->next;
        pthread_mutex_unlock(&allocator.lock);
        return node;
    } else {
        pthread_mutex_unlock(&allocator.lock);
        return malloc(sizeof(ListNode));
    }
}

void deallocateNode(ListNode* node) {
    pthread_mutex_lock(&allocator.lock);
    node->next = allocator.freeList;
    allocator.freeList = node;
    pthread_mutex_unlock(&allocator.lock);
}

ListNode* createLinkedList(int N) {
    if (N > MAX_LIST_SIZE) {
        return NULL; // Error handling for exceeding maximum list size
    }

    ListNode* head = NULL;
    ListNode** current = &head;

    for (int i = 0; i < N; i++) {
        ListNode* newNode = allocateNode();
        if (!newNode) {
            deallocateLinkedList(head);
            return NULL; // Memory allocation failed
        }
        newNode->data.RX_UE_INFORMATION_TAG = i;
        newNode->data.RNTI = i * 100;
        newNode->data.CRCFLAG = MIN_CRF + (rand() % (MAX_CRF - MIN_CRF + 1));
        newNode->next = NULL;

        *current = newNode;
        current = &newNode->next;
    }

    return head;
}

void deallocateLinkedList(ListNode* head) {
    ListNode* current = head;
    while (current) {
        ListNode* next = current->next;
        deallocateNode(current);
        current = next;
    }
}

void traverseLinkedList(ListNode* head) {
    ListNode* current = head;
    while (current) {
        // Perform validation checks on each node's CRCFLAG
        if (current->data.CRCFLAG < MIN_CRF || current->data.CRCFLAG > MAX_CRF) {
            printf("CRCFLAG out of range at node %d\n", current->data.RX_UE_INFORMATION_TAG);
        }
        current = current->next;
    }
}

int main() {
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, (void* (*)(void*))createLinkedList, (void*)(rand() % MAX_LIST_SIZE));
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    // Perform stress testing and validation
    return 0;
}
