#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 * 1024 // 1GB

typedef struct NFAPI_CRC_INDICATION_PDU {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ImageData {
    char* path;
    size_t size;
    unsigned char* data;
    pthread_mutex_t lock;
} ImageData;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int RX_UE_INFORMATION_TAG, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        perror("Failed to allocate memory for NFAPI_CRC_INDICATION_PDU");
        return NULL;
    }
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    return pdu;
}

ImageData* load_image(const char* path, size_t max_size) {
    FILE* file = fopen(path, "rb");
    if (file == NULL) {
        perror("Failed to open image file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    size_t size = ftell(file);
    if (size > max_size) {
        fclose(file);
        fprintf(stderr, "Image size exceeds memory limit\n");
        return NULL;
    }
    fseek(file, 0, SEEK_SET);

    ImageData* image_data = (ImageData*)malloc(sizeof(ImageData));
    if (image_data == NULL) {
        perror("Failed to allocate memory for ImageData");
        fclose(file);
        return NULL;
    }

    image_data->path = strdup(path);
    image_data->size = size;
    image_data->data = (unsigned char*)malloc(size);
    if (image_data->data == NULL) {
        perror("Failed to allocate memory for image data");
        free(image_data->path);
        free(image_data);
        fclose(file);
        return NULL;
    }

    size_t read_size = fread(image_data->data, 1, size, file);
    if (read_size != size) {
        perror("Failed to read image data");
        free(image_data->data);
        free(image_data->path);
        free(image_data);
        fclose(file);
        return NULL;
    }

    pthread_mutex_init(&image_data->lock, NULL);
    fclose(file);
    return image_data;
}

void* process_file(void* arg) {
    char* path = (char*)arg;
    ImageData* image_data = load_image(path, MAX_MEMORY_LIMIT);
    if (image_data != NULL) {
        // Process image data
        printf("Processed image: %s\n", image_data->path);
        pthread_mutex_destroy(&image_data->lock);
        free(image_data->data);
        free(image_data->path);
        free(image_data);
    } else {
        fprintf(stderr, "Failed to process file: %s\n", path);
    }
    return NULL;
}

int main() {
    // Example usage
    pthread_t threads[10];
    char* paths[] = {"image1.jpg", "image2.jpg", "image3.jpg", /* ... */};

    for (int i = 0; i < sizeof(paths) / sizeof(paths[0]); i++) {
        if (pthread_create(&threads[i], NULL, process_file, paths[i]) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < sizeof(paths) / sizeof(paths[0]); i++) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
