#define MAX_PACKET_SIZE 65535 // Maximum possible payload size for a packet

typedef struct {
    uint16_t payload_length;
    void* data;
} PacketHeader;

PacketHeader* allocate_packet_buffer(uint16_t* packet_lengths, int num_packets, size_t max_memory_limit, int* total_packets_processed) {
    if (total_packets_processed == NULL || packet_lengths == NULL || num_packets < 0 || max_memory_limit <= 0) {
        return NULL; // Handle invalid input
    }

    *total_packets_processed = 0;
    PacketHeader* buffer = malloc(num_packets * sizeof(PacketHeader));
    if (buffer == NULL) {
        return NULL; // Allocation failed
    }

    size_t total_size = 0;
    for (int i = 0; i < num_packets; ++i) {
        if ((size_t)(packet_lengths[i]) > UINT16_MAX || packet_lengths[i] >= max_memory_limit / sizeof(PacketHeader)) {
            free(buffer); // Handle integer overflow or excessive size
            return NULL;
        }

        buffer[i].payload_length = packet_lengths[i];
        buffer[i].data = malloc((size_t)packet_lengths[i]);
        if (buffer[i].data == NULL) {
            // Free previously allocated memory before exiting
            for (int j = 0; j < i; ++j) {
                free(buffer[j].data);
            }
            free(buffer);
            return NULL; // Allocation failed
        }

        total_size += sizeof(PacketHeader) + packet_lengths[i];
        if (total_size > max_memory_limit) {
            // Free previously allocated memory before exiting
            for (int j = 0; j <= i; ++j) {
                free(buffer[j].data);
            }
            free(buffer);
            return NULL; // Memory limit exceeded
        }

        (*total_packets_processed)++;
    }

    return buffer;
}

