#define MAX_STREAMS 1024
#define MIN_BUFFER_SIZE 8192

typedef struct {
    int id;
    char* data;
    size_t length;
} AudioStream;

typedef struct {
    AudioStream** streams;
    size_t count;
    size_t capacity;
    size_t buffer_size;
    void (*on_buffer_overflow)(size_t new_size);
} AudioBufferManager;

AudioBufferManager* create_audio_buffer_manager() {
    AudioBufferManager* manager = (AudioBufferManager*)malloc(sizeof(AudioBufferManager));
    manager->streams = NULL;
    manager->count = 0;
    manager->capacity = 0;
    manager->buffer_size = MIN_BUFFER_SIZE;
    manager->on_buffer_overflow = NULL;
    return manager;
}

void destroy_audio_buffer_manager(AudioBufferManager* manager) {
    for (size_t i = 0; i < manager->count; i++) {
        free(manager->streams[i]->data);
        free(manager->streams[i]);
    }
    free(manager->streams);
    free(manager);
}

void add_stream(AudioBufferManager* manager, AudioStream* stream) {
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity == 0 ? 1 : manager->capacity * 2;
        AudioStream** new_streams = (AudioStream**)realloc(manager->streams, new_capacity * sizeof(AudioStream*));
        if (!new_streams) {
            if (manager->on_buffer_overflow) {
                manager->on_buffer_overflow(new_capacity);
            }
            return; // Handle buffer overflow gracefully
        }
        manager->streams = new_streams;
        manager->capacity = new_capacity;
    }

    manager->streams[manager->count++] = stream;

    size_t total_size = 0;
    for (size_t i = 0; i < manager->count; i++) {
        total_size += manager->streams[i]->length;
    }

    if (total_size > manager->buffer_size) {
        size_t new_buffer_size = total_size * 2;
        if (new_buffer_size < MIN_BUFFER_SIZE) {
            new_buffer_size = MIN_BUFFER_SIZE;
        }
        // Resize buffer and copy data here
        manager->buffer_size = new_buffer_size;

        if (manager->on_buffer_overflow) {
            manager->on_buffer_overflow(new_buffer_size);
        }
    }
}

void remove_stream(AudioBufferManager* manager, int stream_id) {
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->streams[i]->id == stream_id) {
            free(manager->streams[i]->data);
            free(manager->streams[i]);
            memmove(&manager->streams[i], &manager->streams[i + 1], (manager->count - i - 1) * sizeof(AudioStream*));
            manager->count--;
            break;
        }
    }

    // Optionally shrink the buffer if it's too large
}

void set_on_buffer_overflow(AudioBufferManager* manager, void (*callback)(size_t new_size)) {
    manager->on_buffer_overflow = callback;
}
