NFAPI_CRC_INDICATION_PDU_T** create_and_populate_list(int num_structures, int batch_size) {
    if (num_structures > USER_DEFINED_LIMIT) {
        printf("Error: Number of structures exceeds user-defined limit.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (list == NULL) {
        printf("Error: Failed to allocate memory for list.\n");
        return NULL;
    }

    srand(time(0));

    int structures_created = 0;

    while (structures_created < num_structures) {
        int batch_size_to_allocate = (num_structures - structures_created > BATCH_SIZE_LIMIT) ? BATCH_SIZE_LIMIT : (num_structures - structures_created);
        NFAPI_CRC_INDICATION_PDU_T** batch = (NFAPI_CRC_INDICATION_PDU_T**)malloc(batch_size_to_allocate * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (batch == NULL) {
            printf("Error: Failed to allocate memory for batch.\n");
            for (int i = 0; i < structures_created; i++) {
                free(list[i]);
            }
            free(list);
            return NULL;
        }

        for (int i = 0; i < batch_size_to_allocate; i++) {
            batch[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (batch[i] == NULL) {
                printf("Error: Failed to allocate memory for individual structure.\n");
                for (int j = 0; j < i; j++) {
                    free(batch[j]);
                }
                free(batch);
                for (int k = 0; k < structures_created; k++) {
                    free(list[k]);
                }
                free(list);
                return NULL;
            }

            batch[i]->RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
            batch[i]->RNTI = rand() % 1000; // Example value
            batch[i]->CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
        }

        for (int i = 0; i < batch_size_to_allocate; i++) {
            list[structures_created + i] = batch[i];
        }

        free(batch);

        structures_created += batch_size_to_allocate;

        if (clock() % CLOCKS_PER_SEC > MAX_OPS_PER_SEC) {
            printf("Warning: Exceeded maximum operations per second limit.\n");
        }
    }

    return list;
}

int main() {
    int num_structures = 5000;
    int batch_size = 256;

    NFAPI_CRC_INDICATION_PDU_T** list = create_and_populate_list(num_structures, batch_size);

    if (list != NULL) {
        for (int i = 0; i < num_structures; i++) {
            free(list[i]);
        }
        free(list);
    }

    return 0;
}
