// Define FrameData structure with necessary metadata
typedef struct FrameData {
    int timestamp;          // Timestamp when frame was received
    int payload_length;     // Length of the data payload
    char source_ip[16];      // Source IP address as a string (IPv4)
    struct FrameData* next;  // Pointer to the next node in the list
    struct FrameData* prev;  // Pointer to the previous node in the list
} FrameData;

// Function prototype for processing network packets and populating the linked list
FrameData* process_packets(const char* packet_data, int max_memory_budget);

int main() {
    const char* packet_data = "Packet1:TS=1234567890;PayloadLen=1024;SourceIP=192.168.1.1,"
                             "Packet2:TS=1234567891;PayloadLen=2048;SourceIP=192.168.1.2";
    int max_memory_budget = 10000; // Maximum memory budget in bytes

    FrameData* head = process_packets(packet_data, max_memory_budget);

    // Print the linked list for demonstration purposes
    FrameData* current = head;
    while (current != NULL) {
        printf("Timestamp: %d, Payload Length: %d, Source IP: %s\n", 
               current->timestamp, current->payload_length, current->source_ip);
        current = current->next;
    }

    // Free the allocated memory
    FrameData* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }

    return 0;
}

FrameData* process_packets(const char* packet_data, int max_memory_budget) {
    FrameData dummy_head; // Dummy head for easier list manipulation
    dummy_head.next = &dummy_head;
    dummy_head.prev = &dummy_head;

    int current_memory_usage = 0;

    // Simulate processing each packet in the data string
    const char* packet_start = packet_data;
    while (*packet_start != '\0') {
        // Find the end of the current packet
        const char* packet_end = strchr(packet_start, ',');
        if (packet_end == NULL) {
            packet_end = packet_data + strlen(packet_data);
        }

        // Extract and parse packet metadata
        FrameData* new_frame = (FrameData*)malloc(sizeof(FrameData));
        if (new_frame == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        const char* timestamp_start = strchr(packet_start, '=') + 1;
        new_frame->timestamp = atoi(timestamp_start);

        const char* payload_len_start = strchr(strchr(packet_start, ';'), '=') + 1;
        new_frame->payload_length = atoi(payload_len_start);

        const char* source_ip_start = strchr(strchr(packet_start, ';'), ';') + 2;
        strncpy(new_frame->source_ip, source_ip_start, sizeof(new_frame->source_ip) - 1);
        new_frame->source_ip[sizeof(new_frame->source_ip) - 1] = '\0';

        // Insert the new frame at the end of the list
        new_frame->prev = dummy_head.prev;
        new_frame->next = &dummy_head;
        dummy_head.prev->next = new_frame;
        dummy_head.prev = new_frame;

        // Update memory usage and check if limit is exceeded
        current_memory_usage += sizeof(FrameData);
        if (current_memory_usage > max_memory_budget) {
            FrameData* oldest_frame = dummy_head.next;
            dummy_head.next = oldest_frame->next;
            oldest_frame->next->prev = &dummy_head;
            free(oldest_frame);
            current_memory_usage -= sizeof(FrameData);
        }

        // Move to the start of the next packet
        packet_start = packet_end + 1;
    }

    return dummy_head.next;
}
