#include <stdio.h>
#include <stdlib.h>

#define MAX_FRAMES 50000
#define MAX_FRAME_SIZE 1024 * 1024 // 1 MB in bytes
#define DEFAULT_MEMORY_THRESHOLD 512 * 1024 * 1024 // 512 MB

typedef struct Frame {
    int size;
    unsigned char* data;
} Frame;

typedef struct ImageProcessor {
    int frame_count;
    Frame** frames;
    size_t total_memory_used;
    size_t memory_threshold;
} ImageProcessor;

ImageProcessor* create_image_processor(size_t initial_memory_threshold) {
    ImageProcessor* processor = (ImageProcessor*)malloc(sizeof(ImageProcessor));
    processor->frame_count = 0;
    processor->frames = NULL;
    processor->total_memory_used = 0;
    processor->memory_threshold = initial_memory_threshold > 0 ? initial_memory_threshold : DEFAULT_MEMORY_THRESHOLD;
    return processor;
}

void add_frame(ImageProcessor* processor, int frame_size) {
    if (processor->frame_count >= MAX_FRAMES) {
        fprintf(stderr, "Error: Maximum number of frames exceeded.\n");
        exit(EXIT_FAILURE);
    }
    if (frame_size > MAX_FRAME_SIZE) {
        fprintf(stderr, "Error: Frame size exceeds maximum allowed.\n");
        exit(EXIT_FAILURE);
    }

    Frame* frame = (Frame*)malloc(sizeof(Frame));
    frame->size = frame_size;
    frame->data = (unsigned char*)malloc(frame_size);

    processor->frames = realloc(processor->frames, sizeof(Frame*) * (processor->frame_count + 1));
    processor->frames[processor->frame_count++] = frame;

    processor->total_memory_used += frame_size;
    if (processor->total_memory_used > processor->memory_threshold) {
        fprintf(stderr, "Warning: Memory usage exceeded threshold.\n");
        // Handle memory usage exceedance
    }
}

void free_image_processor(ImageProcessor* processor) {
    for (int i = 0; i < processor->frame_count; ++i) {
        free(processor->frames[i]->data);
        free(processor->frames[i]);
    }
    free(processor->frames);
    free(processor);
}

// Example usage
int main() {
    ImageProcessor* processor = create_image_processor(1024 * 1024 * 1024); // 1 GB threshold

    add_frame(processor, 512 * 1024); // Add a 512 KB frame
    add_frame(processor, 1024 * 1024); // Add a 1 MB frame

    free_image_processor(processor);

    return 0;
}
