#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_tag;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_flag;
    time_t timestamp;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LinkedList {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T* head;
    size_t total_memory;
    size_t max_memory;
} LinkedList;

NFAPI_CRC_INDICATION_PDU_T* create_node(RX_UE_INFORMATION_TAG ue_tag, uint16_t RNTI, CRC_INDICATION_REL8_TAG crc_flag) {
    NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (node == NULL) return NULL;
    node->ue_tag = ue_tag;
    node->RNTI = RNTI;
    node->crc_flag = crc_flag;
    node->timestamp = time(NULL);
    node->next = NULL;
    return node;
}

LinkedList* create_linked_list(size_t max_memory) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) return NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->head = NULL;
    list->total_memory = 0;
    list->max_memory = max_memory;
    return list;
}

int add_node(LinkedList* list, RX_UE_INFORMATION_TAG ue_tag, uint16_t RNTI, CRC_INDICATION_REL8_TAG crc_flag) {
    pthread_mutex_lock(&list->mutex);
    if (list->total_memory + sizeof(NFAPI_CRC_INDICATION_PDU_T) > list->max_memory) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Memory limit exceeded
    }
    NFAPI_CRC_INDICATION_PDU_T* new_node = create_node(ue_tag, RNTI, crc_flag);
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Allocation failed
    }
    new_node->next = list->head;
    list->head = new_node;
    list->total_memory += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void free_list(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->total_memory = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T* get_list_head(LinkedList* list) {
    return list->head;
}
