PacketHeader** process_packet_headers(const char* config_file) {
    FILE* file = fopen(config_file, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return NULL;
    }

    int packet_count;
    if (fscanf(file, "%d", &packet_count) != 1 || packet_count < 0) {
        fprintf(stderr, "Invalid packet count in configuration file\n");
        fclose(file);
        return NULL;
    }

    PacketHeader** headers = malloc(packet_count * sizeof(PacketHeader*));
    if (!headers) {
        perror("Failed to allocate memory for packet headers");
        fclose(file);
        return NULL;
    }

    for (int i = 0; i < packet_count; ++i) {
        headers[i] = malloc(sizeof(PacketHeader));
        if (!headers[i]) {
            perror("Failed to allocate memory for packet header");
            // Clean up previously allocated headers
            for (int j = 0; j < i; ++j) {
                free(headers[j]);
            }
            free(headers);
            fclose(file);
            return NULL;
        }

        size_t timestamp, length;
        if (fscanf(file, "%zu %zu", &timestamp, &length) != 2 || length > MAX_PACKET_LENGTH) {
            fprintf(stderr, "Invalid packet data in configuration file\n");
            // Clean up previously allocated headers
            for (int j = 0; j <= i; ++j) {
                free(headers[j]);
            }
            free(headers);
            fclose(file);
            return NULL;
        }

        headers[i]->timestamp = timestamp;
        headers[i]->length = length;

        headers[i]->data = malloc(length * sizeof(char));
        if (!headers[i]->data) {
            perror("Failed to allocate memory for packet data");
            // Clean up previously allocated resources
            free(headers[i]);
            for (int j = 0; j < i; ++j) {
                free(headers[j]->data);
                free(headers[j]);
            }
            free(headers);
            fclose(file);
            return NULL;
        }

        if (fread(headers[i]->data, sizeof(char), length, file) != length) {
            fprintf(stderr, "Failed to read packet data from configuration file\n");
            // Clean up previously allocated resources
            for (int j = 0; j <= i; ++j) {
                free(headers[j]->data);
                free(headers[j]);
            }
            free(headers);
            fclose(file);
            return NULL;
        }
    }

    fclose(file);
    return headers;
}

void free_packet_headers(PacketHeader** headers, int packet_count) {
    for (int i = 0; i < packet_count; ++i) {
        free(headers[i]->data);
        free(headers[i]);
    }
    free(headers);
}
