#define MAX_IMAGE_PATH 256

typedef struct {
    char path[MAX_IMAGE_PATH];
    int width;
    int height;
} Image;

int calculateMemorySize(int numImages, int *widths, int *heights) {
    // Calculate memory size considering potential integer overflows
    long long totalPixels = 0;
    for (int i = 0; i < numImages; ++i) {
        if ((long long)widths[i] > LLONG_MAX / heights[i]) {
            return -1; // Integer overflow detected
        }
        totalPixels += (long long)widths[i] * heights[i];
    }

    size_t memorySize = totalPixels * sizeof(Image); // Assuming each pixel needs space for an Image structure
    if (memorySize > SIZE_MAX) {
        return -1; // Memory size exceeds system limit
    }
    return (int)memorySize;
}

void processImages(int numImages, const char *configFile) {
    FILE *file = fopen(configFile, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return;
    }

    int *widths = (int *)malloc(numImages * sizeof(int));
    int *heights = (int *)malloc(numImages * sizeof(int));
    if (!widths || !heights) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(file);
        free(widths);
        free(heights);
        return;
    }

    // Read and validate image metadata from file
    for (int i = 0; i < numImages; ++i) {
        if (fscanf(file, "%d %d", &widths[i], &heights[i]) != 2 || widths[i] <= 0 || heights[i] <= 0) {
            fprintf(stderr, "Invalid image dimensions in configuration file\n");
            fclose(file);
            free(widths);
            free(heights);
            return;
        }
    }

    // Calculate total memory required
    int memorySize = calculateMemorySize(numImages, widths, heights);
    if (memorySize == -1) {
        fprintf(stderr, "Memory calculation failed or exceeds system limit\n");
        fclose(file);
        free(widths);
        free(heights);
        return;
    }

    // Allocate memory for image data structures
    Image *images = (Image *)malloc(memorySize);
    if (!images) {
        fprintf(stderr, "Memory allocation failed for images\n");
        fclose(file);
        free(widths);
        free(heights);
        return;
    }

    // Populate image data structures with metadata
    for (int i = 0; i < numImages; ++i) {
        snprintf(images[i].path, MAX_IMAGE_PATH, "image%d.jpg", i + 1);
        images[i].width = widths[i];
        images[i].height = heights[i];
    }

    // Process images here...

    // Free allocated memory
    free(widths);
    free(heights);
    free(images);

    fclose(file);
}

int main() {
    processImages(3, "config.txt");
    return 0;
}
