#include <stdio.h>
#include <stdlib.h>

#define MAX_STRUCTURES 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
int current_size = 0;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    if (current_size >= MAX_STRUCTURES) {
        printf("Error: Maximum number of structures reached.\n");
        return NULL;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    new_node->data = data;
    new_node->next = NULL;
    current_size++;
    return new_node;
}

int insert_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (!new_node)
        return -1;

    if (head == NULL) {
        head = new_node;
    } else {
        Node* temp = head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }

    return 0;
}

void iterate_list(void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    Node* current = head;
    while (current != NULL) {
        callback(&current->data);
        current = current->next;
    }
}

void cleanup() {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
    current_size = 0;
}

// Example usage
void print_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRCFLAG);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T example_pdu = {1, 2, rand()};
    insert_node(example_pdu);

    iterate_list(print_pdu);

    cleanup();
    return 0;
}
