#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAX_PACKETS 10000
#define DEFAULT_MEMORY_LIMIT (1024 * 1024) // 1MB

typedef struct {
    char* payload;
    size_t payload_size;
} Packet;

typedef struct {
    Packet packets[MAX_PACKETS];
    size_t packet_count;
    size_t memory_limit;
    size_t current_memory_usage;
} NetworkPacketManager;

NetworkPacketManager* create_packet_manager(size_t initial_memory_limit) {
    NetworkPacketManager* manager = (NetworkPacketManager*)malloc(sizeof(NetworkPacketManager));
    if (!manager) return NULL;

    manager->packet_count = 0;
    manager->memory_limit = initial_memory_limit > DEFAULT_MEMORY_LIMIT ? initial_memory_limit : DEFAULT_MEMORY_LIMIT;
    manager->current_memory_usage = 0;

    for (size_t i = 0; i < MAX_PACKETS; ++i) {
        manager->packets[i].payload = NULL;
        manager->packets[i].payload_size = 0;
    }

    return manager;
}

void free_packet_manager(NetworkPacketManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->packet_count; ++i) {
        if (manager->packets[i].payload) {
            free(manager->packets[i].payload);
            manager->packets[i].payload = NULL;
            manager->packets[i].payload_size = 0;
        }
    }

    free(manager);
}

int process_packet(NetworkPacketManager* manager, const char* payload, size_t payload_size) {
    if (!manager || !payload || payload_size == 0) return -1;

    // Check for integer overflow
    if (SIZE_MAX / sizeof(char) < payload_size) {
        fprintf(stderr, "Payload size too large to handle.\n");
        return -1;
    }

    size_t required_memory = payload_size * sizeof(char);
    if (manager->current_memory_usage + required_memory > manager->memory_limit) {
        fprintf(stderr, "Memory limit exceeded.\n");
        return -1;
    }

    // Allocate memory for the packet
    char* new_payload = (char*)malloc(required_memory);
    if (!new_payload) {
        fprintf(stderr, "Failed to allocate memory for packet payload.\n");
        return -1;
    }

    // Copy the payload data
    memcpy(new_payload, payload, required_memory);

    // Add the packet to the manager
    if (manager->packet_count >= MAX_PACKETS) {
        fprintf(stderr, "Packet manager is full.\n");
        free(new_payload);
        return -1;
    }

    manager->packets[manager->packet_count].payload = new_payload;
    manager->packets[manager->packet_count].payload_size = payload_size;
    manager->current_memory_usage += required_memory;
    ++manager->packet_count;

    return 0;
}

size_t get_processed_packet_count(const NetworkPacketManager* manager) {
    if (!manager) return 0;
    return manager->packet_count;
}
