#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1024
#define GROWTH_FACTOR 2

typedef struct Packet {
    int size;
    char *payload;
    struct Packet *next;
} Packet;

typedef struct PacketList {
    Packet *head;
    Packet *tail;
    int count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketList;

void initPacketList(PacketList *list) {
    list->head = list->tail = NULL;
    list->count = 0;
    list->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&list->lock, NULL);
}

void destroyPacketList(PacketList *list) {
    Packet *current = list->head;
    while (current != NULL) {
        Packet *next = current->next;
        free(current->payload);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

void addPacket(PacketList *list, int size, const char *payload) {
    if (list->count >= list->capacity) {
        list->capacity *= GROWTH_FACTOR;
        list->head = realloc(list->head, list->capacity * sizeof(Packet));
    }

    Packet *newPacket = &list->head[list->count++];
    newPacket->size = size;
    newPacket->payload = malloc(size);
    if (payload != NULL) {
        memcpy(newPacket->payload, payload, size);
    }
    newPacket->next = NULL;

    if (list->tail == NULL) {
        list->head = list->tail = newPacket;
    } else {
        list->tail->next = newPacket;
        list->tail = newPacket;
    }

    pthread_mutex_lock(&list->lock);
    // Perform additional thread-safe operations here
    pthread_mutex_unlock(&list->lock);
}

int processPackets(PacketList *list) {
    int processed = 0;
    Packet *current = list->head;

    while (current != NULL) {
        // Process the packet payload
        printf("Processing packet with size %d\n", current->size);

        // Move to the next packet
        Packet *next = current->next;
        free(current->payload);
        free(current);
        current = next;

        processed++;
    }

    list->head = list->tail = NULL;
    list->count = 0;

    return processed;
}
