typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    size_t pool_size;
    Node** pool;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* createList(size_t initialSize) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->count = 0;
    list->pool_size = initialSize > MIN_POOL_SIZE ? initialSize : MIN_POOL_SIZE;
    list->pool = (Node**)calloc(list->pool_size, sizeof(Node*));
    if (!list->pool) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);

    srand(time(NULL));

    for (size_t i = 0; i < list->pool_size; ++i) {
        list->pool[i] = (Node*)malloc(sizeof(Node));
        if (!list->pool[i]) {
            for (size_t j = 0; j < i; ++j) free(list->pool[j]);
            free(list->pool);
            pthread_mutex_destroy(&list->lock);
            free(list);
            return NULL;
        }
    }

    return list;
}

void destroyList(LinkedList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    for (size_t i = 0; i < list->pool_size; ++i) free(list->pool[i]);
    free(list->pool);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void* allocateNode(LinkedList* list) {
    if (!list || list->count == list->pool_size) return NULL;

    Node* node = list->pool[list->count++];
    node->next = NULL;
    return &node->data;
}

int initializeNficIndications(LinkedList* list, size_t N, size_t max_size) {
    if (!list || !N || !max_size || N > max_size) return -1;

    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_lock(&list->lock);
        void* data = allocateNode(list);
        pthread_mutex_unlock(&list->lock);

        if (!data) {
            // Handle allocation failure
            return -2;
        }

        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)data;
        pdu->RX_UE_INFORMATION_TAG = rand() % 0xFFFFFFFF;
        pdu->RNTI = rand() % 0xFFFF;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    return 0;
}
