#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_PACKETS 1000
#define MAX_PAYLOAD_SIZE 1024

typedef struct {
    int packetID;
    time_t timestamp;
    int length;
} PacketInfo;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    PacketInfo info;
    char payload[MAX_PAYLOAD_SIZE];
} PacketBuffer;

PacketBuffer* packetQueue[MAX_PACKETS];
int front = -1, rear = -1;
time_t totalMemoryAllocated = 0;
const time_t MAX_MEMORY_LIMIT = 5 * 1024 * 1024; // 5MB

void enqueue(PacketBuffer* packet) {
    if ((front == 0 && rear == MAX_PACKETS - 1) || (rear == front - 1)) {
        printf("Queue is full!\n");
        return;
    }
    if (front == -1)
        front = rear = 0;
    else
        rear = (rear + 1) % MAX_PACKETS;

    totalMemoryAllocated += packet->info.length;
    while (totalMemoryAllocated > MAX_MEMORY_LIMIT && front != rear) {
        totalMemoryAllocated -= packetQueue[front]->info.length;
        free(packetQueue[front]);
        front = (front + 1) % MAX_PACKETS;
    }
    packetQueue[rear] = packet;
}

PacketBuffer* dequeue() {
    if (front == -1) {
        printf("Queue is empty!\n");
        return NULL;
    }

    PacketBuffer* packet = packetQueue[front];
    front = (front + 1) % MAX_PACKETS;

    if (front == rear)
        front = rear = -1;

    totalMemoryAllocated -= packet->info.length;
    return packet;
}

PacketBuffer* create_packet(int id, int length, const char* payload) {
    PacketBuffer* new_packet = malloc(sizeof(PacketBuffer));
    if (!new_packet) {
        printf("Memory allocation failed!\n");
        return NULL;
    }

    new_packet->info.packetID = id;
    new_packet->info.timestamp = time(NULL);
    new_packet->info.length = length;

    if (length > MAX_PAYLOAD_SIZE) {
        printf("Payload too large!\n");
        free(new_packet);
        return NULL;
    }
    memcpy(new_packet->payload, payload, length);

    return new_packet;
}

int main() {
    srand(time(NULL));

    for (int i = 0; i < 1500; ++i) {
        int id = rand() % MAX_PACKETS;
        int length = rand() % MAX_PAYLOAD_SIZE + 1;
        char payload[length];
        for (int j = 0; j < length; ++j)
            payload[j] = 'A' + rand() % 26;

        PacketBuffer* packet = create_packet(id, length, payload);
        if (packet) {
            enqueue(packet);
        }
    }

    while (front != -1) {
        PacketBuffer* packet = dequeue();
        printf("Processed Packet ID: %d\n", packet->info.packetID);
        free(packet);
    }

    return 0;
}
