#include <pthread.h>
#include <stdlib.h>
#include <time.h>

#define MAX_PACKETS 1024

typedef struct {
    int id;
    time_t timestamp;
    size_t length;
    // Add other metadata fields as needed
} PacketInfo;

typedef struct {
    PacketInfo packet;
    // Add other fields as needed
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPoolNode {
    void* memory;
    struct MemoryPoolNode* next;
} MemoryPoolNode;

typedef struct MemoryPool {
    size_t blockSize;
    MemoryPoolNode* freeList;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t blockSize, int poolSize) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->blockSize = blockSize;
    pool->freeList = NULL;
    pthread_mutex_init(&pool->lock, NULL);

    for (int i = 0; i < poolSize; ++i) {
        MemoryPoolNode* node = (MemoryPoolNode*)malloc(sizeof(MemoryPoolNode));
        if (!node) break;

        node->memory = malloc(blockSize);
        if (!node->memory) {
            free(node);
            break;
        }

        node->next = pool->freeList;
        pool->freeList = node;
    }

    return pool;
}

void* memory_pool_alloc(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    MemoryPoolNode* node = pool->freeList;
    if (node) {
        pool->freeList = node->next;
    } else {
        // Handle out of memory condition
        node = (MemoryPoolNode*)malloc(sizeof(MemoryPoolNode));
        if (!node) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }

        node->memory = malloc(pool->blockSize);
        if (!node->memory) {
            free(node);
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return node->memory;
}

void memory_pool_free(MemoryPool* pool, void* ptr) {
    pthread_mutex_lock(&pool->lock);

    MemoryPoolNode* node = (MemoryPoolNode*)ptr;
    node->next = pool->freeList;
    pool->freeList = node;

    pthread_mutex_unlock(&pool->lock);
}

void process_packet(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Implement packet processing logic here
}

void* packet_processor(void* arg) {
    MemoryPool* pool = (MemoryPool*)arg;
    NFAPI_CRC_INDICATION_PDU_T pdus[MAX_PACKETS];

    while (1) {
        for (int i = 0; i < MAX_PACKETS; ++i) {
            void* memory = memory_pool_alloc(pool);
            if (!memory) break;

            // Simulate packet reception
            PacketInfo packet;
            packet.id = rand() % MAX_PACKETS;
            packet.timestamp = time(NULL);
            packet.length = rand() % 1024;

            NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)memory;
            pdu->packet = packet;

            process_packet(pdu);

            memory_pool_free(pool, memory);
        }
    }

    return NULL;
}

int main() {
    int numThreads = 4;
    MemoryPool* pool = create_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_PACKETS * numThreads);

    pthread_t threads[numThreads];
    for (int i = 0; i < numThreads; ++i) {
        if (pthread_create(&threads[i], NULL, packet_processor, pool)) {
            // Handle error
        }
    }

    for (int i = 0; i < numThreads; ++i) {
        pthread_join(threads[i], NULL);
    }

    memory_pool_free(pool, pool);

    return 0;
}
