#include <stdlib.h>
#include <stdio.h>

#define MAX_INDICATIONS 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void append_node(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = create_node(data);
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
}

void serialize_list(Node* head, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }

    Node* current = head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
}

Node* deserialize_list(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for reading");
        return NULL;
    }

    Node* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T data;
    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) == 1) {
        append_node(&head, data);
    }

    fclose(file);
    return head;
}

void free_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    int n = 500; // Example value
    if (n > MAX_INDICATIONS) {
        fprintf(stderr, "Input exceeds maximum allowed indications\n");
        return 1;
    }

    Node* head = NULL;
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T data = {i, rand() % 65535, rand() % 256, rand() % 2};
        append_node(&head, data);
    }

    serialize_list(head, "crc_indications.bin");
    Node* deserialized_head = deserialize_list("crc_indications.bin");

    free_list(head);
    free_list(deserialized_head);

    return 0;
}
