typedef struct {
    time_t timestamp;
    size_t length;
    unsigned char* data;
} PacketMetadata;

PacketMetadata** process_packets(unsigned char* packet_data, size_t packet_count, size_t max_packet_size, size_t pool_size) {
    // Calculate total memory required
    size_t metadata_size = sizeof(PacketMetadata);
    size_t total_metadata_size = metadata_size * packet_count;
    if (total_metadata_size / packet_count != metadata_size || total_metadata_size > SIZE_MAX) {
        fprintf(stderr, "Error: Integer overflow in memory calculation\n");
        return NULL;
    }

    // Allocate memory from the pool
    PacketMetadata** metadata_array = (PacketMetadata**)malloc(pool_size * sizeof(PacketMetadata*));
    if (!metadata_array) {
        fprintf(stderr, "Error: Failed to allocate memory for metadata array\n");
        return NULL;
    }

    size_t bytes_allocated = 0;
    for (size_t i = 0; i < packet_count; ++i) {
        // Allocate memory for each PacketMetadata structure
        PacketMetadata* metadata = (PacketMetadata*)malloc(metadata_size);
        if (!metadata) {
            fprintf(stderr, "Error: Failed to allocate memory for packet metadata\n");
            for (size_t j = 0; j < i; ++j) {
                free(metadata_array[j]);
            }
            free(metadata_array);
            return NULL;
        }

        // Allocate memory for the packet data
        unsigned char* packet = (unsigned char*)malloc(max_packet_size);
        if (!packet) {
            fprintf(stderr, "Error: Failed to allocate memory for packet data\n");
            for (size_t j = 0; j <= i; ++j) {
                free(metadata_array[j]);
                free(metadata_array[j]->data);
            }
            free(metadata_array);
            return NULL;
        }

        // Initialize PacketMetadata
        metadata->timestamp = time(NULL);
        metadata->length = packet_size;
        memcpy(packet, packet_data + i * max_packet_size, packet_size);

        // Assign pointers and store in array
        metadata->data = packet;
        metadata_array[i] = metadata;

        bytes_allocated += metadata_size + packet_size;
    }

    printf("Processed %zu packets, allocated %zu bytes\n", packet_count, bytes_allocated);
    return metadata_array;
}

int main() {
    // Example usage
    size_t packet_count = 10;
    size_t max_packet_size = 1500;
    size_t pool_size = 20;

    unsigned char* packet_data = (unsigned char*)malloc(packet_count * max_packet_size);
    if (!packet_data) {
        fprintf(stderr, "Error: Failed to allocate memory for example packets\n");
        return 1;
    }

    // Populate packet_data with actual packet data
    // ...

    PacketMetadata** metadata_array = process_packets(packet_data, packet_count, max_packet_size, pool_size);
    if (metadata_array) {
        // Process the metadata array as needed
        // ...
        for (size_t i = 0; i < packet_count; ++i) {
            free(metadata_array[i]->data);
            free(metadata_array[i]);
        }
        free(metadata_array);
    }

    free(packet_data);
    return 0;
}
