#define MAX_PDUS 1000
#define MAX_PDUS_SIZE (MAX_PDUS * sizeof(NFAPI_CRC_INDICATION_PDU_T))
#define MAX_LOG_SIZE 1024

typedef struct {
    uint32_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t num_pdus;
    pthread_mutex_t mutex;
} PDU_Configuration;

void log_message(const char *message) {
    static FILE *log_file = NULL;
    if (!log_file) {
        log_file = fopen("pdu_log.txt", "a");
        if (!log_file) {
            fprintf(stderr, "Failed to open log file\n");
            return;
        }
    }
    struct timeval tv;
    gettimeofday(&tv, NULL);
    fprintf(log_file, "%ld.%06ld: %s\n", tv.tv_sec, tv.tv_usec, message);
}

int read_num_pdus_from_config(const char *config_path) {
    FILE *file = fopen(config_path, "r");
    if (!file) {
        log_message("Failed to open configuration file");
        return -1;
    }
    int num_pdus;
    if (fscanf(file, "%d", &num_pdus) != 1) {
        fclose(file);
        log_message("Failed to read number of PDUs from configuration file");
        return -1;
    }
    fclose(file);
    return num_pdus;
}

void initialize_pdu_config(PDU_Configuration *config, const char *config_path) {
    pthread_mutex_lock(&config->mutex);
    int num_pdus = read_num_pdus_from_config(config_path);
    if (num_pdus < 0) {
        pthread_mutex_unlock(&config->mutex);
        return;
    }
    if ((size_t)num_pdus > MAX_PDUS) {
        log_message("Number of PDUs exceeds maximum allowed");
        pthread_mutex_unlock(&config->mutex);
        return;
    }
    size_t total_size = num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (total_size > MAX_PDUS_SIZE) {
        log_message("Memory allocation would exceed 1 MB limit");
        pthread_mutex_unlock(&config->mutex);
        return;
    }
    config->pdus = realloc(config->pdus, total_size);
    if (!config->pdus) {
        log_message("Failed to allocate memory for PDUs");
        pthread_mutex_unlock(&config->mutex);
        return;
    }
    config->num_pdus = num_pdus;
    for (int i = 0; i < num_pdus; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &config->pdus[i];
        pdu->rx_ue_information_tag = rand() % UINT32_MAX;
        pdu->rnti = rand() % UINT16_MAX;
        pdu->crc_flag = rand() % 256;
    }
    log_message("Successfully initialized PDU configuration");
    pthread_mutex_unlock(&config->mutex);
}

void destroy_pdu_config(PDU_Configuration *config) {
    pthread_mutex_lock(&config->mutex);
    if (config->pdus) {
        free(config->pdus);
        config->pdus = NULL;
    }
    log_message("Destroyed PDU configuration");
    pthread_mutex_unlock(&config->mutex);
}

int main() {
    PDU_Configuration config = { .mutex = PTHREAD_MUTEX_INITIALIZER };
    initialize_pdu_config(&config, "pdu_config.txt");

    // Simulate concurrent access
    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, (void *(*)(void *))initialize_pdu_config, &config);
    pthread_create(&thread2, NULL, (void *(*)(void *))destroy_pdu_config, &config);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    destroy_pdu_config(&config);
    return 0;
}
