    int width;
    int height;
    int id;
} ImageMetadata;

ImageMetadata *imagePool = NULL;
int poolSize = 0;
int usedCount = 0;

int expandPool() {
    // Implement a strategy to expand the pool, handling potential integer overflow
    if (poolSize == INT_MAX) return -1; // Prevent integer overflow

    int newSize = (poolSize > 0) ? poolSize * 2 : 10;
    ImageMetadata *newPool = realloc(imagePool, newSize * sizeof(ImageMetadata));

    if (newPool == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return -1; // Handle insufficient memory
    }

    imagePool = newPool;
    poolSize = newSize;
    return 0;
}

int processImageMetadata(const char *filePath, int width, int height, int id) {
    if (usedCount >= poolSize) {
        if (expandPool() != 0) return -1; // Expand the pool or handle error
    }

    ImageMetadata *meta = &imagePool[usedCount];
    strncpy(meta->filePath, filePath, sizeof(meta->filePath));
    meta->width = width;
    meta->height = height;
    meta->id = id;

    usedCount++;
    return 0; // Success
}

void initializePool() {
    imagePool = malloc(MAX_IMAGES * sizeof(ImageMetadata));
    if (imagePool == NULL) {
        fprintf(stderr, "Failed to allocate initial memory pool.\n");
        exit(EXIT_FAILURE);
    }
    poolSize = MAX_IMAGES;
    usedCount = 0;
}

void cleanupPool() {
    free(imagePool);
    imagePool = NULL;
    poolSize = 0;
    usedCount = 0;
}
