int pool_index = -1;

void initialize_memory_pool() {
    for (int i = 0; i < MAX_STRUCTS; i++) {
        memory_pool[i] = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
}

NFAPI_CRC_INDICATION_PDU_T *create_structure(uint32_t ue_info_tag, uint16_t rnti) {
    if (pool_index >= MAX_STRUCTS - 1) {
        return NULL; // Pool depletion
    }
    pool_index++;
    NFAPI_CRC_INDICATION_PDU_T *pdu = memory_pool[pool_index];
    pdu->RX_UE_INFORMATION_TAG = ue_info_tag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    return pdu;
}

void destroy_structure(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    int index = -1;
    for (int i = 0; i <= pool_index; i++) {
        if (memory_pool[i] == pdu) {
            index = i;
            break;
        }
    }
    if (index != -1) {
        memory_pool[index] = NULL;
        while (index < pool_index) {
            memory_pool[index] = memory_pool[index + 1];
            index++;
        }
        pool_index--;
    }
}

void garbage_collection() {
    for (int i = 0; i <= pool_index; i++) {
        if (memory_pool[i] == NULL) {
            free(memory_pool[i]);
