#include <pthread.h>

typedef struct {
    int id;
    long timestamp;
    size_t payload_len;
    unsigned char* payload;
} Packet;

typedef struct {
    Packet** packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} PacketQueue;

void init_packet_queue(PacketQueue* queue, size_t initial_capacity) {
    queue->packets = (Packet**)malloc(initial_capacity * sizeof(Packet*));
    queue->count = 0;
    queue->capacity = initial_capacity;
    pthread_mutex_init(&queue->mutex, NULL);
}

void enqueue_packet(PacketQueue* queue, Packet* packet) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->count == queue->capacity) {
        size_t new_capacity = queue->capacity * 2;
        queue->packets = (Packet**)realloc(queue->packets, new_capacity * sizeof(Packet*));
        queue->capacity = new_capacity;
    }
    queue->packets[queue->count++] = packet;
    pthread_mutex_unlock(&queue->mutex);
}

Packet* dequeue_packet(PacketQueue* queue) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->count == 0) {
        pthread_mutex_unlock(&queue->mutex);
        return NULL;
    }
    Packet* packet = queue->packets[0];
    for (size_t i = 1; i < queue->count; ++i) {
        queue->packets[i - 1] = queue->packets[i];
    }
    --queue->count;
    pthread_mutex_unlock(&queue->mutex);
    return packet;
}

void free_packet(Packet* packet) {
    free(packet->payload);
    free(packet);
}

void process_packets(PacketQueue* queue, size_t num_packets, Packet* packets[]) {
    for (size_t i = 0; i < num_packets; ++i) {
        if (packets[i]->payload_len > 1024 || packets[i]->timestamp <= 0) {
            free_packet(packets[i]);
            continue;
        }
        Packet* new_packet = (Packet*)malloc(sizeof(Packet));
        memcpy(new_packet, packets[i], sizeof(Packet));
        new_packet->payload = (unsigned char*)malloc(new_packet->payload_len);
        memcpy(new_packet->payload, packets[i]->payload, new_packet->payload_len);
        enqueue_packet(queue, new_packet);
    }
}

void destroy_packet_queue(PacketQueue* queue) {
    for (size_t i = 0; i < queue->count; ++i) {
        free_packet(queue->packets[i]);
    }
    free(queue->packets);
    pthread_mutex_destroy(&queue->mutex);
}
```

This code defines a `Packet` structure to store the details of a network packet and a `PacketQueue` structure to manage a queue of packets. The `init_packet_queue` function initializes the queue with a given capacity, the `enqueue_packet` function adds a packet to the queue, the `dequeue_packet` function removes and returns a packet from the queue, and the `free_packet` function frees the memory allocated for a packet.

The `process_packets` function processes an array of incoming packets by validating their payloads and timestamps. It creates new `Packet` structures for valid packets, copies the payload data to new buffers, and enqueues them in the queue. The `destroy_packet_queue` function frees all memory associated with the queue and its contents.']

