#define MAX_PACKET_SIZE 1024

typedef struct {
    int pixel_data[MAX_PACKET_SIZE];
    char timestamp[20];
    // Add other metadata fields here
} ImageFrame;

typedef struct {
    ImageFrame *frames;
    size_t count;
    size_t capacity;
    size_t total_memory_used;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->frames = (ImageFrame*)malloc(initial_capacity * sizeof(ImageFrame));
    if (!pool->frames) {
        free(pool);
        return NULL;
    }

    pool->count = 0;
    pool->capacity = initial_capacity;
    pool->total_memory_used = 0;

    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    if (pool->frames) free(pool->frames);
    free(pool);
}

int add_image_frame(MemoryPool *pool, ImageFrame frame) {
    if (pool->count >= pool->capacity) {
        // Double the capacity when needed
        size_t new_capacity = pool->capacity ? pool->capacity * 2 : 1;
        ImageFrame *new_frames = (ImageFrame*)realloc(pool->frames, new_capacity * sizeof(ImageFrame));
        if (!new_frames) return -1; // Memory allocation failed

        pool->frames = new_frames;
        pool->capacity = new_capacity;
    }

    pool->frames[pool->count] = frame;
    pool->total_memory_used += sizeof(ImageFrame);
    pool->count++;

    return 0; // Success
}

int remove_image_frame(MemoryPool *pool, size_t index) {
    if (index >= pool->count) return -1; // Index out of bounds

    memmove(&pool->frames[index], &pool->frames[index + 1], (pool->count - index - 1) * sizeof(ImageFrame));
    pool->total_memory_used -= sizeof(ImageFrame);
    pool->count--;

    return 0; // Success
}

int resize_memory_pool(MemoryPool *pool, size_t new_capacity) {
    if (new_capacity < pool->count) return -1; // New capacity must be larger or equal to current count

    ImageFrame *new_frames = (ImageFrame*)realloc(pool->frames, new_capacity * sizeof(ImageFrame));
    if (!new_frames) return -1; // Memory allocation failed

    pool->frames = new_frames;
    pool->capacity = new_capacity;

    return 0; // Success
}
```

