#define MAX_FILES 1000

typedef struct Frame {
    uint8_t* data;
    int width, height;
} Frame;

typedef struct ImageFile {
    FILE* file;
    Frame** frames;
    size_t frame_count;
} ImageFile;

int allocate_frame_buffer(Frame* frame, int width, int height) {
    size_t buffer_size = (size_t)width * height * sizeof(uint8_t);
    if (buffer_size / width != height || buffer_size > SIZE_MAX / 2) {
        return -1; // Potential integer overflow
    }
    frame->data = malloc(buffer_size);
    if (!frame->data) {
        return -1; // Memory allocation failed
    }
    frame->width = width;
    frame->height = height;
    return 0;
}

int process_image_files(ImageFile* files, size_t file_count) {
    if (file_count > MAX_FILES || file_count == 0) {
        fprintf(stderr, "Error: Invalid file count\n");
        return -1;
    }

    for (size_t i = 0; i < file_count; ++i) {
        ImageFile* file = &files[i];
        // Open the image file and read metadata to determine frame dimensions
        // ...

        while (!feof(file->file)) {
            Frame* frame = malloc(sizeof(Frame));
            if (!frame) {
                fprintf(stderr, "Error: Failed to allocate memory for frame\n");
                return -1;
            }
            if (allocate_frame_buffer(frame, /* width */, /* height */) != 0) {
                free(frame);
                fprintf(stderr, "Error: Failed to allocate buffer for frame\n");
                return -1;
            }
            // Read raw image data into frame->data
            // ...
            file->frames[file->frame_count++] = frame;
        }

        fclose(file->file);
    }

    return 0;
}

int main() {
    ImageFile files[MAX_FILES];
    size_t file_count;

    // Populate the files array with actual file handles and metadata
    // ...

    if (process_image_files(files, file_count) != 0) {
        fprintf(stderr, "Error: Failed to process image files\n");
        return EXIT_FAILURE;
    }

    // Clean up allocated memory
    for (size_t i = 0; i < file_count; ++i) {
        ImageFile* file = &files[i];
        for (size_t j = 0; j < file->frame_count; ++j) {
            free(file->frames[j]->data);
            free(file->frames[j]);
        }
        free(file->frames);
    }

    return EXIT_SUCCESS;
}
