// Function to initialize and manage NFAPI PDU list
void createAndManageNfapiPduList(int N, const char* baseUrl, bool disableValidation, size_t maxMemory) {
    if (N <= 0 || maxMemory <= sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        printf("Invalid input parameters.\n");
        return;
    }

    // Allocate memory for the list
    NFAPI_CRC_INDICATION_PDU_T* pduList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduList) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Initialize mutex for thread-safe access
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Populate the list with data
    for (int i = 0; i < N; ++i) {
        pthread_mutex_lock(&lock);
        pduList[i].RX_UE_INFORMATION_TAG = rand();
        pduList[i].RNTI = rand();
        pduList[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        pthread_mutex_unlock(&lock);

        // Simulate network latency and packet loss
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += rand() % 3; // Add 0-2 seconds to simulate latency
        nanosleep(&ts, NULL);
    }

    // Cleanup
    pthread_mutex_destroy(&lock);
    free(pduList);
}

