NFAPI_CRC_INDICATION_PDU_T* manage_crc_indications(int *max_structs, int current_load) {
    static NFAPI_CRC_INDICATION_PDU_T *crc_array = NULL;
    static int allocated_size = 0;

    if (current_load > (*max_structs)) {
        *max_structs *= 2; // Simple heuristic for resizing
    }

    if (*max_structs != allocated_size) {
        crc_array = safe_realloc(crc_array, *max_structs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        allocated_size = *max_structs;
    }

    for (int i = 0; i < *max_structs; i++) {
        crc_array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        crc_array[i].RNTI = rand() % 500;
        crc_array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
