void* create_and_populate_list(int N, int max_elements, float packet_loss_prob, int timeout_ms, size_t max_memory) {
    pthread_mutex_lock(&allocation_mutex);
    if (N > max_elements || N * sizeof(NFAPI_CRC_INDICATION_PDU_T) > max_memory) {
