#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PDUS 10000

typedef struct {
    uint16_t RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    int allocated_pdus[MAX_PDUS];
    int num_allocated;
} PDUAllocator;

int initialize_pdu_allocator(PDUAllocator *allocator) {
    pthread_mutex_init(&allocator->mutex, NULL);
    memset(allocator->allocated_pdus, 0, sizeof(allocator->allocated_pdus));
    allocator->num_allocated = 0;
    return 0;
}

int allocate_pdu(PDUAllocator *allocator, int num_pdus, int crc_flag) {
    pthread_mutex_lock(&allocator->mutex);

    if (num_pdus <= 0 || num_pdus > MAX_PDUS) {
        pthread_mutex_unlock(&allocator->mutex);
        return -1; // Invalid number of PDUs
    }

    for (int i = 0; i < num_pdus; ++i) {
        int rnti;
        do {
            rnti = rand() % MAX_PDUS; // Simulate RNTI generation
        } while (allocator->allocated_pdus[rnti] != 0);

        allocator->allocated_pdus[rnti] = 1;
    }

    pthread_mutex_unlock(&allocator->mutex);
    return num_pdus;
}

void free_pdu(PDUAllocator *allocator, int rnti) {
    pthread_mutex_lock(&allocator->mutex);
    if (rnti >= 0 && rnti < MAX_PDUS) {
        allocator->allocated_pdus[rnti] = 0;
    }
    pthread_mutex_unlock(&allocator->mutex);
}

int query_allocated_pdus(PDUAllocator *allocator, int *pdus) {
    pthread_mutex_lock(&allocator->mutex);
    memcpy(pdus, allocator->allocated_pdus, sizeof(allocator->allocated_pdus));
    pthread_mutex_unlock(&allocator->mutex);
    return allocator->num_allocated;
}

void destroy_pdu_allocator(PDUAllocator *allocator) {
    pthread_mutex_destroy(&allocator->mutex);
}
```

This code provides a thread-safe implementation of a PDU allocator using a mutex to ensure concurrent access. It simulates RNTI generation and tracks allocated PDUs using an array. The `allocate_pdu` function ensures no duplicate RNTIs are allocated, and the `free_pdu` function releases them back into the pool. The `query_allocated_pdus` function allows for querying the current state of allocated PDUs.']

