#define MAX_FILENAME_LENGTH 256

typedef struct {
    char filename[MAX_FILENAME_LENGTH];
    int width;
    int height;
    unsigned char* imageData; // Pointer to the image data
} ImageMetaData;

ImageMetaData* process_image_directory(const char* directoryPath, size_t* numImages) {
    DIR* dir;
    struct dirent* ent;
    struct stat fileStat;
    ImageMetaData* metadataArray = NULL;
    *numImages = 0;

    if ((dir = opendir(directoryPath)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            char filePath[MAX_FILENAME_LENGTH];
            snprintf(filePath, sizeof(filePath), "%s/%s", directoryPath, ent->d_name);

            if (lstat(filePath, &fileStat) == 0 && S_ISREG(fileStat.st_mode)) {
                (*numImages)++;
            }
        }
        closedir(dir);
    }

    // Allocate memory for metadata array
    metadataArray = malloc((*numImages) * sizeof(ImageMetaData));
    if (!metadataArray) {
        perror("Failed to allocate memory for image metadata");
        return NULL;
    }

    // Reopen directory and read files again to fill metadata
    if ((dir = opendir(directoryPath)) != NULL) {
        size_t index = 0;
        while ((ent = readdir(dir)) != NULL) {
            char filePath[MAX_FILENAME_LENGTH];
            snprintf(filePath, sizeof(filePath), "%s/%s", directoryPath, ent->d_name);

            if (lstat(filePath, &fileStat) == 0 && S_ISREG(fileStat.st_mode)) {
                struct stat imageStat;
                if (stat(filePath, &imageStat) == 0) {
                    ImageMetaData* current = metadataArray + index++;
                    strncpy(current->filename, ent->d_name, MAX_FILENAME_LENGTH - 1);
                    current->filename[MAX_FILENAME_LENGTH - 1] = '\0';

                    // Simulate loading image data (replace with actual loading logic)
                    current->width = 800; // Example width
                    current->height = 600; // Example height
                    size_t dataSize = current->width * current->height * 3; // Assuming RGB images

                    // Allocate memory for image data
                    current->imageData = malloc(dataSize);
                    if (!current->imageData) {
                        perror("Failed to allocate memory for image data");
                        // Free previously allocated metadata and imageData
                        for (size_t i = 0; i < index - 1; ++i) {
                            free(metadataArray[i].imageData);
                        }
                        free(metadataArray);
                        return NULL;
                    }

                    // Simulate loading image data into memory
                    memset(current->imageData, 0, dataSize); // Example initialization
                } else {
                    perror("Failed to get file stats");
                    // Handle error similarly as above
                }
            }
        }
        closedir(dir);
    }

    return metadataArray;
}

// Example usage:
int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <directory_path>\n", argv[0]);
        return 1;
    }

    size_t numImages = 0;
    ImageMetaData* metadata = process_image_directory(argv[1], &numImages);

    if (metadata) {
        printf("Processed %zu images.\n", numImages);
        // Free allocated memory
        for (size_t i = 0; i < numImages; ++i) {
            free(metadata[i].imageData);
        }
        free(metadata);
    }

    return 0;
}
```

