void* process_packet_headers(PacketHeader headers[], int count, size_t memory_limit) {
    // Calculate total required memory
    size_t total_memory = 0;
    for (int i = 0; i < count; i++) {
        if (headers[i].payload_size > memory_limit) {
            return NULL; // Header payload too large
        }
        if (total_memory + headers[i].payload_size < total_memory) { // Check for overflow
            return NULL;
        }
        total_memory += headers[i].payload_size;
    }

    // Allocate memory
    void* payloads = malloc(total_memory);
    if (!payloads) {
        return NULL; // Memory allocation failed
    }

    // Process each packet header and allocate payload
    uint8_t* current_payload = (uint8_t*)payloads;
    for (int i = 0; i < count; i++) {
        PacketHeader* header = &headers[i];
        void* payload = malloc(header->payload_size);
        if (!payload) {
            free(payloads); // Free previously allocated memory
            return NULL; // Memory allocation failed
        }
        memcpy(current_payload, payload, header->payload_size);
        current_payload += header->payload_size;
    }

    return payloads;
}
