    if (!file) {
        log_message("Error: Failed to open file for reading.");
        return -1;
    }

    if (fread(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file) != count) {
        log_message("Error: Failed to read from file.");
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}
