void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

NFAPI_CRC_INDICATION_PDU_T* create_nfaapi_crc_indication_pdu_list(int N) {
