    for (int i = 0; i < N; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        list[i].RNTI = rand() % 1000;
        list[i].CRCFLAG = rand() % 2;
    }

    return list;
}

// Asynchronous graph database operation implementation
void* async_graph_db_operation(void* args) {
    // Simulate an asynchronous graph database operation
    struct timespec delay;
    delay.tv_sec = rand() % 3 + 1; // Random delay between 1 to 3 seconds
    delay.tv_nsec = 0;
    nanosleep(&delay, NULL);

    int result = rand() % 2; // Simulate success or failure
    return (void*)result;
}

// Function to handle graph database operation with retries
int handle_graph_db_operation(int max_retries) {
    void* result = async_graph_db_operation(NULL);
    if ((long)result == 0) {
        printf("Graph DB operation failed\n");
        int retry_count = 1;
        while (retry_count <= max_retries) {
            printf("Retrying graph DB operation... Attempt %d\n", retry_count);
            result = async_graph_db_operation(NULL);
            if ((long)result == 0) {
                printf("Graph DB operation succeeded on attempt %d\n", retry_count);
                break;
            }
            retry_count++;
        }
    } else {
        printf("Graph DB operation succeeded immediately\n");
    }

    return (long)result == 0 ? -1 : 0;
}

int main() {
    srand(time(0));

    int N = 5; // Example input size
    NFAPI_CRC_INDICATION_PDU_T* list = create_nfaapi_crc_indication_pdu_list(N);

    printf("NFAPI CRC Indication PDU List:\n");
    for (int i = 0; i < N; i++) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", list[i].RX_UE_INFORMATION_TAG, list[i].RNTI, list[i].CRCFLAG);
    }

    free(list);

    int graph_db_result = handle_graph_db_operation(3);
