#include <stdlib.h>
#include <string.h>
#include <stdio.h>

#define MIN_PACKETS 100
#define MAX_PACKETS 10000
#define MIN_HEADERS 5
#define MAX_HEADERS 100

typedef struct Header {
    int id;
    char data[256];
} Header;

typedef struct Packet {
    int header_count;
    Header headers[MAX_HEADERS];
} Packet;

Packet* allocate_packets(int initial_estimate) {
    if (initial_estimate < MIN_PACKETS || initial_estimate > MAX_PACKETS) {
        fprintf(stderr, "Invalid initial estimate for packet count.\n");
        return NULL;
    }

    Packet* packets = (Packet*)malloc(initial_estimate * sizeof(Packet));
    if (!packets) {
        perror("Failed to allocate memory for packets.");
        return NULL;
    }

    memset(packets, 0, initial_estimate * sizeof(Packet));
    return packets;
}

void free_packets(Packet* packets, int count) {
    if (packets) {
        free(packets);
    }
}

int process_packet_stream(Packet* packets, int packet_count, int header_count_per_packet) {
    if (packet_count < MIN_PACKETS || packet_count > MAX_PACKETS) {
        fprintf(stderr, "Invalid packet count.\n");
        return -1;
    }

    if (header_count_per_packet < MIN_HEADERS || header_count_per_packet > MAX_HEADERS) {
        fprintf(stderr, "Invalid header count per packet.\n");
        return -1;
    }

    for (int i = 0; i < packet_count; i++) {
        if (packets[i].header_count + header_count_per_packet > MAX_HEADERS) {
            fprintf(stderr, "Header count exceeds maximum limit.\n");
            return -1;
        }
        packets[i].header_count += header_count_per_packet;
    }

    return 0;
}

int main() {
    int initial_estimate = 5000;
    Packet* packets = allocate_packets(initial_estimate);
    if (!packets) {
        return 1;
    }

    int packet_count = 3000;
    int header_count_per_packet = 20;

    int result = process_packet_stream(packets, packet_count, header_count_per_packet);
    if (result != 0) {
        free_packets(packets, initial_estimate);
        return 1;
    }

    free_packets(packets, initial_estimate);
    return 0;
}
