NFAPI_CRC_INDICATION_PDU_T* array = NULL;
int count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int add_structure(int RX_UE_INFORMATION_TAG, unsigned short RNTI) {
    pthread_mutex_lock(&mutex);

    if (count >= MAX_STRUCTS || RNTI > TOTAL_RNTI_LIMIT) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    for (int i = 0; i < count; i++) {
        if (array[i].RNTI == RNTI) {
            pthread_mutex_unlock(&mutex);
            return -2;
        }
    }

    if ((count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T) > MAX_ALLOCATION_SIZE) {
        pthread_mutex_unlock(&mutex);
        return -3;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(array, (count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        pthread_mutex_unlock(&mutex);
        return -4;
    }

    array = new_array;
    array[count].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    array[count].RNTI = RNTI;
    array[count].crc_flag = rand() % 2; // Randomly set CRCFLAG

    count++;
    pthread_mutex_unlock(&mutex);

    return 0;
}

