#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_STRUCTS 1024
#define TOTAL_RNTI_LIMIT 512
#define INITIAL_CAPACITY 32

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RNTI;
    // other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPICRCArray {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPICRCArray;

NFAPICRCArray* createNFAPICRCArray() {
    NFAPICRCArray *array = (NFAPICRCArray*)malloc(sizeof(NFAPICRCArray));
    if (!array) {
        perror("Failed to allocate memory for NFAPICRCArray");
        exit(EXIT_FAILURE);
    }
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    array->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        perror("Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T array");
        free(array);
        exit(EXIT_FAILURE);
    }
    return array;
}

void destroyNFAPICRCArray(NFAPICRCArray *array) {
    pthread_mutex_lock(&array->mutex);
    if (array->array) {
        free(array->array);
    }
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int addNFAPICRCIndication(NFAPICRCArray *array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            perror("Failed to reallocate memory for NFAPI_CRC_INDICATION_PDU_T array");
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }

    int sum_rnti = 0;
    for (size_t i = 0; i < array->size; ++i) {
        sum_rnti += array->array[i].RNTI;
    }
    if (sum_rnti + pdu.RNTI > TOTAL_RNTI_LIMIT) {
        pthread_mutex_unlock(&array->mutex);
        return -1; // RNTI limit exceeded
    }

    array->array[array->size++] = pdu;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

// Additional functions for garbage collection, health checks, and logging can be implemented here

int main() {
    NFAPICRCArray *array = createNFAPICRCArray();
    NFAPI_CRC_INDICATION_PDU_T pdu = {123};
    addNFAPICRCIndication(array, pdu);
    destroyNFAPICRCArray(array);
    return 0;
}
