using UnityEngine;

public class NFAPI_CRC_INDICATION_PDU_T
{
    public int RNTI;
    public int RX_UE_INFORMATION_TAG;
    public int CRC_INDICATION_REL8_TAG { get; set; }

    public override string ToString()
    {
        return $"RNTI: {RNTI}, RX_UE_INFORMATION_TAG: {RX_UE_INFORMATION_TAG}, CRCFLAG: {CRC_INDICATION_REL8_TAG % 2}";
    }
}

public class RandomGeneratorHelper
{
    private int minRNTI;
    private int maxRNTI;
    private int minRX_UE_INFORMATION_TAG;
    private int maxRX_UE_INFORMATION_TAG;

    public RandomGeneratorHelper(int minRNTI, int maxRNTI, int minRX_UE_INFORMATION_TAG, int maxRX_UE_INFORMATION_TAG)
    {
        this.minRNTI = minRNTI;
        this.maxRNTI = maxRNTI;
        this.minRX_UE_INFORMATION_TAG = minRX_UE_INFORMATION_TAG;
        this.maxRX_UE_INFORMATION_TAG = maxRX_UE_INFORMATION_TAG;
    }

    public float GenerateRandomFloat()
    {
        return UnityEngine.Random.Range(minRNTI, maxRNTI);
    }

    public int GenerateRandomInt(bool inclusive)
    {
        if (inclusive)
            return UnityEngine.Random.Range(minRNTI, maxRNTI + 1);
        else
            return UnityEngine.Random.Range(minRNTI, maxRNTI);
    }

    public override string ToString()
    {
        return $"RNTI Range: {minRNTI}-{maxRNTI}, RX_UE_INFORMATION_TAG Range: {minRX_UE_INFORMATION_TAG}-{maxRX_UE_INFORMATION_TAG}";
    }
}

public class NFAPICRCIndication
{
    private RandomGeneratorHelper randomGenerator;

    public NFAPICRCIndication(RandomGeneratorHelper randomGenerator)
    {
        this.randomGenerator = randomGenerator;
    }

    public void InitializeStructures(int N, out NFAPI_CRC_INDICATION_PDU_T[] structures)
    {
        try
        {
            structures = new NFAPI_CRC_INDICATION_PDU_T[N];
            HashSet<int> usedTags = new HashSet<int>();

            for (int i = 0; i < N; i++)
            {
                int rnti = randomGenerator.GenerateRandomInt(true);
                int rxUeTag;
                do
                {
                    rxUeTag = randomGenerator.GenerateRandomInt(false);
                } while (!usedTags.Add(rxUeTag));

                structures[i] = new NFAPI_CRC_INDICATION_PDU_T
                {
                    RNTI = rnti,
                    RX_UE_INFORMATION_TAG = rxUeTag,
                    CRC_INDICATION_REL8_TAG = randomGenerator.GenerateRandomInt(true)
                };

                Debug.Log(structures[i]);
            }
        }
        catch (OutOfMemoryException ex)
        {
            Debug.LogError("Out of memory exception: " + ex.Message);
        }
    }
}
