void create_and_populate_crc_indications(int N, size_t max_memory) {
    if (N < 0 || max_memory <= 0) {
        fprintf(stderr, "Invalid input: N must be non-negative and max_memory must be greater than zero.\n");
        return;
    }

    size_t structure_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t chunk_size = 1024; // Example chunk size
    size_t allocated_memory = 0;
    NFAPI_CRC_INDICATION_PDU_T *indication_list = NULL;

    while (allocated_memory < max_memory) {
        if ((allocated_memory + structure_size * chunk_size) > max_memory) {
            chunk_size = (max_memory - allocated_memory) / structure_size;
            if (chunk_size == 0) {
                break; // No more memory can be allocated
            }
        }

        NFAPI_CRC_INDICATION_PDU_T *new_chunk = realloc(indication_list, allocated_memory + chunk_size * structure_size);
        if (new_chunk == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            return;
        }

        indication_list = new_chunk;
        allocated_memory += chunk_size * structure_size;

        for (int i = 0; i < chunk_size; ++i) {
            indication_list[allocated_memory / structure_size - 1 + i].RX_UE_INFORMATION_TAG = rand();
            indication_list[allocated_memory / structure_size - 1 + i].RNTI = rand();
            indication_list[allocated_memory / structure_size - 1 + i].CRC_INDICATION_REL8_TAG = rand();
            indication_list[allocated_memory / structure_size - 1 + i].CRCFLAG = rand() % 2; // Randomly set to 0 or 1
        }
    }

    if (allocated_memory > 0) {
        // Process the populated list here
        free(indication_list);
    }
}
