#include <pthread.h>

#define MAX_CONNECTIONS 100
#define MAX_HEADER_SIZE 128

typedef struct {
    int fd;
    char *message;
} ConnectionData;

pthread_mutex_t data_lock = PTHREAD_MUTEX_INITIALIZER;
ConnectionData connection_data[MAX_CONNECTIONS];

void process_connection(int fd) {
    // Read variable-length message header
    uint32_t header_size;
    if (read(fd, &header_size, sizeof(header_size)) != sizeof(header_size)) {
        perror("Failed to read header size");
        return;
    }

    // Calculate buffer size and handle potential overflow
    uint64_t total_size = 0;
    if (__builtin_mul_overflow(header_size, sizeof(char), (uint32_t *)&total_size) ||
        __builtin_add_overflow(total_size, sizeof(uint32_t), &total_size)) {
        fprintf(stderr, "Buffer size calculation overflow\n");
        return;
    }

    // Allocate buffer and read message content
    char *buffer = malloc(total_size);
    if (!buffer) {
        perror("Failed to allocate buffer");
        return;
    }
    if (read(fd, buffer, total_size - sizeof(uint32_t)) != total_size - sizeof(uint32_t)) {
        free(buffer);
        perror("Failed to read message content");
        return;
    }

    // Store message data in thread-safe manner
    pthread_mutex_lock(&data_lock);
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (!connection_data[i].fd) {
            connection_data[i].fd = fd;
            connection_data[i].message = buffer;
            break;
        }
    }
    pthread_mutex_unlock(&data_lock);
}

void *thread_function(void *arg) {
    int fd = *(int *)arg;
    process_connection(fd);
    free(arg); // Free the allocated memory for file descriptor
    return NULL;
}

int main() {
    // Example usage with 100 connections (simplified)
    pthread_t threads[MAX_CONNECTIONS];
    int fds[MAX_CONNECTIONS];

    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        fd = socket(AF_INET, SOCK_STREAM, 0);
        if (fd == -1) {
            perror("Failed to create socket");
            return EXIT_FAILURE;
        }
        fds[i] = fd;

        // Simulate accepting connections
        pthread_create(&threads[i], NULL, thread_function, &fds[i]);
    }

    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
