NFAPI_CRC_INDICATION_PDU_T** allocateBuffer(int *bufferSize, int maxWaveformLength, int numberOfWaveforms) {
    *bufferSize = maxWaveformLength * numberOfWaveforms;
    NFAPI_CRC_INDICATION_PDU_T **buffer = (NFAPI_CRC_INDICATION_PDU_T**)malloc((*bufferSize) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for(int i = 0; i < *bufferSize; i++) {
        buffer[i] = allocateNFAPDU(numberOfWaveforms);
    }
    return buffer;
}

void freeBuffer(NFAPI_CRC_INDICATION_PDU_T **buffer, int bufferSize, int numberOfWaveforms) {
    for(int i = 0; i < bufferSize; i++) {
        freeNFAPDU(buffer[i], numberOfWaveforms);
    }
    free(buffer);
}

int main() {
    int maxWaveformLength = 1024;
    int numberOfWaveforms = 5;

    int bufferSize;
    NFAPI_CRC_INDICATION_PDU_T **buffer = allocateBuffer(&bufferSize, maxWaveformLength, numberOfWaveforms);

    // Populate the buffer with random data
    for(int i = 0; i < bufferSize; i++) {
        for(int j = 0; j < numberOfWaveforms; j++) {
            buffer[i][j].RX_UE_INFORMATION_TAG = i * numberOfWaveforms + j;
            buffer[i][j].RNTI = rand() % 1024;
            buffer[i][j].CRC_INDICATION_REL8_TAG = i;
            buffer[i][j].CRCFLAG = generateRandomCRCFLAG();
        }
    }

    // Process audio samples
    int audioSampleLength = 512;
    for(int sampleIndex = 0; sampleIndex < maxWaveformLength; sampleIndex += audioSampleLength) {
        int endIndex = sampleIndex + audioSampleLength > maxWaveformLength ? maxWaveformLength : sampleIndex + audioSampleLength;
        for(int waveformIndex = 0; waveformIndex < numberOfWaveforms; waveformIndex++) {
            // Process the audio samples
            printf("Processing sample %d of waveform %d\n", sampleIndex, waveformIndex);
        }
    }

    freeBuffer(buffer, bufferSize, numberOfWaveforms);

    return 0;
}
