#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Image {
    char* filePath;
    int width;
    int height;
    unsigned char* data;
} Image;

typedef struct ImageLibrary {
    Image** images;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ImageLibrary;

ImageLibrary* createImageLibrary(size_t initialCapacity) {
    ImageLibrary* library = (ImageLibrary*)malloc(sizeof(ImageLibrary));
    if (!library) return NULL;

    library->images = (Image**)calloc(initialCapacity, sizeof(Image*));
    if (!library->images) {
        free(library);
        return NULL;
    }

    library->capacity = initialCapacity;
    library->count = 0;
    pthread_mutex_init(&library->lock, NULL);

    return library;
}

void destroyImageLibrary(ImageLibrary* library) {
    for (size_t i = 0; i < library->count; ++i) {
        Image* image = library->images[i];
        free(image->filePath);
        free(image->data);
        free(image);
    }
    free(library->images);
    pthread_mutex_destroy(&library->lock);
    free(library);
}

int addImageToLibrary(ImageLibrary* library, char* filePath, int width, int height, unsigned char* data) {
    pthread_mutex_lock(&library->lock);

    if (library->count >= library->capacity) {
        size_t newCapacity = library->capacity * 2;
        Image** newImages = (Image**)realloc(library->images, newCapacity * sizeof(Image*));
        if (!newImages) {
            pthread_mutex_unlock(&library->lock);
            return -1; // Memory allocation failed
        }
        library->images = newImages;
        library->capacity = newCapacity;
    }

    Image* image = (Image*)malloc(sizeof(Image));
    if (!image) {
        pthread_mutex_unlock(&library->lock);
        return -1; // Memory allocation failed
    }

    image->filePath = strdup(filePath);
    if (!image->filePath) {
        free(image);
        pthread_mutex_unlock(&library->lock);
        return -1; // Memory allocation failed
    }

    image->width = width;
    image->height = height;
    size_t dataSize = (size_t)width * (size_t)height;
    image->data = (unsigned char*)malloc(dataSize);
    if (!image->data) {
        free(image->filePath);
        free(image);
        pthread_mutex_unlock(&library->lock);
        return -1; // Memory allocation failed
    }
    memcpy(image->data, data, dataSize);

    library->images[library->count++] = image;

    pthread_mutex_unlock(&library->lock);
    return 0;
}

Image* getImageFromLibrary(ImageLibrary* library, char* filePath) {
    pthread_mutex_lock(&library->lock);
    for (size_t i = 0; i < library->count; ++i) {
        if (strcmp(library->images[i]->filePath, filePath) == 0) {
            Image* image = library->images[i];
            pthread_mutex_unlock(&library->lock);
            return image;
        }
    }
    pthread_mutex_unlock(&library->lock);
    return NULL;
}

int main() {
    // Example usage
    ImageLibrary* library = createImageLibrary(10);

    unsigned char imageData[100 * 100] = { /* ... */ };
    addImageToLibrary(library, "path/to/image.jpg", 100, 100, imageData);

    Image* retrievedImage = getImageFromLibrary(library, "path/to/image.jpg");
    if (retrievedImage) {
        // Process image data
    }

    destroyImageLibrary(library);
    return 0;
}
