#include <stdlib.h>
#include <pthread.h>
#include <limits.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU;

typedef struct LinkedList {
    NFAPI_CRC_INDICATION_PDU *head;
    pthread_mutex_t mutex;
} LinkedList;

LinkedList* createLinkedList() {
    LinkedList *list = (LinkedList *)malloc(sizeof(LinkedList));
    if (!list) {
        perror("Failed to allocate memory for linked list");
        return NULL;
    }
    list->head = NULL;
    if (pthread_mutex_init(&list->mutex, NULL) != 0) {
        perror("Failed to initialize mutex");
        free(list);
        return NULL;
    }
    return list;
}

NFAPI_CRC_INDICATION_PDU* createNode(int RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU *node = (NFAPI_CRC_INDICATION_PDU *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!node) {
        perror("Failed to allocate memory for node");
        return NULL;
    }
    node->RNTI = RNTI;
    node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    node->next = NULL;
    return node;
}

void insertNode(LinkedList *list, NFAPI_CRC_INDICATION_PDU *node) {
    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = node;
    } else {
        NFAPI_CRC_INDICATION_PDU *temp = list->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = node;
    }
    pthread_mutex_unlock(&list->mutex);
}

void freeLinkedList(LinkedList *list) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU *temp = list->head;
    while (temp != NULL) {
        NFAPI_CRC_INDICATION_PDU *next = temp->next;
        free(temp);
        temp = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}
