#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKET_LENGTH 1024
#define MEMORY_LIMIT 1024 * 1024 // 1MB

typedef struct {
    int protocol_type;
    int packet_length;
    char payload[MAX_PACKET_LENGTH];
} PacketHeader;

PacketHeader* process_packet_headers(int num_headers, ...) {
    va_list args;
    va_start(args, num_headers);

    int total_memory_used = 0;
    PacketHeader* headers = NULL;
    PacketHeader* current_header = NULL;

    for (int i = 0; i < num_headers; i++) {
        PacketHeader header = va_arg(args, PacketHeader);

        // Check memory limit
        if (total_memory_used + sizeof(PacketHeader) + header.packet_length > MEMORY_LIMIT) {
            fprintf(stderr, "Memory limit exceeded.\n");
            break;
        }

        // Allocate memory for the current header and payload
        headers = realloc(headers, total_memory_used + sizeof(PacketHeader) + header.packet_length);
        if (headers == NULL) {
            fprintf(stderr, "Failed to allocate memory.\n");
            break;
        }

        // Initialize current_header pointer to the newly allocated memory block
        current_header = (PacketHeader*)((char*)headers + total_memory_used);

        // Copy data into the allocated memory
        memcpy(current_header, &header, sizeof(PacketHeader));
        memcpy(current_header->payload, header.payload, header.packet_length);

        // Update total memory used
        total_memory_used += sizeof(PacketHeader) + header.packet_length;
    }

    va_end(args);
    return headers;
}

int main() {
    PacketHeader headers[3] = {
        {1, 500, "TCP Data"},
        {2, 700, "UDP Data"},
        {3, 600, "ICMP Data"}
    };

    PacketHeader* processed_headers = process_packet_headers(3, headers[0], headers[1], headers[2]);

    if (processed_headers != NULL) {
        for (int i = 0; i < 3; i++) {
            printf("Protocol Type: %d, Packet Length: %d, Payload: %s\n",
                   processed_headers[i].protocol_type,
                   processed_headers[i].packet_length,
                   processed_headers[i].payload);
        }
        free(processed_headers); // Free the allocated memory
    }

    return 0;
}
```

This code defines a function `process_packet_headers` that takes a variable number of `PacketHeader` structures and dynamically allocates memory for them while ensuring it stays within a predefined memory limit. It uses `realloc` to manage memory, allowing for efficient reallocation as more headers are processed. The function includes basic error handling to check if memory allocation fails or if the total allocated memory exceeds the specified limit.']

