        fprintf(stderr, "Payload length exceeds maximum buffer size\n");
        return NULL;
    }

    Packet* new_packet = (Packet*)malloc(sizeof(Packet));
    if (!new_packet) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    new_packet->payload_length = payload_length;
    new_packet->payload = (char*)malloc(payload_length);
    if (!new_packet->payload) {
        free(new_packet);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    memcpy(new_packet->payload, payload, payload_length);

    return new_packet;
}

PacketList* add_packet_to_list(PacketList** list_head, Packet* packet) {
    PacketList* new_node = (PacketList*)malloc(sizeof(PacketList));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    new_node->packet = packet;
    new_node->next = *list_head;

    *list_head = new_node;

    return *list_head;
}

void free_packet_list(PacketList* list_head) {
    PacketList* current = list_head;
    while (current) {
        Packet* packet = current->packet;
        if (packet) {
            free(packet->payload);
            free(packet);
        }
        PacketList* next = current->next;
        free(current);
        current = next;
    }
}

