#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure for a network packet
typedef struct Packet {
    int payload_length;
    unsigned char *payload;
    struct Packet *next;
} Packet;

// Function to create a new packet with a given payload length
Packet* create_packet(int length) {
    Packet *new_packet = (Packet*)malloc(sizeof(Packet));
    if (new_packet == NULL) {
        fprintf(stderr, "Memory allocation failed for new packet\n");
        return NULL;
    }
    new_packet->payload_length = length;
    new_packet->payload = (unsigned char*)malloc(length);
    if (new_packet->payload == NULL) {
        fprintf(stderr, "Memory allocation failed for payload of new packet\n");
        free(new_packet);
        return NULL;
    }
    memset(new_packet->payload, 0, length);
    new_packet->next = NULL;
    return new_packet;
}

// Function to add a packet to the list
void add_packet_to_list(Packet **head, Packet *new_packet) {
    if (*head == NULL) {
        *head = new_packet;
    } else {
        Packet *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_packet;
    }
}

// Function to process a series of network packets
Packet* process_packets(int max_payload_size, int packet_count, const int payload_lengths[]) {
    Packet *packet_list_head = NULL;
    for (int i = 0; i < packet_count; i++) {
        if (payload_lengths[i] > max_payload_size) {
            fprintf(stderr, "Payload size exceeds maximum limit\n");
            break;
        }
        Packet *new_packet = create_packet(payload_lengths[i]);
        if (new_packet != NULL) {
            add_packet_to_list(&packet_list_head, new_packet);
        }
    }
    return packet_list_head;
}

// Function to free memory allocated for the packet list
void free_packets(Packet **head) {
    Packet *current = *head;
    while (current != NULL) {
        Packet *next = current->next;
        free(current->payload);
        free(current);
        current = next;
    }
    *head = NULL;
}

int main() {
    int max_payload_size = 1024;
    int packet_count = 5;
    int payload_lengths[] = {512, 768, 1024, 128, 256};

    Packet *packet_list = process_packets(max_payload_size, packet_count, payload_lengths);

    // Use the packet list...

    free_packets(&packet_list);
    return 0;
}
