        return -1; // Invalid input
    }

    size_t required_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (required_size > MAX_SIZE) {
        return -2; // Required memory exceeds max allowed
    }

    // Check for integer overflow during multiplication
    uint64_t temp = (uint64_t)N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (temp > UINT32_MAX || temp / N != sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return -3; // Integer overflow detected
    }

    *out_ptr = (NFAPI_CRC_INDICATION_PDU_T *)malloc(required_size);
    if (*out_ptr == NULL) {
        return -4; // Memory allocation failed
    }

    for (uint32_t i = 0; i < N; ++i) {
        (*out_ptr)[i].tag = RX_UE_INFORMATION_TAG;
    }

    return 0; // Success
}

void free_nfa_pi(NFAPI_CRC_INDICATION_PDU_T *ptr) {
    if (ptr != NULL) {
