#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

#define BUFFER_RESIZE_THRESHOLD 0.75
#define MAX_BUFFER_SIZE (1024 * 1024 * 1024) // 1GB

typedef struct {
    uint8_t* buffer;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} PacketBuffer;

PacketBuffer* create_packet_buffer(size_t initial_capacity, size_t average_payload_size) {
    PacketBuffer* buffer = malloc(sizeof(PacketBuffer));
    if (!buffer) return NULL;

    buffer->capacity = round_up_to_nearest_multiple(initial_capacity * average_payload_size, 16);
    buffer->size = 0;
    buffer->buffer = malloc(buffer->capacity);
    if (!buffer->buffer) {
        free(buffer);
        return NULL;
    }

    pthread_mutex_init(&buffer->mutex, NULL);
    return buffer;
}

void destroy_packet_buffer(PacketBuffer* buffer) {
    pthread_mutex_lock(&buffer->mutex);
    free(buffer->buffer);
    pthread_mutex_unlock(&buffer->mutex);
    pthread_mutex_destroy(&buffer->mutex);
    free(buffer);
}

size_t round_up_to_nearest_multiple(size_t value, size_t multiple) {
    return ((value + multiple - 1) / multiple) * multiple;
}

bool resize_packet_buffer(PacketBuffer* buffer, size_t new_capacity) {
    if (new_capacity > MAX_BUFFER_SIZE) return false;

    uint8_t* new_buffer = realloc(buffer->buffer, new_capacity);
    if (!new_buffer) return false;

    buffer->buffer = new_buffer;
    buffer->capacity = new_capacity;
    return true;
}

bool add_packet_to_buffer(PacketBuffer* buffer, const void* payload, size_t payload_size) {
    pthread_mutex_lock(&buffer->mutex);

    if (buffer->size + payload_size > buffer->capacity * BUFFER_RESIZE_THRESHOLD) {
        size_t new_capacity = round_up_to_nearest_multiple(buffer->capacity * 2, 16);
        if (!resize_packet_buffer(buffer, new_capacity)) {
            pthread_mutex_unlock(&buffer->mutex);
            return false;
        }
    }

    memcpy(buffer->buffer + buffer->size, payload, payload_size);
    buffer->size += payload_size;

    pthread_mutex_unlock(&buffer->mutex);
    return true;
}
