    Packet* processed_packets = malloc(num_packets * sizeof(Packet));
    if (!processed_packets) {
        // Handle memory allocation failure
        return NULL;
    }

    for (int i = 0; i < num_packets; ++i) {
        if (packets[i] == NULL || packets[i]->size > MAX_PACKET_SIZE) {
            continue; // Skip invalid or too large packets
        }

        processed_packets[i].payload = malloc(packets[i]->size + 1);
        if (!processed_packets[i].payload) {
            // Handle memory allocation failure for payload
            free(processed_packets);
            return NULL;
        }

        memcpy(processed_packets[i].payload, packets[i]->payload, packets[i]->size);
        processed_packets[i].payload[packets[i]->size] = '\0';
