    }

    int packet_count = rand() % MAX_UE_INFO + 1;
    if (populate_packet_data(pdu, packet_count) != 0) {
        fprintf(stderr, "Invalid packet count\n");
        free_memory(pdu);
        return 1;
    }

    // Start threads for processing packets and memory management
    pthread_create(&packet_processing_thread, NULL, process_network_packets, pdu);
    pthread_create(&memory_manager_thread, NULL, memory_management_system, pdu);

    // Wait for threads to finish
    pthread_join(packet_processing_thread, NULL);
    pthread_join(memory_manager_thread, NULL);

    free_memory(pdu);
    return 0;
}
