#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

#define MAX_PACKETS 1024
#define RX_UE_INFORMATION_TAG 0x12345678
#define RNTI 0xABCD
#define CRC_INDICATION_REL8_TAG 0xEF01

typedef struct {
    int rx_ue_information_tag;
    int rnti;
} RX_UE_INFORMATION_T;

typedef struct {
    int crc_indication_rel8_tag;
    bool crcflag;
} CRC_INDICATION_PDU_T;

typedef struct PoolNode {
    CRC_INDICATION_PDU_T data;
    struct PoolNode* next;
} PoolNode_T;

typedef struct {
    PoolNode_T* head;
    PoolNode_T* tail;
    int size;
} MemoryPool_T;

void initialize_pool(MemoryPool_T* pool, int initial_size) {
    pool->head = NULL;
    pool->tail = NULL;
    pool->size = 0;
    for (int i = 0; i < initial_size && pool->size < MAX_PACKETS; i++) {
        PoolNode_T* new_node = (PoolNode_T*)malloc(sizeof(PoolNode_T));
        if (new_node) {
            new_node->next = NULL;
            if (pool->head == NULL) {
                pool->head = new_node;
            } else {
                pool->tail->next = new_node;
            }
            pool->tail = new_node;
            pool->size++;
        }
    }
}

void destroy_pool(MemoryPool_T* pool) {
    PoolNode_T* current = pool->head;
    while (current != NULL) {
        PoolNode_T* next = current->next;
        free(current);
        current = next;
    }
    pool->head = NULL;
    pool->tail = NULL;
    pool->size = 0;
}

CRC_INDICATION_PDU_T* allocate_packet(MemoryPool_T* pool) {
    if (pool->size == 0) {
        return NULL; // No more packets can be allocated
    }
    PoolNode_T* node = pool->head;
    pool->head = node->next;
    if (pool->tail == node) {
        pool->tail = NULL;
    }
    pool->size--;
    return &node->data;
}

void deallocate_packet(MemoryPool_T* pool, CRC_INDICATION_PDU_T* packet) {
    PoolNode_T* new_node = (PoolNode_T*)malloc(sizeof(PoolNode_T));
    if (new_node) {
        new_node->data = *packet;
        new_node->next = NULL;
        if (pool->tail == NULL) {
            pool->head = new_node;
        } else {
            pool->tail->next = new_node;
        }
        pool->tail = new_node;
        pool->size++;
    }
}

int create_and_populate_packets(MemoryPool_T* pool, int num_packets) {
    if (num_packets > MAX_PACKETS || num_packets < 0) {
        return -1; // Invalid number of packets
    }

    srand(time(NULL));
    for (int i = 0; i < num_packets; i++) {
        CRC_INDICATION_PDU_T* packet = allocate_packet(pool);
        if (!packet) {
            return i; // Allocation failed
        }
        packet->rx_ue_information_tag = RX_UE_INFORMATION_TAG;
        packet->rnti = RNTI;
        packet->crc_indication_rel8_tag = CRC_INDICATION_REL8_TAG;
        packet->crcflag = (rand() % 2) == 0; // Randomly set CRCFLAG
    }
    return num_packets; // Successfully allocated and populated all packets
}
```

