#include <stdio.h>
#include <stdlib.h>

typedef struct Packet {
    int size;
    void *data;
} Packet;

typedef struct PacketQueue {
    Packet **packets;
    size_t capacity;
    size_t count;
} PacketQueue;

PacketQueue* create_packet_queue(size_t initial_capacity) {
    PacketQueue *queue = (PacketQueue*)malloc(sizeof(PacketQueue));
    if (!queue) return NULL;

    queue->capacity = initial_capacity;
    queue->count = 0;
    queue->packets = (Packet**)malloc(initial_capacity * sizeof(Packet*));

    if (!queue->packets) {
        free(queue);
        return NULL;
    }

    return queue;
}

void enqueue_packet(PacketQueue *queue, Packet *packet) {
    if (queue->count >= queue->capacity) {
        size_t new_capacity = queue->capacity == 0 ? 1 : queue->capacity * 2;
        Packet** new_packets = (Packet**)realloc(queue->packets, new_capacity * sizeof(Packet*));

        if (!new_packets) {
            printf("Memory allocation failed. Unable to enqueue packet.\n");
            return;
        }

        queue->packets = new_packets;
        queue->capacity = new_capacity;
    }

    queue->packets[queue->count++] = packet;
}

Packet* dequeue_packet(PacketQueue *queue) {
    if (queue->count == 0) {
        printf("Packet queue is empty.\n");
        return NULL;
    }

    Packet *packet = queue->packets[--queue->count];

    // Optionally, you can set the pointer to NULL to avoid dangling pointers
    queue->packets[queue->count] = NULL;

    if (queue->count > 0 && queue->count == queue->capacity / 4) {
        size_t new_capacity = queue->capacity / 2;
        Packet** new_packets = (Packet**)realloc(queue->packets, new_capacity * sizeof(Packet*));

        if (!new_packets) {
            printf("Memory reallocation failed. Unable to dequeue packet.\n");
            return packet; // Return the packet even though memory was not freed
        }

        queue->packets = new_packets;
        queue->capacity = new_capacity;
    }

    return packet;
}

void free_packet(Packet *packet) {
    if (packet) {
        if (packet->data) {
            free(packet->data);
            packet->data = NULL;
        }
        free(packet);
    }
}

void free_packet_queue(PacketQueue *queue) {
    for (size_t i = 0; i < queue->count; ++i) {
        free_packet(queue->packets[i]);
    }

    free(queue->packets);
    free(queue);
}
