#define MAX_PACKET_SIZE 1024
#define MAX_BUFFER_SIZE 10 * MAX_PACKET_SIZE

typedef struct Packet {
    int length;
    char data[MAX_PACKET_SIZE];
} Packet;

typedef struct Buffer {
    size_t total_length;
    char* buffer;
} Buffer;

int process_packet(Buffer* buffer, const Packet* packet) {
    if (buffer->total_length + packet->length > MAX_BUFFER_SIZE) {
        fprintf(stderr, "Buffer overflow detected!\n");
        return -1;
    }
    memcpy(buffer->buffer + buffer->total_length, packet->data, packet->length);
    buffer->total_length += packet->length;
    return 0;
}

void* packet_processor(void* arg) {
    Buffer* buffer = (Buffer*)arg;
    Packet packet;
    while (1) {
        // Simulate receiving a packet
        int ret = recv_packet(&packet); // Function to receive a packet
        if (ret == -1) {
            break; // End of processing
        }
        ret = process_packet(buffer, &packet);
        if (ret == -1) {
            fprintf(stderr, "Failed to process packet!\n");
            break;
        }
    }
    free(buffer->buffer);
    free(buffer);
    return NULL;
}

int main() {
    Buffer* buffer = malloc(sizeof(Buffer));
    if (!buffer) {
        fprintf(stderr, "Failed to allocate memory for buffer!\n");
        return -1;
    }
    buffer->total_length = 0;
    buffer->buffer = malloc(MAX_BUFFER_SIZE);
    if (!buffer->buffer) {
        fprintf(stderr, "Failed to allocate memory for buffer data!\n");
        free(buffer);
        return -1;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, packet_processor, buffer)) {
        fprintf(stderr, "Failed to create thread!\n");
        free(buffer->buffer);
        free(buffer);
        return -1;
