#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1024
#define THRESHOLD 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* construct_packets(int N, int threshold) {
    if (N < 0 || threshold < 0) {
        return NULL; // Handle negative input
    }

    NFAPI_CRC_INDICATION_PDU_T* packets = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!packets) {
        perror("Failed to allocate memory for packets");
        return NULL;
    }

    int processed_packets = 0;

    while (processed_packets < N && processed_packets < threshold) {
        // Simulate packet processing
        packets[processed_packets].RX_UE_INFORMATION_TAG = rand() % 1000;
        packets[processed_packets].RNTI = rand() % 1024;
        packets[processed_packets].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
        processed_packets++;
    }

    return packets;
}

void* process_packets(void* arg) {
    int N = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T* packets = construct_packets(N, THRESHOLD);

    if (!packets) {
        pthread_exit(NULL);
    }

    // Simulate packet processing
    for (int i = 0; i < N && i < THRESHOLD; i++) {
        printf("Processed packet: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d\n",
               packets[i].RX_UE_INFORMATION_TAG,
               packets[i].RNTI,
               packets[i].CRC_INDICATION_REL8_TAG);
    }

    free(packets);
    pthread_exit(NULL);
}

int main() {
    int num_packets = 150;
    pthread_t thread;

    if (pthread_create(&thread, NULL, process_packets, &num_packets) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread, NULL) != 0) {
        perror("Failed to join thread");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```

