import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;

public class CommandExecutor {

    public static void executeCommand(String command, String[] args, File directory) {
        try {
            Process process = Runtime.getRuntime().exec(command, args, directory);
            int exitCode = process.waitFor();

            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

            String line;
            System.out.println("Output:");
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }

            System.err.println("Error Output:");
            while ((line = errorReader.readLine()) != null) {
                System.err.println(line);
            }

            if (exitCode != 0) {
                System.err.println("Command execution failed with exit code: " + exitCode);
            }
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        File directory = new File("/path/to/directory");
        if (directory.exists()) {
            directory.delete();
        }

        String command = "your_command_here";
        String[] argsArray = {"arg1", "arg2"};

        executeCommand(command, argsArray, directory);
    }
}
