#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MIN_ALLOC_SIZE 10
#define MAX_ALLOC_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdu_array;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t lock;
    time_t last_log_time;
    int log_level;
} ResourceAllocator;

void init_allocator(ResourceAllocator* allocator, int initial_size, int log_level) {
    allocator->pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    allocator->allocated_size = initial_size;
    allocator->used_size = 0;
    pthread_mutex_init(&allocator->lock, NULL);
    allocator->last_log_time = time(NULL);
    allocator->log_level = log_level;
}

void free_allocator(ResourceAllocator* allocator) {
    pthread_mutex_lock(&allocator->lock);
    free(allocator->pdu_array);
    pthread_mutex_unlock(&allocator->lock);
    pthread_mutex_destroy(&allocator->lock);
}

int allocate_pdu(ResourceAllocator* allocator, int N) {
    pthread_mutex_lock(&allocator->lock);

    if (N <= 0) {
        pthread_mutex_unlock(&allocator->lock);
        return -1; // Invalid input
    }

    while (allocator->used_size + N > allocator->allocated_size) {
        time_t current_time = time(NULL);
        if (current_time - allocator->last_log_time >= 60 && allocator->log_level >= 2) {
            printf("Resource limit approaching. Reducing allocation from %zu to %zu.\n", allocator->used_size + N, allocator->allocated_size);
            allocator->last_log_time = current_time;
        }
        N /= 2; // Reduce allocation size
    }

    for (int i = 0; i < N; i++) {
        allocator->pdu_array[allocator->used_size + i].RX_UE_INFORMATION_TAG = rand() % 100;
        allocator->pdu_array[allocator->used_size + i].RNTI = rand() % 256;
        allocator->pdu_array[allocator->used_size + i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    allocator->used_size += N;

    pthread_mutex_unlock(&allocator->lock);
    return 0; // Success
}
