void initialize_memory_pool(MemoryPool* pool) {
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_SIZE);
    if (!pool->pool) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pool->pool_size = MAX_SIZE / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pool->count = 0;
}

void* allocate_item(MemoryPool* pool) {
    if (pool->count >= pool->pool_size) {
        fprintf(stderr, "Memory pool is full\n");
        return NULL;
    }
    void* item = &pool->pool[pool->count++];
    return item;
}

void free_memory_pool(MemoryPool* pool) {
    free(pool->pool);
    pool->pool = NULL;
    pool->pool_size = 0;
    pool->count = 0;
}

