#define MAX_PAYLOAD_SIZE 1024

typedef struct PacketMetadata {
    int sourceId;
    int packetSize;
    void* payload;
} PacketMetadata;

int processPackets(PacketMetadata** packets, int numPackets) {
    if (numPackets < 0) {
        // Handle negative number of packets error
        return -1;
    }

    // Calculate total memory needed for all payloads
    size_t totalPayloadSize = 0;
    for (int i = 0; i < numPackets; ++i) {
        if (packets[i]->packetSize > MAX_PAYLOAD_SIZE) {
            // Handle payload too large error
            return -2;
        }
        totalPayloadSize += packets[i]->packetSize;
    }

    // Check for potential integer overflow in calculating total memory needed
    if ((size_t)-1 / sizeof(PacketMetadata) < (totalPayloadSize + numPackets)) {
        // Handle integer overflow error
        return -3;
    }

    // Allocate memory for all packet metadata structures and payloads
    size_t totalMemory = (totalPayloadSize + numPackets * sizeof(PacketMetadata));
    void* memoryBlock = malloc(totalMemory);
    if (!memoryBlock) {
        // Handle memory allocation failure
        return -4;
    }

    // Set up pointers to allocate memory for payloads within the block
    char* payloadPtr = (char*)memoryBlock + numPackets * sizeof(PacketMetadata);

    for (int i = 0; i < numPackets; ++i) {
        packets[i]->payload = payloadPtr;
        memcpy(payloadPtr, packets[i]->payload, packets[i]->packetSize);
        payloadPtr += packets[i]->packetSize;
    }

    return 0;
}
