    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    unsigned char *payload;
    size_t payload_size;
} NetworkPacketHeader;

NetworkPacketHeader* process_network_packets(unsigned char **packet_buffers, int buffer_count) {
    NetworkPacketHeader *headers = (NetworkPacketHeader *)malloc(buffer_count * sizeof(NetworkPacketHeader));
    if (!headers) {
        perror("Failed to allocate memory for headers");
        return NULL;
    }

    for (int i = 0; i < buffer_count; i++) {
        NetworkPacketHeader *header = &headers[i];
        // Simulate reading packet length and payload size from a buffer
        int packet_length = *(int *)packet_buffers[i]; // Assuming first int is the length
        size_t payload_size = packet_length - sizeof(int); // Subtract the length field itself

        if (payload_size <= 0) {
            printf("Invalid packet size: %zu\n", payload_size);
            continue;
        }

        header->packet_length = packet_length;
        header->timestamp = time(NULL);

        // Simulate reading IP addresses and payload
        memcpy(header->source_ip, packet_buffers[i] + sizeof(int), 16);
        memcpy(header->destination_ip, packet_buffers[i] + sizeof(int) + 16, 16);

        // Check for integer overflow
        size_t total_size = sizeof(NetworkPacketHeader) - sizeof(unsigned char *) + payload_size;
        if (total_size > SIZE_MAX || total_size < payload_size) {
            printf("Buffer size exceeded due to integer overflow\n");
            free(headers);
            return NULL;
        }

        header->payload = (unsigned char *)malloc(payload_size * sizeof(unsigned char));
        if (!header->payload) {
            perror("Failed to allocate memory for payload");
            free(headers);
            return NULL;
        }
        memcpy(header->payload, packet_buffers[i] + sizeof(int) + 32, payload_size); // Assuming IP addresses start at offset 32
        header->payload_size = payload_size;

        // Simulate external data retrieval delay
        usleep(1000); // Delay for 1ms to simulate network latency or database access
    }

    return headers;
}

int main() {
    unsigned char packet_buffers[MAX_BUFFER_COUNT][MAX_PACKET_SIZE];
    // Populate packet_buffers with actual packet data

