    if (headers) {
        for (int i = 0; i < MAX_BUFFER_COUNT; i++) {
            printf("Packet %d: Length=%d, Payload Size=%zu\n", i, headers[i].packet_length, headers[i].payload_size);
            free(headers[i].payload);
        }
        free(headers);
    }

    return 0;
}
