void add_to_array(int rx_tag, int rnti) {
    pthread_mutex_lock(&mutex);

    if (current_size >= max_size) {
        fprintf(stderr, "Error: Maximum elements reached.\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T new_element = {rx_tag, rnti, rand() % 2};
    array[current_size] = new_element;
    current_size++;

