        array = realloc(array, (max_size * 3 / 2) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (array == NULL) {
            fprintf(stderr, "Error: Memory reallocation failed.\n");
            current_size = max_size;
        } else {
            max_size = max_size * 3 / 2;
        }
    }

    pthread_mutex_unlock(&mutex);
}

