typedef enum {
    SUCCESS,
    INSUFFICIENT_MEMORY
} StatusCode;

#define MAX_GROWTH_FACTOR 2

NFAPI_CRC_INDICATION_PDU_T** createDynamicList(int initialSize, int maxSize, int logLevel) {
    if (initialSize < 1 || maxSize < 1 || initialSize > maxSize) {
        return NULL; // Invalid size parameters
    }

    NFAPI_CRC_INDICATION_PDU_T** list = malloc(initialSize * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < initialSize; i++) {
        list[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list[i]) {
            // Clean up allocated memory on failure
            for (int j = 0; j < i; j++) {
                free(list[j]);
            }
            free(list);
            return NULL;
        }

        // Initialize with random values
        list[i]->rxUeInfoTag.tag = rand();
        list[i]->rnti = rand();
        list[i]->crcIndicationRel8Tag.tag = rand();
        list[i]->crcIndicationRel8Tag.crcFlag = rand() % 2;
    }

    if (logLevel > 0) {
        printf("Dynamic list created with initial size: %d\n", initialSize);
    }

    return list;
}

StatusCode resizeList(NFAPI_CRC_INDICATION_PDU_T*** list, int* currentSize, int newSize, int maxSize, int logLevel) {
    if (newSize < *currentSize || newSize > maxSize) {
        return INSUFFICIENT_MEMORY; // Invalid new size
    }

    NFAPI_CRC_INDICATION_PDU_T** newList = realloc(*list, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!newList) {
        return INSUFFICIENT_MEMORY; // Memory reallocation failed
    }

    for (int i = *currentSize; i < newSize; i++) {
        newList[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newList[i]) {
            // Clean up allocated memory on failure
            for (int j = *currentSize; j < i; j++) {
                free(newList[j]);
            }
            realloc(*list, (*currentSize + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
            return INSUFFICIENT_MEMORY;
        }

        // Initialize with random values
        newList[i]->rxUeInfoTag.tag = rand();
        newList[i]->rnti = rand();
        newList[i]->crcIndicationRel8Tag.tag = rand();
        newList[i]->crcIndicationRel8Tag.crcFlag = rand() % 2;
    }

    *list = newList;
    *currentSize = newSize;

    if (logLevel > 1) {
        printf("Dynamic list resized to new size: %d\n", newSize);
    }

    return SUCCESS;
}

void freeDynamicList(NFAPI_CRC_INDICATION_PDU_T** list, int size) {
    for (int i = 0; i < size; i++) {
        free(list[i]);
    }
    free(list);
}

