#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_ROIS 1024

typedef struct {
    uint32_t crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint8_t *data;
    size_t length;
} ROI;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *indicators;
    int num_indicators;
} NFapiContext;

int parse_roi_data(const char *filename, ROI **rois) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    *rois = malloc(file_size * sizeof(ROI));
    if (!*rois) {
        fclose(file);
        return -2;
    }

    for (size_t i = 0; i < file_size / sizeof(ROI); ++i) {
        fread(&(*rois)[i].length, sizeof(size_t), 1, file);
        (*rois)[i].data = malloc((*rois)[i].length);
        if (!(*rois)[i].data) {
            fclose(file);
            free(*rois);
            *rois = NULL;
            return -3;
        }
        fread((*rois)[i].data, sizeof(uint8_t), (*rois)->length, file);
    }

    fclose(file);
    return 0;
}

void* process_rois(void *arg) {
    NFapiContext *context = (NFapiContext *)arg;
    ROI **rois = malloc(MAX_ROIS * sizeof(ROI *));
    if (!rois) return NULL;

    for (int i = 0; i < context->num_indicators; ++i) {
        int rc = parse_roi_data("path_to_image_file", &rois[i]);
        if (rc != 0) {
            fprintf(stderr, "Error parsing ROI data: %d\n", rc);
            free(rois[i]->data);
            free(rois[i]);
        }
    }

    // Process ROIs here

    for (int i = 0; i < context->num_indicators; ++i) {
        free(rois[i]->data);
        free(rois[i]);
    }

    free(rois);
    return NULL;
}

void manage_rois(NFAPI_CRC_INDICATION_PDU_T *indicators, int num_indicators) {
    NFapiContext context = {indicators, num_indicators};
    pthread_t threads[num_indicators];

    for (int i = 0; i < num_indicators; ++i) {
        if (pthread_create(&threads[i], NULL, process_rois, &context)) {
            fprintf(stderr, "Error creating thread\n");
            return;
        }
    }

    for (int i = 0; i < num_indicators; ++i) {
        pthread_join(threads[i], NULL);
    }
}
