#include <stdlib.h>
#include <string.h>
#include <stdio.h>

#define MAX_ENTRIES 100000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T** crc_indication_array = NULL;
int array_size = 0;
int entry_count = 0;

int init_crc_indication_array(int size) {
    if (size <= 0 || size > MAX_ENTRIES) {
        fprintf(stderr, "Invalid size for CRC indication array\n");
        return -1;
    }

    crc_indication_array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!crc_indication_array) {
        fprintf(stderr, "Memory allocation failed for CRC indication array\n");
        return -2;
    }

    memset(crc_indication_array, 0, size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    array_size = size;
    entry_count = 0;

    return 0;
}

int add_crc_indication_entry(unsigned short rnti) {
    if (entry_count >= array_size) {
        fprintf(stderr, "CRC indication array is full\n");
        return -1;
    }

    for (int i = 0; i < entry_count; i++) {
        if (crc_indication_array[i]->RNTI == rnti) {
            fprintf(stderr, "Duplicate RNTI found in CRC indication array\n");
            return -2;
        }
    }

    crc_indication_array[entry_count] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_indication_array[entry_count]) {
        fprintf(stderr, "Memory allocation failed for CRC indication entry\n");
        return -3;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_entry = crc_indication_array[entry_count];
    new_entry->RX_UE_INFORMATION_TAG = rand();
    new_entry->RNTI = rnti;
    new_entry->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG

    entry_count++;
    return 0;
}

int remove_crc_indication_entry(unsigned short rnti) {
    int index_to_remove = -1;

    for (int i = 0; i < entry_count; i++) {
        if (crc_indication_array[i]->RNTI == rnti) {
            index_to_remove = i;
            break;
        }
    }

    if (index_to_remove == -1) {
        fprintf(stderr, "No entry found with RNTI %d\n", rnti);
        return -1;
    }

    free(crc_indication_array[index_to_remove]);
    for (int i = index_to_remove; i < entry_count - 1; i++) {
        crc_indication_array[i] = crc_indication_array[i + 1];
    }
    crc_indication_array[entry_count - 1] = NULL;
    entry_count--;

    return 0;
}

int get_entry_count() {
    return entry_count;
}
