typedef struct {
    char *filename;
    int size_kb;
} ImageMetadata;

int processImageMetadata(ImageMetadata *metadata, int metadata_count, int max_buffer_size, float grace_factor, char **output_buffer) {
    if (metadata == NULL || metadata_count <= 0 || output_buffer == NULL) {
        return -1; // Invalid input
    }

    int total_size = 0;
    for (int i = 0; i < metadata_count; i++) {
        total_size += strlen(metadata[i].filename);
        if (total_size > max_buffer_size * (1.0 + grace_factor)) {
            return -2; // Exceeds buffer size with grace factor
        }
    }

    int adjusted_buffer_size = (int)(max_buffer_size * (1.0 - grace_factor));
    char *buffer = realloc(*output_buffer, adjusted_buffer_size);
    if (buffer == NULL) {
        return -3; // Memory allocation failed
    }
    *output_buffer = buffer;

    int buffer_index = 0;
    for (int i = 0; i < metadata_count; i++) {
        int filename_length = strlen(metadata[i].filename);
        if (buffer_index + filename_length + 1 > adjusted_buffer_size) {
            break; // Buffer overflow protection
        }
        strcpy(buffer + buffer_index, metadata[i].filename);
        buffer_index += filename_length + 1;
    }

    return 0; // Success
}

int main() {
    ImageMetadata metadata[] = {
        {"image1.jpg", 50},
        {"image2.jpg", 75},
        {"image3.jpg", 100}
    };
    int metadata_count = sizeof(metadata) / sizeof(metadata[0]);
    int max_buffer_size = 200;
    float grace_factor = 0.1;

    char *output_buffer = NULL;
    int result = processImageMetadata(metadata, metadata_count, max_buffer_size, grace_factor, &output_buffer);
    if (result == 0) {
        printf("Buffer created: %s\n", output_buffer);
        free(output_buffer);
    } else {
        printf("Error code: %d\n", result);
    }

    return 0;
}
