typedef struct MemoryPool {
    void* pool;
    size_t block_size;
    size_t num_blocks;
    size_t free_index;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t max_blocks) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (pool == NULL) return NULL;

    pool->block_size = block_size;
    pool->num_blocks = max_blocks;
    pool->free_index = 0;

    pool->pool = calloc(max_blocks, block_size);
    if (pool->pool == NULL) {
        free(pool);
        return NULL;
    }

    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    if (pool != NULL) {
        free(pool->pool);
        free(pool);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfaapi_crc_pdu(MemoryPool* pool, size_t N) {
    if (pool == NULL || N > pool->num_blocks - pool->free_index) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* p = (NFAPI_CRC_INDICATION_PDU_T*)(pool->pool + pool->block_size * pool->free_index);
    pool->free_index += N;

    for (size_t i = 0; i < N; ++i) {
        p[i].RNTI = rand() % 1024; // Random RNTI
        memset(&p[i].ue_info_tag, 0, sizeof(RX_UE_INFORMATION_TAG));
        p[i].crc_indication_rel8_tag = rand() % 2; // Random CRCFLAG
    }

    return p;
}

void deallocate_nfaapi_crc_pdu(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* pdu, size_t N) {
    if (pool == NULL || pdu < (NFAPI_CRC_INDICATION_PDU_T*)pool->pool || pdu > (NFAPI_CRC_INDICATION_PDU_T*)(pool->pool + pool->block_size * pool->num_blocks)) return;

    // No deallocation needed in a fixed-size memory pool
}

int main() {
    srand(time(NULL));

    MemoryPool* pool = create_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), 1024);
    if (pool == NULL) {
        fprintf(stderr, "Failed to create memory pool\n");
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T* p = allocate_nfaapi_crc_pdu(pool, 512);
    if (p == NULL) {
        fprintf(stderr, "Failed to allocate NFAPI_CRC_INDICATION_PDU_T structures\n");
        destroy_memory_pool(pool);
        return 1;
    }

    // Use the allocated memory for processing

    deallocate_nfaapi_crc_pdu(pool, p, 512); // No-op in fixed-size pool
    destroy_memory_pool(pool);

    return 0;
}
