// Function to create and populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_and_populate_linked_list(int N, size_t MAX_MEMORY) {
    // Initialize variables
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* current = NULL;
    size_t total_memory_used = 0;

    // Seed the random number generator
    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        // Calculate memory required for the next node
        size_t node_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
        if (total_memory_used + node_size > MAX_MEMORY) {
            printf("Error: Maximum memory limit reached.\n");
            return head;
        }

        // Allocate memory for the new node
        NFAPI_CRC_INDICATION_PDU_T* new_node = malloc(node_size);
        if (new_node == NULL) {
            printf("Error: Memory allocation failed.\n");
            return head;
        }

        // Populate the new node with random data
        new_node->RX_UE_INFORMATION_TAG = rand() % 1000;
        new_node->RNTI = rand() % 65536;
        new_node->CRCFLAG = rand() % 2;

        // Add the new node to the linked list
        if (head == NULL) {
            head = new_node;
            current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }

        // Update total memory used
        total_memory_used += node_size;

        // Log the operation details
        printf("Added node %d with RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", i, new_node->RX_UE_INFORMATION_TAG, new_node->RNTI, new_node->CRCFLAG);
    }

    return head;
}

int main() {
    int N = 10; // Number of structures to create
    size_t MAX_MEMORY = 1024 * 1024; // Maximum memory limit in bytes

    NFAPI_CRC_INDICATION_PDU_T* list_head = create_and_populate_linked_list(N, MAX_MEMORY);

    if (list_head != NULL) {
        printf("Linked list created successfully with %d nodes.\n", N);
        // Free the allocated memory
        while (list_head != NULL) {
            NFAPI_CRC_INDICATION_PDU_T* temp = list_head;
            list_head = list_head->next;
            free(temp);
        }
    }

    return 0;
}
