#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_NFAPIS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    bool CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *nfapi_list[MAX_NFAPIS];
int nfapi_count = 0;
pthread_mutex_t nfapi_mutex;

void initialize_nfaapi_list(int count) {
    if (count <= 0 || count > MAX_NFAPIS) {
        fprintf(stderr, "Invalid count for NFAPI list\n");
        return;
    }

    pthread_mutex_lock(&nfapi_mutex);
    if (nfapi_count != 0) {
        fprintf(stderr, "NFAPI list already initialized\n");
        pthread_mutex_unlock(&nfapi_mutex);
        return;
    }

    for (int i = 0; i < count; ++i) {
        nfapi_list[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!nfapi_list[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&nfapi_mutex);
            return;
        }
        // Initialize fields here
    }

    nfapi_count = count;
    pthread_mutex_unlock(&nfapi_mutex);
}

void populate_nfaapi_list() {
    if (nfapi_count == 0) {
        fprintf(stderr, "NFAPI list not initialized\n");
        return;
    }

    pthread_mutex_lock(&nfapi_mutex);
    for (int i = 0; i < nfapi_count; ++i) {
        // Populate fields with random values
        nfapi_list[i]->RX_UE_INFORMATION_TAG = rand();
        nfapi_list[i]->RNTI = (unsigned short)rand();
        nfapi_list[i]->CRC_INDICATION_REL8_TAG = (bool)(rand() % 2);
    }
    pthread_mutex_unlock(&nfapi_mutex);
}

void free_nfaapi_list() {
    if (nfapi_count == 0) {
        fprintf(stderr, "NFAPI list not initialized\n");
        return;
    }

    pthread_mutex_lock(&nfapi_mutex);
    for (int i = 0; i < nfapi_count; ++i) {
        free(nfapi_list[i]);
        nfapi_list[i] = NULL;
    }
    nfapi_count = 0;
    pthread_mutex_unlock(&nfapi_mutex);
}
