    Packet** packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketList;

void initPacketList(PacketList* list, size_t initialCapacity) {
    list->packets = malloc(initialCapacity * sizeof(Packet*));
    if (list->packets == NULL) {
        // Handle memory allocation failure
        return;
    }
    list->count = 0;
    list->capacity = initialCapacity;
    pthread_mutex_init(&list->lock, NULL);
}

void destroyPacketList(PacketList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->packets[i]->payload);
        free(list->packets[i]);
    }
    free(list->packets);
    pthread_mutex_destroy(&list->lock);
}

int appendPacket(PacketList* list, char* payload, size_t size) {
    if (size > PAYLOAD_LIMIT) {
        // Log error: Payload too large
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        Packet** newPackets = realloc(list->packets, list->capacity * 2 * sizeof(Packet*));
        if (newPackets == NULL) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->packets = newPackets;
        list->capacity *= 2;
    }

    Packet* newPacket = malloc(sizeof(Packet));
    if (newPacket == NULL) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    newPacket->payload = malloc(size);
    if (newPacket->payload == NULL) {
        free(newPacket);
        // Handle memory allocation failure
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    memcpy(newPacket->payload, payload, size);
    newPacket->size = size;

    list->packets[list->count++] = newPacket;

    pthread_mutex_unlock(&list->lock);

    // Log successful packet append

    return 0;
}
