        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);
}

void add_image(DynamicImageList *list, ImageMetadata *image) {
    if (list->count >= list->capacity) {
        list->capacity *= 2;
        list->images = (ImageMetadata *)realloc(list->images, list->capacity * sizeof(ImageMetadata));
        if (!list->images) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }
    pthread_mutex_lock(&list->mutex);
    memcpy(&list->images[list->count++], image, sizeof(ImageMetadata));
    pthread_mutex_unlock(&list->mutex);
}

void filter_images_by_extension(DynamicImageList *list, const char *extension) {
