ListNode* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    ListNode* node = (ListNode*)malloc(sizeof(ListNode));
    if (node == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    node->data = data;
    node->next = NULL;
    return node;
}

void add_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    ListNode* new_node = create_node(data);
    if (new_node != NULL) {
        if (list->head == NULL) {
            list->head = new_node;
        } else {
            ListNode* temp = list->head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = new_node;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

void free_list(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
}

