private:
    std::mt19937 gen;
    std::uniform_int_distribution<int> intDist;
    std::uniform_real_distribution<float> floatDist;
    std::mutex mtx;

public:
    ValueGenerator(int minRange, int maxRange) : intDist(minRange, maxRange), gen(std::random_device{}()) {}

    void setRange(int minRange, int maxRange) {
        std::lock_guard<std::mutex> lock(mtx);
        if (maxRange < minRange) {
            throw std::invalid_argument("Max range must be greater than or equal to min range");
        }
        intDist = std::uniform_int_distribution<int>(minRange, maxRange);
    }

    int getInteger() {
        std::lock_guard<std::mutex> lock(mtx);
        return intDist(gen);
    }

    float getFloat() {
        std::lock_guard<std::mutex> lock(mtx);
        return floatDist(gen);
    }
};

