#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_PAYLOAD_SIZE 1024
#define INITIAL_CAPACITY 16

typedef struct {
    char **payloads;
    size_t *payload_sizes;
    size_t capacity;
    size_t count;
    size_t total_size;
    pthread_mutex_t lock;
} PacketList;

void init_packet_list(PacketList *list) {
    list->payloads = malloc(INITIAL_CAPACITY * sizeof(char *));
    list->payload_sizes = malloc(INITIAL_CAPACITY * sizeof(size_t));
    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    list->total_size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void free_packet_list(PacketList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->payloads[i]);
    }
    free(list->payloads);
    free(list->payload_sizes);
    pthread_mutex_destroy(&list->lock);
}

int add_packet(PacketList *list, const char *payload, size_t payload_size) {
    if (payload_size > MAX_PAYLOAD_SIZE || list->total_size + payload_size > MAX_TOTAL_SIZE) {
        return -1; // Packet too large or total exceeds limit
    }

    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        char **new_payloads = realloc(list->payloads, new_capacity * sizeof(char *));
        size_t *new_sizes = realloc(list->payload_sizes, new_capacity * sizeof(size_t));

        if (!new_payloads || !new_sizes) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Memory allocation failed
        }

        list->payloads = new_payloads;
        list->payload_sizes = new_sizes;
        list->capacity = new_capacity;
    }

    list->payloads[list->count] = malloc(payload_size + 1);
    if (!list->payloads[list->count]) {
        pthread_mutex_unlock(&list->lock);
        return -3; // Memory allocation failed
    }

    memcpy(list->payloads[list->count], payload, payload_size);
    list->payload_sizes[list->count] = payload_size;
    list->payloads[list->count][payload_size] = '\0';
    list->total_size += payload_size;
    ++list->count;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

void log_packet_list(const PacketList *list) {
    printf("Total packets: %zu\n", list->count);
    printf("Total payload size: %zu\n", list->total_size);
}

int main() {
    PacketList packet_list;
    init_packet_list(&packet_list);

    // Example usage
    char packet1[] = "Hello";
    char packet2[] = "World";

    add_packet(&packet_list, packet1, sizeof(packet1) - 1);
    add_packet(&packet_list, packet2, sizeof(packet2) - 1);

    log_packet_list(&packet_list);

    free_packet_list(&packet_list);
    return 0;
}
```

**Design Decisions:**
1. **Thread Safety**: Mutex is used to ensure that adding packets is thread-safe.
2. **Dynamic Resizing**: The payload array doubles in size when needed, ensuring efficient scaling without frequent allocations.
3. **Logging Mechanism**: A simple logging function tracks key metrics.
4. **Memory Management**: Explicit memory allocation and deallocation for each packet, with checks for failures.

**Trade-offs:**
- **Latency vs Memory Footprint**: Doubling the capacity of the payload array minimizes reallocations but increases memory usage.
- **Scalability**: Dynamic resizing allows the system to handle varying loads efficiently.
- **Maintainability**: Simple and clear structure makes it easier to understand and extend.

This design provides a robust starting point that can be scaled and extended based on specific requirements.']

