        node->RNTI = rand();
        node->CRC_INDICATION_REL8_TAG = rand();
        node->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
        node->prev = NULL;
        node->next = NULL;
    }
