    printf("Enter the number of audio frames to allocate: ");
    scanf("%d", &requested_frames);

    AudioFrame* frames = allocate_audio_frames(requested_frames, log_file);
    if (frames) {
        verify_audio_frames(frames, requested_frames, log_file);
        free(frames); // Free allocated memory when done
    }

