#include <stdio.h>
#include <stdlib.h>

// Define the structure for a packet metadata
typedef struct PacketMetadata {
    int sourceId;
    int destinationId;
} PacketMetadata;

// Define the structure for a network packet
typedef struct NetworkPacket {
    PacketMetadata meta;
    int payloadSize;
    char* payload;
    struct NetworkPacket* next;
} NetworkPacket;

// Function to create a new network packet
NetworkPacket* createPacket(int sourceId, int destinationId, const char* payload, int payloadSize) {
    NetworkPacket* packet = (NetworkPacket*)malloc(sizeof(NetworkPacket));
    if (!packet) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    packet->meta.sourceId = sourceId;
    packet->meta.destinationId = destinationId;
    packet->payloadSize = payloadSize;
    packet->payload = (char*)malloc(payloadSize * sizeof(char));
    if (!packet->payload) {
        fprintf(stderr, "Memory allocation failed\n");
        free(packet);
        exit(1);
    }
    memcpy(packet->payload, payload, payloadSize);
    packet->next = NULL;
    return packet;
}

// Function to add a packet to the linked list
void addPacket(NetworkPacket** head, NetworkPacket* newPacket) {
    if (*head == NULL) {
        *head = newPacket;
    } else {
        NetworkPacket* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newPacket;
    }
}

// Function to process a stream of network packets
void processPackets(NetworkPacket** head, const char* packetStream, int totalBytes) {
    // Simulate parsing and creating packets from the stream
    for (int i = 0; i < totalBytes;) {
        int sourceId = packetStream[i++] * 256 + packetStream[i++];
        int destinationId = packetStream[i++] * 256 + packetStream[i++];
        int payloadSize = packetStream[i++] * 256 + packetStream[i++];
        NetworkPacket* newPacket = createPacket(sourceId, destinationId, packetStream + i, payloadSize);
        addPacket(head, newPacket);
        i += payloadSize;
    }
}

// Function to free the memory allocated for the linked list
void freePackets(NetworkPacket* head) {
    NetworkPacket* current = head;
    while (current != NULL) {
        NetworkPacket* next = current->next;
        free(current->payload);
        free(current);
        current = next;
    }
}

// Example usage
int main() {
    NetworkPacket* packetList = NULL;
    const char packetStream[] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08}; // Example stream
    int totalBytes = sizeof(packetStream);
    processPackets(&packetList, packetStream, totalBytes);
    freePackets(packetList);
    return 0;
}
```

This code snippet defines the necessary structures and functions to process a stream of network packets into a singly linked list. Each packet includes metadata and a payload, which are dynamically allocated based on the size provided in the packet stream. The `processPackets` function simulates parsing and creating packets from a byte stream, adding them to a linked list, while the `freePackets` function handles memory deallocation when packets are processed.']

