#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int width;
    int height;
    long fileSize;
    float compressionRatio;
    int orientation;
} ImageMetadata;

typedef struct Node {
    char* fileName;
    ImageMetadata metadata;
    struct Node* next;
} ListNode;

typedef struct {
    ListNode* head;
    ListNode* tail;
    size_t currentSize;
    size_t maxSize;
} ImageList;

int createImageMetadata(ListNode** node, const char* fileName) {
    *node = (ListNode*)malloc(sizeof(ListNode));
    if (*node == NULL) return -1; // Memory allocation failed
    (*node)->fileName = strdup(fileName);
    if ((*node)->fileName == NULL) {
        free(*node);
        return -2; // Memory allocation for file name failed
    }
    (*node)->metadata.width = 0;
    (*node)->metadata.height = 0;
    (*node)->metadata.fileSize = 0;
    (*node)->metadata.compressionRatio = 1.0;
    (*node)->metadata.orientation = 0;
    (*node)->next = NULL;
    return 0; // Success
}

void freeImageMetadata(ListNode* node) {
    if (node != NULL) {
        free(node->fileName);
        free(node);
    }
}

int processImages(const char** fileNames, int count, ImageList* list, size_t maxSize) {
    for (int i = 0; i < count; i++) {
        ListNode* newNode;
        if (createImageMetadata(&newNode, fileNames[i]) != 0) return -1; // Failed to create node
        if (list->currentSize + sizeof(ListNode) > list->maxSize) {
            freeImageMetadata(newNode);
            return -2; // Memory limit exceeded
        }
        newNode->next = NULL;
        if (list->head == NULL) {
            list->head = newNode;
        } else {
            list->tail->next = newNode;
        }
        list->tail = newNode;
        list->currentSize += sizeof(ListNode);
    }
    return 0; // Success
}

void freeImageList(ImageList* list) {
    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* next = current->next;
        freeImageMetadata(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->currentSize = 0;
}
