#include <stdlib.h>
#include <pthread.h>
#include <assert.h>

// Define NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a node in the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define the linked list structure
typedef struct LinkedList {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t mutex;
} LinkedList;

// Function to create a new node
Node* create_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        return NULL; // Handle allocation failure
    }
    newNode->data = *data;
    newNode->next = NULL;
    return newNode;
}

// Function to initialize the linked list
void init_list(LinkedList* list) {
    pthread_mutex_init(&list->mutex, NULL);
    list->head = list->tail = NULL;
    list->size = 0;
}

// Function to add a new element to the linked list
int add_element(LinkedList* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->mutex);
    Node* newNode = create_node(data);
    if (newNode == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Handle allocation failure
    }
    if (list->head == NULL) {
        list->head = list->tail = newNode;
    } else {
        list->tail->next = newNode;
        list->tail = newNode;
    }
    list->size++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Function to remove an element based on RNTI
int remove_element_by_rnti(LinkedList* list, int rnti) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    Node* prev = NULL;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            if (current == list->tail) {
                list->tail = prev;
            }
            free(current);
            list->size--;
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return 0; // Return success
}

// Function to iterate over the linked list and process each element
void iterate_list(LinkedList* list, void (*process)(const NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        process(&current->data);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to free the linked list
void free_list(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
