FrameHeader* create_frame_header(size_t payload_length) {
    if (payload_length > MAX_PAYLOAD_SIZE) {
        return NULL; // Payload too large
    }

    FrameHeader *header = (FrameHeader *)malloc(sizeof(FrameHeader));
    if (!header) {
        return NULL; // Memory allocation failed
    }

    header->length = payload_length;
    header->timestamp = 0; // Initialize timestamp

    // Allocate memory for the payload
    header->payload = (uint8_t *)malloc(payload_length);
    if (!header->payload) {
        free(header); // Free partially allocated structure
        return NULL; // Memory allocation failed
    }

    return header;
}

void destroy_frame_header(FrameHeader *header) {
    if (header && header->payload) {
        free(header->payload); // Free payload memory
    }
    free(header); // Free frame header memory
}
