#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <zlib.h>

#define MAX_FRAME_SIZE 1024 * 1024
#define DEFAULT_PAYLOAD_COMPRESSION Z_DEFLATED

typedef struct FrameHeader {
    time_t timestamp;
    size_t length;
    unsigned char *payload;
} FrameHeader;

typedef struct FrameManager {
    FrameHeader **frames;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    size_t total_allocated_size;
    size_t total_deallocated_size;
} FrameManager;

FrameManager* create_frame_manager(size_t initial_capacity) {
    FrameManager *manager = malloc(sizeof(FrameManager));
    if (!manager) return NULL;

    manager->frames = malloc(initial_capacity * sizeof(FrameHeader *));
    if (!manager->frames) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    manager->total_allocated_size = 0;
    manager->total_deallocated_size = 0;

    return manager;
}

void destroy_frame_manager(FrameManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->frames[i]->payload);
        free(manager->frames[i]);
    }
    free(manager->frames);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int add_frame(FrameManager *manager, time_t timestamp, size_t length, const unsigned char *data) {
    pthread_mutex_lock(&manager->mutex);

    if (length > MAX_FRAME_SIZE || length > manager->capacity - manager->count) {
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    FrameHeader *frame = malloc(sizeof(FrameHeader));
    if (!frame) {
        pthread_mutex_unlock(&manager->mutex);
        return -2;
    }

    frame->timestamp = timestamp;
    frame->length = length;

    unsigned char *compressed_data = NULL;
    uLong compressed_length = compressBound(length);
    compressed_data = malloc(compressed_length);
    if (!compressed_data) {
        free(frame);
        pthread_mutex_unlock(&manager->mutex);
        return -3;
    }

    int ret = compress2(compressed_data, &compressed_length, data, length, DEFAULT_PAYLOAD_COMPRESSION);
    if (ret != Z_OK) {
        free(compressed_data);
        free(frame);
        pthread_mutex_unlock(&manager->mutex);
        return -4;
    }

    frame->payload = compressed_data;

    manager->frames[manager->count] = frame;
    ++manager->count;
    manager->total_allocated_size += sizeof(FrameHeader) + compressed_length;

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

int get_frame_payload(FrameManager *manager, size_t index, unsigned char **data, size_t *length) {
    pthread_mutex_lock(&manager->mutex);

    if (index >= manager->count) {
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    FrameHeader *frame = manager->frames[index];
    uLong decompressed_length = frame->length;
    unsigned char *decompressed_data = malloc(decompressed_length);
    if (!decompressed_data) {
        pthread_mutex_unlock(&manager->mutex);
        return -2;
    }

    int ret = uncompress(decompressed_data, &decompressed_length, frame->payload, frame->length);
    if (ret != Z_OK) {
        free(decompressed_data);
        pthread_mutex_unlock(&manager->mutex);
        return -3;
    }

    *data = decompressed_data;
    *length = decompressed_length;

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

void log_memory_operation(const char *operation, size_t size) {
    // Implement logging mechanism here
}

int preallocate_frames(FrameManager *manager, size_t num_frames) {
    pthread_mutex_lock(&manager->mutex);

    if (num_frames + manager->count > manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        FrameHeader **new_frames = realloc(manager->frames, new_capacity * sizeof(FrameHeader *));
        if (!new_frames) {
            pthread_mutex_unlock(&manager->mutex);
            return -1;
        }
        manager->frames = new_frames;
        manager->capacity = new_capacity;
    }

    for (size_t i = 0; i < num_frames; ++i) {
        FrameHeader *frame = malloc(sizeof(FrameHeader));
        if (!frame) {
            pthread_mutex_unlock(&manager->mutex);
            return -2;
        }
        frame->timestamp = 0;
        frame->length = 0;
        frame->payload = NULL;
        manager->frames[manager->count] = frame;
        ++manager->count;
    }

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

void serialize_frame_manager(const FrameManager *manager, FILE *file) {
