#include <stdlib.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    int size;
    pthread_mutex_t mutex;
} LinkedList;

int add_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->size >= MAX_LIST_SIZE) {
        return -1; // Error: List is full
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        return -2; // Error: Memory allocation failed
    }

    pthread_mutex_lock(&list->mutex);
    new_node->data = data;
    new_node->next = NULL;

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        list->tail->next = new_node;
    }
    list->tail = new_node;
    list->size++;
    pthread_mutex_unlock(&list->mutex);

    return 0; // Success
}

void init_list(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void free_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
}
```

