#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_IMAGE_ENTRIES 1000
#define MEM_USAGE_THRESHOLD 500 // in MB

typedef struct {
    int width;
    int height;
    long long fileSize;
} ImageMetadata;

typedef struct {
    ImageMetadata *metadataArray;
    size_t count;
    size_t capacity;
    FILE *stream;
    off_t lastValidPosition;
    size_t memoryUsage;
} ImageProcessor;

void initImageProcessor(ImageProcessor *processor, const char *filename) {
    processor->metadataArray = (ImageMetadata *)malloc(sizeof(ImageMetadata) * MAX_IMAGE_ENTRIES);
    processor->count = 0;
    processor->capacity = MAX_IMAGE_ENTRIES;
    processor->stream = fopen(filename, "rb");
    processor->lastValidPosition = 0;
    processor->memoryUsage = 0;
}

void freeImageProcessor(ImageProcessor *processor) {
    if (processor->metadataArray) {
        free(processor->metadataArray);
    }
    if (processor->stream) {
        fclose(processor->stream);
    }
}

int readNextEntry(ImageProcessor *processor) {
    if (!feof(processor->stream)) {
        size_t bytesRead = fread(&processor->metadataArray[processor->count], sizeof(ImageMetadata), 1, processor->stream);
        if (bytesRead == 1) {
            processor->memoryUsage += sizeof(ImageMetadata);
            if (processor->memoryUsage > MEM_USAGE_THRESHOLD) {
                fseek(processor->stream, -sizeof(ImageMetadata), SEEK_CUR);
                processor->memoryUsage -= sizeof(ImageMetadata);
                return -1; // Memory usage threshold exceeded
            }
            processor->count++;
        } else {
            return -2; // Read error
        }
    }
    return 0;
}

void processImageEntries(ImageProcessor *processor) {
    while (readNextEntry(processor) == 0) {
        printf("Processed entry %zu: Width=%d, Height=%d, File Size=%lld\n", processor->count - 1, 
               processor->metadataArray[processor->count - 1].width,
               processor->metadataArray[processor->count - 1].height,
               processor->metadataArray[processor->count - 1].fileSize);
    }
}

int main() {
    ImageProcessor processor;
    initImageProcessor(&processor, "image_metadata.bin");
    processImageEntries(&processor);
    freeImageProcessor(&processor);
    return 0;
}
