    for (int i = 0; i < packet_count; ++i) {
        if (payload_sizes[i] > MAX_PACKET_SIZE) {
            return NULL; // Payload too large
        }
        total_payload_size += payload_sizes[i];
    }

    PacketHeader** packet_headers = malloc(packet_count * sizeof(PacketHeader*));
    if (packet_headers == NULL) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < packet_count; ++i) {
        packet_headers[i] = malloc(sizeof(PacketHeader));
        if (packet_headers[i] == NULL) {
            for (int j = 0; j < i; ++j) {
                free(packet_headers[j]);
            }
            free(packet_headers);
            return NULL; // Memory allocation failed
        }

        packet_headers[i]->PacketID = i;
        packet_headers[i]->PayloadData = malloc(payload_sizes[i] + 1); // Extra space for null terminator
        if (packet_headers[i]->PayloadData == NULL) {
            for (int j = 0; j <= i; ++j) {
                free(packet_headers[j]);
            }
            free(packet_headers);
            return NULL; // Memory allocation failed
        }

        memcpy(packet_headers[i]->PayloadData, packet_data[i], payload_sizes[i]);
        packet_headers[i]->PayloadData[payload_sizes[i]] = '\0'; // Null terminate the string
    }

    return packet_headers;
}

void free_packet_headers(PacketHeader** packet_headers, int packet_count) {
    for (int i = 0; i < packet_count; ++i) {
        if (packet_headers[i] != NULL) {
            free(packet_headers[i]->PayloadData);
            free(packet_headers[i]);
        }
    }
    free(packet_headers);
}
