    char rx_ue_information_tag[RX_UE_INFORMATION_TAG_SIZE];
    int rnti;
} NFAPICRCIndicationPDU;

NFAPICRCIndicationPDU* generateCrcIndicationList(int numStructures, int maxLimit) {
    if (numStructures > maxLimit || numStructures < 1) {
        return NULL; // Invalid size
    }

    NFAPICRCIndicationPDU* list = malloc(numStructures * sizeof(NFAPICRCIndicationPDU));
    if (!list) {
        return NULL; // Memory allocation failed
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < numStructures; i++) {
        pthread_mutex_lock(&mutex);
        if ((i + 1) * sizeof(NFAPICRCIndicationPDU) > maxLimit) {
            pthread_mutex_unlock(&mutex);
            free(list);
            return NULL; // Exceeds memory limit
        }
        pthread_mutex_unlock(&mutex);

        list[i].rnti = rand() % (1 << 30); // Random RNTI
        snprintf(list[i].rx_ue_information_tag, RX_UE_INFORMATION_TAG_SIZE, "RX_%d", i);
        list[i].rx_ue_information_tag[RX_UE_INFORMATION_TAG_SIZE - 1] = '\0';

        list[i].rxueinformationtag.len = sizeof(NFAPICRCIndicationPDU) - offsetof(NFAPICRCIndicationPDU, rxueinformationtag);
    }

    pthread_mutex_destroy(&mutex);

    return list;
}

int main() {
